var __index = {"config":{"lang":["zh","en"],"separator":"[\\s\\u200b\\u3000\\-\u3001\u3002\uff0c\uff0e\uff1f\uff01\uff1b]+","pipeline":["stemmer"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"\u6982\u8ff0","text":""},{"location":"index.html#_1","title":"\u70ed\u529b\u5b66\u4e0e\u7edf\u8ba1\u7269\u7406\u7b14\u8bb0","text":""},{"location":"index.html#_2","title":"\u80cc\u666f\u4ecb\u7ecd","text":"<p>\u70ed\u529b\u5b66\u4e0e\u7edf\u8ba1\u7269\u7406\u8ba8\u8bba\u7684\u662f\u540c\u4e00\u4ef6\u4e8b\u7684\u4e24\u79cd\u8bed\u8a00\uff1a\u70ed\u529b\u5b66\u4ece\u5b8f\u89c2\u72b6\u6001\u51fd\u6570\u51fa\u53d1\uff0c\u7528\u5c11\u6570\u53d8\u91cf\u63cf\u8ff0\u7cfb\u7edf\u7684\u5e73\u8861\u3001\u76f8\u53d8\u548c\u80fd\u91cf\u8f6c\u5316\uff1b\u7edf\u8ba1\u7269\u7406\u5219\u4ece\u5fae\u89c2\u7c92\u5b50\u7684\u72b6\u6001\u6570\u51fa\u53d1\uff0c\u89e3\u91ca\u6e29\u5ea6\u3001\u71b5\u3001\u70ed\u5bb9\u3001\u6da8\u843d\u548c\u5206\u5e03\u51fd\u6570\u4e3a\u4ec0\u4e48\u4f1a\u51fa\u73b0\u3002</p> <p>\u8fd9\u4efd\u7b14\u8bb0\u6cbf\u7740\u201c\u70ed\u529b\u5b66\u57fa\u672c\u89c4\u5f8b \\(\\rightarrow\\) \u5e73\u8861\u5224\u636e\u4e0e\u76f8\u53d8 \\(\\rightarrow\\) \u5206\u5b50\u52a8\u7406\u5b66 \\(\\rightarrow\\) \u7edf\u8ba1\u5206\u5e03 \\(\\rightarrow\\) \u7cfb\u7efc\u7406\u8bba\u201d\u7684\u8def\u7ebf\u6574\u7406\u3002\u524d\u534a\u90e8\u5206\u66f4\u50cf\u5b8f\u89c2\u70ed\u529b\u5b66\u7684\u8ba1\u7b97\u5de5\u5177\u7bb1\uff0c\u540e\u534a\u90e8\u5206\u5219\u9010\u6e10\u8f6c\u5411\u5fae\u89c2\u56fe\u50cf\uff0c\u628a\u71b5\u3001\u914d\u5206\u51fd\u6570\u548c\u7cfb\u7efc\u8fd9\u4e9b\u6982\u5ff5\u4e32\u8d77\u6765\u3002</p>"},{"location":"index.html#pdf","title":"PDF \u7248\u672c","text":"<p>\u5982\u679c\u60f3\u79bb\u7ebf\u9605\u8bfb\u53ef\u4ee5\u4e0b\u8f7d2021\u5e74\u7684\u6574\u7406\u7248\uff1a\u70ed\u7edf\u77e5\u8bc6\u68b3\u7406 PDF\u3002</p>"},{"location":"index.html#_3","title":"\u5185\u5bb9\u7ed3\u6784","text":"\u7ae0\u8282 \u5185\u5bb9 \u7b2c1\u7ae0 \u70ed\u529b\u5b66\u7684\u57fa\u672c\u6982\u5ff5 \u7b2c2\u7ae0 \u5747\u5300\u4f53\u7cfb\u7684\u70ed\u529b\u5b66\u6027\u8d28 \u7b2c3\u7ae0 \u5355\u5143\u4f53\u7cfb\u76f8\u53d8 \u7b2c4\u7ae0 \u591a\u5143\u4f53\u7cfb\u5e73\u8861 \u7b2c5\u7ae0 \u5206\u5b50\u52a8\u7406\u5b66 \u7b2c6\u7ae0 \u8fd1\u72ec\u7acb\u5b50\u7cfb\u6700\u6982\u7136\u5206\u5e03 \u7b2c7\u7ae0 Boltzmann\u7edf\u8ba1\u7406\u8bba \u7b2c8\u7ae0 Bose/Fermi\u7edf\u8ba1\u7406\u8bba \u7b2c9\u7ae0 \u7cfb\u7efc\u7406\u8bba"},{"location":"index.html#_4","title":"\u9605\u8bfb\u5efa\u8bae","text":"<p>\u5efa\u8bae\u5148\u628a\u7b2c\u4e00\u3001\u4e8c\u7ae0\u4e2d\u7684\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001Maxwell \u5173\u7cfb\u548c\u7279\u6027\u51fd\u6570\u8bfb\u987a\uff1b\u5b83\u4eec\u4f1a\u5728\u76f8\u53d8\u3001\u5316\u5b66\u52bf\u548c\u7cfb\u7efc\u7406\u8bba\u4e2d\u53cd\u590d\u51fa\u73b0\u3002\u516c\u5f0f\u8f83\u5bc6\u7684\u5730\u65b9\u53ef\u4ee5\u5148\u6293\u4f4f\u201c\u53d8\u91cf\u9009\u62e9\u201d\u548c\u201c\u7ea6\u675f\u6761\u4ef6\u201d\uff0c\u518d\u56de\u5934\u8865\u63a8\u5bfc\u7ec6\u8282\u3002</p> <p>\u8bfb\u7edf\u8ba1\u7269\u7406\u90e8\u5206\u65f6\uff0c\u53ef\u4ee5\u59cb\u7ec8\u76ef\u4f4f\u4e00\u6761\u7ebf\u7d22\uff1a\u5fae\u89c2\u72b6\u6001\u6570 \\(\\Omega\\) \u7ed9\u51fa\u71b5\uff0c\u914d\u5206\u51fd\u6570 \\(Z\\) \u7ed9\u51fa\u70ed\u529b\u5b66\u91cf\uff0c\u800c\u4e0d\u540c\u7ea6\u675f\u6761\u4ef6\u5bf9\u5e94\u4e0d\u540c\u7cfb\u7efc\u3002\u8fd9\u6837\u770b\uff0cBoltzmann\u3001Bose\u3001Fermi \u5206\u5e03\u5c31\u4e0d\u662f\u5b64\u7acb\u516c\u5f0f\uff0c\u800c\u662f\u540c\u4e00\u5957\u6781\u503c\u601d\u60f3\u5728\u4e0d\u540c\u7c92\u5b50\u7edf\u8ba1\u4e0b\u7684\u7ed3\u679c\u3002</p>"},{"location":"references.html","title":"\u53c2\u8003\u8d44\u6599","text":""},{"location":"references.html#_1","title":"\u53c2\u8003\u8d44\u6599","text":"<p>\u672c\u8282\u5217\u4e3e\u672c\u4efd\u70ed\u529b\u5b66\u4e0e\u7edf\u8ba1\u7269\u7406\u7b14\u8bb0\u53c2\u8003\u8fc7\u7684\u4e3b\u8981\u6559\u6750\u4e0e\u8bb2\u4e49\uff0c\u4fbf\u4e8e\u56de\u5230\u539f\u59cb\u6750\u6599\u4e2d\u67e5\u8bc1\u63a8\u5bfc\u7ec6\u8282\u3001\u7b26\u53f7\u7ea6\u5b9a\u548c\u4f8b\u9898\u80cc\u666f\u3002</p> <ul> <li>\u6c6a\u5fd7\u8bda. \u70ed\u529b\u5b66\u00b7\u7edf\u8ba1\u7269\u7406 [M]. \u9ad8\u7b49\u6559\u80b2\u51fa\u7248\u793e, 2013.</li> <li>\u6797\u5b97\u6db5. \u70ed\u529b\u5b66\u4e0e\u7edf\u8ba1\u7269\u7406 [M]. \u5317\u4eac\u5927\u5b66\u51fa\u7248\u793e, 2007.</li> <li>\u5218\u5ddd. \u70ed\u529b\u5b66\u4e0e\u7edf\u8ba1\u7269\u7406 [M]. \u81ea\u7f16\u8bb2\u4e49, 2002.</li> <li>\u674e\u653f\u9053. \u7edf\u8ba1\u529b\u5b66 [M]. \u4e0a\u6d77\u79d1\u5b66\u6280\u672f\u51fa\u7248\u793e, 2007.</li> </ul>"},{"location":"chapter_01_basic_concepts/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_01_basic_concepts/index.html#1","title":"\u7b2c1\u7ae0 \u70ed\u529b\u5b66\u7684\u57fa\u672c\u6982\u5ff5","text":"<p>\u8fd9\u4e00\u7ae0\u4e3b\u8981\u662f\u56de\u987e\u666e\u901a\u7269\u7406\u4e2d\u201c\u70ed\u5b66\u201d\u7684\u76f8\u5173\u6982\u5ff5\u548c\u601d\u60f3\u65b9\u6cd5\uff0c\u4e3a\u4e4b\u540e\u70ed\u529b\u5b66\u90e8\u5206\u7684\u5b66\u4e60\u8fdb\u884c\u9884\u70ed\u3002\u672c\u7ae0\u7684\u6838\u5fc3\u662f\u56f4\u7ed5\u70ed\u529b\u5b66\u7b2c\u4e00\u5b9a\u5f8b\u548c\u7b2c\u4e8c\u5b9a\u5f8b\u5c55\u5f00\u7684\uff0c\u6700\u7ec8\u5f97\u5230\u5c01\u95ed\u7cfb\u7edf\u7684\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\\(dU=TdS-pdV\\).\u5728\u6b64\u671f\u95f4\uff0c\u4f1a\u5f15\u5165\u5404\u79cd\u70ed\u529b\u5b66\u51fd\u6570\uff0c\u5f62\u6210\u70ed\u529b\u5b66\u7814\u7a76\u95ee\u9898\u7684\u8303\u5f0f\u3002</p>"},{"location":"chapter_01_basic_concepts/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u57fa\u672c\u6982\u5ff5</li> <li>\u7269\u6001\u65b9\u7a0b</li> <li>\u51c6\u9759\u6001\u8fc7\u7a0b\u3001\u529f\u7684\u8868\u793a</li> <li>\u70ed\u529b\u5b66\u7b2c\u4e00\u5b9a\u5f8b\u3001\u70ed\u5bb9</li> <li>\u7406\u60f3\u6c14\u4f53\u70ed\u5b66\u8fc7\u7a0b\u7684\u76f8\u5173\u8ba1\u7b97</li> <li>\u5361\u8bfa\u5faa\u73af\u4ee5\u53ca\u6548\u7387</li> <li>\u70ed\u529b\u5b66\u7b2c\u4e8c\u5b9a\u5f8b</li> <li>\u5361\u8bfa\u5b9a\u7406\u3001\u70ed\u529b\u5b66\u6e29\u6807\u5b58\u5728</li> <li>\u514b\u52b3\u4fee\u65af\u4e0d\u7b49\u5f0f\u3001\u71b5\u7684\u6982\u5ff5\u3001\u71b5\u589e\u539f\u7406</li> <li>\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001\u7406\u60f3\u6c14\u4f53\u7684\u71b5\u4e0e\u76f8\u5173\u8ba1\u7b97</li> <li>\u81ea\u7531\u80fd\u3001Gibbs\u51fd\u6570</li> </ul>"},{"location":"chapter_01_basic_concepts/01_basic_concepts.html","title":"\u57fa\u672c\u6982\u5ff5","text":""},{"location":"chapter_01_basic_concepts/01_basic_concepts.html#_1","title":"\u57fa\u672c\u6982\u5ff5","text":"<p>\u2605   \u70ed\u529b\u5b66\u7814\u7a76\u7684\u5bf9\u8c61\u662f\u5404\u79cd\u5404\u6837\u7684\u70ed\u529b\u5b66\u7cfb\u7edf\uff0c\u201c\u7cfb\u7edf\u201d\u4e00\u8bcd\u662f\u4e3a\u4e86\u4e0e\u5916\u754c\u8fdb\u884c\u533a\u5206\u800c\u5f15\u5165\u7684\uff0c\u901a\u5e38\u5bf9\u7cfb\u7edf\u6709\u5982\u4e0b\u5206\u7c7b\uff1a</p> \\[ \\begin{matrix} &amp; \\text{\u7269\u8d28\u4ea4\u6362} &amp;\\text{\u80fd\u91cf\u4ea4\u6362} \\\\ \\text{\u5f00\u653e}&amp; \\checkmark  &amp; \\checkmark  \\\\ \\text{\u5c01\u95ed}&amp;  \\times   &amp; \\checkmark  \\\\ \\text{\u5b64\u7acb}&amp; \\times&amp;\\times \\end{matrix} \\] <p>\u5728\u5b9e\u9645\u7684\u751f\u6d3b\u4e2d\uff0c\u5f00\u653e\u7cfb\u7edf\u548c\u5c01\u95ed\u7cfb\u7edf\u662f\u6700\u5e38\u89c1\u7684\uff0c\u800c\u5b64\u7acb\u7cfb\u7edf\u4ec5\u4ec5\u4f5c\u4e3a\u4e00\u79cd\u7406\u60f3\u7684\u6a21\u578b\u3002\u5f53\u7cfb\u7edf\u4e0e\u5916\u754c\u76f8\u4e92\u4f5c\u7528\u7684\u80fd\u91cf\u8fdc\u5c0f\u4e8e\u7cfb\u7edf\u80fd\u91cf\uff0c\u4ea4\u6362\u7c92\u5b50\u6570\u8fdc\u5c0f\u4e8e\u7cfb\u7edf\u7c92\u5b50\u6570\u65f6\uff0c\u53ef\u5c06\u7cfb\u7edf\u8fd1\u4f3c\u4e3a\u5b64\u7acb\u7cfb\u7edf\u3002</p> <p>\u6b64\u5916\uff0c\u5e94\u5f53\u6ce8\u610f\u533a\u5206\uff1a\u5143(\u5316\u5b66\u6027\u8d28\u76f8\u540c)\u3001\u76f8(\u7269\u7406\u6027\u8d28\u76f8\u540c)\u3001\u6001(\u540c\u4e00\u4e2a\u201c\u6001\u201d\u53ef\u4ee5\u6709\u8bb8\u591a\u201c\u76f8\u201d)\u7684\u6982\u5ff5\u3002\u4f8b\u5982\uff0c\u67d0\u6e29\u5ea6\u4e0b\u7684\u76d0\u6c34\uff0c\u7531\u4e8e\u5177\u6709\u4e24\u79cd\u5316\u5b66\u7ec4\u6210(NaCl\u548c\\(H_2O\\))\u56e0\u800c\u662f\u4e8c\u5143\u7cfb\uff0c\u4f46\u53ea\u8003\u8651\u76d0\u6c34\u7684\u6db2\u6001\u65f6\uff0c\u76d0\u548c\u6c34\u53c8\u53ea\u7ec4\u6210\u4e00\u4e2a\u76f8\u3002\u5f53\u6e29\u5ea6\u964d\u4f4e\uff0c\u76d0\u4f1a\u6790\u51fa\u6210\u56fa\u6001\uff0c\u76d0\u6c34\u4e2d\u51fa\u73b0\u4e86\u65b0\u7684\u76f8\uff0c\u4f46\u6574\u4f53\u4ecd\u7136\u662f\u4e8c\u5143\u7cfb\u3002</p> <p>\u7c7b\u6bd4\u7ecf\u5178\u529b\u5b66\u4e2d\u7684\u9759\u529b\u5b66\uff0c\u70ed\u529b\u5b66\u4e2d\u4e5f\u6709\u5e73\u8861\u6001\u3002\u70ed\u529b\u5b66\u5e73\u8861\u6001\uff0c\u5373\u5e73\u8861\u6001(\u6ce8\u610f\u4e0e\u70ed\u5e73\u8861\u4e0d\u540c)\uff0c\u901a\u5e38\u5b9a\u4e49\u4e3a\uff1a\u4e0d\u53d7\u5916\u754c\u6761\u4ef6\u5f71\u54cd(\u6216\u5b64\u7acb\u7cfb\u7edf)\u7684\u5404\u90e8\u5206\u5b8f\u89c2\u6027\u8d28\u4e0d\u968f\u65f6\u95f4\u53d8\u5316\u7684\u72b6\u6001\u3002 \u5e94\u5f53\u6ce8\u610f\u4ee5\u4e0b\u51e0\u70b9\uff1a</p> <ul> <li>\u6ce8\u610f\u4e0d\u662f\u53ea\u6709\u5b64\u7acb\u7cfb\u7edf\u624d\u80fd\u8fbe\u5230\u5e73\u8861\u6001\uff0c\u6bd4\u5982\u5c01\u95ed\u7cfb\u7edf\u4e0e\u5916\u754c\u6e29\u5ea6\u76f8\u540c\u65f6\uff0c\u4ecd\u4e3a\u5e73\u8861\u6001\u3002</li> <li>\u5224\u65ad\u662f\u5426\u4e3a\u5e73\u8861\u6001\uff0c\u901a\u5e38\u5c06\u7cfb\u7edf\u5b64\u7acb\uff0c\u770b\u7cfb\u7edf\u662f\u5426\u53d1\u751f\u53d8\u5316\u3002</li> <li>\u53ea\u6709\u6ee1\u8db3\u5e73\u8861\u6001\u6761\u4ef6\u7684\u72b6\u6001\uff0c\u624d\u80fd\u6210\u4e3aP-V\u56fe\u4e0a\u7684\u67d0\u4e2a\u70b9\uff0c\u800c\u70b9\u5230\u70b9\u7684\u8fc7\u7a0b\u5fc5\u987b\u662f\u51c6\u9759\u6001\u8fc7\u7a0b\u3002</li> <li>\u5e73\u8861\u6001\u5b9a\u4e49\u7684\u6838\u5fc3\u662f\u201c\u4e0d\u53d7\u5916\u754c\u5f71\u54cd\u201d\uff0c\u800c\u6240\u8c13\u7684\u4e0d\u53d7\u5916\u754c\u5f71\u54cd\u901a\u5e38\u6ee1\u8db3\u56db\u6761\u5e73\u8861\uff1a\u529b\u5b66\u5e73\u8861(\u65e0\u7c92\u5b50\u6d41\uff0c\u5728\u573a\u4e2d\u7684\u5e73\u8861)\u3001\u70ed\u5e73\u8861(\u65e0\u70ed\u6d41\uff0c\u7cfb\u7edf\u5185\u6e29\u5ea6\u76f8\u540c)\u3001\u5316\u5b66\u5e73\u8861(\u7cfb\u7edf\u5185\u5404\u90e8\u5206\u5316\u5b66\u7ec4\u6210\u76f8\u540c)\u3001\u76f8\u5e73\u8861(\u5316\u5b66\u52bf\u76f8\u540c)</li> <li>\u7531\u4e8e\u5fae\u89c2\u4e0a\uff0c\u7cfb\u7edf\u7684\u7c92\u5b50\u662f\u4e0d\u65ad\u8fd0\u52a8\u7684\uff0c\u5b8f\u89c2\u6027\u8d28\u53ea\u662f\u5728\u5f1b\u8c6b\u65f6\u95f4\u4e0b\u7edf\u8ba1\u5e73\u5747\u7684\u7ed3\u679c\uff0c\u56e0\u6b64\u5fc5\u5b9a\u4f1a\u51fa\u73b0\u6da8\u843d\uff0c\u4f46\u8fd9\u79cd\u6da8\u843d\u6781\u5c0f\u56e0\u6b64\u70ed\u529b\u5b66\u90e8\u5206\u5ffd\u7565\u4e0d\u8ba1\u3002\u6b64\u5916\uff0c\u5e73\u8861\u6001\u4e5f\u53eb\u70ed\u52a8\u5e73\u8861\u3002</li> </ul> <p>\u81f3\u4e8e\u975e\u5e73\u8861\u6001\uff0c\u6700\u5178\u578b\u7684\u4f8b\u5b50\u5c31\u662f\u7a33\u6001\uff1a\u4e00\u4e2a\u6728\u5757\u8fde\u63a5\u5de6\u53f3\u4e24\u4e2a\u6e29\u5ea6\u4e0d\u540c\u7684\u6052\u6e29\u70ed\u6e90\uff0c\u867d\u7136\u8fbe\u5230\u4e86\u6e29\u5ea6\u5206\u5e03\u4e0d\u968f\u65f6\u95f4\u53d8\u5316\u7684\u72b6\u6001\u3002\u4f46\u56e0\u4e3a\u5176\u5b58\u5728\u70ed\u6d41\u548c\u5916\u754c\u7cfb\u7edf\u7684\u5f71\u54cd\u800c\u662f\u975e\u5e73\u8861\u6001\u3002</p> \u6b64\u540e\uff0c\u6ca1\u6709\u7279\u522b\u8bf4\u660e\uff0c\u9ed8\u8ba4\u63cf\u8ff0\u548c\u7814\u7a76\u7684\u90fd\u662f\u5e73\u8861\u6001 <p>\u76ee\u524d\u6709\u4e86\u8bb8\u591a\u6982\u5ff5\uff0c\u4f46\u5bf9\u4e8e\u5177\u4f53\u7684\u70ed\u529b\u5b66\u7cfb\u7edf\u9996\u8981\u7684\u95ee\u9898\u662f\u5982\u4f55\u63cf\u8ff0\u3002\u6211\u4eec\u63cf\u8ff0\u7684\u5927\u4f53\u601d\u8def\u662f\u901a\u8fc7\u9009\u5b9a\u63cf\u8ff0\u5b8f\u89c2\u6027\u8d28\u7684\u72b6\u6001\u53c2\u91cf\uff0c\u8fdb\u800c\u7531\u6b64\u8868\u793a\u51fa\u72b6\u6001\u51fd\u6570\uff0c\u7531\u6b64\u5bf9\u7cfb\u7edf\u8fdb\u884c\u63cf\u8ff0\u3002</p> <p>\u5e38\u89c1\u7684\u53c2\u91cf\u6709\uff1a\u51e0\u4f55\u53c2\u91cf\u3001\u529b\u5b66\u53c2\u91cf\u3001\u7535\u78c1\u53c2\u91cf\u3001\u5316\u5b66\u53c2\u91cf.\u5bf9\u5e94\u7684\u4f8b\u5b50\u662f\uff1a\u4f53\u79efV\u3001\u538b\u5f3aP\u3001\u7535\u573a\u5f3a\u5ea6E\u3001\u7269\u8d28\u7684\u91cfn\u3002\u6b64\u5916\uff0c\u5c06\u53ea\u7528(P,V)\u786e\u5b9a\u7684\u7cfb\u7edf\u53eb\u505a\u7b80\u5355\u7cfb\u7edf.</p> <p>\u81f3\u4e8e\u975e\u5e73\u8861\u6001\u7684\u63cf\u8ff0\uff0c\u8981\u5229\u7528\u201c\u5c40\u57df\u5e73\u8861\u5047\u8bbe\u201d\uff0c\u7528\u5b8f\u89c2\u5c0f\u5fae\u89c2\u5927\u7684\u601d\u60f3\uff0c\u5c06\u7cfb\u7edf\u5206\u6bb5\uff0c\u518d\u7528\u201c\u573a\u201d\u7684\u65b9\u6cd5\u8fdb\u884c\u63cf\u8ff0\u3002\u8fd9\u662f\u56e0\u4e3a\uff0c\u975e\u5e73\u8861\u6001\u4e2d\uff0c\u8bb8\u591a\u7269\u7406\u91cf\u65e0\u6cd5\u5355\u72ec\u63cf\u8ff0\u4e00\u4e2a\u7cfb\u7edf\uff0c\u53ea\u80fd\u5c06\u5176\u5316\u4e3a\u573a\u6765\u63cf\u8ff0\u3002</p> <p>\u2605   \u6e29\u5ea6\u662f\u4e2anon-trivial\u7684\u6982\u5ff5\uff0c\u867d\u7136\u5b83\u7684\u6df1\u523b\u5185\u6db5\u65e9\u5df2\u4e60\u7109\u4e0d\u5bdf\uff0c\u4f46\u5728\u8ba8\u8bba\u5177\u4f53\u70ed\u529b\u5b66\u95ee\u9898\u4e4b\u524d\u5fc5\u987b\u5c06\u4e4b\u9610\u660e\u3002</p> <p>\u70ed\u5e73\u8861\u5b9a\u5f8b\u7684\u5b9e\u9a8c\u8868\u660e\uff1a\\(A\\sim B,\\ B\\sim C \\Rightarrow A\\sim C\\)\uff0c\u5176\u4e2d\\(\\sim\\)\u8868\u793a\u5de6\u53f3\u4e24\u8fb9\u8fbe\u5230\u70ed\u5e73\u8861\u3002\u8fd9\u4e5f\u79f0\u4e3a\u70ed\u529b\u5b66\u7b2c0\u5b9a\u5f8b\u3002</p> <p>\u6ce8\u610f\u4ee5\u4e0a\u201c\u70ed\u5e73\u8861\u201d\u548c\u4e4b\u524d\u7684\u201c\u5e73\u8861\u6001\u201d\u7684\u533a\u522b\uff0c\u70ed\u5e73\u8861\u662f\u4e0d\u540c\u72b6\u6001(\u6216\u7cfb\u7edf)\u901a\u8fc7\u70ed\u63a5\u89e6\u8fbe\u5230\u5171\u540c\u72b6\u6001\u7684\u4e00\u79cd\u4e8c\u5143\u7b49\u4ef7\u5173\u7cfb(\u7b49\u4ef7\u7c7b)\uff1b\u5e73\u8861\u6001\u662f\u7cfb\u7edf\u5728\u6ca1\u6709\u53d7\u5916\u754c\u5f71\u54cd\u4e0b\uff0c\u5b8f\u89c2\u6027\u8d28\u4e0d\u53d8\u7684\u72b6\u6001\u3002</p> <p>\u6839\u636e\u70ed\u529b\u5b66\u7b2c0\u5b9a\u5f8b\uff0c\u53ef\u4ee5\u8ba8\u8bba\u6e29\u5ea6\u7684\u5b58\u5728\u6027\u3002\u8bbeA\u3001B\u3001C\u4e09\u4e2a\u7cfb\u7edf\uff0cA\u548cC\u8fbe\u5230\u70ed\u5e73\u8861;B\u548cC\u8fbe\u5230\u70ed\u5e73\u8861\uff0c\u4e4b\u95f4\u7684\u5173\u7cfb\u7531\u6b64\u63cf\u8ff0\uff1a</p> \\[ f_{AC}(p_A,V_A;p_C,V_C)=0,f_{BC}(p_B,V_B;p_C,V_C)=0 \\] <p>\u7531\u6b64,\u539f\u5219\u4e0a\u53ef\u4ee5\u89e3\u51fa\uff1a</p> \\[ p_C=F_{AC}(p_A,V_A;V_C)=F_{BC}(p_B,V_B;V_C) \\] <p>\u53c8\u6839\u636e\u70ed0\u5b9a\u5f8b\u5f97\u5230A\u548cB\u8fbe\u5230\u70ed\u5e73\u8861\uff0c\u6545\u6709\uff1a</p> \\[ f_{AB}(p_A,V_A;p_B,V_B)=0\\Rightarrow g_A(p_A,V_A)=g_B(p_B,V_B) \\] <p>\u7531\u6b64\u5f97\u5230\u70ed\u5e73\u8861\u4e0b\uff0c\u6570\u503c\u76f8\u540c\u7684\u4e00\u4e2a\u72b6\u6001\u91cf\\(g(p,V)\\)\u5373\u7cfb\u7edf\u7684\u6e29\u5ea6\u3002\u56e0\u6b64\uff0c\u4e0b\u9762\u8981\u89e3\u51b3\u7684\u95ee\u9898\u5c31\u662f\u6e29\u5ea6\u7684\u6d4b\u91cf\u95ee\u9898\uff0c\u5373\u6e29\u6807\u3002</p> <ul> <li>\u7ecf\u9a8c\u6e29\u6807:\u5229\u7528\u67d0\u7269\u8d28\u7684\u5c5e\u6027\uff0c\u4f8b\u5982\u6cb8\u70b9\u548c\u51dd\u56fa\u70b9\u4f5c\u4e3a\u5b9a\u6807\u70b9\u3002\u5e38\u89c1\u7684\u6709\uff1a\u6444\u6c0f\u3001\u534e\u6c0f\u3001\u5217\u6c0f\u3002\uff08\u6d4b\u6e29\u7269\u8d28\u5c5e\u6027\u3001\u5b9a\u6807\u70b9\u3001\u5206\u5ea6\uff09</li> <li>\u7406\u60f3\u6c14\u4f53\u6e29\u6807:\u5229\u7528\u6c14\u4f53\u538b\u5f3a\u8d8b\u4e8e0\u6027\u8d28\u8d8b\u4e8e\u76f8\u540c\u7684\u7279\u6027\uff0c\u5e76\u4ee5\u6c34\u7684\u4e09\u76f8\u70b9(273.16K)\u4f5c\u4e3a\u5b9a\u6807\u70b9\u3002\u5206\u4e3a\u5b9a\u538b\u548c\u5b9a\u4f53\u4e24\u79cd\uff0c\u4e14\u90fd\u8981\u6c42\u538b\u5f3a\u5c3d\u53ef\u80fd\u5c0f\u3002</li> <li>\u70ed\u529b\u5b66\u6e29\u6807:\u57fa\u4e8e\u5361\u8bfa\u5b9a\u7406\uff0c\u8be6\u89c1\u5361\u8bfa\u5b9a\u7406\u76f8\u5173\u5c0f\u8282\u3002</li> </ul> <p>\u2605 \u5bf9\u4e8e\u5206\u6790\u5177\u4f53\u70ed\u529b\u5b66\u95ee\u9898\u4f1a\u6d89\u53ca\u201c\u900f\u70ed\u58c1\u201d\u3001\u201c\u7edd\u70ed\u58c1\u201d\u548c\u201c\u5149\u6ed1\u201d\u7684\u6982\u5ff5\uff0c(1)\u900f\u70ed\u58c1\u5373\u5e73\u8861\u65f6\uff0c\u6e29\u5ea6T\u76f8\u540c\uff1b(2)\u7edd\u70ed\u58c1\u5373\u6ca1\u6709\u70ed\u4ea4\u6362\uff0c\u5927\u591a\u662f\u7edd\u70ed\u8fc7\u7a0b(3)\u5149\u6ed1\u5373\u8981\u6839\u636e\u76f8\u5173\u51e0\u4f55\u9762\u79ef\uff0c\u8003\u8651\u529b\u5b66\u5e73\u8861\u7684\u95ee\u9898\u3002</p>"},{"location":"chapter_01_basic_concepts/02_equation_of_state.html","title":"\u7269\u6001\u65b9\u7a0b","text":""},{"location":"chapter_01_basic_concepts/02_equation_of_state.html#_1","title":"\u7269\u6001\u65b9\u7a0b","text":"<p>\u2605 \u4e3a\u4e86\u63cf\u8ff0\u4e0d\u540c\u7269\u4f53\u7684\u70ed\u529b\u5b66\u53c2\u91cf\u7684\u5173\u7cfb\uff0c\u6709\u5fc5\u8981\u5f15\u5165\u7269\u6001\u65b9\u7a0b\u7684\u6982\u5ff5\u3002\u9996\u5148\u8981\u660e\u786e\u7684\u662f\uff0c\u6839\u636e\u70ed0\u7ed9\u51fa\u70ed\u5e73\u8861\u4e0b\u6e29\u5ea6\u7684\u5b58\u5728\u6027\uff0c\u4ece\u800c\u624d\u80fd\u5229\u7528\u7269\u6001\u65b9\u7a0b\u7ed9\u51fa\u6e29\u5ea6\u4e0e\u72b6\u6001\u53c2\u91cf\u4e4b\u95f4\u7684\u51fd\u6570\u5173\u7cfb\u3002\u56e0\u800c\uff1a\u7269\u6001\u65b9\u7a0b\u63cf\u8ff0\u7684\u662f\u5e73\u8861\u72b6\u6001\u4e0b\u7684\u60c5\u51b5\uff0c\u4e14\u5fc5\u987b\u542b\u6709\u6e29\u5ea6\u3002\u6ce8\u610f\u4e00\u4e2a\u7269\u6001\u65b9\u7a0b\u53ea\u80fd\u63cf\u8ff0\u67d0\u4e00\u5355\u76f8\u7cfb\u3002</p> <p>\u4e00\u822c\u800c\u8a00\uff0c\u7269\u6001\u65b9\u7a0b\u53ef\u4ee5\u901a\u8fc7\u5b9e\u9a8c\u6d4b\u5f97\u6216\u7edf\u8ba1\u7269\u7406\u63a8\u5bfc\u5f97\u5230\u3002\u540e\u4e00\u79cd\u5c06\u5728\u4e0b\u534a\u90e8\u5206\u5c55\u5f00\u3002</p> <p>\u4e3a\u4e86\u5b9e\u9a8c\u4e2d\u65b9\u4fbf\u6d4b\u5b9a\uff0c\u901a\u5e38\u5f15\u5165\u8f85\u52a9\u7684\u7269\u7406\u91cf\uff1a</p> \\[ \\boxed{ \\alpha=\\frac{1}{V}\\left ( \\frac{\\partial V}{\\partial T} \\right )_{p}\\quad\\beta=\\frac{1}{p}\\left ( \\frac{\\partial p}{\\partial T} \\right )_{V}\\quad\\kappa_{T}=-\\frac{1}{V}\\left ( \\frac{\\partial V}{\\partial p} \\right )_{T} } \\] <p>\u4ee5\u4e0a\u4e09\u79cd\u6700\u4e3a\u5e38\u89c1\uff0c\u5206\u522b\u4e3a\u4f53\u80c0\u7cfb\u6570\u3001\u538b\u5f3a\u7cfb\u6570\u3001\u7b49\u6e29\u538b\u7f29\u7cfb\u6570(\u6ce8\u610f\u8d1f\u53f7)\u3002</p> <p>\\(\\beta\\)\u662f\u4e0d\u6613\u6d4b\u91cf\u7684\uff0c\u4f46\u901a\u8fc7\u9690\u51fd\u6570\u5b9a\u7406\u4e0d\u96be\u7531\\(F(p,V,T)=0\\)\u5f97\u5230\uff1a</p> \\[ \\left(\\frac{\\partial V}{\\partial p}\\right)_{T}\\left(\\frac{\\partial p}{\\partial T}\\right)_{V}\\left(\\frac{\\partial T}{\\partial V}\\right)_{p}=-1\\Rightarrow \\boxed{ \\alpha=\\kappa_{T}\\beta p} \\] <p>\u4e3a\u4e86\u89c1\u8bc6\u4ee5\u4e0a\u7cfb\u6570\u7684\u4f5c\u7528\uff0c\u8003\u8651\u5c06\u4f53\u79ef\u5199\u6210\u6e29\u5ea6\u548c\u538b\u5f3a\u7684\u51fd\u6570\\(V=V(T,p)\\):</p> \\[ \\mathrm{d}V=\\left(\\frac{\\partial V}{\\partial T}\\right)_{p}\\mathrm{d}T+\\left(\\frac{\\partial V}{\\partial p}\\right)_{T}\\mathrm{d}p=\\alpha V \\mathrm{d}T-\\kappa_{T}V\\mathrm{d}p \\] <p>\u8fd9\u65f6\u901a\u8fc7\u5b9e\u9a8c\u6d4b\u5f97\\(\\alpha\\text{\u548c}\\kappa_{T}\\)\u4ee3\u5165\u5fae\u5206\u5f0f\uff0c\u518d\u79ef\u5206\u5373\u53ef\u5f97\u5230\u7269\u6001\u65b9\u7a0b\u3002\u82e5\u8fd9\u4e24\u4e2a\u7cfb\u6570\u4e3a\u5e38\u6570\uff0c\u53ef\u4ee5\u76f4\u63a5\u79ef\u5206\u5f97\u5230\uff1a</p> \\[ \\int_{V_0}^{V}\\frac{dV'}{V'}=\\int_{T_0}^{T}\\alpha dT'-\\int_{p_0}^{p}\\kappa_{T} dp' \\Rightarrow V(T,p)=V_0 e^{\\alpha(T-T_0)-\\kappa_{T}(p-p_0)} \\] <p>\u901a\u5e38\u5c06\u4e0a\u5f0f\u8fdb\u884c\u7b49\u4ef7\u65e0\u7a77\u5c0f\u8fd1\u4f3c\uff0c\u4f5c\u4e3a\u7269\u6001\u65b9\u7a0b\u5206\u6790\u95ee\u9898(\u901a\u5e38\u662f\u6db2\u6001\u548c\u56fa\u4f53):</p> \\[ \\boxed{V=V_0[1+\\alpha(T-T_0)-\\kappa_{T}(p-p_0)]} \\] <p>\u4ee5\u4e0a\u7684\u8fd9\u79cd\u5168\u5fae\u5206\u5c55\u5f00\u7684\u65b9\u6cd5\u8d2f\u7a7f\u70ed\u529b\u5b66\u7684\u59cb\u672b\uff0c\u5f88\u591aTips\u9700\u8981\u540e\u7eed\u4e0d\u65ad\u79ef\u7d2f\u3002\u4f8b\u5982\uff0c\u5fae\u5206\u5f0f\u7684\u79ef\u5206\u4e0b\u9650\u901a\u5e38\u4e3a\u5df2\u77e5\u72b6\u6001\u7684\u5b9a\u503c\uff0c\u4e0a\u9650\u4e3a\u53d8\u91cf\u3002</p> <p>\u4e0b\u9762\u4e3e\u51e0\u4e2a\u7269\u6001\u65b9\u7a0b\u7684\u4f8b\u5b50\uff1a</p> <ul> <li>\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\uff1a\\(pV=nRT\\)\u7531\u4e8e\u6b64\u65b9\u7a0b\u6ca1\u6709\u8003\u8651\u5206\u5b50\u4e4b\u95f4\u7684\u5438\u5f15\u529b\u548c\u6392\u65a5\u529b\uff0c\u56e0\u6b64\u53ea\u80fd\u63cf\u8ff0\u6c14\u4f53\uff0c\u4e0d\u80fd\u63cf\u8ff0\u76f8\u53d8\u3002\u4e14\u5728\u6e29\u5ea6\u9ad8\u3001\u538b\u5f3a\u5c0f\u65f6\u4e0e\u5b9e\u9645\u6c14\u4f53\u7b26\u5408\u7684\u66f4\u597d,\u56e0\u800c\u5bf9\u538b\u5f3a\u53d6\u8d8b\u4e8e0\u7684\u6781\u9650\uff0c\u53ef\u5c06\u4efb\u4f55\u6c14\u4f53\u7cfb\u7edf\u5316\u4e3a\u7406\u60f3\u6c14\u4f53\u7684\u5f62\u5f0f\uff0c\u8fdb\u800c\u5f97\u5230\u4e00\u4e9b\u9690\u85cf\u7684\u7ed3\u679c\u3002\u5e38\u89c1\u7684\u53d8\u5f62\u6709\uff1a\\(p=\\frac{N}{V}\\frac{R}{N_A}T=n_{D}k_{B}T\\)\u548c\\(\\rho=\\frac{pM}{RT}\\)\uff0c\u4ee5\u53ca\u538b\u5f3a\u6781\u5c0f\u65f6\u7684\u6781\u9650\uff1a\\(pV\\rightarrow nRT\\).</li> <li>\u8303\u6c0f\u6c14\u4f53\u65b9\u7a0b\uff1a\\((p+\\frac{an^2}{V^2})(V-nb)=nRT\\)\u8003\u8651\u5206\u5b50\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u548c\u5206\u5b50\u5927\u5c0f\uff0c\u5206\u522b\u7528a\u548cb\u5bf9\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u8fdb\u884c\u4fee\u6b63\u5f97\u5230\u7684\u3002\u5176\u8003\u8651\u76f8\u4e92\u4f5c\u7528\u65f6\u7528\u5230\u4e86\u201c\u5e73\u5747\u573a\u8fd1\u4f3c\u201d\uff0c\u4e14\u53ef\u4ee5\u89e3\u91ca\u76f8\u53d8\u548c\u4e34\u754c\u70b9\u7b49\u73b0\u8c61\u3002</li> <li>\u987a\u78c1\u6027\u56fa\u4f53\uff1a\\(M=\\frac{C}{T-\\theta}H\\)\u79f0\u4e3a\u5c45\u91cc-\u5916\u65af\u5b9a\u7406\uff0c\u540c\u6837\u4f7f\u7528\u4e86\u201c\u5e73\u5747\u573a\u8fd1\u4f3c\u201d\u7684\u601d\u60f3\uff0c\u7edf\u8ba1\u7269\u7406\u90e8\u5206\u5c06\u4f1a\u8fdb\u884c\u76f8\u5173\u63a8\u5bfc\u3002</li> </ul> <p>\u2605 \u6839\u636e\u662f\u5426\u4e0e\u7cfb\u7edf\u8d28\u91cf\u6216\u7269\u8d28\u7684\u91cf\u6210\u6b63\u6bd4\uff0c\u53ef\u4ee5\u5c06\u70ed\u529b\u5b66\u91cf\u5206\u4e3a\u5e7f\u5ef6\u91cf\u548c\u5f3a\u5ea6\u91cf\uff0c\u4e14\u901a\u5e38\u5c06\u4e24\u4e2a\u5e7f\u5ef6\u91cf\u76f8\u9664\u5f97\u5230\u4e00\u4e2a\u5f3a\u5ea6\u91cf\u3002</p> <p>\u9700\u8981\u6ce8\u610f\uff0c\u5f53\u7cfb\u7edf\u6ee1\u8db3\u70ed\u529b\u5b66\u6781\u9650:\\( \\mathop{lim}\\limits_{N,V \\to \\infty}\\frac{N}{V}=\\mathrm{finite} \\)\uff0c\u4ee5\u4e0a\u533a\u5206\u624d\u80fd\u6210\u7acb\u3002</p>"},{"location":"chapter_01_basic_concepts/03_quasi_static_work.html","title":"\u51c6\u9759\u6001\u8fc7\u7a0b\u3001\u529f\u7684\u8868\u793a","text":""},{"location":"chapter_01_basic_concepts/03_quasi_static_work.html#_1","title":"\u51c6\u9759\u6001\u8fc7\u7a0b\u3001\u529f\u7684\u8868\u793a","text":"<p>\u2605 \u4e4b\u524d\u63d0\u5230\uff0c\u53ea\u6709\u5e73\u8861\u6001\u624d\u80fd\u753b\u51faP-V\u56fe\u4e0a\u5bf9\u5e94\u7684\u70b9\uff0c\u56e0\u6b64\u5728\u7cfb\u7edf\u53d8\u5316\u8fc7\u7a0b\u4e2d\uff0c\u5fc5\u987b\u65f6\u65f6\u523b\u523b\u4fdd\u6301\u5e73\u8861\u6001\uff0c\u624d\u80fd\u5728P-V\u56fe\u4e0a\u753b\u51fa\u8f68\u8ff9\u3002\u7531\u6b64\u5f15\u5165\u51c6\u9759\u6001\u8fc7\u7a0b\u7684\u6982\u5ff5\uff1a\u7cfb\u7edf\u5728\u53d8\u5316\u8fc7\u7a0b\u4e2d\u7ecf\u5386\u7684\u6bcf\u4e00\u4e2a\u72b6\u6001\u90fd\u662f\u5e73\u8861\u6001\u3002\u5373\u5f1b\u8c6b\u65f6\u95f4&lt;&lt;\u89c2\u6d4b\u65f6\u95f4\u3002</p> <p>\u56e0\u6b64\u4e4b\u540e\u5173\u4e8e\u505a\u529f\u7684\u8ba8\u8bba\u4e2d\uff0c\u5747\u9ed8\u8ba4\u4e3a\u51c6\u9759\u6001\u8fc7\u7a0b\u3002\u5229\u7528\u6c14\u4f53\u7684\u538b\u5f3a\u4e0e\u5916\u754c\u4fdd\u6301\u76f8\u7b49\u7684\u529b\u5b66\u5e73\u8861\u6761\u4ef6\u3002\u7531\u6b64\uff0c\u6839\u636e\u529b\u5b66\u4e2d\u529f\u7684\u5b9a\u4e49\\(\\delta W=Fds\\),\u8003\u8651\u5916\u754c\u5bf9\u6c14\u4f53\u505a\u529f\u4ea7\u751f\u7684\u6b63\u8d1f\u53f7\uff0c\u4ee5\u53ca\u538b\u5f3a\u4e0e\u529b\u4e4b\u95f4\u7684\u5173\u7cfb\u6613\u5f97\uff1a</p> \\[ \\delta W=-pdV,\\quad W=-\\int_{V_A}^{V_B}pdV \\] <p>\u6ce8\u610f\\(\\delta\\)\u8868\u793a\u5fae\u5206\u4f9d\u8d56\u4e8e\u5177\u4f53\u8fc7\u7a0b\uff0c\u5373\u7f3a\u5c11\u7ea6\u675f\u3002\u6b64\u5916\uff0c\u5bf9\u4e8e\u201c\u975e\u51c6\u9759\u6001\u8fc7\u7a0b\u201d\uff0c\u53ea\u8003\u8651\u4e24\u79cd\u5904\u7406\u8d77\u6765\u6bd4\u8f83\u7b80\u5355\u7684\u60c5\u51b5\uff1a(1)\u7b49\u5bb9\u8fc7\u7a0b\uff0c\u7cfb\u7edf\u4f53\u79ef\u4e0d\u53d8\u5316\uff0c\u6545\\(W=0\\)\uff1b(2)\u7b49\u538b\u8fc7\u7a0b\uff0c\u5916\u754c\u538b\u5f3a\u4e0d\u53d8\uff0c\u6545\\(W=-p(V_B-V_A)\\)\u3002</p> <p>\u5bf9\u4e8e\u975e\u4f53\u79ef\u529f\u7684\u4f8b\u5b50\uff1a</p> <ul> <li>\u6db2\u4f53\u8868\u9762\u529f\uff1a\u5bf9\u5bbd\u4e3a\\(l\\)\u7684\u6db2\u4f53\u9762\u62c9\u4f38\\(dx\\)\u7684\u8ddd\u79bb\uff0c\u6839\u636e\u8868\u9762\u5f20\u529b\u7684\u5b9a\u4e49\u5f0f(\u6ce8\u610f\u4e0a\u4e0b\u6709\u4e24\u4e2a\u9762)\u548c\u589e\u52a0\u7684\u9762\u79ef\\(dA=2ldx\\)\u6709\uff1a</li> </ul> \\[ \\delta W=2\\sigma l dx=\\boxed{\\sigma dA} \\] <ul> <li>\u7535\u78c1\u4ecb\u8d28:\u5bf9\u4e8e\u8ddd\u79bb\u4e3a\\(l\\)\u8868\u9762\u7535\u8377\u5bc6\u5ea6\u4e3a\\(\\sigma\\)\u7684\u5e73\u884c\u6781\u677f\u7535\u4ecb\u8d28\uff0c\u6709\\(U=El,dq=Ad\\sigma\\),\u4e14\u7531\u9ad8\u65af\u5b9a\u7406\u5f97\\(D=\\sigma\\)\u6545:</li> </ul> \\[ \\delta W=Udq=ElAd\\sigma=VEd\\sigma=\\boxed{VEdD} \\] <p>(P.S.\u6ce8\u610f\u4e0a\u5f0f\u56e0\u4e3a\\(d(q)=d(\\sigma A)\\)=Ad\\(\\sigma\\)+\\(\\sigma\\)dA\uff0c\u7531\u4e8e\u6781\u677f\u9762\u79ef\u4e0d\u53d8\uff0c\u53d8\u5316\u7684\u662f\u7535\u8377\u5206\u5e03\uff0c\u56e0\u800c\u6709\\(dq=Ad\\sigma\\))</p> <p>\u540c\u7406\uff0c\u5bf9\u4e8e\u78c1\u4ecb\u8d28\u4e5f\u6709\uff1a</p> \\[ \\delta W=\\boxed{VHdB} \\] <p>\u6b64\u5916\u5229\u7528\\(D=\\varepsilon_0 E+P\\)\u548c\\(B=\\mu_0(H+M)\\)\u5f97\u5230\uff1a</p> \\[ \\boxed{\\delta W=Vd(\\frac{\\varepsilon_0 E^2}{2})+VEdP\\qquad \\delta W=Vd(\\frac{\\mu_0 H^2}{2})+\\mu_0 VHdM} \\] <p>\u4e00\u822c\u800c\u8a00\uff0c\u51c6\u9759\u6001\u5916\u754c\u5bf9\u7cfb\u7edf\u505a\u529f\u53ef\u4ee5\u666e\u904d\u5199\u4e3a\uff1a</p> \\[ \\delta W=\\sum_{i}Y_i dy_i \\] <p>\u5176\u4e2d\\(y_i\\)\u662f\u5916\u53c2\u91cf\uff0c\\(Y_i\\)\u662f\u5176\u5bf9\u5e94\u7684\u5e7f\u4e49\u529b</p>"},{"location":"chapter_01_basic_concepts/04_first_law_heat_capacity.html","title":"\u70ed\u529b\u5b66\u7b2c\u4e00\u5b9a\u5f8b\u3001\u70ed\u5bb9","text":""},{"location":"chapter_01_basic_concepts/04_first_law_heat_capacity.html#_1","title":"\u70ed\u529b\u5b66\u7b2c\u4e00\u5b9a\u5f8b\u3001\u70ed\u5bb9","text":"<p>\u2605 \u70ed\u529b\u5b66\u7b2c\u4e00\u5b9a\u5f8b\u7684\u672c\u8d28\u5c31\u662f\u80fd\u91cf\u5b88\u6052\uff0c\u56e0\u6b64\u975e\u5e73\u8861\u6001\u4e5f\u9002\u7528\u3002\u4f46\u8981\u6ce8\u610f\uff0c\u80fd\u5217\u51fa\u65b9\u7a0b\u7684\u90fd\u662f\u51c6\u9759\u6001\u8fc7\u7a0b\uff0c\u6709\u4e9b\u8fc7\u7a0b\u65e0\u6cd5\u7528\u65b9\u7a0b\u63cf\u8ff0\u3002\u901a\u5e38\u5176\u7b49\u5f0f\u5de6\u8fb9\u4e3a\u72b6\u6001\u91cf\uff0c\u53f3\u8fb9\u4e3a\u8fc7\u7a0b\u91cf\u3002\u8868\u793a\u7ecf\u5386\u67d0\u4e2a\u8fc7\u7a0b\uff0c\u5176\u80fd\u91cf\u5e76\u4e0d\u4f1a\u6d88\u5931\uff0c\u800c\u662f\u5f62\u5f0f\u4e0a\u8fdb\u884c\u4e86\u8f6c\u5316\u3002\u5bf9\u4e8e\u5c01\u95ed\u7cfb\u7edf\uff1a</p> \\[ dU=\\delta Q+\\delta W \\] <p>\u4e0a\u5f0f\u8868\u793a\u7cfb\u7edf\u7684\u5185\u80fd\u589e\u91cf\u4e3a\u5916\u754c\u7684\u4f20\u70ed\u548c\u5916\u754c\u5bf9\u7cfb\u7edf\u505a\u7684\u529f\u3002(\u5f53\u7136\uff0c\u4e4b\u540e\u8003\u8651\u7c92\u5b50\u6570\u4ea4\u6362\u7b49\u8fd8\u4f1a\u52a0\u5165\u65b0\u7684\u9879)\u4e14\u5176\u4e2d\u529f\u3001\u70ed\u91cf\u3001\u5185\u80fd\u53ef\u4ee5\u8fd9\u6837\u7406\u89e3\uff1a</p> <ul> <li>\u529f\uff1a\u901a\u8fc7\u5916\u754c\u5b8f\u89c2\u8fd0\u52a8\u5c06\u80fd\u91cf\u4f20\u7ed9\u7cfb\u7edf\u5206\u5b50\u70ed\u8fd0\u52a8\u548c\u5206\u5b50\u95f4\u52bf\u80fd\u3002</li> <li>\u70ed\u91cf\uff1a\u901a\u8fc7\u5916\u754c\u5206\u5b50\u70ed\u8fd0\u52a8\u5c06\u80fd\u91cf\u4f20\u7ed9\u7cfb\u7edf\u5206\u5b50\u70ed\u8fd0\u52a8\u548c\u5206\u5b50\u95f4\u52bf\u80fd\u3002\u5f53\\(\\delta Q=0\\)\u5373\u7edd\u70ed\u8fc7\u7a0b\u3002</li> <li>\u5185\u80fd\uff1a\u662f\u6001\u51fd\u6570\uff0c\u8868\u793a\u7cfb\u7edf\u5fae\u89c2\u7c92\u5b50\u5404\u79cd\u80fd\u91cf\u7684\u603b\u548c\u3002\u5728\u70ed\u529b\u5b66\u6781\u9650\u4e0b\uff0c\u4e3a\u5e7f\u5ef6\u91cf\u3002</li> </ul> <p>\u2605 \u4e3a\u4e86\u63cf\u8ff0\u7cfb\u7edf\u5347\u9ad81K\u6240\u5438\u6536\u7684\u80fd\u91cf\uff0c\u53ef\u4ee5\u5b9a\u4e49\u70ed\u5bb9\uff1a</p> \\[ C=\\frac{\\delta Q}{d T} \\] <p>\u6ce8\u610f\uff0c\u6b64\u65f6\u70ed\u5bb9\u8fd8\u662f\u4e0e\u8fc7\u7a0b\u76f8\u5173\u7684\u5e7f\u5ef6\u91cf\u3002\u4ee5\u4e0b\u8fdb\u884c\u201c\u53bb\u4e2a\u6027\u5316\u201d\u7684\u64cd\u4f5c\uff1a</p> <ul> <li>\u6bd4\u70ed\u5bb9\uff1a\\(c=\\frac{C}{m}\\)\u5373\u5355\u4f4d\u8d28\u91cf\u5355\u4f4d\u6e29\u5ea6\u4e0b\u50a8\u5b58\u7684\u70ed\u91cf\u3002</li> <li>\u6469\u5c14\u70ed\u5bb9\uff1a\\(C_m=\\frac{C}{n}\\)\u3002\u5373\u5355\u4f4d\u6469\u5c14\u5355\u4f4d\u6e29\u5ea6\u4e0b\u50a8\u5b58\u7684\u70ed\u91cf\uff0c\u5316\u5b66\u4e2d\u5e38\u7528\u3002</li> <li>\u5b9a\u4f53\u70ed\u5bb9\uff1a\\(C_V=\\left(\\frac{\\delta Q}{d T}\\right)_{V}=\\left(\\frac{\\partial U}{\\partial T}\\right)_{V}\\) \u6839\u636e\u70ed\u4e00\uff0c\u5f53\u7cfb\u7edf\u7684\u4f53\u79ef\u4e0d\u53d8\uff0c\u5c31\u4e0d\u4f1a\u901a\u8fc7\u505a\u4f53\u79ef\u529f\u7684\u65b9\u5f0f\u589e\u52a0\u5185\u80fd\uff0c\u56e0\u6b64\u5b9a\u4f53\u70ed\u5bb9\u5e38\u5e38\u4e0e\u5185\u80fd\u8054\u7cfb\u8d77\u6765\u3002</li> <li>\u5b9a\u538b\u70ed\u5bb9\uff1a\\(C_P=\\left(\\frac{\\delta Q}{d T}\\right)_{p}=\\left(\\frac{\\partial H}{\\partial T}\\right)_{p}\\)\u5176\u4e2dH\u5b9a\u4e49\u4e3a\\(H=U+pV\\)\u79f0\u4e3a\u7113\u3002\u5728\u7b49\u538b\u7684\u4f53\u7cfb\u4e2d\uff0c\u7ecf\u5e38\u4f7f\u7528\uff0c\u4e5f\u79f0\u4e3a\u6052\u538b\u53cd\u5e94\u70ed\u3002</li> </ul> <p>\u901a\u8fc7\u201c\u53bb\u4e2a\u6027\u5316\u201d\u4ea7\u751f\u4e86\u4ee5\u4e0a\u7684\u5f3a\u5ea6\u91cf\u610f\u4e49\u4e0b\u7684\u70ed\u5bb9\uff0c\u4e14\u51fa\u73b0\u7684\u6700\u591a\u7684\u5c31\u662f\u5b9a\u4f53\u70ed\u5bb9\\(C_V\\)\u548c\u5b9a\u538b\u70ed\u5bb9\\(C_p\\)\u4e86\uff0c\u800c\u4e14\u5b83\u4eec\u4e4b\u95f4\u7684\u5173\u7cfb\u4e5f\u975e\u5e38\u591a\u3002\u901a\u5e38\u5b9a\u4e49\u6bd4\u70ed\u5bb9\u6bd4\\(\\gamma=\\frac{C_p}{C_V}\\)\u6765\u7b80\u5316\u8868\u8fbe\u3002</p> <p>\u6b64\u5916\uff0c\u5b9a\u538b\u70ed\u5bb9\u548c\u5b9a\u4f53\u70ed\u5bb9\u7684\u5dee\u503c\u53ef\u4ee5\u901a\u8fc7\u5b9a\u4e49\u5f0f\u5bfc\u51fa\uff1a</p> \\[ C=\\frac{\\delta Q}{d T}=\\frac{dU -\\delta W  }{d T}=\\frac{\\left(\\frac{\\partial U}{\\partial T}\\right)_{V}dT+\\left(\\frac{\\partial U}{\\partial V}\\right)_{T}dV}{dT}-\\frac{-pdV}{dT}=\\left(\\frac{\\partial U}{\\partial T}\\right)_{V}+\\frac{dV}{dT}\\left[\\left(\\frac{\\partial U}{\\partial V}\\right)_{T}+p\\right] \\] <p>\u518d\u4e24\u8fb9\u56fa\u5b9a\u538b\u5f3ap\u53ef\u5f97\uff1a</p> \\[ C_p=\\left(\\frac{\\partial U}{\\partial T}\\right)_{V}+\\left(\\frac{\\partial V}{\\partial T}\\right)_{p} \\left[\\left(\\frac{\\partial U}{\\partial V}\\right)_{T}+p\\right] \\] <p>\u6839\u636e\u7b49\u4f53\u70ed\u5bb9\u7684\u6027\u8d28\uff0c\u5f97\u5230\uff1a</p> \\[ C_p-C_V=\\left(\\frac{\\partial V}{\\partial T}\\right)_{p} \\left[\\left(\\frac{\\partial U}{\\partial V}\\right)_{T}+p\\right] \\] <p>\u90a3\u4e48\u4e0a\u5f0f\u4e2d\u7684\\(\\left(\\frac{\\partial U}{\\partial V}\\right)_T\\)\u53c8\u8be5\u5982\u4f55\u8ba1\u7b97\u5462\uff1f\u6839\u636e\u6587\u732e\uff1a\u5218\u6c38\u519b.\u8303\u5fb7\u74e6\u5c14\u65af\u6c14\u4f53\u7684\u5185\u80fd\u53ca\u6469\u5c14\u70ed\u5bb9[J].\u4f0a\u7281\u6559\u80b2\u5b66\u9662\u5b66 \u62a5.2002,15(2):67-68 \u6709\uff1a</p> \\[ \\left(\\frac{\\partial U}{\\partial V}\\right)_T=T\\left(\\frac{\\partial p}{\\partial T}\\right)_V-p\\Rightarrow \\boxed{C_p-C_V=T\\left(\\frac{\\partial V}{\\partial T}\\right)_{p}\\left(\\frac{\\partial p}{\\partial T}\\right)_V} \\] <p>\u4e4b\u540e\uff0c\u4e5f\u4f1a\u7528\u9ea6\u6c0f\u5173\u7cfb\u63a8\u51fa\u6b64\u5f0f\u3002</p>"},{"location":"chapter_01_basic_concepts/05_ideal_gas_processes.html","title":"\u7406\u60f3\u6c14\u4f53\u70ed\u5b66\u8fc7\u7a0b\u7684\u76f8\u5173\u8ba1\u7b97","text":""},{"location":"chapter_01_basic_concepts/05_ideal_gas_processes.html#_1","title":"\u7406\u60f3\u6c14\u4f53\u70ed\u5b66\u8fc7\u7a0b\u7684\u76f8\u5173\u8ba1\u7b97","text":"<p>\u2605 1845\u5e74\u7126\u8033\u901a\u8fc7(\u7edd\u70ed)\u81ea\u7531\u81a8\u80c0\u5b9e\u9a8c(\u7531\\(\\delta W=\\delta Q=0\\)\u5bfc\u51fa\\(dU=0\\))\u6d4b\u5f97\u7126\u8033\u7cfb\u6570\\(\\left(\\frac{\\partial T}{\\partial V}\\right)_U=0\\)\uff0c\u4ece\u800c\u6839\u636e\\(U(T,V)\\)\u7684\u504f\u5bfc\u5173\u7cfb\u63a8\u51fa\u6c14\u4f53\u7684\u5185\u80fd\u53ea\u662f\u6e29\u5ea6\u7684\u51fd\u6570\uff0c\u4e0e\u4f53\u79ef\u65e0\u5173\uff0c\u79f0\u4e3a\u7126\u8033\u5b9a\u5f8b\u3002(P.S.\u6ce8\u610f\u8fd9\u91cc\u7684\u6c14\u4f53\u662f\u4e00\u56e2\u7c92\u5b50\u6570\u56fa\u5b9a\u7684\u6c14\u4f53)\u7136\u800c\uff0c1852\u5e74\u901a\u8fc7\u8282\u6d41\u8fc7\u7a0b\u7684\u5b9e\u9a8c\u53d1\u73b0\u5185\u80fd\u8fd8\u548c\u4f53\u79ef\u6709\u5173\u3002\u7a76\u5176\u539f\u56e0\uff0c\u8fd9\u79cd\u4e0e\u4f53\u79ef\u76f8\u5173\u7684\u5185\u80fd\u6765\u6e90\u4e8e\u5206\u5b50\u95f4\u7684\u4f5c\u7528\u529b\uff0c\u56e0\u6b64\u4f5c\u4e3a\u5ffd\u89c6\u4f5c\u7528\u529b\u548c\u5206\u5b50\u5927\u5c0f\u7684\u7ecf\u5178\u7406\u60f3\u6c14\u4f53\uff0c\u5176\u5185\u80fd\u7684\u786e\u53ea\u662f\u6e29\u5ea6\u7684\u51fd\u6570\u3002</p> <p>\u2605 \u5bf9\u4e8e\u7406\u60f3\u6c14\u4f53\uff0c\u7acb\u9a6c\u5f97\u5230\u5c5e\u4e8e\u7406\u60f3\u6c14\u4f53\u7684\u5b9a\u4f53\u548c\u5b9a\u538b\u70ed\u5bb9\u5b9a\u4e49\u5f0f\uff0c\u5e76\u6839\u636e\u5185\u80fd\u53ea\u662f\u6e29\u5ea6\u7684\u51fd\u6570\u548c\u4e4b\u524d\u63a8\u5bfc\u7684\\(C_p\\)\u548c\\(C_V\\)\u7684\u5dee\u503c\uff1a</p> \\[ C_V=\\left(\\frac{\\partial U}{\\partial T}\\right)_{V}=\\frac{dU}{dT}\\Rightarrow \\boxed{dU=C_VdT}\\quad C_p=\\left(\\frac{\\partial H}{\\partial T}\\right)_{p}=\\frac{dH}{dT}\\Rightarrow \\boxed{dH=C_pdT} \\] \\[ C_p-C_V=\\left(\\frac{\\partial V}{\\partial T}\\right)_{p} \\left[\\left(\\frac{\\partial U}{\\partial V}\\right)_{T}+p\\right]=\\left(\\frac{\\partial V}{\\partial T}\\right)_{p}p=\\boxed{nR} \\] <p>\u4e0a\u5f0f\uff0c\u518d\u6839\u636e\\(\\gamma=\\frac{C_p}{C_V}\\)\u7684\u5b9a\u4e49\u5f97\u5230(\u8bc1\u660e\u9898\u5e38\u4f1a\u4f7f\u7528)\uff1a</p> \\[ \\boxed{C_V=\\frac{nR}{\\gamma-1}\\quad C_p=\\gamma\\frac{nR}{\\gamma-1}} \\] <p>\u6b64\u5916\uff0c\u53ef\u4ee5\u7acb\u9a6c\u5bfc\u51fa\u5bf9\u4e8e\u7406\u60f3\u6c14\u4f53\u4efb\u610f\u8fc7\u7a0b\u7684\u70ed\u5bb9\u8ba1\u7b97\u5f0f\u4e3a\uff1a</p> \\[ C=\\left(\\frac{\\partial U}{\\partial T}\\right)_{V}+\\frac{dV}{dT}\\left[\\left(\\frac{\\partial U}{\\partial V}\\right)_{T}+p\\right]=C_V+p\\frac{dV}{dT} \\] <p>\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u4e3a\\(pV=nRT\\),\u4e3a\u4e86\u4e0e\u540e\u7eed\u591a\u65b9\u8fc7\u7a0b\u7684\\(n\\)\u6307\u6570\u8fdb\u884c\u533a\u5206\uff0c\u8fd9\u91cc\u6682\u65f6\u5199\u4e3a\\(pV=\\nu RT\\) .\u6b64\u5916\uff0c\u4ece\u65b9\u7a0b\u4e2d\u7684\u53d8\u91cf\u53ef\u4ee5\u770b\u51fa\uff0c\u6700\u7b80\u5355\u7684\u4e09\u4e2a\u8fc7\u7a0b\uff1a\u7b49\u538b\u8fc7\u7a0b\u3001\u7b49\u4f53\u8fc7\u7a0b\u3001\u7b49\u6e29\u8fc7\u7a0b\u3002\u6b64\u5916\u6839\u636e\u70ed\u4e00\u53c8\u53ef\u4ee5\u6709\u7edd\u70ed\u8fc7\u7a0b\u3002\u4e8b\u5b9e\u4e0a\uff0c\u66f4\u4e00\u822c\u5730\u6765\u8bf4\uff0c\u8fd9\u4e9b\u5747\u4e3a\u591a\u65b9\u8fc7\u7a0b\u7684\u7279\u6b8a\u60c5\u51b5\uff0c\u4e0b\u9762\u9010\u4e2a\u5206\u6790\u3002</p> <p>\u9996\u5148\u8ba8\u8bba\u5916\u754c\u5bf9\u7cfb\u7edf\u505a\u529f\uff1a</p> \\[ \\begin{aligned} (1)\\text{\u7b49\u538b\u8fc7\u7a0b} \\quad&amp; \\Delta W  =  -\\int_{V_1}^{V_2}pdV  =  -p(V_2-V_1)\\\\ (2)\\text{\u7b49\u4f53\u8fc7\u7a0b} \\quad&amp; \\Delta W  = -\\int_{V_1}^{V_2}pdV =  0\\\\ (3)\\text{\u7b49\u6e29\u8fc7\u7a0b} \\quad&amp;\\Delta W  =  -\\int_{V_1}^{V_2}pdV  =  -\\int_{V_1}^{V_2}\\frac{\\nu RT}{V}dV  = \\boxed{ \\nu RTln(\\frac{V_1}{V_2})  =  \\nu RTln(\\frac{p_2}{p_1})}  \\\\ (4)\\text{\u7edd\u70ed\u8fc7\u7a0b} \\quad&amp; \\Delta W  =  -\\int_{V_1}^{V_2}pdV=?(\\text{\u9700\u8981\u901a\u8fc7\u70ed\u4e00\u5fae\u5206\u5f0f\u548c\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u5bfc\u51fa}) \\end{aligned} \\] <p>\u4e0b\u9762\u6211\u4eec\u4f7f\u7528\u4e0a\u9762\u7684\u7ed3\u8bba\uff0c\u5229\u7528p-V\u56fe\u8fdb\u884c\u8be6\u7ec6\u8ba8\u8bba\uff1a(Tip\uff1a\u8fd9\u91cc\u8981\u6ce8\u610f\u533a\u5206\u4e09\u7c7b\u65b9\u7a0b\uff1a\u70ed\u4e00\u5fae\u5206\u5f0f\u3001\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u3001\u8fc7\u7a0b\u7ea6\u675f\u65b9\u7a0b)</p> <p>(1)\u7b49\u538b\u8fc7\u7a0b\uff1a\u6839\u636e\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u5f97\u5230\u8fc7\u7a0b\u7ea6\u675f\u65b9\u7a0b\uff1a\\(\\boxed{p=\\mathrm{Const.}}\\) \u7531\u70ed\u4e00\u5f97\u5230\uff1a</p> \\[ dU=\\delta Q+\\delta W\\Rightarrow dQ=C_V dT-dW \\] <p>\u4ece\u800c\u5f97\u5230\uff1a</p> \\[ \\Delta U=C_V(T_2-T_1) \\] \\[ \\Delta W=-p(V_2-V_1) \\] \\[ \\Delta Q=\\Delta U-\\Delta W=(C_V+\\nu R)(T_2-T_1)=C_P(T_2-T_1)=\\Delta H \\] <p>\u25a0 \u6ce8\u610f\uff0c\u70ed\u5bb9\u90fd\u662f\u7cfb\u7edf\u7684\u5185\u7980\u5c5e\u6027\uff0c\u901a\u5e38\u4e3a\u5df2\u77e5\u91cf\u3002\u6b64\u5916\uff0c\u8fd9\u91cc\u7528\u7b49\u4f53\u70ed\u5bb9\u5bf9\u7406\u60f3\u6c14\u4f53\u5185\u80fd\u53d8\u5316\u91cf\u7684\u4ee3\u6362\u662f\u6700\u5e38\u89c1\u7684\u64cd\u4f5c\uff0c\u9700\u8981\u4e60\u60ef\u548c\u7406\u89e3\u3002\u5177\u4f53\u539f\u56e0\u53ef\u4ee5\u901a\u8fc7\u8303\u6c0f\u6c14\u4f53\u7684\\(U(T,V)\\)\u5fae\u5206\u5f0f\u89e6\u7c7b\u65c1\u901a\uff1a</p> \\[ \\left(\\frac{\\partial U}{\\partial V}\\right)_T=T\\left(\\frac{\\partial p}{\\partial T}\\right)_V-p=\\frac{a\\nu^2}{V^2}\\Rightarrow dU=C_VdT+\\frac{a\\nu^2}{V^2}dV \\] <p>\u800c\u7406\u60f3\u6c14\u4f53\\(\\left(\\frac{\\partial U}{\\partial V}\\right)_T\\)\u6c42\u51fa\u6765\u4e3a0\uff0c\u56e0\u800c\u53ef\u4ee5\u76f4\u63a5\u4ee3\u6362\u3002</p> <p>(2)\u7b49\u4f53\u8fc7\u7a0b\uff1a\u6839\u636e\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u5f97\u5230\u8fc7\u7a0b\u7ea6\u675f\u65b9\u7a0b\uff1a\\(\\boxed{V=\\mathrm{Const.}}\\)\u7531\u70ed\u4e00\u5f97\u5230\uff1a</p> \\[ dU=\\delta Q+\\delta W\\Rightarrow dQ=C_V dT \\] <p>\u4ece\u800c\u5f97\u5230\uff1a</p> \\[ \\Delta U=C_V(T_2-T_1) \\] \\[ \\Delta W=0 \\] \\[ \\Delta Q=\\Delta U=C_V(T_2-T_1) \\] <p>(3)\u7b49\u6e29\u8fc7\u7a0b\uff1a\u6839\u636e\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u5f97\u5230\u8fc7\u7a0b\u7ea6\u675f\u65b9\u7a0b\uff1a\\(\\boxed{pV=\\mathrm{Const.}}\\) \u7531\u70ed\u4e00\u5f97\u5230\uff1a</p> \\[ dU=\\delta Q+\\delta W\\Rightarrow dQ=C_V dT+\\frac{\\nu RT}{V}dV \\] <p>\u4ece\u800c\u5f97\u5230\uff1a</p> \\[ \\Delta U=0 \\] \\[ \\Delta W=\\nu RTln(\\frac{V_1}{V_2}) \\] \\[ \\Delta Q=-\\Delta W=\\nu RTln(\\frac{V_2}{V_1}) \\] <p>\u6ce8\u610f\u5185\u80fd\u4e0d\u53d8\u53ea\u5bf9\u7406\u60f3\u6c14\u4f53\u6210\u7acb\uff0c\u7531\u6b64\u4e5f\u53ef\u5bfc\u51fa\u5176\u81ea\u7531\u81a8\u80c0\u6e29\u5ea6\u4e0d\u53d8</p> <p>(4)\u7edd\u70ed\u8fc7\u7a0b\uff1a\u4e0e\u4e4b\u524d\u4e0d\u540c\uff0c\u7531\u4e8e\u8fc7\u7a0b\u7ea6\u675f\u6d89\u53ca\u70ed\u91cf\\(Q\\)\uff0c\u4f46\u5e76\u4e0d\u5728\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u4e2d\uff0c\u56e0\u6b64\u9700\u8981\u501f\u52a9\u70ed\u4e00\u6765\u63a8\u51fa\u5fae\u5206\u5f0f\uff0c\u4ece\u800c\u5f97\u5230\u8fc7\u7a0b\u7ea6\u675f\u65b9\u7a0b\u3002</p> \\[ \\delta Q=0\\Rightarrow dU=\\delta W\\Rightarrow C_VdT=-\\frac{\\nu R T}{V}dV \\] \\[ \\int\\frac{C_V dT}{T}=-\\int\\frac{\\nu RdV}{V}\\Rightarrow TV^{\\gamma-1}=Const.\\quad or\\quad\\boxed{ pV^\\gamma=Const.} \\] <p>\u73b0\u5728\u53ef\u4ee5\u63a8\u5bfc\u7edd\u70ed\u8fc7\u7a0b\u5916\u754c\u5bf9\u7cfb\u7edf\u505a\u529f\u4e86\uff1a</p> \\[ \\Delta W=-\\int_{V_1}^{V_2}pdV=-\\int_{V_1}^{V_2}\\frac{Const.}{V^\\gamma}dV=Const.\\frac{V^{1-\\gamma}_2-V^{1-\\gamma}_1}{\\gamma-1} \\] \\[ =\\frac{Const.V^{1-\\gamma}_2-Const.V^{1-\\gamma}_1}{\\gamma-1}=\\frac{p_2V_2^\\gamma V^{1-\\gamma}_2-p_1V_1^\\gamma V^{1-\\gamma}_1}{\\gamma-1}=\\frac{p_2V_2-p_1V_1}{\\gamma-1}=\\frac{\\nu R(T_2-T_1)}{\\gamma-1} \\] <p>\u7efc\u4e0a\u6709\uff1a</p> \\[ \\Delta U=\\frac{\\nu R(T_2-T_1)}{\\gamma-1}=C_V(T_2-T_1) \\] \\[ \\Delta W=\\frac{p_2V_2-p_1V_1}{\\gamma-1}=\\frac{\\nu R(T_2-T_1)}{\\gamma-1} \\] \\[ \\Delta Q=0 \\] <p>Tip:\u6c42\u72b6\u6001\u53c2\u91cfp,V,T\u65f6\uff0c\u5e38\u501f\u52a9\u7269\u6001\u65b9\u7a0b\u548c\u8fc7\u7a0b\u7ea6\u675f\uff0c\u800c\u6c42W,Q,U\u5219\u5229\u7528\u70ed\u4e00\u7684\u5fae\u5206\u5f0f\u79ef\u5206\u5f97\u5230\u3002</p> <p>\u4ee5\u4e0a\u7684\u70ed\u529b\u5b66\u8fc7\u7a0b\u7684\u7ea6\u675f\u5747\u53ef\u8868\u8fbe\u4e3a\\(\\boxed{pV^n=Const.}\\),\u5176\u4e2d\\(n=0\\)\u4e3a\u7b49\u538b\u8fc7\u7a0b\u3001\\(n=\\infty\\)\u4e3a\u7b49\u4f53\u8fc7\u7a0b\u3001\\(n=1\\)\u4e3a\u7b49\u6e29\u8fc7\u7a0b\u3001\\(n=\\gamma\\)\u4e3a\u7edd\u70ed\u8fc7\u7a0b\u3002</p> <p>\u4ec5\u6839\u636e\u6b64\u7ea6\u675f\u65b9\u7a0b\uff0c\u6613\u5f97(\u8ba1\u7b97\u8fc7\u7a0b\u548c\u7edd\u70ed\u8fc7\u7a0b\u76f8\u4f3c\uff0c\u6545\u7701\u7565)\uff1a</p> \\[ \\Delta U=C_V(T_2-T_1) \\] \\[ \\Delta W=\\frac{p_2V_2-p_1V_1}{n-1}=\\frac{\\nu R(T_2-T_1)}{n-1} \\] \\[ \\Delta Q=\\Delta U-\\Delta W=\\left(C_V-\\frac{\\nu R}{n-1}\\right)(T_2-T_1) \\] <p>\u7531\u4e0a\u5f0f\u4e2d\\(\\Delta Q=C_n \\Delta T\\)\u5f97\u5230\u591a\u65b9\u8fc7\u7a0b\u7684\u70ed\u5bb9\uff1a</p> \\[ \\boxed{C_n=C_V-\\frac{\\nu R}{n-1}=\\frac{n-\\gamma}{n-1}C_V} \\] <p>\u5f53\u7136\u4e5f\u4e0d\u7528\u8fd9\u4e48\u9ebb\u70e6\uff0c\u4e0a\u5f0f\u4e5f\u53ef\u4ece\u70ed\u4e00\u548c\u591a\u65b9\u8fc7\u7a0b\u7ea6\u675f\u65b9\u7a0b\u76f4\u63a5\u63a8\u5f97\u3002</p> <p>\u2605 \u6700\u540e\u6765\u7814\u7a76\u4e00\u4e0bp-V\u56fe\u7684\u5173\u7cfb\uff1a\u60f3\u8c61\u8fd9\u6837\u4e00\u4e2a\u8fc7\u7a0b\uff0c\u65b9\u7a0b\\(pV^n=Const.\\)\u4e2d\u7684n\u4ece0\u5f00\u59cb\u589e\u957f\u5230\u65e0\u7a77\u5927\uff0c\u5373\u4ece\u7b49\u538b\u8fc7\u7a0b\u9010\u6e10\u53d8\u4e3a\u7b49\u6e29\u8fc7\u7a0b\uff0c\u518d\u5230\u7edd\u70ed\u8fc7\u7a0b\uff0c\u6700\u540e\u6210\u4e3a\u7b49\u4f53\u8fc7\u7a0b\u3002\u66f2\u7ebf\u7531\u6c34\u5e73\u9010\u6e10\u53d8\u9661\u5ced\u3002\u4e0b\u56fe\u5c55\u793a\u4e86\uff0c\u5e38\u89c1\u7684\u56db\u79cd\u8fc7\u7a0b\u3002</p> <p></p>"},{"location":"chapter_01_basic_concepts/06_carnot_cycle.html","title":"\u5361\u8bfa\u5faa\u73af\u4ee5\u53ca\u6548\u7387","text":""},{"location":"chapter_01_basic_concepts/06_carnot_cycle.html#_1","title":"\u5361\u8bfa\u5faa\u73af\u4ee5\u53ca\u6548\u7387","text":"<p>\u2605 \u9996\u5148\u6765\u8ba8\u8bba\u5faa\u73af\u7684\u6982\u5ff5:\u7cfb\u7edf\u7ecf\u5386\u4e00\u7cfb\u5217\u53d8\u5316\uff0c\u53c8\u56de\u5230\u539f\u6765\u7684\u72b6\u6001\u79f0\u4e3a\u5faa\u73af\u3002\u5f53\u4e3a\u51c6\u9759\u6001\u8fc7\u7a0b\u65f6\uff0c\u53ef\u4ee5\u5728p-V\u56fe\u4e0a\u753b\u51fa\u5c01\u95ed\u7684\u66f2\u7ebf\u3002</p> <p>\u6ce8\u610f\uff0c\u5faa\u73af\u8fc7\u7a0b\u66f2\u7ebf\u7684\u65b9\u5411\u6027\u3002\u6839\u636e\u7cfb\u7edf\u5bf9\u5916\u505a\u529f\u7684\u5b9a\u4e49\u5f0f\uff1a</p> \\[ W_{\\text{\u7cfb\u7edf\u5bf9\u5916}}=\\oint pdV \\] <p>\u53ef\u4ee5\u770b\u51fa\u51e0\u4f55\u610f\u4e49\u4e3ap-V\u56fe\u5c01\u95ed\u66f2\u7ebf\u5305\u56f4\u7684\u9762\u79ef(\u7531\u4e8e\\(\\Delta U=0\\),\u6545\u9762\u79ef\u4e5f\u4e3a\u7cfb\u7edf\u7684\u5438\u70ed\u91cf)\uff0c\u4f46\u8981\u6ce8\u610f\u79ef\u5206\u7684\u65b9\u5411\u6027\u5bfc\u81f4\u9762\u79ef\u6709\u6b63\u6709\u8d1f\uff0c\u5373\u7cfb\u7edf\u5bf9\u5916\u505a\u529f\u7684\u6b63\u8d1f\u3002\u56e0\u800c\u901a\u5e38\u5c06\u5faa\u73af\u5206\u4e3a\u4e24\u7c7b\uff1a\u6b63\u5faa\u73af\u548c\u9006\u5faa\u73af\u3002</p> <p>\u5982\u56fe\u6240\u793a\uff0c\u7531\u4e8e\u5185\u80fd\u662f\u72b6\u6001\u51fd\u6570\uff0c\u7ecf\u5386\u4e00\u4e2a\u5faa\u73af\u4e0d\u6539\u53d8\uff0c\u56e0\u800c\uff1a(1)\u6b63\u5faa\u73af:\u7cfb\u7edf\u4ece\u9ad8\u6e29\u70ed\u6e90\u5438\u6536\u70ed\u91cf\\(Q_1\\)\uff0c\u5e76\u4e14\u5bf9\u5916\u505a\u529f\\(W\\)\uff0c\u4e5f\u79f0\u4e3a\u70ed\u673a\uff1b(2)\u9006\u5faa\u73af:\u7cfb\u7edf\u5438\u6536\u4f4e\u6e29\u70ed\u6e90\u7684\u70ed\u91cf\\(Q_2\\)\uff0c\u5e76\u4e14\u9760\u5916\u754c\u5bf9\u5176\u505a\u529f\\(W\\)\u5411\u9ad8\u6e29\u70ed\u6e90\u653e\u51fa\u70ed\u91cf\uff0c\u79f0\u4e3a\u5236\u51b7\u673a\u3002\u4e14\u5747\u6ee1\u8db3\uff1a\\(Q_1=W+Q_2\\).</p> <p></p> <p>\u6839\u636e\u4ee5\u4e0a\u673a\u7406\uff0c\u4ece\u201c\u4ed8\u51fa\u201d\u548c\u201c\u56de\u62a5\u201d\u7684\u89d2\u5ea6\uff0c\u53ef\u4ee5\u5b9a\u4e49\u5faa\u73af\u6548\u7387\uff1a</p> \\[ \\text{\u70ed\u673a\u6548\u7387:}\\eta =\\frac{W}{Q_1}\\qquad\\text{\u5236\u51b7\u7cfb\u6570:}\\eta=\\frac{Q_2}{W} \\] <p>\u6ce8\u610f\u5bf9\u4e8e\u70ed\u673a\u548c\u5236\u51b7\u673a\uff0c\\(Q_1\\)\u548c\\(Q_2\\)\u4ee3\u8868\u7684\u610f\u601d\u7565\u6709\u4e0d\u540c\uff0c\u4f46\u90fd\u662f\u5206\u522b\u4e0e\u9ad8\u6e29\u548c\u4f4e\u6e29\u70ed\u6e90\u7684\u70ed\u91cf\u4ea4\u6362\u95ee\u9898\u3002\u6700\u5178\u578b\u7684\u4f8b\u5b50\u662f\u7406\u60f3\u6c14\u4f53\u7684\u5361\u8bfa\u5faa\u73af\uff1a</p> <p>\u2605 \u5361\u8bfa\u5faa\u73af\u7531\u4e24\u4e2a\u7b49\u6e29\u8fc7\u7a0b\u548c\u4e24\u4e2a\u7edd\u70ed\u8fc7\u7a0b\u7ec4\u6210\uff0c\u56e0\u800c\u67094\u4e2a\u8f6c\u6298\u70b9\u3002\u6839\u636ep-V\u56fe\u4e0d\u96be\u5206\u51fa\u54ea\u4e2a\u662f\u7b49\u6e29\u54ea\u4e2a\u662f\u7edd\u70ed\u8fc7\u7a0b\uff0c\u4e14\u5bf9\u5e94\u7684\u70ed\u91cf-\u80fd\u91cf\u8f6c\u5316\u56fe\u53ef\u4ee5\u5f97\u5230\\(\\boxed{Q_1=Q_2+W}\\)\u3002\u8be6\u7ec6\u7684\u6548\u7387\u8ba1\u7b97\u5982\u4e0b(\u9ed8\u8ba4\\(T_1&gt;T_2\\))\uff1a</p> <p>(1)\u5361\u8bfa\u70ed\u673ap-V\u56fe\u5982\u4e0b\uff0c\u7ecf\u53861\\(\\sim\\)4\u8fc7\u7a0b\u4f5c\u4e3a\u4e00\u4e2a\u5faa\u73af\u3002</p> <p></p> <p>\u9996\u5148\u8003\u8651\u7b49\u6e29\u8fc7\u7a0b1\\(\\sim\\)2\u548c3\\(\\sim\\)4\uff0c\u6c42\u51fa\u7cfb\u7edf\u5438\u6536\u548c\u653e\u51fa\u7684\u70ed\u91cf\uff1a</p> \\[ Q_1=nRT_1ln(\\frac{V_2}{V_1})\\qquad Q_2=nRT_2ln(\\frac{V_3}{V_4}) \\] <p>\u6ce8\u610f\u7531\\(Q_2\\)\u653e\u70ed\u4ea7\u751f\u7684\u6b63\u8d1f\u53f7\u95ee\u9898\uff0c\u518d\u6839\u636e\u70ed\u673a\u6548\u7387\u7684\u5b9a\u4e49\uff1a</p> \\[ \\eta=\\frac{W}{Q_1}=1-\\frac{Q_2}{Q_1}=1-\\frac{T_2ln(\\frac{V_3}{V_4})}{T_1ln(\\frac{V_2}{V_1})} \\] <p>\u518d\u5229\u75282\\(\\sim\\)3\u548c4\\(\\sim\\)1\u7684\u7edd\u70ed\u8fc7\u7a0b\u6709\uff1a</p> \\[ T_1V_2^{\\gamma-1}=T_2V_3^{\\gamma-1}\\qquad T_2V_4^{\\gamma-1}=T_1V_1^{\\gamma-1} \\] <p>\u4ee3\u5165\u5f97\u5230\uff1a</p> \\[ \\eta=1-\\frac{T_2}{T_1} \\] <p>\u6b64\u5916\uff0c\u5bf9\u4e8e\u70ed\u5bb9\u968f\u6e29\u5ea6\u53d8\u5316\u7684\u60c5\u51b5\uff0c\u6613\u8bc1\u6548\u7387\u4e0d\u53d8\u3002</p> <p>(2)\u5361\u8bfa\u5236\u51b7\u673ap-V\u56fe\u5982\u4e0b\uff0c\u7ecf\u53861\\(\\sim\\)4\u8fc7\u7a0b\u4f5c\u4e3a\u4e00\u4e2a\u5faa\u73af\u3002</p> <p></p> <p>\u9996\u5148\u6839\u636e\u5236\u51b7\u673a\u6548\u7387\u7684\u5b9a\u4e49\uff1a</p> \\[ \\eta=\\frac{Q_2}{W} \\] <p>\u7531\u4e8e\u9006\u5361\u8bfa\u5faa\u73af\u4ec5\u4ec5\u662f\u8fc7\u7a0b\u53cd\u4e86\uff0c\u56e0\u800c\u8ba1\u7b97\u7684\u7ed3\u679c\u4e0d\u53d8\uff0c\u76f4\u63a5\u5f97\u5230\uff1a</p> \\[ \\eta=\\frac{T_2}{T_1-T_2} \\] <p>\u5236\u51b7\u673a\u6548\u7387\u8d8a\u5927\u8bf4\u660e\u51e0\u4e4e\u4e0d\u7528\u505a\u529f\u5c31\u53ef\u4ee5\u5b9e\u73b0\u70ed\u4f20\u9012\u3002</p> <p>\u2605 \u5361\u8bfa\u5faa\u73af\u867d\u7136\u5f88\u7b80\u5355\uff0c\u4f46\u5176\u63cf\u8ff0\u4e86\u4e24\u4e2a\u4e0d\u540c\u6e29\u5ea6\u7684\u70ed\u6e90\u901a\u8fc7\u70ed\u673a\u505a\u529f\u7684\u95ee\u9898\uff0c\u4ece\u7e41\u6742\u7684\u5faa\u73af\u4e2d\u62bd\u51fa\u6700\u57fa\u672c\u7684\u4e1c\u897f\uff0c\u4f7f\u5f97\u4e4b\u540e\u5206\u6790\u57fa\u7840\u95ee\u9898\u6210\u4e3a\u53ef\u80fd\u3002\u5f53\u7136\uff0c\u4e5f\u53ef\u4ee5\u5229\u7528\u5176\u4ed6\u65b9\u5f0f\u8fdb\u884c\u4e4b\u540e\u7684\u63a8\u5bfc\uff0c\u4e0d\u8fc7\u6570\u5b66\u8fc7\u4e8e\u590d\u6742\u3002</p>"},{"location":"chapter_01_basic_concepts/07_second_law.html","title":"\u70ed\u529b\u5b66\u7b2c\u4e8c\u5b9a\u5f8b","text":""},{"location":"chapter_01_basic_concepts/07_second_law.html#_1","title":"\u70ed\u529b\u5b66\u7b2c\u4e8c\u5b9a\u5f8b","text":"<p>\u2605 \u70ed\u529b\u5b66\u7b2c\u4e00\u5b9a\u5f8b\u8868\u660e\u80fd\u91cf\u7684\u5b88\u6052\uff0c\u4f46\u4ec5\u9760\u8fd9\u4e00\u4fe1\u606f\u5e76\u4e0d\u80fd\u5bf9\u80fd\u91cf\u6f14\u5316\u7684\u65b9\u5411\u6027\u8fdb\u884c\u7ea6\u675f\u548c\u5224\u65ad\u3002\u6709\u4e9b\u5047\u60f3\u7684\u8fc7\u7a0b\u5c3d\u7ba1\u539f\u5219\u4e0a\u4e0d\u8fdd\u80cc\u70ed\u4e00\uff0c\u4f46\u5374\u662f\u4e0d\u5b58\u5728\u7684\u3002\u7531\u6b64\u70ed\u529b\u5b66\u7b2c\u4e8c\u5b9a\u5f8b\u5e94\u8fd0\u800c\u751f\u3002</p> <p>\u5f00\u5c14\u6587\u8868\u8ff0\uff1a\u4e0d\u53ef\u80fd\u4ece\u5355\u4e00\u70ed\u6e90\u5438\u70ed\u4f7f\u4e4b\u5b8c\u5168\u53d8\u4e3a\u6709\u7528\u7684\u529f\uff0c\u800c\u4e0d\u4ea7\u751f\u5176\u4ed6\u5f71\u54cd\uff0e</p> <p>\u514b\u52b3\u4fee\u65af\u8868\u8ff0\uff1a\u4e0d\u53ef\u80fd\u628a\u70ed\u4ece\u4f4e\u6e29\u7269\u4f53\u4f20\u5230\u9ad8\u6e29\u7269\u4f53\uff0c\u800c\u4e0d\u4ea7\u751f\u5176\u4ed6\u5f71\u54cd\uff0e</p> <ul> <li>\u5982\u679c\u5c06\u70ed\u4e8c\u53cd\u8fc7\u6765\u8bf4\uff0c\u4e5f\u662f\u6b63\u786e\u7684\u3002\u5373\u529f\u53ef\u4ee5\u5b8c\u5168\u53d8\u4e3a\u70ed\uff0c\u70ed\u53ef\u4ee5\u4ece\u9ad8\u6e29\u4f20\u5230\u4f4e\u6e29\uff0c\u800c\u4e0d\u4ea7\u751f\u5176\u4ed6\u5f71\u54cd\u3002</li> <li>\u4ea7\u751f\u5176\u4ed6\u5f71\u54cd\u6307\u7684\u662f\uff0c\u4f8b\u5982\u5361\u8bfa\u5faa\u73af\u7684\\(Q_2\\)\u3001\u5236\u51b7\u673a\u5faa\u73af\u7684\\(W\\)\u3001\u7b49\u6e29\u8fc7\u7a0b\u7684\u4f53\u79ef\u81a8\u80c0\u3002</li> <li>\u70ed\u529b\u5b66\u7684\u76f8\u5173\u547d\u9898\u5e38\u5e38\u901a\u8fc7\u6784\u9020\u70ed\u673a\u8fdb\u884c\u53cd\u8bc1\uff0c\u6216\u8005\u5229\u7528p-V\u56fe\u6784\u9020\u8fdd\u53cd\u70ed\u4e8c\u7684\u5faa\u73af\u8fdb\u884c\u8bc1\u660e\u3002</li> </ul> <p>\u4e0b\u9762\u6765\u8bc1\u660e\u4e24\u4e2a\u8868\u8ff0\u7684\u7b49\u4ef7\u6027(\u9ed8\u8ba4\\(T_1&gt;T_2\\))\uff1a</p> <p></p> <p>\u2605 \u70ed\u4e8c\u7684\u7b49\u4ef7\u8868\u8ff0\u8fd8\u6709\u8bb8\u591a\uff0c\u751a\u81f3\u65e0\u6cd5\u7a77\u5c3d\u5730\u7f57\u5217\u51fa\u6765\u3002\u8c08\u53ca\u70ed\u4e8c\u4e2d\u201c\u4ea7\u751f\u7684\u5f71\u54cd\u201d\uff0c\u5f80\u5f80\u6d89\u53ca\u4e0d\u53ef\u9006\u8fc7\u7a0b\u7684\u6982\u5ff5\u3002\u4e0d\u4e25\u683c\u5730\uff0c\u53ef\u4ee5\u7406\u89e3\u4e3a\u529f\u8f6c\u5316\u4e3a\u70ed\u7684\u4e0d\u53ef\u9006\uff0c\u5373\u70ed\u529f\u8f6c\u5316\u7684\u4e0d\u7b49\u4ef7\u6027\uff0c\u53ef\u4ee5\u5f62\u8c61\u5730\u7406\u89e3\u4e3a\u201c\u8986\u6c34\u96be\u6536\u201d\u3002\u540e\u7eed\u4f1a\u5f15\u5165\u201c\u71b5\u201d\u7684\u6982\u5ff5\uff0c\u6765\u7528\u6570\u5b66\u8bed\u8a00\u8fdb\u884c\u63cf\u8ff0\u3002</p>"},{"location":"chapter_01_basic_concepts/08_carnot_theorem_temperature_scale.html","title":"\u5361\u8bfa\u5b9a\u7406\u3001\u70ed\u529b\u5b66\u6e29\u6807\u5b58\u5728","text":""},{"location":"chapter_01_basic_concepts/08_carnot_theorem_temperature_scale.html#_1","title":"\u5361\u8bfa\u5b9a\u7406\u3001\u70ed\u529b\u5b66\u6e29\u6807\u5b58\u5728","text":"<p>\u2605 \u9996\u5148\u8981\u533a\u5206\u53ef\u9006\u548c\u4e0d\u53ef\u9006\u7684\u6982\u5ff5\uff1a</p> <p>\u53ef\u9006\uff1a\u65e0\u8017\u6563\u6216\u65e0\u6469\u64e6\u7684\u51c6\u9759\u6001\u8fc7\u7a0b\uff0c\u7c7b\u6bd4\u53ef\u9006\u7684\u5316\u5b66\u53cd\u5e94\u3002\u6b64\u5916\uff0c\u80fd\u753b\u5728p-V\u56fe\u4e0a\u7684\u90fd\u662f\u53ef\u9006\u8fc7\u7a0b\u3002</p> <p>\u4e0d\u53ef\u9006\uff1a\u8fc7\u7a0b\u6240\u4ea7\u751f\u7684 \u540e\u679c\uff0c\u65e0\u8bba\u7528\u4efb\u4f55\u65b9\u6cd5\uff0c\u90fd\u4e0d\u53ef\u80fd\u5b8c\u5168\u6062\u590d\u539f\u72b6\u800c\u4e0d\u5f15\u8d77\u5176\u4ed6\u53d8 \u5316\uff0c\u7c7b\u6bd4\u81ea\u53d1\u7684\u5316\u5b66\u53cd\u5e94\u3002\u5e76\u4e14\u4e0d\u80fd\u753b\u5728p-V\u56fe\u4e0a\u3002</p> <p>\u7531\u4e8e\u81ea\u7136\u754c\u4e00\u5207\u70ed\u73b0\u8c61\u90fd\u662f\u4e0d\u53ef\u9006\u8fc7\u7a0b\uff0c\u56e0\u6b64\u53ef\u9006\u8fc7\u7a0b\u7684\u56fe\u666f\u5f88\u96be\u60f3\u8c61\u3002\u7136\u800c\uff0c\u53ef\u9006\u8fc7\u7a0b\u5728\u5206\u6790\u95ee\u9898\u65f6\u5374\u5f88\u6709\u7528\uff0c\u662f\u4e00\u79cd\u975e\u5e38\u597d\u7684\u601d\u7ef4\u65b9\u6cd5\u3002</p> <p>\u2605 \u5361\u8bfa\u5b9a\u7406\uff1a\u6240\u6709\u5de5\u4f5c\u4e8e\u4e24\u4e2a\u4e00\u5b9a\u6e29\u5ea6\u4e4b\u95f4\u7684\u70ed\u673a\uff0c\\(\\eta_{\\text{\u53ef\u9006}}\\geqslant\\eta_{\\text{\u672a\u77e5\u70ed\u673a}}\\)\uff0e</p> <p>\u8bc1\u660e\u5982\u4e0b\uff1a\u5047\u8bbe\\(\\eta_{\\text{\u53ef\u9006}}&lt;\\eta_{\\text{\u672a\u77e5\u70ed\u673a}}\\),\u4e14\u4e24\u70ed\u673a\u5438\u6536\u70ed\u91cf\\(Q_1\\)\u76f8\u540c\uff0c\u53ef\u9006\u70ed\u673a\u505a\u529f\u4e3aW\uff0c\u672a\u77e5\u70ed\u673a\u505a\u529f\u4e3a\\(W'\\)\u3002\u4ece\u800c\u6709\uff1a</p> \\[ \\frac{W}{Q_1}&lt;\\frac{W'}{Q_1}\\Rightarrow W'-W&gt;0 \\] <p>\u4ece\u800c\u672a\u77e5\u70ed\u673a\u6bd4\u53ef\u9006\u70ed\u673a\u591a\u4f59\u51fa\u6765\u7684\u529f\uff0c\u53ef\u4ee5\u7ed9\u53ef\u9006\u70ed\u673a\uff0c\u8fdb\u884c\u9006\u5faa\u73af\u3002\u6b64\u65f6\uff0c\u4e24\u70ed\u673a\u7ec4\u6210\u7684\u6574\u4f53\u7b49\u4ef7\u4e8e\u7b2c\u4e8c\u7c7b\u6c38\u52a8\u673a\uff0c\u4ece\u800c\u5047\u8bbe\u9519\u8bef\uff0c\u5361\u8bfa\u5b9a\u7406\u5f97\u8bc1\u3002</p> <p></p> <p>\u540c\u7406\u53ef\u5f97\uff0c\u6240\u6709\u5de5\u4f5c\u4e8e\u4e24\u4e2a\u4e00\u5b9a\u6e29\u5ea6\u4e4b\u95f4\u7684\u53ef\u9006\u70ed\u673a\uff0c\u6548\u7387\u76f8\u7b49\u3002\u7531\u4e8e\u5361\u8bfa\u5faa\u73af\u6ee1\u8db3\u65e0\u6469\u64e6\u7684\u51c6\u9759\u6001\u8fc7\u7a0b\uff0c\u56e0\u800c\u53ef\u5f97\u53ef\u9006\u70ed\u673a\u7684\u6548\u7387\u4e3a\\(\\eta=1-\\frac{T_2}{T_1}\\)</p> <p>\u2605 \u5229\u7528\u4ee5\u4e0a\u7ed3\u8bba\uff0c\u53ef\u4ee5\u8bc1\u660e\u70ed\u529b\u5b66\u6e29\u6807\u7684\u5b58\u5728\u3002\u8bbe\u53ef\u9006\u5361\u8bfa\u70ed\u673a\u5438\u6536\u548c\u653e\u51fa\u7684\u70ed\u91cf\u4e3a\\(Q_1\\)\u548c\\(Q_2\\)\uff1a</p> \\[ \\eta=1-\\frac{Q_2}{Q_1}\\Rightarrow \\frac{Q_2}{Q_1}=f(\\theta_1,\\theta_2 ) \\] <p>\u53e6\u4e00\u53ef\u9006\u5361\u8bfa\u70ed\u673a\u4e3a\\(Q_3\\)\u548c\\(Q_1\\)\uff1a</p> \\[ \\frac{Q_1}{Q_3}=f(\\theta_1,\\theta_3 ) \\] <p>\u5c06\u7b2c\u4e8c\u4e2a\u70ed\u673a\u653e\u51fa\u7684\u70ed\u91cf\\(Q_1\\)\u8f93\u5165\u7ed9\u7b2c\u4e00\u4e2a\uff0c\u5219\u6574\u4f53\u7ec4\u6210\u7684\u70ed\u673a\u6709\uff1a</p> \\[ \\frac{Q_2}{Q_3}=f(\\theta_2,\\theta_3) \\] <p>\u6613\u5f97\uff1a</p> \\[ \\frac{Q_2}{Q_1}=f(\\theta_1,\\theta_2)=\\frac{f(\\theta_2,\\theta_3)}{f(\\theta_1,\\theta_3)}\\Rightarrow \\frac{Q_2}{Q_1}=\\frac{f(\\theta_2)}{f(\\theta_1)} \\] <p>\u4ece\u800c\u53ef\u4ee5\u9009\u62e9\u4e0e\\(\\theta\\)\u6b63\u6bd4\u7684\u51fd\u6570\u5173\u7cfb\u5b9a\u4e49\u6e29\u6807\uff0c\u5373\u70ed\u529b\u5b66\u6e29\u6807\u3002\u6b64\u5916\u53ef\u4ee5\u5bfc\u51fa\u6e29\u5ea6\u6052\u6b63\uff0c\u5426\u5219\u4f1a\u8fdd\u53cd\u70ed\u4e8c\u3002</p>"},{"location":"chapter_01_basic_concepts/09_clausius_entropy.html","title":"\u514b\u52b3\u4fee\u65af\u4e0d\u7b49\u5f0f\u3001\u71b5\u7684\u6982\u5ff5\u3001\u71b5\u589e\u539f\u7406","text":""},{"location":"chapter_01_basic_concepts/09_clausius_entropy.html#_1","title":"\u514b\u52b3\u4fee\u65af\u4e0d\u7b49\u5f0f\u3001\u71b5\u7684\u6982\u5ff5\u3001\u71b5\u589e\u539f\u7406","text":"<p>\u2605 \u6839\u636e\u5361\u8bfa\u5b9a\u7406\\(\\eta_{\\text{\u53ef\u9006}}\\geqslant\\eta_{\\text{\u672a\u77e5\u70ed\u673a}}\\)\u518d\u7531\u4e24\u4e0d\u540c\u70ed\u6e90\u95f4\u7684\u6700\u5927\u6548\u7387\u4e3a\u5361\u8bfa\u5faa\u73af\u7684\u6548\u7387\u5f97\u5230\\(1-\\frac{T_2}{T_1}\\geqslant 1-\\frac{Q_2}{Q_1} \\Rightarrow \\frac{Q_1}{T_1}-\\frac{Q_2}{T_2}\\leqslant0\\)</p> <p>\u8fd9\u91cc\u5c06\u4e4b\u524d\u5361\u8bfa\u5faa\u73af\u4e2d\u7684\\(Q_2\\)\u5b9a\u4e49\u6210\u5438\u6536\\(T_2\\)\u70ed\u6e90\u7684\u70ed\u91cf\uff0c\u4f7f\u5f97\\(Q\\)\u7684\u6b63\u8d1f\u53f7\u542b\u4e49\u7edf\u4e00\uff0c\u5219\u5f97\u5230\u514b\u52b3\u4fee\u65af\u4e0d\u7b49\u5f0f\uff1a</p> \\[ \\frac{Q_1}{T_1}+\\frac{Q_2}{T_2}\\leqslant0 \\] <p>\u4e0a\u5f0f\u4e0d\u96be\u63a8\u5e7f\u5230n\u4e2a\u4e0d\u540c\u70ed\u6e90\u7684\u60c5\u51b5\uff0c\u5e76\u5f97\u5230\u8fde\u7eed\u7684\u60c5\u5f62\uff1a</p> \\[ \\sum_{i=1}^{n}\\frac{Q_i}{T_i}\\leqslant0\\Rightarrow\\boxed{ \\oint \\frac{\\delta Q}{T}\\leqslant0} \\] <p>\u5176\u4e2d\\(\\delta Q\\)\u4e3a\u4ece\u6e29\u5ea6\\(T\\)\u7684\u70ed\u6e90\u5438\u6536\u7684\u70ed\u91cf\uff0c\u6b64\u5373\u4e3a\u514b\u52b3\u4fee\u65af\u4e0d\u7b49\u5f0f\u3002</p> <p>\u2605 \u4e3a\u4e86\u7b80\u5355\uff0c\u53ef\u4ee5\u4ece\u53ef\u9006\u8fc7\u7a0b\u5165\u624b\uff0c\u8ba8\u8bba\u514b\u52b3\u4fee\u65af\u4e0d\u7b49\u5f0f\u53d6\u7b49\u53f7\u7684\u60c5\u51b5\uff0c\u4ece\u800c\u5f15\u5165\u71b5\u7684\u6982\u5ff5\u3002</p> \\[ \\oint_{C}\\frac{\\delta Q}{T}=0\\Rightarrow \\int_{C_1}^{A\\to B}\\frac{\\delta Q}{T}+\\int_{C_2}^{B\\to A}\\frac{\\delta Q}{T}=0 \\] <p>\u5176\u4e2d\\(C_1\\)\u548c\\(C_2\\)\u4e3aC\u66f2\u7ebf\u7684\u4e00\u4e2a\u5212\u5206\uff0c\u53ef\u4ee5\u8868\u793a\u4e24\u4e2a\u8d77\u70b9\u548c\u7ec8\u70b9\u76f8\u540c\u4f46\u8fc7\u7a0b\u4e0d\u540c\u7684\u79ef\u5206\uff1a</p> \\[ \\int_{C_1}^{A\\to B}\\frac{\\delta Q}{T}=-\\int_{C_2}^{B\\to A}\\frac{\\delta Q}{T}=\\int_{C_2}^{A\\to B}\\frac{\\delta Q}{T}=Const. \\] <p>\u8868\u660e\u6b64\u79ef\u5206\u53ea\u4e0e\u521d\u672b\u7684\u72b6\u6001\u6709\u5173\uff0c\u4e0e\u5177\u4f53\u8fc7\u7a0b\u65e0\u5173\uff0c\u56e0\u800c\u53ef\u4ee5\u5b9a\u4e49\u71b5\u8fd9\u4e2a\u6001\u51fd\u6570:</p> \\[ \\boxed{S_B-S_A=\\int_{A}^{B}\\frac{\\delta Q}{T}}\\Rightarrow \\boxed{dS=\\frac{\\delta Q}{T}} \\] <p>\u53ef\u89c1T\u4e3a\\(\\delta Q\\)\u7684\u79ef\u5206\u56e0\u5b50,\u4e14\u7531\u4e8e\u53ef\u9006\u8fc7\u7a0b\u70ed\u5e73\u8861\uff0c\u8fd9\u91cc\u7684T\u4e3a\u7cfb\u7edf\u7684\u6e29\u5ea6\u3002</p> <p>\u2605 \u8ba8\u8bba\u71b5\u589e\u4e4b\u524d\uff0c\u5148\u8981\u8ba8\u8bba\u521d\u672b\u72b6\u6001\u4e3a\u5e73\u8861\u6001\u7684\u4e0d\u53ef\u9006\u8fc7\u7a0b\u3002\u8bbe\u4e0d\u53ef\u9006\u8fc7\u7a0bA\u5230B\uff0c\u5e76\u4f34\u968f\u4e00\u4e2a\u53ef\u9006\u8fc7\u7a0bB\u5230A\uff0c\u5219\u6709\uff1a</p> \\[ \\oint_{C}\\frac{\\delta Q_{\\text{\u4e0d\u53ef\u9006}}}{T}&lt; 0\\Rightarrow \\int_{A}^{B}\\frac{\\delta Q_{\\text{\u4e0d\u53ef\u9006}}}{T}+\\int_{B}^{A}\\frac{\\delta Q_{\\text{\u53ef\u9006}}}{T}&lt;0 \\] <p>\u540c\u7406\u5f97\u5230\uff1a</p> \\[ \\int_{A}^{B}\\frac{\\delta Q_{\\text{\u4e0d\u53ef\u9006}}}{T}&lt;\\int_{A}^{B}\\frac{\\delta Q_{\\text{\u53ef\u9006}}}{T}=S_B-S_A\\Rightarrow \\boxed{S_B-S_A&gt; \\int_{A}^{B}\\frac{\\delta Q_{\\text{\u4e0d\u53ef\u9006}}}{T}}\\Rightarrow \\boxed{dS&gt;\\frac{\\delta Q_{\\text{\u4e0d\u53ef\u9006}}}{T}} \\] <p>\u2605 \u7efc\u4e0a\uff0c\u5f97\u5230\u70ed\u4e8c\u7684\u6570\u5b66\u8868\u8ff0\uff1a(\u6ce8\u610f\u4ee5\u4e0b\u7684T\u4e3a\u73af\u5883\u70ed\u6e90\u7684\u6e29\u5ea6)</p> \\[ \\boxed{S_B-S_A\\geqslant \\int_{A}^{B}\\frac{\\delta Q}{T}}\\Rightarrow \\boxed{dS\\geqslant\\frac{\\delta Q}{T}} \\] <p>\u8003\u8651\u7edd\u70ed\u8fc7\u7a0b\uff0c\u6709\\(\\delta Q=0\\),\u5f97\u5230\u71b5\u589e\u539f\u7406\uff1a</p> \\[ \\boxed{dS\\geqslant0} \\] <p>\u8868\u660e\u5728\u7edd\u70ed\u8fc7\u7a0b(\u5b64\u7acb\u7cfb)\u6761\u4ef6\u4e0b\uff0c\u71b5\u6c38\u4e0d\u51cf\u5c11\u3002\u5bf9\u4e8e\u4efb\u4f55\u4f53\u7cfb\uff0c\u5747\u53ef\u5c06\u4e4b\u6269\u5c55\u6210\u5b64\u7acb\u7cfb\uff0c\u4ece\u800c\u4f7f\u7528\u71b5\u589e\u539f\u7406\uff0c\u6b64\u5916\uff0c\u5176\u4e5f\u4e0e\u70ed\u4e8c\u7b49\u4ef7\u3002</p> <ul> <li>\u6ce8\u610f\u71b5\u589e\u539f\u7406\u7684\u6761\u4ef6\u4e3a\u7edd\u70ed\u8fc7\u7a0b\uff0c\u5e76\u4e14\\(\\Delta S\\)\u662f\u5426\u7b49\u4e8e\u96f6\u53ef\u4ee5\u4f5c\u4e3a\u7edd\u70ed\u8fc7\u7a0b\u53ef\u9006\u6027\u7684\u5224\u636e\u3002\u5176\u4ed6\u8fc7\u7a0b\u5219\u8981\u4e0e\\(\\frac{\\delta Q}{T}\\)\u8fdb\u884c\u6bd4\u8f83\u3002</li> <li>\u7531\u4e8e\u8868\u8fbe\u5f0f\u4e2d\\(\\delta Q\\)\u4e0e\u7cfb\u7edf\u8d28\u91cf\u6210\u6b63\u6bd4\uff0c\u56e0\u800c\u71b5\u662f\u4e00\u4e2a\u5e7f\u5ef6\u91cf</li> <li>\u5bf9\u4e8e\u53ef\u9006\u8fc7\u7a0b\uff0c\u4e4b\u524d\u7528p-V\u5206\u6790\u8fc7\u7a0b\u7684\u60f3\u6cd5\u6765\u6e90\u4e8e\\(\\delta W=-pdV\\)\u3002\u5f15\u5165\u71b5\u540e\uff0c\u6709\\(\\delta Q=TdS\\)\u56e0\u800c\u53ef\u4ee5\u7528T-S\u56fe\u5206\u6790\u3002\u4f8b\u5982\u5361\u8bfa\u5faa\u73af\u7684T-S\u56fe\u5c31\u662f\u5c01\u95ed\u7684\u77e9\u5f62\uff0c\u5176\u5c01\u95ed\u66f2\u7ebf\u7684\u9762\u79ef\u5373\u5438\u6536\u7684\u70ed\u91cf,\u53c8\u7531\u4e8e\\(\\Delta U=0\\)\u6240\u4ee5\u4e5f\u4e3a\u7cfb\u7edf\u5bf9\u5916\u4f5c\u7684\u529f\u3002</li> </ul> <p>\u2605 \u6700\u5927\u529f\u7684\u6e29\u5ea6\u95ee\u9898\uff1a\u4e24\u4e2a\u6e29\u5ea6\u5206\u522b\u4e3a\\(T_1\\)\u548c\\(T_2\\)\u7684\u5b8c\u5168\u76f8\u540c\u7684\u70ed\u6e90\uff0c\u4e14\u5ffd\u7565\u4f53\u79ef\u53d8\u5316\u3002\u70ed\u6e90\u4e4b\u95f4\u5b58\u5728\u70ed\u673a\uff0c\u6c42\u6700\u7ec8\u4e24\u70ed\u6e90\u70ed\u5e73\u8861\u6e29\u5ea6\\(T_f\\)\u7684\u8303\u56f4\u3002</p> <p>\u8fd9\u91cc\u7684\u5207\u5165\u70b9\u5728\u4e8e\u5c06\u4e24\u4e2a\u70ed\u6e90\u770b\u6210\u4e00\u4e2a\u7edd\u70ed\u5c01\u95ed\u7684\u7cfb\u7edf\uff0c\u56e0\u4e3a\u53ea\u80fd\u901a\u8fc7\u5bf9\u5916\u505a\u529f\u4e00\u79cd\u65b9\u5f0f\u6539\u53d8\u5185\u80fd,\u5373\\(\\Delta U=-W_{\\text{\u7cfb\u7edf\u5bf9\u5916}}\\).\u8fd9\u91cc\u53ef\u4ee5\u901a\u8fc7\u8c03\u8282W\u6765\u8fdb\u884c\u5206\u6790\uff0c\u5f53\u505a\u529f\u4e3a0\u65f6\uff0c\u7531\u4e8e\u5185\u80fd\u4e0d\u53d8\uff0c\u6545\\(\\Delta U=0\\).\u5f53\u505a\u6700\u5927\u529f\u65f6\uff0c\u4e3a\u53ef\u9006\u70ed\u673a\uff0c\u7531\\(dS\\geqslant0\\)\u53d6\u7b49\u6761\u4ef6\uff0c\u4ece\u800c\u6ee1\u8db3\\(\\Delta S=0\\).\u8bbe\u70ed\u6e90\u7684\u70ed\u5bb9\u4e3a\\(C_V\\)\u53ef\u5f97\uff1a</p> \\[ \\Delta U=C_V(2T_f-T_1-T_2)\\qquad \\Delta S=C_Vln(\\frac{T_f^2}{T_1T_2}) \\] <p>\u518d\u5229\u7528\\(\\Delta U=0\\)\u548c\\(\\Delta S=0\\)\u6c42\u5f97\\(T_f\\)\u7684\u4e0a\u4e0b\u9650\u5373\u53ef\uff0c\u5f97\u5230\uff1a</p> \\[ \\sqrt{T_1T_2}\\leqslant T_f\\leqslant \\frac{T_1+T_2}{2} \\] <p>\u6ce8\u610f\uff0c\u4ee5\u4e0a\u7ed3\u679c\u5ffd\u7565\u4e86\u4f53\u79ef\u53d8\u5316\u5e26\u6765\u7684\u5f71\u54cd\uff0c\u4e14\u9ed8\u8ba4\u70ed\u5bb9\u4e0d\u53d8\u3002</p>"},{"location":"chapter_01_basic_concepts/10_fundamental_equation_entropy.html","title":"\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001\u7406\u60f3\u6c14\u4f53\u7684\u71b5\u4e0e\u76f8\u5173\u8ba1\u7b97","text":""},{"location":"chapter_01_basic_concepts/10_fundamental_equation_entropy.html#_1","title":"\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001\u7406\u60f3\u6c14\u4f53\u7684\u71b5\u4e0e\u76f8\u5173\u8ba1\u7b97","text":"<p>\u2605 \u5bf9\u4e8e\u4e00\u822c\u8fc7\u7a0b\u800c\u8a00\uff0c\u7531\\(dS\\geqslant\\frac{\\delta Q}{T}\\)\u548c\u70ed\u4e00\u5f97\u5230\uff1a</p> \\[ \\boxed{dU \\leqslant TdS+\\delta W} \\] <p>\u5373\u5c01\u95ed\u7cfb\u7edf\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u7684\u4e00\u822c\u5f62\u5f0f\uff0c\u4f46\u8981\u6ce8\u610f\uff0c\u5206\u6790\\(\\delta Q=0\\)\u4e0d\u80fd\u4f7f\u7528\u6b64\u4e0d\u7b49\u5f0f\uff0c\u56e0\u4e3a\\(TdS\\geqslant\\delta Q\\).\u6b64\u5916\uff0c\u5bf9\u4e8e\u53ef\u9006\u8fc7\u7a0b\u7684\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u6709\uff1a</p> \\[ dU=TdS+\\sum_{i} Y_idy_i\\Rightarrow \\boxed{dU=TdS-pdV} \\] <p>\u2605 \u6839\u636e\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u548c\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u5f97\u5230\uff1a</p> \\[ dS=\\frac{dU+pdV}{T}=\\frac{n C_{V,m}dT}{T}+\\frac{nRdV}{V} \\] <p>\u9ed8\u8ba4\u70ed\u5bb9\u4e0d\u53d8\uff0c\u79ef\u5206\u5f97\u5230\u71b5\u53d8\uff1a</p> \\[ \\Delta S=nC_{V,m}ln(\\frac{T_2}{T_1})+nRln(\\frac{V_2}{V_1}) \\] <p>\u6839\u636e\u71b5\u548c\u4f53\u79ef\u7684\u5e7f\u5ef6\u6027\uff0c\u4e5f\u53ef\u5199\u51fa\u71b5\u7684\u8868\u8fbe\u5f0f\uff1a</p> \\[ S(T,V)=nC_{V,m}lnT+nRlnV+S_0\\qquad S_0=nS_{m0}-nRln(n) \\] <p>\u6b64\u5916\u4ee3\u5165\\(V=\\frac{nRT}{p}\\)\u5f97\u5230\u71b5\u53d8\u548c\u71b5\u7684\u8868\u8fbe\u5f0f\uff1a</p> \\[ \\Delta S=nC_{p,m}ln(\\frac{T_2}{T_1})-nRln(\\frac{p_2}{p_1}) \\] \\[ S(T,p)=nC_{p,m}lnT-nRlnp+S_0\\qquad S_0=nS_{m0} \\] <p>\u4e0a\u5f0f\u4e2d\uff0c\u6ce8\u610f\u71b5\u53d8\u548c\u71b5\u7684\u533a\u522b\uff0c\u540e\u9762\u8ba1\u7b97\u540c\u79cd\u6c14\u4f53\u6df7\u5408\u7684\u71b5\u589e\u4f1a\u7528\u5230\u3002\u539f\u56e0\u5728\u4e8e\uff0c\u5212\u7ebf\u90e8\u5206\u662f\u8003\u8651\u4f53\u79ef\u7684\u5e7f\u5ef6\u6027\u5f97\u5230\u7684\u3002\u7136\u800c\uff0c\u7531\u4e8e\u901a\u5e38\u8003\u8651\u7684\u6c14\u4f53\u7c92\u5b50\u6570\u56fa\u5b9a\uff0c\u8fd9\u4e00\u70b9\u5e38\u5e38\u5bb9\u6613\u88ab\u5ffd\u89c6\u3002</p> <p>Tips:(1)\u8ba1\u7b97\u71b5\u53d8\u4e4b\u524d\u8981\u660e\u786e\u8fc7\u7a0b\u662f\u5426\u53ef\u9006\uff0c\u5f53\u8fc7\u7a0b\u662f\u5728\u7b49\u538b\u73af\u5883\u4e0b\u53d1\u751f\uff0c\u9700\u8981\u8003\u5bdf\\(dS=\\frac{C_pdT}{T}\\)\u5404\u9879\u8fdb\u884c\u5206\u6790\u3002 (2)\u6b64\u5916\uff0c\u5f53\u70ed\u673a\u5728\u8fd0\u884c\u65f6\uff0c\\(Q_1=W+Q_2\\)\u7684\u5173\u7cfb\u9700\u8981\u7ecf\u5e38\u4f7f\u7528\u3002(3)\u8ba1\u7b97\u76f8\u53d8\u71b5\u53d8\u65f6\uff0c\u9700\u8981\u5229\u7528\u71b5\u662f\u72b6\u6001\u51fd\u6570\u7684\u7279\u6027\uff0c\u6784\u9020\u5de7\u5999\u7684\u56de\u8def\u8fdb\u884c\u5dee\u7684\u8ba1\u7b97,\u7c7b\u4f3c\u4e8e\u9ad8\u4e2d\u7684\u76d6\u65af\u5b9a\u5f8b\u3002</p>"},{"location":"chapter_01_basic_concepts/11_free_energy_gibbs.html","title":"\u81ea\u7531\u80fd\u3001Gibbs\u51fd\u6570","text":""},{"location":"chapter_01_basic_concepts/11_free_energy_gibbs.html#gibbs","title":"\u81ea\u7531\u80fd\u3001Gibbs\u51fd\u6570","text":"<p>\u2605 \u8003\u8651\u4e24\u79cd\u8fc7\u7a0b\uff1a\u7b49\u6e29\u7b49\u5bb9\u548c\u7b49\u6e29\u7b49\u538b\u3002\u867d\u7136\u5229\u7528\u71b5\u7684\u5b9a\u4e49\u53ef\u4ee5\u5bf9\u5176\u6f14\u5316\u7684\u65b9\u5411\u8fdb\u884c\u5224\u65ad\uff0c\u4f46\u5728\u5904\u7406\u590d\u6742\u95ee\u9898\u65f6\u4e0d\u592a\u65b9\u4fbf\uff0c\u56e0\u800c\u5f15\u5165\u4e24\u4e2a\u8f85\u52a9\u91cf\uff1a\u81ea\u7531\u80fdF\u548cGibbs\u51fd\u6570G\u3002(P.S.\u8fd9\u91cc\u7684\u7b49\u6e29\u3001\u7b49\u538b\u3001\u7b49\u5bb9\u662f\u6307\u7cfb\u7edf\u4e0e\u76f8\u5e94\u7684\u70ed\u6e90\u3001\u5b9a\u5bb9\u6216\u5b9a\u538b\u73af\u5883\u76f8\u8054\u7cfb\uff0c\u521d\u672b\u5e73\u8861\u6001\u6ee1\u8db3\u8fd9\u4e9b\u7ea6\u675f\uff1b\u4e0d\u53ef\u9006\u8fc7\u7a0b\u4e2d\u95f4\u6001\u4e0d\u4e00\u5b9a\u5904\u5904\u5e73\u8861\u3002)</p> <p>\u7531\u4e00\u822c\u8fc7\u7a0b\u7684\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b,\u5bf9\u4e8e\u7b49\u6e29\u8fc7\u7a0b\u5f97\u5230\uff1a</p> \\[ \\Delta U\\leqslant T\\Delta S+W \\Rightarrow W\\geqslant \\Delta U-T\\Delta S \\] <p>\u4ece\u800c\u5b9a\u4e49\\(\\boxed{F=U-TS}\\)\uff0c\u4e0a\u5f0f\u53ef\u4ee5\u5199\u4f5c\uff1a</p> \\[ W\\geqslant\\Delta F\\Rightarrow -W=W_{\\text{\u7cfb\u7edf\u5bf9\u5916}}\\leqslant-\\Delta F \\] <p>\u8868\u793a\u7cfb\u7edf\u5bf9\u5916\u505a\u529f\u7684\u4e0a\u9650\u662fF\u7684\u51cf\u5c11\u91cf\u3002</p> <p>(1)\u5728\u7b49\u6e29\u7684\u540c\u65f6\u8003\u8651\u7b49\u5bb9\u8fc7\u7a0b,\u7cfb\u7edf\u5bf9\u5916\u4e0d\u505a\u529f\uff0c\u56e0\u800c\u6709\uff1a</p> \\[ \\Delta F\\leqslant0 \\] <p>\u5373\u7b49\u6e29\u7b49\u5bb9\u6761\u4ef6\u4e0b\uff0c\u7cfb\u7edf\u81ea\u7531\u80fd\u6c38\u4e0d\u589e\u52a0\u3002</p> <p>(2)\u5728\u7b49\u6e29\u7684\u540c\u65f6\u8003\u8651\u7b49\u538b\u8fc7\u7a0b\uff0c\u4e14\u53ea\u6709\u4f53\u79ef\u529f\uff0c\u5219\uff1a</p> \\[ -p\\Delta V\\geqslant\\Delta U-T\\Delta S\\Rightarrow \\Delta U-T\\Delta S+p\\Delta V\\leqslant0 \\] <p>\u4ece\u800c\u5b9a\u4e49\\(\\boxed{G=H-TS}\\)\uff0c\u5230\uff1a</p> \\[ \\Delta G\\leqslant0 \\] <p>\u5373\u7b49\u6e29\u7b49\u538b\u6761\u4ef6\u4e0b\uff0c\u7cfb\u7edf\u5409\u5e03\u65af\u51fd\u6570\u6c38\u4e0d\u589e\u52a0\u3002</p> <p>\u6ce8\u610f\uff0c\u4ee5\u4e0a\u63a8\u5bfc\u4ec5\u8003\u8651\u4f53\u79ef\u529f\uff0c\u5bf9\u4e8e\u975e\u4f53\u79ef\u529f\\(W'\\),\u6709\\(\\Delta F\\leqslant W'\\)\u548c\\(\\Delta G\\leqslant W'\\)\u4f5c\u4e3a\u8fc7\u7a0b\u53ef\u9006\u6027\u7684\u5224\u636e\u3002</p>"},{"location":"chapter_02_uniform_system/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_02_uniform_system/index.html#2","title":"\u7b2c2\u7ae0 \u5747\u5300\u4f53\u7cfb\u7684\u70ed\u529b\u5b66\u6027\u8d28","text":"<p>\u5728\u4e0a\u4e00\u7ae0\u5bf9\u70ed\u529b\u5b66\u57fa\u672c\u6982\u5ff5\u56de\u987e\u548c\u68b3\u7406\u7684\u57fa\u7840\u4e4b\u4e0a\uff0c\u672c\u7ae0\u4f1a\u7528\u4e00\u4e9b\u6570\u5b66\u6280\u5de7\uff0c\u8fdb\u4e00\u6b65\u8ba8\u8bba\u57fa\u672c\u70ed\u529b\u5b66\u91cf(\u7269\u6001\u65b9\u7a0b,U,S)\u3001\u8f85\u52a9\u91cf\u3001\u54cd\u5e94\u91cf\u4e4b\u95f4\u7684\u5173\u7cfb\uff0c\u5e76\u5229\u7528\u8fd9\u4e9b\u5173\u7cfb\u6765\u5904\u7406\u5747\u5300\u4f53\u7cfb\u7684\u5177\u4f53\u4f8b\u5b50(\u8282\u6d41\u8fc7\u7a0b\u3001\u70ed\u8f90\u5c04\u3001\u78c1\u4ecb\u8d28)\uff0c\u5f97\u5230\u5176\u70ed\u529b\u5b66\u6027\u8d28\u3002\u603b\u7684\u6765\u8bf4\uff0c\u53ea\u6709\u7269\u6001\u65b9\u7a0b\u548c\u67d0\u4e9b\u54cd\u5e94\u91cf\u53ef\u4ee5\u901a\u8fc7\u5b9e\u9a8c\u76f4\u63a5\u6d4b\u91cf\uff0c\u56e0\u800c\u4e9f\u9700\u627e\u5230\u4ece\u5176\u5bfc\u51fa\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\u7684\u65b9\u6cd5\uff0c\u8fd9\u4fbf\u662f\u672c\u7ae0\u7684\u6838\u5fc3\u3002</p>"},{"location":"chapter_02_uniform_system/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u56db\u4e2a\u7279\u6027\u51fd\u6570\u7684\u5fae\u5206\u65b9\u7a0b\u4ee5\u53caMaxwell\u5173\u7cfb</li> <li>\u7279\u6027\u51fd\u6570\u3001G-H\u65b9\u7a0b</li> <li>\u8303\u6c0f\u6c14\u4f53\u8282\u6d41\u8fc7\u7a0b\u3001\u7126\u6c64\u7cfb\u6570</li> <li>\u70ed\u8f90\u5c04\u3001\u78c1\u4ecb\u8d28\u7684\u70ed\u5b66\u6027\u8d28</li> </ul>"},{"location":"chapter_02_uniform_system/01_maxwell_relations.html","title":"\u56db\u4e2a\u7279\u6027\u51fd\u6570\u7684\u5fae\u5206\u65b9\u7a0b\u4ee5\u53caMaxwell\u5173\u7cfb","text":""},{"location":"chapter_02_uniform_system/01_maxwell_relations.html#maxwell","title":"\u56db\u4e2a\u7279\u6027\u51fd\u6570\u7684\u5fae\u5206\u65b9\u7a0b\u4ee5\u53caMaxwell\u5173\u7cfb","text":"<p>\u2605 \u76ee\u524d\u4e3a\u6b62\uff0c\u6211\u4eec\u5229\u7528\u70ed\u4e00\u548c\u70ed\u4e8c\uff0c\u5b9a\u4e49\u4e86\u4e0e\u5185\u80fdU\u76f8\u5173\u7684\u8f85\u52a9\u91cf\u7113H\u3001\u81ea\u7531\u80fdF\u3001\u5409\u5e03\u65af\u51fd\u6570G,\u5e76\u4e14\u5f97\u5230\u4e86\u53ef\u9006\u8fc7\u7a0b\u7684\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\uff1a</p> \\[ \\begin{array}{l} \\left\\{\\begin{matrix} H=U+pV \\\\ F=U-TS \\\\ G=H-TS \\end{matrix}\\right. \\end{array}\\quad + \\quad dU=TdS-pdV \\] <p>\u6839\u636e\u4ee5\u4e0a\u4fe1\u606f\uff0c\u4e0d\u96be\u5f97\u5230\u4e09\u4e2a\u8f85\u52a9\u91cf\u7684\u5168\u5fae\u5206(\u5b9e\u9645\u4e0a\u5c31\u662f\u52d2\u8ba9\u5fb7\u53d8\u6362)\uff1a</p> \\[ \\boxed{dH}=dU+pdV+Vdp=TdS-\\cancel{pdV}+\\cancel{pdV}+Vdp=\\boxed{TdS+Vdp} \\] \\[ \\boxed{dF}=dU-TdS-SdT=\\cancel{TdS}-pdV-\\cancel{TdS}-SdT=\\boxed{-SdT-pdV} \\] \\[ \\boxed{dG}=dH-TdS-SdT=\\cancel{TdS}+Vdp-\\cancel{TdS}-SdT=\\boxed{-SdT+Vdp} \\] <p>\u7531\u4e8e\u6001\u51fd\u6570\u5168\u5fae\u5206\u7684\u6027\u8d28\uff0c\u6df7\u5408\u4e8c\u9636\u504f\u5bfc\u53ef\u4ee5\u4ea4\u6362\u987a\u5e8f\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> <p>(1)\u5185\u80fdU(S,V)\uff1a</p> \\[ dU=\\left(\\frac{\\partial U}{\\partial S}\\right)_VdS+\\left(\\frac{\\partial U}{\\partial V}\\right)_SdV=TdS-pdV \\] \\[ \\Rightarrow\\begin{array}{l} \\left\\{\\begin{matrix} \\left(\\frac{\\partial U}{\\partial S}\\right)_V=T \\\\ \\left(\\frac{\\partial U}{\\partial V}\\right)_S=-p \\end{matrix}\\right. \\end{array}\\Rightarrow \\boxed{ \\left(\\frac{\\partial T}{\\partial V}\\right)_S=-\\left(\\frac{\\partial p}{\\partial S}\\right)_V} \\] <p>(2)\u7113H(S,p)\uff1a</p> \\[ dH=\\left(\\frac{\\partial H}{\\partial S}\\right)_pdS+\\left(\\frac{\\partial H}{\\partial p}\\right)_Sdp=TdS+Vdp \\] \\[ \\Rightarrow\\begin{array}{l} \\left\\{\\begin{matrix} \\left(\\frac{\\partial H}{\\partial S}\\right)_p=T \\\\ \\left(\\frac{\\partial H}{\\partial p}\\right)_S=V \\end{matrix}\\right. \\end{array}\\Rightarrow \\boxed{ \\left(\\frac{\\partial T}{\\partial p}\\right)_S=\\left(\\frac{\\partial V}{\\partial S}\\right)_p} \\] <p>(3)\u81ea\u7531\u80fdF(T,V)\uff1a</p> \\[ dF=\\left(\\frac{\\partial F}{\\partial T}\\right)_VdT+\\left(\\frac{\\partial F}{\\partial V}\\right)_TdV=-SdT-pdV \\] \\[ \\Rightarrow\\begin{array}{l} \\left\\{\\begin{matrix} \\left(\\frac{\\partial F}{\\partial T}\\right)_V=-S \\\\ \\left(\\frac{\\partial F}{\\partial V}\\right)_T=-p \\end{matrix}\\right. \\end{array}\\Rightarrow \\boxed{ \\left(\\frac{\\partial S}{\\partial V}\\right)_T=\\left(\\frac{\\partial p}{\\partial T}\\right)_V} \\] <p>(4)\u5409\u5e03\u65af\u51fd\u6570G(T,p)\uff1a</p> \\[ dG=\\left(\\frac{\\partial G}{\\partial T}\\right)_pdT+\\left(\\frac{\\partial G}{\\partial p}\\right)_Tdp=-SdT+Vdp \\] \\[ \\Rightarrow\\begin{array}{l} \\left\\{\\begin{matrix} \\left(\\frac{\\partial G}{\\partial T}\\right)_p=-S \\\\ \\left(\\frac{\\partial G}{\\partial p}\\right)_T=V \\end{matrix}\\right. \\end{array}\\Rightarrow \\boxed{ \\left(\\frac{\\partial S}{\\partial p}\\right)_T=-\\left(\\frac{\\partial V}{\\partial T}\\right)_p} \\] <p>\u7531\u6b64\u5f97\u5230\u56db\u4e2a\u5e38\u7528\u7684Maxwell\u5173\u7cfb\u3002\u5bf9\u4e8e\u8fd9\u56db\u4e2a\u5173\u7cfb\u7684\u8bb0\u5fc6\u548c\u4f7f\u7528\uff0c\u9700\u8981\u9996\u5148\u7406\u89e3\u5e76\u8bb0\u5fc6\u56db\u4e2a\u7279\u6027\u51fd\u6570\u7684\u5168\u5fae\u5206\u8868\u8fbe\u5f0f\uff0c\u5728\u6b64\u57fa\u7840\u4e0a\u77e5\u9053\u9ea6\u6c0f\u5173\u7cfb\u5bf9\u89d2\u5206\u522b\u662fp\u3001V\u548cT\u3001S\uff0c\u5e76\u4e14\u5206\u6bcd\u6216\u5206\u5b50\u4e0e\u504f\u5bfc\u56fa\u5b9a\u7684\u91cf\u8fdb\u884c\u4ea4\u6362\uff0c\u504f\u5bfc\u5206\u5b50\u5206\u6bcdp\u3001T\u540c\u53f7p\u3001S\u4e0d\u540c\u53f7\u3002\u6839\u636e\u4ee5\u4e0a\u6280\u5de7\uff0c\u4e0d\u96be\u8bb0\u4f4f\u56db\u5f0f\u3002</p> <p>\u2605 \u4e0b\u9762\u521d\u6b65\u5bf9\u4ee5\u4e0a\u5173\u7cfb\u5f0f\u8fdb\u884c\u5e94\u7528\uff0c\u6c42\u51fa\u70ed\u5bb9\u7684\u504f\u5bfc\u5f0f\u3002</p> <p>\u9996\u5148\u7531\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u548cS(T,V)\u7684\u5168\u5fae\u5206\u5c55\u5f00\u5f97\u5230\uff1a</p> \\[ dU=TdS-pdV\\qquad dS=\\left(\\frac{\\partial S}{\\partial T}\\right)_VdT+\\left(\\frac{\\partial S}{\\partial V}\\right)_TdV \\] <p>\u4e3a\u4e86\u4f7f\u57fa\u672c\u65b9\u7a0b\u4e2d\u7684\\(dS\\)\u53d8\u4e3a\\(dT\\)\uff0c\u5c06\\(dS\\)\u4ee3\u5165\u5f97\u5230\uff1a</p> \\[ dU=T\\left(\\frac{\\partial S}{\\partial T}\\right)_VdT+\\left[T\\left(\\frac{\\partial S}{\\partial V}\\right)_T-p\\right]dV \\] <p>\u6839\u636edU\u7684\u504f\u5bfc\u5f97\u5230\uff1a</p> \\[ \\left(\\frac{\\partial U}{\\partial T}\\right)_V=\\boxed{T\\left(\\frac{\\partial S}{\\partial T}\\right)_V=C_V}\\qquad \\left(\\frac{\\partial U}{\\partial V}\\right)_T=T\\left(\\frac{\\partial S}{\\partial V}\\right)_T-p \\] <p>\u5229\u7528\u9ea6\u6c0f\u5173\u7cfb\uff0c\u6d88\u53bb\u4e0d\u6613\u6d4b\u91cf\u7684S\uff0c\u5c06\u7b2c\u4e8c\u5f0f\u5316\u4e3a\u4e0a\u4e00\u7ae0\u6587\u732e\u4e2d\u7684\u516c\u5f0f\uff1a</p> \\[ \\boxed{\\left(\\frac{\\partial U}{\\partial V}\\right)_T=T\\left(\\frac{\\partial p}{\\partial T}\\right)_V-p} \\] <p>\u4e0a\u5f0f\u5373\u53ef\u6839\u636e\u7269\u6001\u65b9\u7a0b\u6c42\u51fa\u5185\u80fd\u5bf9\u4f53\u79ef\u7684\u4f9d\u8d56\u5173\u7cfb\uff0c\u8be6\u89c1\u524d\u4e00\u7ae0\u8282\u3002</p> <p>\u53e6\u4e00\u65b9\u9762\uff0c\u5982\u679c\u5c55\u5f00H(T,p)\u548cS(T,p),\u5e76\u5229\u7528\\(dH=TdS+Vdp\\)\u540c\u7406\u53ef\u4ee5\u5f97\u5230\uff1a</p> \\[ \\left(\\frac{\\partial H}{\\partial T}\\right)_p=\\boxed{T\\left(\\frac{\\partial S}{\\partial T}\\right)_p=C_p}\\qquad \\left(\\frac{\\partial H}{\\partial p}\\right)_T=T\\left(\\frac{\\partial S}{\\partial p}\\right)_T+V \\] <p>\u540c\u6837\u5229\u7528\u9ea6\u6c0f\u5173\u7cfb\u6d88\u53bbS\u5f97\u5230\uff1a</p> \\[ \\boxed{\\left(\\frac{\\partial H}{\\partial p}\\right)_T=-T\\left(\\frac{\\partial V}{\\partial T}\\right)_p+V} \\] <p>\u4e0a\u5f0f\u5373\u53ef\u6c42\u51fa\u7113\u5bf9\u538b\u5f3a\u7684\u4f9d\u8d56\u5173\u7cfb\uff0c\u6613\u5f97\u7406\u60f3\u6c14\u4f53\u7113\u4e0ep\u65e0\u5173\u3002</p> <p>\u4e0a\u8ff0\u65b9\u6cd5\u4e5f\u53ef\u9009\u62e9S(V,p)\u8fdb\u884c\uff0c\u7531\u6b64\u5f97\u5230U\u548cH\u5173\u4e8ep\u548cV\u53d8\u91cf\u7684\u504f\u5bfc\u5173\u7cfb\u3002\u518d\u6b21\u5229\u7528\u9ea6\u6c0f\u5173\u7cfb\u53ef\u4ee5\u5f97\u5230\u7edd\u70ed\u8fc7\u7a0b\u7684\u5fae\u5206\u65b9\u7a0b\u3002</p> <p>\u2605 \u6839\u636e\u4ee5\u4e0a\u5bfc\u51fa\u7684\u70ed\u5bb9\u504f\u5bfc\u5f0f\uff0c\u4e0d\u96be\u6c42\u51fa\u4e0a\u4e00\u7ae0\u5bfc\u51fa\u7684\\(C_p-C_V\\)\u8868\u8fbe\u5f0f\uff1a</p> \\[ C_p-C_V=T\\left(\\frac{\\partial S}{\\partial T}\\right)_p-T\\left(\\frac{\\partial S}{\\partial T}\\right)_V \\] <p>\u5229\u7528\u94fe\u5f0f\u6cd5\u5219\u5bf9S(T,V(T,p))\u8fdb\u884c\u504f\u5bfc(\u5bf9S(T,p(T,V))\u504f\u5bfc\u6548\u679c\u4e00\u6837)\uff1a</p> \\[ \\left(\\frac{\\partial S}{\\partial T}\\right)_p=\\left(\\frac{\\partial S}{\\partial T}\\right)_V+\\left(\\frac{\\partial S}{\\partial V}\\right)_T\\left(\\frac{\\partial V}{\\partial T}\\right)_p \\] <p>\u4ee3\u5165\uff0c\u5e76\u5229\u7528\u9ea6\u6c0f\u5173\u7cfb\u5f97\u5230\uff1a</p> \\[ \\boxed{C_p-C_V}=T\\left(\\frac{\\partial S}{\\partial V}\\right)_T\\left(\\frac{\\partial V}{\\partial T}\\right)_p=\\boxed{T\\left(\\frac{\\partial p}{\\partial T}\\right)_V\\left(\\frac{\\partial V}{\\partial T}\\right)_p} \\] <p>\u5728\u5b9e\u9645\u6d4b\u91cf\u4e2d\uff0c\u5bb9\u6613\u5f97\u5230\u7684\u662f\\(\\alpha\\)\u548c\\(\\kappa_T\\),\u56e0\u800c\u4e0a\u5f0f\u53ef\u6539\u5199\u4e3a\uff1a</p> \\[ \\left(\\frac{\\partial p}{\\partial V}\\right)_T \\left(\\frac{\\partial V}{\\partial T}\\right)_p \\left(\\frac{\\partial T}{\\partial p}\\right)_V=-1\\Rightarrow \\left(\\frac{\\partial p}{\\partial T}\\right)_V=\\frac{\\alpha}{\\kappa_T} \\] \\[ \\boxed{C_p-C_V=\\frac{TV\\alpha^2}{\\kappa_T}} \\] <p>\u2605 \u5bf9\u4e8e\u590d\u6742\u504f\u5bfc\u7684\u62fc\u51d1\uff0c\u5e38\u5e38\u7528\u5230\u96c5\u53ef\u6bd4\u884c\u5217\u5f0f\u7684\u6027\u8d28\u8fdb\u884c\u53d8\u6362\uff1a</p> \\[ \\left(\\frac{\\partial u}{\\partial x}\\right)_y=\\frac{\\partial(u,y)}{\\partial(x,y)}=-\\frac{\\partial(y,u)}{\\partial(x,y)}=\\frac{\\partial(u,y)\\partial(r,s)}{\\partial(r,s)\\partial(x,y)}=\\frac{1}{\\frac{\\partial(x,y)}{\\partial(u,y)}} \\] <p>\u7ec3\u4e60\u7528\u4ee5\u4e0a\u6027\u8d28\u8bc1\u660e\uff1a\\(\\frac{\\kappa_S}{\\kappa_T}=\\frac{C_V}{C_p}\\)\u548c\\(C_p-C_V=\\frac{TV\\alpha^2}{\\kappa_T}\\)</p> <p>\u5229\u7528\u96c5\u53ef\u6bd4\u884c\u5217\u5f0f\uff0c\u4e5f\u53ef\u5c06\u9ea6\u6c0f\u5173\u7cfb\u91cd\u65b0\u8868\u8fbe\uff1a</p> \\[ \\left(\\frac{\\partial T}{\\partial V}\\right)_S=-\\left(\\frac{\\partial p}{\\partial S}\\right)_V=\\frac{\\partial(T,S)}{\\partial(V,S)}=-\\frac{\\partial(p,V)}{\\partial(S,V)}\\Rightarrow\\boxed{\\frac{\\partial(p,V)}{\\partial(T,S)}=\\frac{\\partial(x,y)}{\\partial(x,y)}=1} \\] <p>\u5176\u4e2dx\uff0cy\u53ef\u4ee5\u5728(p,V)\u548c(T,S)\u4e2d\u4efb\u9009\u4e00\u4e2a\uff0c\u603b\u5171\u6709\u56db\u79cd\u7ec4\u5408\uff0c\u5373\u9ea6\u6c0f\u5173\u7cfb\u3002</p> <p>\u2605 \u6700\u540e\uff0c\u5229\u7528\u9ea6\u6c0f\u5173\u7cfb\u53ef\u4ee5\u5bfc\u51fa\\(C_V\\)\u548c\\(C_p\\)\u5728\u4e0d\u540c\u4f53\u79ef\u548c\u538b\u5f3a\u4e0b\u7684\u53d8\u5316\uff1a</p> \\[ \\boxed{\\left(\\frac{\\partial C_V}{\\partial V}\\right)_T}=T\\left[\\frac{\\partial }{\\partial V}\\left(\\frac{\\partial S}{\\partial T}\\right)_V\\right]_T=T\\left[\\frac{\\partial }{\\partial T}\\left(\\frac{\\partial S}{\\partial V}\\right)_T\\right]_V=\\boxed{T\\left(\\frac{\\partial^2 p}{\\partial T^2}\\right)_V} \\] \\[ \\boxed{\\left(\\frac{\\partial C_p}{\\partial p}\\right)_T}=T\\left[\\frac{\\partial }{\\partial p}\\left(\\frac{\\partial S}{\\partial T}\\right)_p\\right]_T=T\\left[\\frac{\\partial }{\\partial T}\\left(\\frac{\\partial S}{\\partial p}\\right)_T\\right]_p=\\boxed{-T\\left(\\frac{\\partial^2 V}{\\partial T^2}\\right)_p} \\] <p>\u4ece\u800c\u53ea\u8981\u77e5\u9053\u67d0\u4e00\u4f53\u79ef\u6216\u538b\u5f3a\u4e0b\u7684\u70ed\u5bb9\uff0c\u6839\u636e\u7269\u6001\u65b9\u7a0b\u5c31\u53ef\u4ee5\u6c42\u5f97\u4efb\u610f\u4f53\u79ef\u6216\u538b\u5f3a\u4e0b\u7684\u70ed\u5bb9\u3002</p>"},{"location":"chapter_02_uniform_system/02_characteristic_functions_gh.html","title":"\u7279\u6027\u51fd\u6570\u3001G-H\u65b9\u7a0b","text":""},{"location":"chapter_02_uniform_system/02_characteristic_functions_gh.html#g-h","title":"\u7279\u6027\u51fd\u6570\u3001G-H\u65b9\u7a0b","text":"<p>\u2605 \u6709\u4e86\u4ee5\u4e0a\u7684\u6570\u5b66\u57fa\u7840\uff0c\u8bd5\u60f3\u80fd\u4e0d\u80fd\u4ece\u53ef\u6d4b\u7684\u70ed\u5bb9\u548c\u7269\u6001\u65b9\u7a0b\u51fa\u53d1\uff0c\u5148\u5bfc\u51fa\u57fa\u672c\u70ed\u529b\u5b66\u91cf\uff0c\u518d\u5bfc\u51fa\u5176\u4ed6\u6240\u6709\u70ed\u529b\u5b66\u91cf\u5462\uff1f</p> <p>\u7531\u7269\u6001\u65b9\u7a0b\u548c\u5185\u80fdU\u7684\u5168\u5fae\u5206\u5373\u53ef\u5f97\u5230\uff1a</p> \\[ U=\\int\\left\\{C_VdT+\\left[T\\left(\\frac{\\partial p}{\\partial T}\\right)_V-p\\right]dV\\right\\} +U_0 \\] <p>\u518d\u6839\u636eS\u7684\u5168\u5fae\u5206\u5f97\u5230\uff1a</p> \\[ S=\\int\\left[\\frac{C_V}{T}dT+\\left(\\frac{\\partial p}{\\partial T}\\right)_VdV\\right]+S_0 \\] <p>(P.S.\u6ce8\u610f\\(dS=\\frac{dU}{T}+\\frac{pdV}{T}\\)\u5e76\u4e0d\u4e0e\u4e0a\u5f0f\u77db\u76fe\uff0c\u56e0\u4e3aU\u7684\u5168\u5fae\u5206\u8fd8\u6709\u4f53\u79ef\u9879)</p> <p>\u7c7b\u4f3c\u7684\u65b9\u6cd5\uff0cH\u548c\u7528\\(C_p\\)\u8868\u8fbe\u7684S\u4e5f\u4e0d\u96be\u5f97\u51fa\uff1a</p> \\[ H=\\int\\left\\{C_pdT+\\left[V-T\\left(\\frac{\\partial V}{\\partial T}\\right)_p\\right]dp\\right\\} +H_0 \\] \\[ S=\\int\\left[\\frac{C_p}{T}dT-\\left(\\frac{\\partial V}{\\partial T}\\right)_pdp\\right]+S_0 \\] <p>\u6839\u636eF\u548cG\u5b9a\u4e49\u5f0f\uff0c\u4ee3\u5165U(\u6216H)\u548cS\u7684\u8868\u8fbe\u5f0f\u5373\u53ef\u6c42\u5f97F\u548cG\uff0c\u8be6\u89c1G-H\u65b9\u7a0b\u3002\u7531\u4e8eG\u5728\u540e\u9762\u7684\u7ae0\u8282\u5341\u5206\u91cd\u8981\uff0c\u56e0\u800c\u8fd9\u91cc\u5199\u51fa\u7406\u60f3\u6c14\u4f53\u7684\u5409\u5e03\u65af\u51fd\u6570\u3002</p> \\[ G=H-TS=\\int C_pdT+H_0-T\\left(\\int \\frac{C_p}{T}dT-nRln(p)+S_0\\right) \\] <p>\u6839\u636e\\(\\frac{1}{T}\\int C_p dT=\\int \\frac{C_pdT}{T}+\\int d(\\frac{1}{T})\\int C_pdT\\)\u5f97\u5230\uff1a</p> \\[ G_m=-T\\int\\frac{dT}{T^2}\\int C_{p,m}dT+H_{m,0}-TS_{m,0}+RTln(p) \\] <p>\u901a\u5e38\u5199\u4f5c\u5982\u4e0b\u5f62\u5f0f\uff1a</p> \\[ \\boxed{G_m=RT[\\phi(T)+ln(p)]} \\] <p>\u2605 \u5229\u7528\u7279\u6027\u51fd\u6570\u53ef\u4ee5\u5c06\u4ee5\u4e0a\u4fe1\u606f\u6d53\u7f29\u4e3aU(S,V),H(S,p),F(T,V),G(T,p)\u4e2d\u7684\u4e00\u4e2a\uff0c\u518d\u6839\u636e\u6c42\u5bfc\u6570\u7684\u65b9\u5f0f\u5f97\u5230\u6240\u6709\u7684\u70ed\u529b\u5b66\u51fd\u6570\u3002\u4ee5U\u4e3a\u4f8b\u8fdb\u884c\u8bf4\u660e\u3002</p> <p>\u7531U(S,V)\u4ee3\u5165\\(\\left(\\frac{\\partial U}{\\partial S}\\right)_V=T\\)\u548c\\(\\left(\\frac{\\partial U}{\\partial V}\\right)_S=-p\\)\uff0c\u5206\u522b\u5f97\u5230S(T,V)\u548cp(S,V)\u3002\u518d\u5c06\u7ed3\u679c\u8054\u7acb\u6d88\u53bbS\u5f97\u5230P(T,V)\uff0c\u6700\u540e\u518d\u8054\u7acb\u6d88\u53bbU\u4e2d\u7684S\uff0c\u5373\u53ef\u5f97\u5230U(T,V)\u3002\u4ece\u800c\u5f97\u5230\u4e09\u4e2a\u57fa\u672c\u70ed\u529b\u5b66\u91cf\u3002\u5373\uff0c\u7279\u6027\u51fd\u6570\u8574\u542b\u4e86\u7269\u6001\u65b9\u7a0b\u3001\u5185\u80fd\u548c\u71b5\u3002</p> <p>\u2605 \u5728\u7531F\u5bfc\u51faU\u6216\u7531G\u5bfc\u51faH\u7684\u8fc7\u7a0b\u4e2d\uff0c\u96be\u514d\u8981\u4f7f\u7528G-H\u65b9\u7a0b\uff1a</p> \\[ F+TS=\\boxed{F-T\\left(\\frac{\\partial F}{\\partial T}\\right)_V=U}\\qquad G+TS=\\boxed{G-T\\left(\\frac{\\partial G}{\\partial T}\\right)_p=H} \\] <p>\u5229\u7528\u5b9a\u4e49\u5f0f\u548c\u9ea6\u6c0f\u5173\u7cfb\uff0c\u5bf9\u4e0a\u5f0f\u505a\u53d8\u5f62\u7684\u5f0f\u5b50\u5747\u4e3aG-H\u65b9\u7a0b\u3002\u4f8b\u5982\uff1a</p> \\[ U=H-pV=G-T\\left(\\frac{\\partial G}{\\partial T}\\right)_p-p\\left(\\frac{\\partial G}{\\partial p}\\right)_T \\] <p>\u25a0 \u5bf9\u4e8e\u4e00\u4e2a\u8868\u9762\u5f20\u529b\u7684\u7cfb\u7edf\uff0c\u7531\u4e8e\\(\\sigma(T)\\)\u4ec5\u4e3a\u6e29\u5ea6\u7684\u51fd\u6570\uff0c\u56e0\u800c\u7531\uff1a</p> \\[ dF=-SdT+\\sigma dA\\Rightarrow \\sigma(T)=\\left(\\frac{\\partial F}{\\partial A}\\right)_T\\Rightarrow F=\\sigma(T)A \\] <p>\u4e0a\u5f0f\u8003\u8651\u4e86\\(A=0\\)\u65f6\\(F=0\\)\uff0c\u6545\u65e0\u79ef\u5206\u5e38\u6570\u3002\u518d\u7531G-H\u65b9\u7a0b\u5f97\u5230\uff1a</p> \\[ U=A(\\sigma -T\\frac{d\\sigma}{dT}) \\]"},{"location":"chapter_02_uniform_system/03_joule_thomson.html","title":"\u8303\u6c0f\u6c14\u4f53\u8282\u6d41\u8fc7\u7a0b\u3001\u7126\u6c64\u7cfb\u6570","text":""},{"location":"chapter_02_uniform_system/03_joule_thomson.html#_1","title":"\u8303\u6c0f\u6c14\u4f53\u8282\u6d41\u8fc7\u7a0b\u3001\u7126\u6c64\u7cfb\u6570","text":"<p>\u2605 \u5bf9\u5e94\u4e0a\u4e00\u7ae0\u7684\u7126\u8033\u5b9e\u9a8c\u548c\u7126\u8033\u7cfb\u6570\uff0c\u8fd9\u91cc\u8ba8\u8bba\u540e\u7eed\u8fdb\u884c\u7684\u8282\u6d41\u8fc7\u7a0b\u7684\u5b9e\u9a8c\uff0c\u4ee5\u53ca\u5bf9\u5e94\u7684\u7126\u6c64\u7cfb\u6570\u3002\u6240\u8c13\u8282\u6d41\u8fc7\u7a0b\uff0c\u5373\u5c06\u591a\u5b54\u585e\u4e00\u7aef\u7684\u9ad8\u538b\u6c14\u4f53\u538b\u5411\u53e6\u4e00\u7aef\u4f4e\u538b\u7684\u533a\u57df\uff0c\u7814\u7a76\u6c14\u4f53\u7684\u6e29\u5ea6\u53d8\u5316\u3002</p> <p>\u8bbe\u8282\u6d41\u8fc7\u7a0b\u524d\u540e\u6c14\u4f53\u7684\u72b6\u6001\u53c2\u91cf\u4e3a\\((p_1,V_1,T_1,U_1,H_1)\\)\u548c\\((p_2,V_2,T_2,U_2,H_2)\\)\u7531\u4e8e\u591a\u5b54\u585e\u4e24\u7aef\u538b\u5f3a\u662f\u6052\u5b9a\u7684\uff0c\u5e76\u4e14\u6574\u4e2a\u4f53\u7cfb\u7edd\u70ed\uff0c\u56e0\u800c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ U_2-U_1=W=p_1V_1-p_2V_2\\Rightarrow \\boxed{H_1=H_2} \\] <p>\u6ce8\u610f\u6211\u4eec\u4ec5\u5173\u6ce8\u521d\u672b\u72b6\u6001\uff0c\u4e2d\u95f4\u7684\u8fc7\u7a0b\u5341\u5206\u590d\u6742\uff0c\u4e14\u5bf9\u72b6\u6001\u91cf\u65e0\u5f71\u54cd\u3002</p> <p>\u7531\u6b64\uff0c\u65e2\u7136\u6574\u4e2a\u8fc7\u7a0b\u662f\u7b49\u7113\u7684\uff0c\u51fa\u4e8e\u7814\u7a76\u6c14\u4f53\u6e29\u5ea6\u968f\u538b\u5f3a\u53d8\u5316\u7684\u76ee\u7684\uff0c\u4e0d\u59a8\u5f15\u5165\u7126\u6c64\u7cfb\u6570\\(\\mu\\):</p> \\[ \\mu=\\left(\\frac{\\partial T}{\\partial p}\\right)_H \\] <p>\u518d\u6839\u636e\\(f(H,T,p)=0\\)\u7684\u504f\u5bfc\u5173\u7cfb\u4ee5\u53ca\u4e0a\u4e00\u8282\u7684\u7ed3\u8bba\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ \\mu=-\\left(\\frac{\\partial T}{\\partial H}\\right)_p\\left(\\frac{\\partial H}{\\partial p}\\right)_T=-\\frac{1}{C_p}\\left(\\frac{\\partial H}{\\partial p}\\right)_T=\\boxed{\\frac{1}{C_p}\\left[T\\left(\\frac{\\partial V}{\\partial T}\\right)_p-V\\right]}=\\frac{V}{C_p}(T\\alpha-1) \\] <p>\u7531\u4e8e\\(C_p&gt;0\\)\u56e0\u800c\\(\\mu\\)\u7684\u6b63\u8d1f\u53d6\u51b3\u4e8e\\(T\\left(\\frac{\\partial V}{\\partial T}\\right)_p-V\\) .\u5e76\u79f0\\(\\mu&gt;0\\)\u7684\u533a\u57df\u4e3a\u5236\u51b7\u533a\uff0c\\(\\mu&lt;0\\)\u7684\u533a\u57df\u4e3a\u81f4\u6e29\u533a\uff0c\u56e0\u800c\u53cd\u8f6c\u66f2\u7ebf\\(\\mu=0\\)\u5341\u5206\u91cd\u8981\u3002\u7531\u4e8e\u7406\u60f3\u6c14\u4f53\u6052\u6709\\(\\mu=0\\)\u56e0\u800c\u6e29\u5ea6\u4e0d\u53d8\u5316\uff0c\u8fd9\u91cc\u5229\u7528\u8303\u6c0f\u6c14\u4f53\u8fdb\u884c\u63a8\u5bfc\u3002</p> <p>\u7531\\(\\mu=0\\)\u5f97\u5230\uff1a</p> \\[ T\\left(\\frac{\\partial V}{\\partial T}\\right)_p=V\\Rightarrow \\frac{8RTb}{a}=\\left(\\frac{b^2p}{a}+\\frac{3RTb}{2a}+1\\right)^2 \\] <p>\u5f97\u5230\u4e0a\u5f0f\u9700\u8981\u6bd4\u8f83\u590d\u6742\u7684\u6570\u5b66\u6280\u5de7\uff0c\u8be6\u89c1\u6797\u4e66p83.\u7531\u4e0a\u5f0f\u5373\u53ef\u753b\u51fap-T\u56fe\u4e2d\u7684\u53cd\u8f6c\u66f2\u7ebf\u3002\u5de5\u4e1a\u4e0a\u5e38\u5229\u7528\u6b64\u539f\u7406\u8fdb\u884c\u5236\u51b7\u64cd\u4f5c\u3002</p>"},{"location":"chapter_02_uniform_system/04_radiation_magnetic_media.html","title":"\u70ed\u8f90\u5c04\u3001\u78c1\u4ecb\u8d28\u7684\u70ed\u5b66\u6027\u8d28","text":""},{"location":"chapter_02_uniform_system/04_radiation_magnetic_media.html#_1","title":"\u70ed\u8f90\u5c04\u3001\u78c1\u4ecb\u8d28\u7684\u70ed\u5b66\u6027\u8d28","text":"<p>\u2605 \u5bf9\u4e8e\u70ed\u8f90\u5c04\u800c\u8a00\uff0c\u901a\u5e38\u5229\u7528\u9ed1\u4f53\u6a21\u578b\u8fdb\u884c\u8ba8\u8bba\uff0c\u5373\u7a7a\u7a96\u6a21\u578b\u3002\u5229\u7528\u70ed\u4e8c\u4e0d\u96be\u8bc1\u660e\uff0c\u7a7a\u7a96\u7684\u5185\u80fd\u5bc6\u5ea6\\(u=\\frac{U}{V}\\)\u4ec5\u662f\u6e29\u5ea6T\u7684\u51fd\u6570\uff0c\u4e0d\u968f\u7a7a\u7a96\u7684\u5176\u4ed6\u6027\u8d28\u53d1\u751f\u53d8\u5316\u3002\u4ece\u800c\u5f97\u5230\\(U(T,V)=u(T)V\\).</p> <p>\u6839\u636e\u7535\u52a8\u529b\u5b66\u4e2d\u7535\u78c1\u6ce2\u538b\u5f3ap\u4e0e\u80fd\u91cf\u5bc6\u5ea6u\u4e4b\u95f4\u7684\u5173\u7cfb\u2014\u2014\u7b80\u5355\u6765\u8bf4\uff0c\u8fd9\u6e90\u4e8e\u5149\u5b50\u7684\u80fd\u91cf\u52a8\u91cf\u5173\u7cfb\\(\\varepsilon=pc\\)\u4ee5\u53ca\u4e09\u7ef4\u7a7a\u95f4\u7684\u6d4b\u5ea6\uff0c\u5728\u7edf\u8ba1\u7269\u7406\u4e2d\u53ef\u7531\u538b\u5f3a\u7684\u5fae\u89c2\u8868\u8fbe\u5f0f\u5f97\u5230\uff0c\u8fd9\u91cc\u5148\u63a5\u53d7\u5373\u53ef\uff1a</p> \\[ p=\\frac{1}{3}u \\] <p>\u4e0a\u5f0f\u4e5f\u662f\u5149\u5b50\u6c14\u4f53\u7684\u201c\u7269\u6001\u65b9\u7a0b\u201d\u3002\u518d\u5229\u7528\u5185\u80fd\u5bf9\u4f53\u79ef\u7684\u4f9d\u8d56\u5173\u7cfb\u5f97\u5230\uff1a</p> \\[ \\left(\\frac{\\partial U}{\\partial V}\\right)_T=T\\left(\\frac{\\partial p}{\\partial T}\\right)_V-p\\Rightarrow \\boxed{u(T)=aT^4}\\Rightarrow U=aT^4V \\] <p>\u4e0d\u96be\u770b\u51fa\u538b\u5f3a\u548c\u6e29\u5ea6\u5e76\u4e0d\u72ec\u7acb\uff1a\\(p=\\frac{1}{3}aT^4\\),\u8fd9\u4e5f\u662f\u70ed\u8f90\u5c04\u7684\u72ec\u7279\u4e4b\u5904\u3002</p> <p>\u5bf9\u4e8e\u4f53\u7cfb\u7684\u71b5\u4e5f\u4e0d\u96be\u6c42\u5f97\uff1a</p> \\[ dS=\\frac{1}{T}(dU+pdV)=d(\\frac{4}{3}aT^3V)\\Rightarrow S=\\frac{4}{3}aT^3V \\] <p>\u4e0a\u5f0f\u8003\u8651\u5230\\(V=0\\)\u65f6\\(S=0\\)\uff0c\u6545\u65e0\u79ef\u5206\u5e38\u6570\u3002</p> <p>\u6709\u4e86\u5185\u80fd\u548c\u71b5\u7684\u8868\u8fbe\u5f0f\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ H=\\frac{4}{3}aT^4V\\qquad F=-\\frac{1}{3}aT^4V\\qquad G=0 \\] <p>\u5176\u4e2d\\(G=0\\)\u4f53\u73b0\u4e86\u7cfb\u7edf\u7c92\u5b50\u6570\u4e0d\u5b88\u6052\u7684\u7279\u6027\uff0c\u4e0b\u4e00\u7ae0\u5c06\u901a\u8fc7\u53d8\u5206\u8bf4\u660e\u8fd9\u4e00\u70b9\u3002\u5bf9\u4e8e\u7edd\u70ed\u8fc7\u7a0b\uff0c\u53ea\u9700\u4ee4\\(S=Const.\\)\u5373\u53ef\u5f97\u5230\u7edd\u70ed\u65b9\u7a0b\u3002</p> <p>\u7c7b\u6bd4\u5206\u5b50\u52a8\u7406\u8bba\u4e2d\u7684\u6c14\u4f53\u78b0\u58c1\u6570\\(\\Gamma\\)\uff0c\u70ed\u8f90\u5c04\u7cfb\u7edf\u4e5f\u53ef\u5f15\u5165\u8f90\u5c04\u901a\u91cf\u5bc6\u5ea6J\uff0c\u8868\u793a\u5355\u4f4d\u65f6\u95f4\u5355\u4f4d\u9762\u79ef\u901a\u8fc7\u7684\u8f90\u5c04\u80fd\u91cf\u3002\u7c7b\u6bd4\u4e25\u683c\u6c14\u4f53\u78b0\u58c1\u6570\\(\\Gamma=\\frac{1}{4}n\\bar{v}\\),\u8f90\u5c04\u901a\u91cf\u5bc6\u5ea6\\(J=\\frac{1}{4}cu\\),\u8bc1\u660e\u5982\u4e0b\uff1a</p> \\[ JdA=\\frac{cudA}{4\\pi}\\int \\cos(\\theta)d\\Omega=\\frac{cudA}{4\\pi}\\int_{0}^{\\frac{\\pi}{2}}\\sin(\\theta)\\cos(\\theta)d\\theta\\int_{0}^{2\\pi}d\\varphi =\\frac{1}{4}cudA \\] <p>\u4e0a\u5f0f\u53ef\u4ee5\u8fd9\u6837\u7406\u89e3\uff1a\u8f90\u5c04\u7531\u67d0\u4e00\u70b9\u53d1\u51fa\uff0c\u5448\u7403\u9762\u5411\u5916\u8f90\u5c04\uff0c\u5176\u4e2d\\(\\varphi \\)\u4e3a\u6e90\u70b9\u5230\u8f90\u5c04\u70b9\u8fde\u7ebf\u7684\u65cb\u8f6c\u8f74\u7684\u8f6c\u89d2\uff0c\u6545\u53d6\u503c\u5230\\(2\\pi\\)\u3002\u56e0\u4e3a\u6cbf\u67d0\u4e00\u65b9\u5411\u8f90\u5c04\u7684\u8d21\u732e\u4e3a\u534a\u4e2a\u7403\u9762\uff0c\u4ece\u800c\\(\\theta\\)\u53d6\u503c\u5230\\(\\frac{\\pi}{2}\\).\u7531\u6b64\u5f97\u5230Stefan-Boltzmann\u5b9a\u5f8b:</p> \\[ J=\\frac{1}{4}caT^4=\\sigma T^4 \\] <p>\u5229\u7528\u4e0a\u5f0f\u53ef\u4ee5\u901a\u8fc7\u6d4b\u91cf\u8f90\u5c04\u901a\u91cf\u5bc6\u5ea6\uff0c\u5f97\u5230\u7269\u4f53\u7684\u8868\u9762\u6e29\u5ea6\u3002</p> <p>\u2605 \u5bf9\u4e8e\u78c1\u4ecb\u8d28\u7684\u78c1\u5316\u7edd\u70ed\u8fc7\u7a0b\uff0c\u7531\u4e4b\u524d\u5bfc\u51fa\u7684\u975e\u4f53\u79ef\u529f\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ dU=TdS+Vd(\\frac{\\mu_0 H^2}{2})+\\mu_0 VHdM\\approx TdS+\\mu_0 Hdm \\] <p>\u4e0a\u5f0f\u5ffd\u7565\u4e86\u771f\u7a7a\u4e2d\u7684\u78c1\u573a\u5f3a\u5ea6\u53d8\u5316\u548c\u4f53\u79ef\u53d8\u5316\uff0c\u4ec5\u8003\u8651\u78c1\u5316\u5f3a\u5ea6\u7684\u53d8\u5316\u3002\u4e14\\(m=MV\\)\u4e3a\u603b\u78c1\u77e9\u3002\u7c7b\u6bd4\u4e4b\u524d\u7684\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\uff0c\u76f8\u5f53\u4e8e:</p> \\[ p\\rightarrow -\\mu_0H\\quad V\\rightarrow m \\] <p>\u7531\u6b64\u4e0d\u96be\u5f97\u5230\\(dG=-SdT-m\\mu_0dH\\)\u548c\u9ea6\u6c0f\u5173\u7cfb\\(\\left(\\frac{\\partial S}{\\partial H}\\right)_T=\\mu_0\\left(\\frac{\\partial m}{\\partial T}\\right)_H\\).</p> <p>\u7c7b\u6bd4\u4e4b\u524d\u5b9a\u5bb9\u70ed\u5bb9\u7684\u5b9a\u4e49\uff0c\u8fd9\u91cc\u53ef\u4ee5\u5b9a\u4e49\u5b9a\u78c1\u573a\u70ed\u5bb9\u3002\u4ece\u800c\u518d\u5229\u7528\u4e0a\u8ff0\u9ea6\u6c0f\u5173\u7cfb\u5c06\u6211\u4eec\u8981\u7814\u7a76\u7684\u6e29\u5ea6\u968f\u78c1\u573a\u53d8\u5316\u7684\u7edd\u70ed\u8fc7\u7a0b\uff0c\u8868\u8fbe\u4e3a\uff1a</p> \\[ C_H=T\\left(\\frac{\\partial S}{\\partial T}\\right)_H\\Rightarrow \\boxed{ \\left(\\frac{\\partial T}{\\partial H}\\right)_S}=-\\left(\\frac{\\partial T}{\\partial S}\\right)_H\\left(\\frac{\\partial S}{\\partial H}\\right)_T=\\boxed{-\\frac{T}{C_H}\\mu_0\\left(\\frac{\\partial m}{\\partial T}\\right)_H} \\] <p>\u518d\u4ee3\u5165\u5c45\u91cc\u5b9a\u5f8b\\(m=\\frac{CV}{T}H(C&gt;0)\\)\uff0c\u5f97\u5230\uff1a</p> \\[ \\boxed{\\left(\\frac{\\partial T}{\\partial H}\\right)_S=\\mu_0\\frac{CVH}{TC_H}} \\] <p>\u901a\u5e38\u4e0a\u5f0f\u4e3a\u975e\u8d1f\u7684\uff0c\u4ece\u800c\u53ef\u4ee5\u5229\u7528\u7edd\u70ed\u53bb\u78c1\u5316\u5236\u51b7\u3002\u6ce8\u610f\uff0c\u8fd9\u91cc\u7684\u7ed3\u8bba\u6765\u81ea\u4e8e\u5c45\u91cc\u5b9a\u5f8b\uff0c\u5f53\u78c1\u573a\u8fc7\u5f3a\u4f1a\u4ea7\u751f\u5176\u4ed6\u6548\u5e94\u3002</p> <p>\u2605 \u73b0\u5728\u6211\u4eec\u5c1d\u8bd5\u8003\u8651\u78c1\u4ecb\u8d28\u4f53\u79ef\u7684\u53d8\u5316\uff0c\u5185\u80fd\u548c\u5409\u5e03\u65af\u51fd\u6570\u7684\u5fae\u5206\u5f0f\u4e3a\uff1a</p> \\[ dU=TdS+\\mu_0 Hdm-pdV\\Rightarrow dG=-SdT-\\mu_0mdH+Vdp \\] <p>\u4ece\u800c\u5f97\u5230\u9ea6\u6c0f\u5173\u7cfb\uff1a</p> \\[ \\left(\\frac{\\partial V}{\\partial H}\\right)_{p,T}=-\\mu_0\\left(\\frac{\\partial m}{\\partial p}\\right)_{H,T} \\] <p>\u4e0a\u5f0f\u5de6\u53f3\u8054\u7cfb\u4e86\u78c1\u81f4\u4f38\u7f29\u6548\u5e94\u548c\u538b\u78c1\u6548\u5e94\uff0c</p>"},{"location":"chapter_03_phase_transition/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_03_phase_transition/index.html#3","title":"\u7b2c3\u7ae0 \u5355\u5143\u4f53\u7cfb\u76f8\u53d8","text":"<p>\u719f\u6089\u4e86\u70ed\u529b\u5b66\u7684\u57fa\u672c\u6982\u5ff5\u548c\u6570\u5b66\u65b9\u6cd5\u7684\u57fa\u672c\u64cd\u4f5c\u4e4b\u540e\uff0c\u672c\u7ae0\u4e3b\u8981\u662f\u5229\u7528\u53d8\u5206\u7684\u65b9\u6cd5\u7814\u7a76\u5355\u5143\u4f53\u7cfb\u7684\u70ed\u52a8\u5e73\u8861\u548c\u76f8\u53d8\u95ee\u9898(\u5bf9\u4e8e\u5355\u5143\u7cfb\uff0c\u6ca1\u6709\u5316\u5b66\u5e73\u8861\u7684\u95ee\u9898)\u3002\u501f\u7528\u5206\u6790\u529b\u5b66\u4e2d\u7684\u53d8\u5206\u6280\u5de7\u7814\u7a76\u70ed\u529b\u5b66\u5e73\u8861\u548c\u7a33\u5b9a\u7684\u786e\u5341\u5206\u6709\u8da3\uff0c\u76f8\u53d8\u95ee\u9898\u8fd8\u6d89\u53ca\u5230\u8bb8\u591a\u524d\u6cbf\u95ee\u9898\uff0c\u70ed\u529b\u5b66\u4ece\u8fd9\u4e00\u7ae0\u5f00\u59cb\u6709\u8da3\u8d77\u6765\u4e86\u3002</p>"},{"location":"chapter_03_phase_transition/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u70ed\u52a8\u5e73\u8861\u5224\u636e</li> <li>\u5316\u5b66\u52bf\u7684\u5f15\u5165\u3001\u5e73\u8861\u5224\u636e\u3001\u7a33\u5b9a\u5e73\u8861\u5224\u636e</li> <li>\u514b\u62c9\u4f2f\u9f99\u65b9\u7a0b</li> <li>Maxwell\u7b49\u9762\u79ef\u89c4\u5219\u3001\u8303\u6c0f\u6c14\u4f53\u4e34\u754c\u70b9\u4f4d\u7f6e</li> <li>\u6db2\u6ef4\u7684\u5f62\u6210</li> <li>\u6717\u9053\u8fde\u7eed\u76f8\u53d8\u7406\u8bba\uff08\u6c42\u4e34\u754c\u6307\u6570\uff09</li> </ul>"},{"location":"chapter_03_phase_transition/01_thermal_equilibrium_criteria.html","title":"\u70ed\u52a8\u5e73\u8861\u5224\u636e","text":""},{"location":"chapter_03_phase_transition/01_thermal_equilibrium_criteria.html#_1","title":"\u70ed\u52a8\u5e73\u8861\u5224\u636e","text":"<p>\u2605 \u6839\u636e\u71b5\u589e\u539f\u7406\uff0c\u5b64\u7acb\u7cfb\u7edf\u7684\u71b5\u53ea\u589e\u4e0d\u51cf\uff0c\u4ece\u800c\u7cfb\u7edf\u8fbe\u5230\u5e73\u8861\u6001\u65f6\uff0c\u71b5\u5fc5\u7136\u6700\u5927\u3002\u5229\u7528\u8fd9\u4e00\u7279\u6027\uff0c\u5f53\u7cfb\u7edf\u5904\u4e8e\u5e73\u8861\u6001\u65f6\u7ed9\u4e88\u7cfb\u7edf\u4e00\u4e2a\u865a\u53d8\u52a8\uff0c\u4e00\u5b9a\u6709\uff1a</p> \\[ \\tilde{\\Delta}S=S(x_1+\\delta x_1,...,x_n+\\delta x_n)-S(x_1,...,x_n)&lt;0 \\] <p>\u6ce8\u610f\u4e0a\u5f0f\\(\\tilde{\\Delta}\\)\u8868\u793a\u71b5\u7684\u865a\u53d8\u52a8\uff0c\u5e76\u4e0d\u662f\u5b9e\u9645\u53d1\u751f\u7684\u8fc7\u7a0b\u3002\u5229\u7528\u6cf0\u52d2\u5c55\u5f00\u53ef\u4ee5\u5199\u4e3a\u66f4\u8be6\u7ec6\u7684\u5f62\u5f0f\uff1a</p> \\[ \\begin{array}{l} \\left\\{\\begin{matrix} \\tilde{\\Delta}S&amp;=&amp;\\delta S+ \\frac{1}{2!}\\delta^2 S+\\frac{1}{3!}\\delta^3S+...\\\\ \\delta S&amp;=&amp;\\sum_{i=1}^{n}\\left(\\frac{\\partial S}{\\partial x_i}\\right)\\delta x_i\\\\ \\delta^2S&amp;=&amp;\\sum_{i,j} \\left(\\frac{\\partial^2S}{\\partial x_i\\partial x_j}\\right)\\delta x_i \\delta x_j\\\\ ...&amp;=&amp;... \\end{matrix}\\right. \\end{array} \\] <p>\u6839\u636e\u71b5\u53d6\u6781\u503c\uff0c\u6545\u6709\\(\\delta S=0\\),\u5f97\u5230\u5e73\u8861\u6761\u4ef6\u3002\u71b5\u53d6\u6781\u5927\u6709\\(\\delta^2S&lt;0\\),\u5f97\u5230\u7a33\u5b9a\u6761\u4ef6\u3002\u6b64\u5916\u6839\u636e\u5b64\u7acb\u7cfb\u7edf\u7684\u6027\u8d28\uff0c\u7cfb\u7edf\u7684\u5185\u80fd\u3001\u4f53\u79ef\u3001\u7c92\u5b50\u6570\u90fd\u4e0d\u53d8\u3002\u4ece\u800c\u6709\uff1a</p> \\[ \\begin{array}{l} \\left\\{\\begin{matrix} \\delta S=0\\\\ \\delta^2 S&lt;0\\\\ \\delta U=0\\quad\\delta V=0\\quad \\delta N=0 \\end{matrix}\\right. \\end{array} \\] <p>\u4ee5\u4e0a\u4e3a\u5b64\u7acb\u7cfb\u7edf\u7684\u71b5\u5224\u636e\u7684\u53d8\u5206\u8868\u8fbe\u5f62\u5f0f\u3002\u6ce8\u610f\u8fd9\u91cc\u4ec5\u5f97\u5230\u71b5\u53d6\u6781\u5927\u503c\u7684\u6761\u4ef6\uff0c\u5e76\u6ca1\u6709\u533a\u5206\u51fa\u662f\u7a33\u5b9a\u8fd8\u662f\u4e9a\u7a33\u5e73\u8861\u3002\u6b64\u5916\uff0c\u7814\u7a76\u4e34\u754c\u6001\u65f6\u9700\u8981\u5206\u6790\u66f4\u591a\u7684\\(\\delta^nS\\)\uff0c\u901a\u5e38\u6839\u636e\u5947\u5076\u6027\uff0c\u65ad\u5b9a\\(\\delta^{2n-1}S=0\\)\u548c\\(\\delta^{2n}S&lt;0\\).\u4e4b\u540e\u7684\u5176\u4ed6\u5224\u636e\u4e5f\u7c7b\u4f3c\u3002</p> <p>\u2605 \u6839\u636e\u4ee5\u4e0a\u7684\u601d\u60f3\u6307\u5bfc\uff0c\u5229\u7528\u7b49\u6e29\u7b49\u5bb9\\(F=F_{min}\\)\u548c\u7b49\u6e29\u7b49\u538b\\(G=G_{min}\\)\u7684\u5e73\u8861\u6761\u4ef6,\u5f97\u5230\uff1a</p> \\[ \\begin{array}{l} \\left\\{\\begin{matrix} \\delta F=0\\\\ \\delta^2 F&gt;0\\\\ \\delta T=0\\quad\\delta V=0\\quad \\delta N=0 \\end{matrix}\\right. \\end{array} \\qquad \\begin{array}{l} \\left\\{\\begin{matrix} \\delta G=0\\\\ \\delta^2 G&gt;0\\\\ \\delta T=0\\quad\\delta p=0\\quad \\delta N=0 \\end{matrix}\\right. \\end{array} \\] <p>\u5f53\u7136\u4e5f\u53ef\u5bfc\u51fa\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\u7684\u5224\u636e\uff0c\u901a\u5e38\u5229\u7528\\(\\boxed{\\delta U\\leqslant T\\delta S-p\\delta V}\\),\u5728\u89c4\u5b9a\u67d0\u4e9b\u91cf\u4e0d\u53d8\u7684\u60c5\u51b5\u4e0b\uff0c\u5bf9\u4e0d\u7b49\u5f0f\u8fdb\u884c\u6784\u9020\u5bfc\u51fa\u865a\u53d8\u52a8\u8d8b\u52bf\uff0c\u4ece\u800c\u63a8\u65ad\u51fa\u5e73\u8861\u6761\u4ef6\u3002</p>"},{"location":"chapter_03_phase_transition/02_chemical_potential_stability.html","title":"\u5316\u5b66\u52bf\u7684\u5f15\u5165\u3001\u5e73\u8861\u5224\u636e\u3001\u7a33\u5b9a\u5e73\u8861\u5224\u636e","text":""},{"location":"chapter_03_phase_transition/02_chemical_potential_stability.html#_1","title":"\u5316\u5b66\u52bf\u7684\u5f15\u5165\u3001\u5e73\u8861\u5224\u636e\u3001\u7a33\u5b9a\u5e73\u8861\u5224\u636e","text":"<p>\u2605 \u8003\u8651\u4e00\u4e2a\u5f00\u653e\u5747\u5300\u7684\u7cfb\u7edf\uff0c\u5bf9\u4e8e1mol\u7684\u5185\u80fd\\(du=Tds-pdv\\),\u4e0e\u603b\u91cf\u4e4b\u95f4\u7684\u5173\u7cfb\u4e3a\\(U=nu,S=ns,V=nv\\),\u53d6\u5fae\u5206\u5f97\u5230\uff1a</p> \\[ dU=udn+ndu=udn+Tnds-pndv=(u-Ts+pv)dn+TdS-pdV \\] <p>\u4e0a\u5f0f\u7528\u5230\u4e86\\(dS=sdn+nds,dV=vdn+ndv\\).\u4ee4\u5316\u5b66\u52bf\\(\\boxed{\\mu=u-Ts+pv}\\),\u5373\u6469\u5c14\u5409\u5e03\u65af\u51fd\u6570.\u4ece\u800c\u53ef\u5c06\u5f00\u653e\u7cfb\u7edf\u7684\u57fa\u672c\u70ed\u529b\u5b66\u65b9\u7a0b\u5199\u4f5c\uff1a</p> \\[ \\boxed{dU=TdS-pdV+\\mu dn} \\] <p>\u5bf9\u4e8e\u53e6\u59163\u4e2a\u5e38\u7528\u7279\u6027\u51fd\u6570\u7684\u5fae\u5206\u5f0f\uff0c\u53ea\u8981\u76f4\u63a5\u52a0\u4e0a\\(\\mu dn\\)\u9879\u5373\u53ef\uff0c\u56e0\u4e3a\u5176\u5b9a\u4e49\u5f0f\u4e2d\u672a\u6d89\u53ca\u7c92\u5b50\u6570\u3002\u56e0\u800c\u6709\uff1a</p> \\[ \\mu=\\left(\\frac{\\partial U}{\\partial n}\\right)_{S,V}=\\left(\\frac{\\partial H}{\\partial n}\\right)_{S,p}=\\left(\\frac{\\partial F}{\\partial n}\\right)_{T,V}=\\left(\\frac{\\partial G}{\\partial n}\\right)_{T,p} \\] <p>\u6b64\u5916\u8fd8\u53ef\u5b9a\u4e49\u5de8\u52bf\u51fd\u6570\\(\\boxed{J=F-\\mu n=F-G}\\)\u4ece\u800c:</p> \\[ dJ=-SdT-pdV-nd\\mu \\] <p>\u7edf\u8ba1\u7269\u7406\u4e2d\u7684\u5de8\u914d\u5206\u51fd\u6570\u4f1a\u6d89\u53ca\u3002</p> <p>\u2605 \u73b0\u5728\u6211\u4eec\u5229\u7528\u71b5\u5224\u636e\uff0c\u63a8\u5bfc\\(\\phi\\)\u76f8\u5b64\u7acb\u7cfb\u7edf\u7684\u5e73\u8861\u5224\u636e\u3002\u901a\u5e38\u7684\u65b9\u6cd5\u662f\u62c9\u683c\u6717\u65e5\u4e58\u5b50\u6cd5\u3002\u8fd9\u91cc\u5f15\u5165\u4e58\u5b50\u6240\u9644\u52a0\u7684\u7ea6\u675f\u4e3a\uff1a\\(U=\\sum n_iu_i,V=\\sum n_iv_i,n=\\sum n_i\\)\u90fd\u4e3a\u5b9a\u503c\uff0c\u4ece\u800c\u5f97\u5230(\u6c42\u548c\u9ed8\u8ba4i=1,...,\\(\\phi\\))\uff1a</p> \\[ \\delta U=\\sum u_i\\delta n_i+n_i\\delta u_i=0\\quad\\delta V=\\sum v_i\\delta n_i+n_i\\delta v_i=0\\quad\\delta n=\\sum \\delta n_i=0 \\] <p>\u518d\u6839\u636e\u6469\u5c14\u71b5\u53d8\u548c\\(S=\\sum n_is_i\\):</p> \\[ \\delta s_i=\\frac{\\delta u_i}{T_i}+\\frac{p_i\\delta v_i}{T_i}\\qquad\\delta S=\\sum s_i\\delta n_i+n_i\\delta s_i \\] <p>\u6700\u540e\u5229\u7528\u62c9\u683c\u6717\u65e5\u4e58\u5b50\u6cd5\uff0c\u5e76\u4e14\u4e3a\u4e86\u65b9\u4fbf\u5206\u522b\u8bbe\u4e58\u5b50\u4e3a\\(-\\frac{1}{T},-\\frac{p}{T},\\frac{\\mu}{T}\\)\uff0c\u7531\\(\\tilde{\\delta}S=0\\):</p> \\[ \\tilde{\\delta}S=\\delta S-\\frac{\\delta U}{T}-\\frac{p\\delta V}{T}+\\frac{\\mu\\delta n}{T}=0 \\] <p>\u4ee3\u5165\u5404\u5f0f\uff0c\u5e76\u5316\u4e3a\u4ee5\\(\\delta u_i,\\delta v_i,\\delta n_i\\)\u4e09\u4e2a\u72ec\u7acb\u53d8\u91cf\u7684\u5f62\u5f0f\uff1a</p> \\[ \\tilde{\\delta} S=\\sum n_i\\left(\\frac{1}{T_i}-\\frac{1}{T}\\right)\\delta u_i+\\sum n_i\\left(\\frac{p_i}{T_i}-\\frac{p}{T}\\right)\\delta v_i+\\sum\\left(\\frac{\\mu}{T}-\\frac{\\mu_i}{T_i}\\right)\\delta n_i=0 \\] <p>\u4ece\u800c\u5f97\u5230\uff0c\u5e73\u8861\u5224\u636e(\u5206\u522b\u5bf9\u5e94\u70ed\u5e73\u8861\u3001\u529b\u5b66\u5e73\u8861\u3001\u76f8\u5e73\u8861)\uff1a</p> \\[ \\boxed{T_i=T\\qquad p_i=p\\qquad \\mu_i=\\mu} \\] <p>\u4ee5\u4e0a\u5bf9\u4e8e\u5b64\u7acb\u7cfb\u7edf\u4e2d\\(\\phi\\)\u4e2a\u76f8\u90fd\u6210\u7acb\uff0c\u5f53\\(\\phi=2\\)\u4ee5\u4e0a\u63a8\u5bfc\u53ef\u4ee5\u7b80\u5316\u8bb8\u591a\u3002</p> <p>\u5982\u679c\u4e0d\u6ee1\u8db3\u5e73\u8861\u5224\u636e\uff0c\u5229\u7528\\(\\delta S&gt;0\\)\u7684\u53d1\u5c55\u8d8b\u52bf\uff0c\u4e0d\u96be\u5f97\u5230\uff1a(1)\\(T_i&gt;T\\Rightarrow \\delta u_i&lt;0\\),\u5373\u80fd\u91cf\u4ece\u9ad8\u6e29\u76f8\u4f20\u5411\u4f4e\u6e29(2)\\(p_i&gt;p\\Rightarrow \\delta v_i&gt;0\\),\u5373\u538b\u5f3a\u5927\u7684\u5c06\u81a8\u80c0\uff0c\u5c0f\u7684\u5c06\u6536\u7f29(3)\\(\\mu_i&gt;\\mu\\Rightarrow \\delta n_i&lt;0\\),\u5373\u5316\u5b66\u52bf\u9ad8\u7684\u4f1a\u5411\u5316\u5b66\u52bf\u4f4e\u7684\u8f6c\u5316\u3002\u6b64\u5916\uff0c\u53ef\u4ee5\u770b\u51fa\u5e73\u8861\u5224\u636e\u5747\u4e3a\u5f3a\u5ea6\u91cf\u3002</p> <p>\u5bf9\u4e8e\u67d0\u4e9b\u7c92\u5b50\u6570\u4e0d\u53d7\u5b88\u6052\u7ea6\u675f\u7684\u4f53\u7cfb\uff0c\u82e5\u8be5\u7c92\u5b50\u6570\u53ef\u4ee5\u72ec\u7acb\u53d8\u5316\u4e14\u6ca1\u6709\u989d\u5916\u7ea6\u675f\u9879\uff0c\u5219\u5e73\u8861\u65f6\u76f8\u5e94\u5316\u5b66\u52bf\u4e3a0\uff0c\u5178\u578b\u4f8b\u5b50\u662f\u5149\u5b50\u6c14\u4f53\u7684\\(\\mu=0\\)\u3002\u4f46\u5bf9\u4e00\u822c\u5316\u5b66\u53cd\u5e94\u4f53\u7cfb\uff0c\u7c92\u5b50\u6570\u53d8\u5316\u4ecd\u53d7\u5316\u5b66\u8ba1\u91cf\u5173\u7cfb\u7ea6\u675f\uff0c\u4e0d\u80fd\u7b80\u5355\u63a8\u51fa\u6bcf\u4e2a\u7ec4\u5206\u7684\u5316\u5b66\u52bf\u90fd\u4e3a0\u3002</p> <p>\u2605 \u6700\u540e\u8ba8\u8bba\u7a33\u5b9a\u5e73\u8861\u5224\u636e\u3002\u5229\u7528\\(\\delta^2S&lt;0\\)\u7ecf\u8fc7\u590d\u6742\u7684\u63a8\u5bfc\u5f97\u5230\uff1a</p> \\[ \\delta^2 S=-\\frac{C_V}{T^2}(\\delta T)^2+\\frac{1}{T}\\left(\\frac{\\partial p}{\\partial V}\\right)_T(\\delta V)^2&lt;0 \\] <p>\u4ece\u800c\u5f97\u5230\u7a33\u5b9a\u5e73\u8861\u5224\u636e\uff1a</p> \\[ \\boxed{C_V&gt;0\\qquad\\left(\\frac{\\partial p}{\\partial V}\\right)_T&lt;0} \\] <p>\u4e0a\u5f0f\u8868\u660e\u4e00\u79cd\u201c\u8d1f\u53cd\u9988\u201d\u673a\u5236\uff0c\u4e5f\u662f\u52d2\u590f\u7279\u5217\u539f\u7406\u7684\u6838\u5fc3\u3002</p>"},{"location":"chapter_03_phase_transition/03_clapeyron_equation.html","title":"\u514b\u62c9\u4f2f\u9f99\u65b9\u7a0b","text":""},{"location":"chapter_03_phase_transition/03_clapeyron_equation.html#_1","title":"\u514b\u62c9\u4f2f\u9f99\u65b9\u7a0b","text":"<p>\u2605 \u8003\u8651\u7b80\u5355\u7cfb\u7edf\u7684\u76f8\u53d8\uff0c\u6c14\u6db2\u901a\u5e38\u53ea\u6709\u4e00\u4e2a\u76f8\u3001\u56fa\u4f53\u901a\u5e38\u53ef\u4ee5\u6709\u591a\u4e2a\u76f8\u3002\u6839\u636e\u4e0d\u540c\u7684\u76f8\uff0c\u5c06p-T\u56fe\u8fdb\u884c\u533a\u57df\u5212\u5206\u79f0\u4e3a\u76f8\u56fe\uff0c\u5982\u4e0b\u56fe\u6240\u793a\u3002</p> <p></p> <p>\u5176\u4e2d\u4e09\u76f8\u70b9\u4e3a\u56fa\u6db2\u6c14\u4e09\u76f8\u5e73\u8861\u5171\u5b58\u7684\u72b6\u6001\u70b9\uff0c\u4e34\u754c\u70b9\u4e3a\u6c14\u6001\u4e0e\u6db2\u6001\u65e0\u6cd5\u533a\u5206\u7684\u4e34\u754c\u72b6\u6001\u70b9\u3002\u4ece\u67d0\u4e00\u76f8\uff0c\u8d8a\u8fc7\u66f2\u7ebf\u53d1\u751f\u76f8\u53d8\uff0c\u4f1a\u653e\u51fa\u6216\u5438\u6536\u6240\u8c13\u76f8\u53d8\u6f5c\u70ed\u3002\u6ce8\u610f\uff0c\u5728\u67d0\u4e00\u76f8\u533a\u57df\u5185\uff0c\u5176\u4ed6\u76f8\u4ecd\u7136\u53ef\u4ee5\u901a\u8fc7\u6da8\u843d\u800c\u5b58\u5728\uff0c\u53ea\u662f\u5316\u5b66\u52bf\u8fc7\u5c0f\u3002\u5f53\u67d0\u4e24\u76f8\u5316\u5b66\u52bf\u76f8\u7b49\u65f6\uff0c\u5c31\u4f1a\u5f62\u6210p-T\u56fe\u4e0a\u7684\u76f8\u5e73\u8861\u66f2\u7ebf\u3002\u56e0\u800c\uff0c\u5206\u6790\u76f8\u53d8\u65f6\u5316\u5b66\u52bf\u8d77\u5230\u5341\u5206\u5173\u952e\u7684\u4f5c\u7528\u3002</p> <p>\u8003\u8651\u4e24\u79cd\u76f8\\(\\alpha\\)\u548c\\(\\beta\\)\u4e4b\u95f4\u7684\u5e73\u8861\uff0c\u6839\u636e\u5e73\u8861\u5224\u636e\uff0c\u4e24\u76f8\u5fc5\u987b\u6ee1\u8db3\\(T,p,\\mu\\)\u76f8\u7b49\uff0c\u4ece\u800c\u5316\u5b66\u52bf\u7684\u5fae\u5206\u4e5f\u8981\u6ee1\u8db3\\(d\\mu^\\alpha=d\\mu^\\beta\\),\u4ece\u800c\uff1a</p> \\[ -s^\\alpha dT+v^\\alpha dp=-s^\\beta dT+v^\\beta dp\\Rightarrow \\frac{dp}{dT}=\\frac{s^\\beta-s^\\alpha}{v^\\beta-v^\\alpha } \\] <p>\u901a\u5e38\u76f8\u53d8\u70b9\u5904\u8fdb\u884c\u7684\u662f\u53ef\u9006\u7684\u7b49\u6e29\u7b49\u538b\u8fc7\u7a0b\uff0c\u5e76\u4e14\u76f8\u53d8\u6f5c\u70ed\\(L=\\Delta H=Q\\)\u548c\\(\\Delta v\\)\u662f\u5bb9\u6613\u6d4b\u91cf\u7684\uff0c\u5229\u7528\u53ef\u9006\u76f8\u53d8\u7684\u6027\u8d28\u5f97\u5230\uff1a</p> \\[ L=\\int Tds=T(s^\\beta-s^\\alpha)\\Rightarrow \\boxed{\\frac{dp}{dT}=\\frac{L}{T(v^\\beta-v^\\alpha)}} \\] <p>\u4e0a\u5f0f\u5373\u514b\u62c9\u4f2f\u9f99\u65b9\u7a0b,\u7528\u4e8e\u63cf\u8ff0\u76f8\u53d8\u66f2\u7ebf\u7684\u659c\u7387\u3002\u6ce8\u610f\u6b64\u65b9\u7a0b\u7684\u9002\u7528\u6761\u4ef6\u662f\u4e00\u7ea7\u76f8\u53d8\uff0c\u5373\u5409\u5e03\u65af\u51fd\u6570(\u5316\u5b66\u52bf)\u8fde\u7eed\uff0c\u800c\u5176\u4e00\u9636\u5bfc\u4e0d\u8fde\u7eed(\u71b5\u548c\u4f53\u79ef\u6709\u4e00\u4e2a\u8dc3\u53d8)\u3002\u57fa\u4e8e\u6b64\uff0c\u53ef\u4ee5\u5b9a\u4e49\u51fa\\(n\\)\u7ea7\u76f8\u53d8\uff0c\u5373\u5409\u5e03\u65af\u51fd\u6570\u4ece\\(n\\)\u9636\u5bfc\u5f00\u59cb\u7a81\u53d8\u7684\u76f8\u53d8\u8fc7\u7a0b\u3002\u5bf9\u4e8e\u4e8c\u7ea7\u76f8\u53d8\uff0c\u7531\u4e8e\u71b5\u548c\u4f53\u79ef\u4e0d\u53d8\uff0c\u56e0\u800c\u51fa\u73b0\\(0/0\\)\u4e0d\u5b9a\u578b\uff0c\u5229\u7528\u6d1b\u5fc5\u8fbe\u6cd5\u5219\u5bf9\\(T\\)\u548c\\(p\\)\u6c42\u5bfc\u5f97\u5230\uff1a</p> \\[ \\boxed{\\frac{dp}{dT}=\\frac{\\alpha^{(2)}-\\alpha^{(1)}}{\\kappa_T^{(2)}-\\kappa_{T}^{(1)}}=\\frac{c_p^{(2)}-c_p^{(1)}}{Tv(\\alpha^{(2)}-\\alpha^{(1)})}} \\] <p>\u4e0a\u5f0f\u4e3aEhrenfest\u65b9\u7a0b\uff0c\u5229\u7528\u5728\u4e8c\u7ea7\u76f8\u53d8\u4e2d\u7684\u7a81\u53d8\u7684\u54cd\u5e94\u91cf\u548c\u70ed\u5bb9\u6765\u8868\u8fbe\u3002</p> <p>\u2605 \u518d\u56de\u5230\u514b\u62c9\u4f2f\u9f99\u65b9\u7a0b\uff0c\u8c08\u53ca\u4e00\u4e9b\u5e94\u7528\u95ee\u9898\u3002\u4f8b\u5982\uff0c\u7531\u4e8e\u51b0\u7684\u6469\u5c14\u4f53\u79ef\u6bd4\u6c34\u7684\u5927\uff0c\u4e14\u4ece\u6c34\u5230\u51b0\u7684\u76f8\u53d8\u8981\u653e\u51fa\u70ed\u91cf\uff0c\u4ece\u800c\\(\\frac{dp}{dT}&lt;0\\).\u5373\u538b\u5f3a\u548c\u76f8\u53d8\u7684\u6e29\u5ea6\u8d1f\u76f8\u5173\uff0c\u4ece\u800c\u6ed1\u51b0\u65f6\u51b0\u5200\u7ed9\u4e88\u7684\u9ad8\u538b\u5f3a\u4f1a\u4f7f\u51b0\u7194\u70b9\u4e0b\u964d\uff0c\u4ece\u800c\u76f8\u53d8\u4e3a\u6c34\u964d\u4f4e\u6469\u64e6\u7cfb\u6570\u3002</p> <p>\u6b64\u5916\uff0c\u5bf9\u4e8e\u76f8\u53d8\u6f5c\u70ed\u968f\u6e29\u5ea6\u53d8\u5316\u7684\u95ee\u9898\uff0c\u7531\u51dd\u805a\u76f8\\(\\alpha\\)\u5230\u84b8\u6c14\u76f8\\(\\beta\\),\u6839\u636e\u7b49\u538b\u7684\u6761\u4ef6\u6709\uff1a</p> \\[ \\left(\\frac{\\partial L}{\\partial T}\\right)_p=\\left(\\frac{\\partial \\Delta h}{\\partial T}\\right)_p=c_p^\\beta-c_p^\\alpha\\Rightarrow L=\\int(c_p^\\beta-c_p^\\alpha)dT+L_0 \\] <p>\u4e0a\u5f0f\u9ed8\u8ba4\u7b49\u538b\u6761\u4ef6\uff0c\u8fd9\u4e5f\u5c31\u4e0e\u7269\u7406\u5316\u5b66\u4e2d\u7684\u57fa\u5c14\u970d\u592b\u65b9\u7a0b\u7c7b\u4f3c\u3002</p> <p>\u6700\u540e\uff0c\u4e3a\u4e86\u7c97\u7565\u5bfc\u51fa\u84b8\u6c14\u538b\u65b9\u7a0b\uff0c\u8003\u8651\u6469\u5c14\u7406\u60f3\u6c14\u4f53\u4e14\u5ffd\u7565\u6db2\u76f8\u4f53\u79ef\u548c\u76f8\u53d8\u6f5c\u70ed\u968f\u6e29\u5ea6\u7684\u53d8\u5316\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ \\frac{dp}{dT}=\\frac{Lp}{T^2R}\\Rightarrow p=p_0e^{\\frac{-L}{RT}} \\]"},{"location":"chapter_03_phase_transition/04_maxwell_equal_area.html","title":"Maxwell\u7b49\u9762\u79ef\u89c4\u5219\u3001\u8303\u6c0f\u6c14\u4f53\u4e34\u754c\u70b9\u4f4d\u7f6e","text":""},{"location":"chapter_03_phase_transition/04_maxwell_equal_area.html#maxwell","title":"Maxwell\u7b49\u9762\u79ef\u89c4\u5219\u3001\u8303\u6c0f\u6c14\u4f53\u4e34\u754c\u70b9\u4f4d\u7f6e","text":"<p>\u2605 \u8303\u5fb7\u74e6\u5c14\u65af\u65b9\u7a0b\u56e0\u5176\u8003\u8651\u4e86\u5206\u5b50\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u548c\u5206\u5b50\u5927\u5c0f\uff0c\u89e3\u91ca\u4e86\u6c14\u6db2\u76f8\u53d8\u548c\u4e34\u754c\u70b9\u7b49\u73b0\u8c61\u800c\u51fa\u540d\u3002\u4f46\u5176p-V\u56fe\u5728\u76f8\u53d8\u8fc7\u7a0b\u4f1a\u51fa\u73b0\u5982\u4e0b\u56fe\u7b49\u6e29\u7ebf\u7684JN\u6bb5\uff0c\u5373\u538b\u5f3a\u8d8a\u5927\u4f53\u79ef\u8d8a\u5927\u7684\u4e0d\u7a33\u5b9a\u72b6\u6001\u3002\u4e3a\u4e86\u4e0e\u5b9e\u9a8c\u7ed3\u679c\u543b\u5408\uff0c\u9700\u8981\u8fdb\u884c\u76f8\u5173\u4fee\u6b63\uff0c\u5373\u672c\u8282\u7684Maxwell\u7b49\u9762\u79ef\u89c4\u5219\u3002</p> <p></p> <p>\u5bf9\u4e0a\u56fe\u7b49\u6e29\u7ebf\u8fdb\u884c\u5206\u6790\uff0c\u7531\u7b49\u6e29\u5316\u5b66\u52bf\u7684\u5fae\u5206\u5f97\u5230\uff1a</p> \\[ d\\mu=vdp\\Rightarrow \\mu=\\int vdp+\\mu_0 \\] <p>\u6ce8\u610f\u79ef\u5206\u7684\u65b9\u5411\u6027\uff0c\u5206\u6bb5\u8fdb\u884c\u79ef\u5206\uff1aKN\u6bb5\u548cJM\u6bb5\u65b9\u5411\u4f7f\u5f97\u538b\u5f3ap\u589e\u52a0\uff0c\u4ece\u800c\u79ef\u5206\u548c\u5316\u5b66\u52bf\u4e5f\u589e\u52a0\u3002NJ\u6bb5\u65b9\u5411\u4f7f\u5f97\u538b\u5f3ap\u51cf\u5c11\uff0c\u4ece\u800c\u79ef\u5206\u548c\u5316\u5b66\u52bf\u51cf\u5c11\u3002</p> <p>\u4fee\u6b63\u7684\u65b9\u6cd5\u662f\u7528\u4e00\u6761\u76f4\u7ebf\u4ee3\u66ff\u4e2d\u95f4\u7684\u4e0d\u7a33\u5b9a\u90e8\u5206\u3002\u5982\u56fe\u76f4\u7ebfAB\u6bb5\u4e3a\u4fee\u6b63\u7684\u76f8\u53d8\u8fc7\u7a0b\uff0c\u5728\u6b64\u533a\u57df\u5316\u5b66\u52bf\u4e3a\u5b9a\u503c\uff0c\u4ece\u800c\uff1a</p> \\[ \\int_{\\overset{\\frown}{BA}}v\\,dp=0 \\] <p>\u4e0d\u96be\u770b\u51fa\u79ef\u5206\u610f\u4e49\u4e3a\u6b63\u7684BND\u9762\u79ef\u52a0\u4e0a\u8d1f\u7684DJA\u9762\u79ef\uff0c\u6545\u8981\u4f7f\u79ef\u5206\u4e3a0\u5219\u4e24\u9879\u9762\u79ef\u7684\u7edd\u5bf9\u503c\u5e94\u8be5\u76f8\u7b49\u3002\u7b49\u4ef7\u5730\uff0c\u5728\u5e38\u89c1\u7684\\(p\\)-\\(v\\)\u56fe\u4e0a\u4e5f\u53ef\u5199\u6210\\(\\int_{v_l}^{v_g}[p(v)-p_0]\\,dv=0\\)\u3002\u8fd9\u5c31\u662f\u6240\u8c13\u7684Maxwell\u7b49\u9762\u79ef\u89c4\u5219\u3002</p> <p>\u5f53\u7136\uff0c\u4e5f\u53ef\u4ee5\u4ece\u53ef\u9006\u5faa\u73af\u7684\u89d2\u5ea6\u5f97\u5230Maxwell\u7b49\u9762\u79ef\u89c4\u5219\uff1a\u6784\u9020\u4e00\u4e2a\u53ef\u9006\u5faa\u73afAJDNBDA,\u7531\u4e8e\u5faa\u73af\u6e29\u5ea6T\u59cb\u7ec8\u4e0d\u53d8\uff0c\u6839\u636e\\(\\oint dU=\\oint TdS-\\oint pdV\\),\u5c06T\u63d0\u51fa\u6765\uff0c\u518d\u7531\\(\\oint dU=0,\\oint dS=0\\)\u5f97\u5230\\(\\oint pdV=0\\).</p> <p>\u6b64\u5916\uff0c\u4e9a\u7a33\u6001AJ\u548cNB\u6bb5\u5206\u522b\u4ee3\u8868\u8fc7\u70ed\u6db2\u4f53\u548c\u8fc7\u9971\u548c\u84b8\u6c14\u3002\u4e0b\u4e00\u8282\u5c06\u8be6\u7ec6\u8ba8\u8bba\u3002</p> <p>\u2605 \u73b0\u5728\u5229\u7528\u6469\u5c14\u8303\u6c0f\u65b9\u7a0b\uff0c\u8ba8\u8bba\u6c14\u6db2\u4e34\u754c\u70b9\u7684\u6027\u8d28\u3002\u5f53\u7b49\u6e29\u7ebf\u7684\u6781\u5c0f\u503cJ\u4e0e\u6781\u5927\u503cN\u5171\u70b9\u65f6\uff0c\u5373\u8fbe\u5230\u4e34\u754c\u70b9\u3002\u4ece\u800c\u53ef\u5c06\u8303\u6c0f\u65b9\u7a0b\u4ee3\u5165\u4e0b\u5f0f\uff1a</p> \\[ \\left(\\frac{\\partial p}{\\partial v}\\right)_T=0\\qquad\\left(\\frac{\\partial^2 p}{\\partial v^2}\\right)_T=0 \\] <p>\u4e0a\u5f0f\u8868\u793a\u4e34\u754c\u70b9\u662f\u7b49\u6e29\u7ebf\u7684\u62d0\u70b9\u3002\u8054\u7acb\u6c42\u5f97\uff1a</p> \\[ T_c=\\frac{8a}{27bR}\\qquad p_c=\\frac{a}{27b^2}\\qquad v_c=3b \\] <p>\u6d88\u53bb\u4e0a\u5f0f\u7684\u6d4b\u91cf\u7cfb\u6570\uff0c\u4e0d\u96be\u53d1\u73b0\u4efb\u4f55\u8303\u6c0f\u6c14\u4f53\u5e94\u8be5\u6ee1\u8db3\uff1a</p> \\[ \\frac{RT_c}{p_cv_c}=\\frac{8}{3} \\] <p>\u6b64\u5916,\u5f15\u5165\u65e0\u91cf\u7eb2\u7684\u6e29\u5ea6\u3001\u538b\u5f3a\u3001\u4f53\u79ef\u53ef\u5c06\u8303\u6c0f\u65b9\u7a0b\u5199\u4f5c\uff1a</p> \\[ T^*=\\frac{T}{T_c}\\quad p^*=\\frac{p}{p_c}\\quad v^*=\\frac{v}{v_c}\\Rightarrow \\left(p^*+\\frac{3}{{v^*}^2}\\right)\\left(3v^*-1\\right)=8T^* \\] <p>\u5176\u4e2d\u5e26\u661f\u53f7\u7684\u4e3a\u5bf9\u6bd4\u91cf\uff0c\u5f53\u4e24\u4e2a\u5bf9\u6bd4\u91cf\u76f8\u540c\u65f6\uff0c\u7b2c\u4e09\u4e2a\u5bf9\u6bd4\u91cf\u5fc5\u5b9a\u76f8\u540c\uff0c\u6b64\u79f0\u4e3a\u5bf9\u5e94\u6001\u5b9a\u7406\u3002</p>"},{"location":"chapter_03_phase_transition/05_droplet_formation.html","title":"\u6db2\u6ef4\u7684\u5f62\u6210","text":""},{"location":"chapter_03_phase_transition/05_droplet_formation.html#_1","title":"\u6db2\u6ef4\u7684\u5f62\u6210","text":"<p>\u2605 \u672c\u8282\u5229\u7528\u5e73\u8861\u5224\u636e\u5206\u6790\u6db2\u6ef4\u548c\u5176\u6c14\u76f8\u7ec4\u6210\u7684\u7cfb\u7edf\u7684\u5e73\u8861\u95ee\u9898\uff0c\u5e76\u8003\u8651\u6db2\u6ef4\u8868\u9762\u76f8\u5e26\u6765\u7684\u5f71\u54cd\u3002\u4e8b\u5b9e\u4e0a\uff0c\u8868\u9762\u76f8\u53ef\u4ee5\u770b\u4f5c\u662f\u4ea7\u751f\u989d\u5916\u538b\u529b\u7684\u201c\u819c\u201d\u3002</p> <p>\u8fd9\u91cc\u5229\u7528\u5185\u80fd\u5224\u636e\u8fdb\u884c\u5206\u6790\uff0c\u5f53\u7136\u4e5f\u53ef\u7528\u81ea\u7531\u80fd\u7b49\u5176\u4ed6\u5224\u636e\u3002\u5e76\u8bbe\u6db2\u76f8\u4e3a\\(\\alpha\\),\u6c14\u76f8\u4e3a\\(\\beta\\),\u8868\u9762\u76f8\u4e3a\\(\\gamma\\),\u6839\u636e\u5224\u636e\u6709\uff1a</p> \\[ \\begin{array}{l} \\left\\{\\begin{matrix} \\delta U=0\\\\ \\delta S=0\\quad\\delta V=0\\quad \\delta n=0 \\end{matrix}\\right. \\end{array} \\qquad \\begin{array}{l} \\left\\{\\begin{matrix} \\delta U^\\alpha&amp;=&amp;T^\\alpha\\delta S^\\alpha-p^\\alpha\\delta V^\\alpha+\\mu^\\alpha\\delta n^\\alpha\\\\ \\delta U^\\beta&amp;=&amp;T^\\beta\\delta S^\\beta-p^\\beta\\delta V^\\beta+\\mu^\\beta\\delta n^\\beta\\\\ \\delta U^\\gamma&amp;=&amp;T^\\gamma\\delta S^\\gamma+\\sigma\\delta A \\end{matrix}\\right. \\end{array} \\] <p>\u4e0a\u5f0f\u9ed8\u8ba4\u7406\u60f3\u8868\u9762\u7684\u7c92\u5b50\u6570\u4e3a0\uff0c\u4ece\u800c\u4e0d\u542b\u8868\u9762\u76f8\u7684\u5316\u5b66\u52bf\u3002\u6b64\u5916\uff0c\u4e3a\u4e86\u5206\u6790\u51e0\u4f55\u7ea6\u675f\uff0c\u8fd9\u91cc\u5047\u8bbe\u6db2\u6ef4\u4e3a\u7403\u4f53\uff0c\u56e0\u4e3a\u5176\u8868\u9762\u79ef\u6700\u5c0f\u6700\u7a33\u5b9a\uff0c\u4e14\u5904\u7406\u8d77\u6765\u65b9\u4fbf\u3002</p> \\[ V^\\alpha=\\frac{4}{3}\\pi r^3\\qquad A=4\\pi r^2\\quad\\Rightarrow\\quad \\delta V^\\alpha=4\\pi r^2\\delta r\\qquad \\delta A=8\\pi r\\delta r \\] <p>\u5e76\u4ee3\u5165\u7ea6\u675f\u6761\u4ef6\\(\\delta S=0\\quad\\delta V=0\\quad \\delta n=0\\)\u4e2d\uff0c\u5f97\u5230\uff1a</p> \\[ \\delta U=\\left(T^\\alpha-T^\\gamma\\right)\\delta S^\\alpha+\\left(T^\\beta-T^\\gamma\\right)\\delta S^\\beta-\\left(p^\\alpha-p^\\beta-\\frac{2\\sigma}{r}\\right)4\\pi r^2\\delta r+\\left(\\mu^\\alpha-\\mu^\\beta\\right)\\delta n^\\alpha=0 \\] <p>\u6ce8\u610f\u5230\\(\\delta S^\\alpha,\\delta S^\\beta,\\delta r,\\delta n^\\alpha\\)\u72ec\u7acb\u53d8\u5316\uff0c\u6545\uff1a</p> \\[ \\boxed{T^\\alpha=T^\\beta=T^\\gamma\\qquad p^\\alpha=p^\\beta+\\frac{2\\sigma}{r}\\qquad\\mu^\\alpha=\\mu^\\beta} \\] <p>\u53ef\u89c1\uff0c\u7531\u4e8e\u8868\u9762\u76f8\u7684\u5b58\u5728\u4f7f\u5f97\u6db2\u6ef4\u538b\u5f3a\u589e\u5927\uff0c\u8fd9\u662f\u8868\u9762\u5f20\u529b\u4f7f\u6db2\u6ef4\u6536\u7f29\u7684\u4f53\u73b0\u3002\u5982\u679c\u6db2\u6ef4\u548c\u6c14\u76f8\u7684\u5730\u4f4d\u4e92\u6362\uff0c\u5219\u8fd9\u4efd\u538b\u529b\u8981\u9760\u6c14\u6ce1\u6765\u627f\u53d7\uff0c\u53ef\u4ee5\u5229\u7528\\(r\\rightarrow -r\\)\u5b9e\u73b0\u3002\u6b64\u5916\uff0c\u8003\u8651\u5e26\u7535\u7403\u4f53\u65f6:\\(\\sigma\\delta A\\rightarrow \\delta(q\\phi)=q\\left(\\frac{\\partial \\phi}{\\partial r}\\right)  \\delta r\\).</p> <p>\u2605 \u4e0b\u9762\u5229\u7528\u76f8\u5e73\u8861\u6761\u4ef6\uff0c\u8ba8\u8bba\u6db2\u6ef4\u5f62\u6210\u7684\u95ee\u9898\u3002\u5bf9\u4e8e\u6db2\u76f8\\(\\alpha\\)\u548c\u6c14\u76f8\\(\\beta\\)\uff0c\u6c34\u5e73\u9762\u548c\u7403\u5f62\u9762\u6db2\u76f8\u7684\u5316\u5b66\u52bf\u5e94\u8be5\u6ee1\u8db3(\u5e73\u8861\u6761\u4ef6\u4e0b\uff0c\\(p\\)\u4e3a\u6c34\u5e73\u9762\u84b8\u6c14\u538b\u5f3a\uff0c\\(p^\\beta\\)\u4e3a\u7403\u5f62\u9762\u84b8\u6c14\u538b\u5f3a)\uff1a</p> \\[ \\mu^\\alpha(T,p)=\\mu^\\beta(T,p)\\qquad\\mu^\\alpha(T,p^\\beta+\\frac{2\\sigma}{r})=\\mu^\\beta(T,p^\\beta) \\] <p>\u5bf9\u4e8e\u6db2\u76f8\uff0c\u7531\u4e8e\\(p^\\beta-p\\ll\\frac{2\\sigma}{r}\\),\u6545\u5bf9\u7403\u5f62\u9762\u6db2\u76f8\u5316\u5b66\u52bf\u5728\\(p\\)\u9644\u8fd1\u8fdb\u884c\u5c55\u5f00\u5f97\u5230\uff1a</p> \\[ \\mu^\\alpha(T,p^\\beta+\\frac{2\\sigma}{r})\\approx\\mu^\\alpha(T,p)+(p^\\beta-p+\\frac{2\\sigma}{r})\\frac{\\partial \\mu^\\alpha}{\\partial p}=\\mu^\\alpha(T,p)+(p^\\beta-p+\\frac{2\\sigma}{r})v^\\alpha \\] <p>\u5047\u8bbe\u84b8\u6c14\u4e3a\u7406\u60f3\u6c14\u4f53\uff0c\u6839\u636e\\(G_m=RT(\\phi+ln(p))\\),\u5219\u7403\u5f62\u9762\u6469\u5c14\u5409\u5e03\u65af\u51fd\u6570\u53ef\u7528\u6c34\u5e73\u9762\u8868\u8fbe\u4e3a\uff1a</p> \\[ \\mu^\\beta(T,p^\\beta)=\\mu^\\beta(T,p)+RTln(\\frac{p^\\beta}{p}) \\] <p>\u8054\u7acb\u5404\u5f0f\uff0c\u5f97\u5230\uff1a</p> \\[ RTln(\\frac{p^\\beta}{p})=(p^\\beta-p+\\frac{2\\sigma}{r})v^\\alpha\\approx \\frac{2\\sigma}{r}v^\\alpha\\Rightarrow \\boxed{r_c=\\frac{2\\sigma v^\\alpha}{RTln(\\frac{p^\\beta}{p})}} \\] <p>\u63a8\u5bfc\u601d\u8def\uff1a\u5c06\u7403\u5f62\u4e24\u76f8\u538b\u5f3a\u76f8\u7b49\u7684\u5173\u7cfb\u5f0f\u5c55\u5f00\u4e3a\u5e73\u9762\u538b\u5f3a\u9879\u4e0e\u9644\u52a0\u9879\u4e4b\u548c\uff0c\u5229\u7528\u6c34\u5e73\u4e24\u76f8\u538b\u5f3a\u76f8\u7b49\uff0c\u5bfc\u51fa\u4e24\u76f8\u7684\u9644\u52a0\u9879\u76f8\u7b49\uff0c\u4ece\u800c\u5f97\u5230\u534a\u5f84\u7684\u5173\u7cfb\u3002\u5176\u4e2d\\(r_c\\)\u79f0\u4e3a\u4e2d\u80af\u534a\u5f84\u3002\u5f53\\(r&gt;r_c\\)\u65f6\uff0c\u7531\u753b\u76f4\u7ebf\u7684\u5f0f\u5b50\u4e0d\u96be\u770b\u51fa\\(\\mu^\\alpha&lt;\\mu^\\beta\\),\u4ece\u800c\u6c14\u76f8\u4e0d\u65ad\u8f6c\u5316\u4e3a\u6db2\u76f8\uff0c\u6700\u7ec8\u53d1\u751f\u6c14\u5230\u6db2\u7684\u76f8\u53d8\u3002\u5f53\\(r&lt;r_c\\)\u65f6\uff0c\u540c\u7406\u6709\\(\\mu^\\alpha&gt;\\mu^\\beta\\),\u5373\u6db2\u76f8\u4e0d\u65ad\u5411\u6c14\u76f8\u8f6c\u5316\u3002\u7efc\u4e0a\uff0c\u7531\u4e8e\\(r_c\\)\u6052\u6b63\uff0c\u53ea\u6709\\(p^\\beta&gt;p\\)\u624d\u53ef\u80fd\u53d1\u751f\u6c14\u5230\u6db2\u7684\u76f8\u53d8\uff0c\u5373\u8fc7\u9971\u548c\u84b8\u6c14\u3002\u5982\u679c\u51dd\u7ed3\u6838\u534a\u5f84\u4e0d\u591f\uff0c\u4e5f\u4e0d\u80fd\u53d1\u751f\u76f8\u53d8\u3002</p> <p>\u6b64\u5916\uff0c\u8003\u8651\u6c14\u6ce1\u5e73\u8861\\((r\\rightarrow -r)\\)\uff0c\u53ef\u4ee5\u89e3\u91ca\u8fc7\u70ed\u6db2\u4f53\u7684\u73b0\u8c61\u3002</p>"},{"location":"chapter_03_phase_transition/06_landau_phase_transition.html","title":"\u6717\u9053\u8fde\u7eed\u76f8\u53d8\u7406\u8bba\uff08\u6c42\u4e34\u754c\u6307\u6570\uff09","text":""},{"location":"chapter_03_phase_transition/06_landau_phase_transition.html#_1","title":"\u6717\u9053\u8fde\u7eed\u76f8\u53d8\u7406\u8bba\uff08\u6c42\u4e34\u754c\u6307\u6570\uff09","text":"<p>\u2605 \u4e3a\u4e86\u7814\u7a76\u4e8c\u7ea7\u76f8\u53d8\u7406\u8bba\uff0c\u6717\u9053\u5c06\u81ea\u7531\u80fd\u5728\u4e34\u754c\u70b9\u9644\u8fd1\u8fdb\u884c\u5c55\u5f00\uff0c\u5e76\u5e94\u7528\u81ea\u7531\u80fd\u6781\u5c0f\u7684\u6761\u4ef6\u6c42\u51fa\u5e8f\u53c2\u91cf\u7684\u89e3\uff0c\u8fdb\u800c\u8ba1\u7b97\u51fa\u5404\u4e2a\u4e34\u754c\u6307\u6570\u3002</p> <p>\u6240\u8c13\u5e8f\u53c2\u91cf\uff0c\u5373\u9009\u5b9a\u4e86\u4e00\u4e2a\u7269\u7406\u91cf\u63cf\u8ff0\u7cfb\u7edf\u76f8\u53d8\u7684\u5bf9\u79f0\u6027\u53d8\u5316\uff0c\u4e14\u5728\u5bf9\u79f0\u6027\u9ad8\u7684\u65e0\u5e8f\u76f8\u4e3a0\uff0c\u5bf9\u79f0\u6027\u4f4e\u7684\u6709\u5e8f\u76f8\u4e0d\u4e3a0.\u5e8f\u53c2\u91cf\u7684\u9009\u62e9\u4e0d\u662f\u4e00\u4ef6\u5bb9\u6613\u7684\u4e8b\u60c5\uff0c\u9700\u8981\u4e30\u5bcc\u7684\u7ecf\u9a8c\u548c\u7269\u7406\u76f4\u89c9\u3002</p> <p>\u5728\u4e34\u754c\u70b9\u5177\u6709\u5947\u5f02\u6027\u7684\u7269\u7406\u91cf\uff0c\u7528\u4e34\u754c\u6307\u6570\u6765\u63cf\u8ff0\u3002\u901a\u5e38\u7684\u5f62\u5f0f\u5982\u4e0b\uff1a</p> \\[ A\\backsim B^{\\pm\\alpha} \\] <p>\u5176\u4e2dA\u4e3a\u5177\u6709\u5947\u5f02\u6027\u7684\u7269\u7406\u91cf\uff0cB\u4e3a\u5e8f\u53c2\u91cf\u6216\u6e29\u5ea6\u7b49\uff0c\\(\\alpha\\)\u5373\u4e34\u754c\u6307\u6570\u3002</p> <p>\u2605 \u4e0b\u9762\u5229\u7528\u6717\u9053\u7406\u8bba\u5bf9\u5747\u5300\u7cfb\u94c1\u78c1\u76f8\u53d8\u8fdb\u884c\u5206\u6790(\u975e\u5747\u5300\u7cfb\u9700\u8981\u7528\u5230\u6cdb\u51fd)\u3002\u901a\u5e38\u9009\u62e9\u78c1\u5316\u5f3a\u5ea6M\u4e3a\u5e8f\u53c2\u91cf\uff0c\u5219\u5c06\u81ea\u7531\u80fd\u5c55\u5f00\u4e3a\uff1a</p> \\[ F(T,M)=\\sum_{n=0}^\\infty a_n(T)M^n\\approx a_0(T)+a_2(T)M^2+a_4(T)M^4 \\] <p>\u4e0a\u5f0f\u5229\u7528\u4e86\\(F(T,M)=F(T,-M)\\)\u5e76\u5ffd\u7565\\(M^4\\)\u4ee5\u4e0a\u7684\u5c0f\u91cf\u3002\u73b0\u5728\u8003\u8651\u5728\u67d0\u4e00\\(T\\)\u4e0b\uff0c\\(M\\)\u7684\u53d6\u503c\u3002\u5229\u7528\u81ea\u7531\u80fd\u5224\u636e\u5f97\u5230\uff1a</p> \\[ \\left(\\frac{\\partial F}{\\partial M}\\right)_T=0\\qquad\\left(\\frac{\\partial^2 F}{\\partial M^2}\\right)_T&gt;0\\Rightarrow M=0,\\pm \\sqrt{-\\frac{a_2(T)}{2a_4(T)}} \\] <p>\u5982\u679c\u5047\u8bbe\\(a_2(T)=a_{20}(T-T_c),a_4=Const.\\)\u6839\u636e\u7a33\u5b9a\u5e73\u8861\u6761\u4ef6\uff0c\u5f97\u5230\u5f53\\(T&gt;T_c\\)\u65f6\\(M=0\\);\u5f53\\(T&lt;T_c\\)\u65f6\\(M=\\pm \\sqrt{\\frac{a_{20}(T_c-T)}{2a_4}}\\).\u4ece\u800c\u6839\u636e\u5b9a\u4e49\u5f97\u5230\uff1a</p> \\[ M\\backsim (T_c-T)^\\beta\\quad(T\\rightarrow T_c^{-},H=0)\\quad\\Rightarrow\\quad \\beta=\\frac{1}{2} \\] <p>\u5229\u7528\u540c\u6837\u7684\u65b9\u6cd5\uff0c\u4e5f\u53ef\u6c42\u51fa\u5176\u4ed6\u4e34\u754c\u6307\u6570\\(\\delta,\\gamma,\\alpha\\)</p> <p>\u2605 \u662f\u4e0d\u662f\u611f\u89c9\u6717\u9053\u7406\u8bba\u4e3b\u8981\u9760\u201c\u8c03\u53c2\u201d\u6765\u548c\u5b9e\u9a8c\u7b26\u5408\uff1f\u7684\u786e\uff0c\u7b14\u8005\u4e5f\u8fd9\u4e48\u8ba4\u4e3a\u3002\u901a\u8fc7\u8c03\u6574\\(a_n(T)\\)\u7684\u6b63\u8d1f\u4ee5\u53ca\u81ea\u7531\u80fd\u5c55\u5f00\u7684\u9636\u6570\uff0c\u4ea6\u53ef\u4ee5\u5f97\u5230\u4e00\u7ea7\u548c\u4e09\u4e34\u754c\u70b9\u76f8\u53d8\u7684\u4e34\u754c\u6307\u6570\u3002\u5e76\u4e14\uff0c\u7531\u4e8e\u5176\u6ca1\u6709\u8003\u8651\u6da8\u843d\u7b49\u56e0\u7d20\uff0c\u672c\u8d28\u4e0a\u4f5c\u4e3a\u4e00\u79cd\u5e73\u5747\u573a\u7406\u8bba\uff0c\u5fc5\u5b9a\u4f7f\u5f97\u67d0\u4e9b\u65f6\u5019\u4e0e\u5b9e\u9a8c\u76f8\u5dee\u8fc7\u5927(\u5229\u7528\u91d1\u5179\u5821\u5224\u636e\u53ef\u4ee5\u5927\u81f4\u5224\u65ad\u9002\u7528\u6027)\u3002\u7136\u800c\uff0c\u6717\u9053\u6240\u63d0\u51fa\u7684\u5e8f\u53c2\u91cf\u7684\u6982\u5ff5\uff0c\u5374\u63a8\u52a8\u4e86\u8d85\u5bfc\u3001\u8d85\u6d41\u76f8\u53d8\u3001\u76f8\u573a\u6cd5\u8ba1\u7b97\u7b49\u7b49\u7684\u53d1\u5c55\u3002</p>"},{"location":"chapter_04_multicomponent_system/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_04_multicomponent_system/index.html#4","title":"\u7b2c4\u7ae0 \u591a\u5143\u4f53\u7cfb\u5e73\u8861","text":"<p>\u5728\u5355\u5143\u7cfb\u5e73\u8861\u7684\u57fa\u7840\u4e0a\uff0c\u672c\u7ae0\u5c06\u4e4b\u63a8\u5e7f\u4e3a\u591a\u5143\u7cfb\uff0c\u5e76\u5bf9\u6574\u4e2a\u5e73\u8861\u6001\u70ed\u529b\u5b66\u7406\u8bba\u8fdb\u884c\u5b8c\u5584\u3002\u6838\u5fc3\u5728\u4e8e\u7406\u89e3\u504f\u6469\u5c14\u91cf\u7684\u601d\u60f3\uff0c\u628a\u63e1\u591a\u5143\u548c\u591a\u76f8\u7684\u5173\u7cfb\u3002\u5e94\u7528\u65b9\u9762\uff0c\u5206\u6790\u4e86\u5316\u5b66\u4e2d\u7684\u5e73\u8861\u5e38\u6570\u548c\u7406\u60f3\u6eb6\u6db2\u7684\u95ee\u9898\u3002\u6b64\u5916\uff0c\u8fd8\u8981\u6ce8\u91cd\u627f\u524d\u542f\u540e\u7684\u90e8\u5206\uff0cGibbs\u4f6f\u8c2c\u3001\u7edd\u5bf9\u71b5\u90fd\u4e3a\u540e\u7eed\u7684\u7edf\u8ba1\u7269\u7406\u57cb\u4e0b\u4f0f\u7b14\u3002</p>"},{"location":"chapter_04_multicomponent_system/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u591a\u5143\u4f53\u7cfb\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001\u590d\u76f8\u5e73\u8861\u3001Gibbs\u76f8\u5f8b</li> <li>\u6df7\u5408\u7406\u60f3\u6c14\u4f53\u3001Gibbs\u4f6f\u8c2c</li> <li>\u5316\u5b66\u5e73\u8861\u548c\u5316\u5b66\u5e38\u6570</li> <li>\u7406\u60f3\u6eb6\u6db2</li> <li>\u80fd\u65af\u7279\u5b9a\u7406\u548c\u70ed\u529b\u5b66\u7b2c\u4e09\u5b9a\u5f8b</li> </ul>"},{"location":"chapter_04_multicomponent_system/01_fundamental_equation_phase_rule.html","title":"\u591a\u5143\u4f53\u7cfb\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001\u590d\u76f8\u5e73\u8861\u3001Gibbs\u76f8\u5f8b","text":""},{"location":"chapter_04_multicomponent_system/01_fundamental_equation_phase_rule.html#gibbs","title":"\u591a\u5143\u4f53\u7cfb\u70ed\u529b\u5b66\u57fa\u672c\u65b9\u7a0b\u3001\u590d\u76f8\u5e73\u8861\u3001Gibbs\u76f8\u5f8b","text":"<p>\u2605 \u4e3a\u4e86\u7b80\u4fbf\uff0c\u5148\u5bf9\u67d0\u4e00\u76f8\u8fdb\u884c\u7814\u7a76\uff1a\u8bbe\u6b64\u76f8\u7ec4\u5143\u6570\u4e3ak(\u8fd9\u91cc\u4e0d\u8003\u8651\u5316\u5b66\u53cd\u5e94\u7b49\u7ea6\u675f\u4f7f\u5f97\u7ec4\u5143\u548c\u7269\u8d28\u79cd\u7c7b\u6570\u4e0d\u76f8\u7b49\u7684\u60c5\u51b5\uff0c\u90a3\u662f\u7269\u7406\u5316\u5b66\u7814\u7a76\u7684\u8303\u7574),\u57fa\u672c\u70ed\u529b\u5b66\u91cf\u90fd\u662f\u5e7f\u5ef6\u91cf\uff0c\u4fdd\u6301\u6e29\u5ea6\u548c\u538b\u5f3a\u4e0d\u53d8\uff0c\u6469\u5c14\u6570\u53d8\u4e3a\u539f\u6765\u7684\\(\\lambda\\)\u500d\uff1a</p> \\[ \\begin{array}{l} \\left\\{\\begin{matrix} V(T,p,\\lambda n_1,...,\\lambda n_k)=\\lambda V(T,p, n_1,..., n_k)\\\\ U(T,p,\\lambda n_1,...,\\lambda n_k)=\\lambda U(T,p, n_1,..., n_k)\\\\ S(T,p,\\lambda n_1,...,\\lambda n_k)=\\lambda S(T,p, n_1,..., n_k) \\end{matrix}\\right. \\end{array} \\] <p>\u6839\u636e\u9f50\u6b21\u51fd\u6570\u7684\u6b27\u62c9\u5b9a\u7406(\u8be6\u89c1\u5206\u6790\u529b\u5b66)\u5f97\u5230(\u6c42\u548c\u9ed8\u8ba4i=1,...,\\(k\\))\uff1a</p> \\[ V=\\sum n_i \\left(\\frac{\\partial V}{\\partial n_i}\\right)_{T,p,n_{j\\neq i}}\\qquad U=\\sum n_i \\left(\\frac{\\partial U}{\\partial n_i}\\right)_{T,p,n_{j\\neq i}}\\qquad S=\\sum n_i \\left(\\frac{\\partial S}{\\partial n_i}\\right)_{T,p,n_{j\\neq i}} \\] <p>\u4e3a\u4e86\u65b9\u4fbf\uff0c\u5b9a\u4e49\u504f\u6469\u5c14\u91cf\\(v_i=\\left(\\frac{\\partial V}{\\partial n_i}\\right)_{T,p,n_{j\\neq i}},u_i=\\left(\\frac{\\partial U}{\\partial n_i}\\right)_{T,p,n_{j\\neq i}},s_i=\\left(\\frac{\\partial S}{\\partial n_i}\\right)_{T,p,n_{j\\neq i}}\\).\u6ce8\u610f\u504f\u6469\u5c14\u91cf\u5fc5\u987b\u6ee1\u8db3T\u548cp\u4fdd\u6301\u4e0d\u53d8\uff0c\u5e76\u4e14\u4e0e\u4e4b\u524d\u5355\u5143\u7cfb\u7684\u5b57\u6bcd\u8fdb\u884c\u533a\u5206\u3002\u7531\u6b64\u53ef\u4ee5\u65b9\u4fbf\u8868\u8fbe\u504f\u5bfc\u5173\u7cfb\uff0c\u5e76\u63a8\u5e7f\u5230\u5409\u5e03\u65af\u51fd\u6570G\uff1a</p> \\[ V=\\sum n_iv_i\\qquad U=\\sum n_i u_i\\qquad S=\\sum n_i s_i\\qquad G=\\sum n_i\\mu_i \\] <p>\u5bf9\\(G(T,p,n_1,...,n_k)\\)\u8fdb\u884c\u5168\u5fae\u5206\u5c55\u5f00,\u5e76\u5229\u7528\u5b9a\u4e49\u5f97\u5230\u591a\u5143\u5f00\u653e\u7cfb\u7684\u57fa\u672c\u70ed\u529b\u5b66\u65b9\u7a0b\u3002\u6ce8\u610f\uff0c\u5176\u4e2d\\(\\mu_i\\)\u79f0\u4e3a\u504f\u6469\u5c14\u5409\u5e03\u65af\u51fd\u6570:</p> \\[ dG=-SdT+Vdp+\\sum \\mu_i d n_i\\qquad \\boxed{dU=TdS-pdV+\\sum\\mu_idn_i} \\] <p>\u6b64\u5916\uff0c\u4e0d\u96be\u770b\u51fak+2\u4e2a\u5f3a\u5ea6\u91cf\u4e4b\u95f4\u7684\u5173\u7cfb,\u4e5f\u5c31\u662f\u5409\u5e03\u65af\u5173\u7cfb\uff1a</p> \\[ -SdT+Vdp+\\sum_i n_i d\\mu_i=0\\quad\\Rightarrow\\quad \\boxed{U=TS-pV+\\sum_i\\mu_i n_i} \\] <p>\u4e0a\u5f0f\u8bf4\u660e\u591a\u5143\u5355\u76f8\u7cfb\u7684\u81ea\u7531\u5ea6(\u72ec\u7acb\u7684\u5f3a\u5ea6\u91cf\u4e2a\u6570)\u4e3ak+1.\u540e\u9762\u6211\u4eec\u5c06\u4e4b\u63a8\u5e7f\u4e3a\\(\\phi\\)\u4e2a\u76f8\u7684\u591a\u5143\u4f53\u7cfb\uff0c\u5373\u5409\u5e03\u65af\u76f8\u5f8b\u3002</p> <p>\u2605 \u5bf9\u4e8e\u591a\u5143\u590d\u76f8\u7cfb\u7edf\uff0c\u6ee1\u8db3\u67d0\u4e9b\u6761\u4ef6\u540e\uff0c\u53ef\u4ee5\u5b9a\u4e49\u7cfb\u7edf\u603b\u4f53\u7684\u5e7f\u5ef6\u91cf\u3002\u5982\u5404\u76f8\u6e29\u5ea6\u538b\u5f3a\u76f8\u7b49\uff0c\u53ef\u4ee5\u5b9a\u4e49\u603b\u7684\u5409\u5e03\u65af\u51fd\u6570\uff1a</p> \\[ G=\\sum_\\alpha G^\\alpha=\\sum_\\alpha\\sum_i n^\\alpha_i \\mu^\\alpha_i \\] <p>\u6839\u636e\u4e0a\u5f0f\uff0c\u53ef\u4ee5\u5f88\u597d\u5730\u7406\u89e3\u590d\u76f8\u4e0e\u7ec4\u5143\u7684\u5173\u7cfb\u3002\u4e0b\u9762\u63a8\u5bfc\u590d\u76f8\u5e73\u8861\u6761\u4ef6\u3002</p> <p>\u4e3a\u4e86\u7b80\u4fbf\uff0c\u8fd9\u91cc\u4ec5\u8003\u8651\u4e24\u76f8\\(\\alpha,\\beta\\)\uff0c\u4e14\u6bcf\u76f8\u7ec4\u5206\u4e3ak.\u4ece\u800c\u6bcf\u7ec4\u5206\u5728\u4e24\u76f8\u4e2d\u7684\u7c92\u5b50\u6570\u5b88\u6052\uff1a\\(\\delta n^\\alpha_i+\\delta n^\\beta_i=0\\quad(i=1,2,...,k)\\).\u5728\u7b49\u6e29\u7b49\u538b\u6761\u4ef6\u4e0b\uff0c\u7531\u5409\u5e03\u65af\u5e73\u8861\u5224\u636e\u5f97\u5230\uff1a</p> \\[ \\delta G=\\delta G^\\alpha+\\delta G^\\beta=\\sum_{i=1}^{k}(\\mu_i^\\alpha-\\mu_i^\\beta)\\delta n^\\alpha_i=0\\Rightarrow \\boxed{\\mu_i^\\alpha=\\mu_i^\\beta\\quad(i=1,2,...,k)} \\] <p>\u5373\u5404\u4e2a\u7ec4\u5143\u5728\u6bcf\u76f8\u4e2d\u7684\u5316\u5b66\u52bf\u76f8\u7b49\u3002</p> <p>\u2605 \u6839\u636e\u4ee5\u4e0a\u7ed3\u8bba\uff0c\u53ef\u4ee5\u5bfc\u51fa\u8457\u540d\u7684\u5409\u5e03\u65af\u76f8\u5f8b\u3002\u8003\u8651\\(\\phi\\)\u4e2a\u76f8\uff0c\u4e14\u5bf9\u4e8e\u67d0\\(\\alpha\\)\u76f8\u6709\\(k_\\alpha\\)\u4e2a\u7ec4\u5143\uff0c\u8bbe\u603b\u7ec4\u5143\u4e3a\\(k\\),\u5219\u6709\\(k_\\alpha\\leqslant k\\)\u3002\u4e3a\u4e86\u7edf\u4e00\u5206\u6790\u5f3a\u5ea6\u91cf\uff0c\u5bf9\u4e8e\u67d0\\(\\alpha\\)\u76f8\u800c\u8a00\uff0c\u5c06\u6469\u5c14\u91cf\u5316\u4f5c\u7ec4\u5206\u7684\u6bd4\u4f8b\uff1a</p> \\[ x^\\alpha_i=\\frac{n^\\alpha_i}{n^\\alpha}\\quad\\Rightarrow\\quad \\sum_{i=1}^{k_\\alpha}x^\\alpha_i=1 \\] <p>\u4ece\u800c\u5bf9\u4e8e\u67d0\\(\\alpha\\)\u76f8\u7ec4\u5206\u6bd4\u4f8b\\(x^\\alpha_i\\)\u7684\u81ea\u7531\u5ea6\u4e3a\\(k_\\alpha-1\\)\uff0c\u7531\u4e8e\u76f8\u7684\u7269\u7406\u6027\u8d28\u5747\u5300\uff0c\u518d\u7b97\u4e0a\u8be5\u76f8\u7684\u538b\u5f3a\\(p^\\alpha\\)\u548c \u6e29\u5ea6\\(T^\\alpha\\)\uff0c\u5c31\u6709\\(k_\\alpha+1\\)\u4e2a\u81ea\u7531\u5ea6\u3002\u90a3\u4e48\u5bf9\u4e8e\\(\\phi\\)\u4e2a\u76f8\uff0c\u5c31\u6709\\(\\sum_{\\alpha=1}^{\\phi}(k_\\alpha+1)\\)\u4e2a\u81ea\u7531\u5ea6\u3002</p> <p>\u8bbe\u67d0\u4e00\u7ec4\u5206\u5360\u636e\u76f8\u7684\u4e2a\u6570\u4e3a\\(\\phi_i\\),\u5f53\u7136\u4e5f\u6709\\(\\phi_i\\leqslant\\phi\\),\u518d\u6839\u636e\u5e73\u8861\u6761\u4ef6\uff1a</p> \\[ T^1=T^2=...=T^\\phi\\qquad p^1=p^2=...=p^\\phi\\qquad \\mu_i^1=\\mu_i^2=...=\\mu_i^{\\phi_i}(i=1,2,...,k) \\] <p>\u5219\u7ea6\u675f\u7684\u81ea\u7531\u5ea6\u4e3a\\(2(\\phi-1)+\\sum_{i=1}^{k}(\\phi_i-1)\\),\u4ece\u800c\u7cfb\u7edf\u603b\u5171\u7684\u81ea\u7531\u5ea6\u4e3a</p> \\[ f=\\sum_{\\alpha=1}^{\\phi}(k_\\alpha+1)-2(\\phi-1)-\\sum_{i=1}^{k}(\\phi_i-1)=k+2-\\phi+\\sum_{\\alpha=1}^{\\phi}k_\\alpha-\\sum_{i=1}^{k}\\phi_i \\] <p>\u6839\u636e\u590d\u76f8\u4e0e\u7ec4\u5143\u7684\u5173\u7cfb\uff0c\u663e\u7136\u6709\\(\\sum_{\\alpha=1}^{\\phi}k_\\alpha=\\sum_{i=1}^{k}\\phi_i\\),\u53ef\u4ee5\u901a\u8fc7\u8868\u683c\u66f4\u76f4\u89c2\u7684\u770b\u51fa\u8fd9\u4e00\u70b9\u3002\u4ece\u800c\u5f97\u5230\uff1a</p> \\[ \\boxed{f=k+2-\\phi} \\] <p>\u8981\u6ce8\u610f\u7684\u662f\uff0c\u4e0a\u5f0f\u4ec5\u8003\u8651\u4e86\u6e29\u5ea6\u548c\u538b\u5f3a\u7684\u5e73\u8861\uff0c\u5bf9\u4e8e\u9700\u8981\u7535\u78c1\u53c2\u91cf\u7b49\u63cf\u8ff0\u624d\u80fd\u786e\u5b9a\u7684\u4f53\u7cfb\uff0c\u4e0a\u9762\u753b\u6a2a\u7ebf\u7684\u5730\u65b9\u8fd8\u9700\u8981\u6539\u52a8\uff0c\u624d\u80fd\u5f97\u5230\u6b63\u786e\u7684\u81ea\u7531\u5ea6\u3002</p> <p>\u901a\u5e38\u7cfb\u7edf\u7684\u7ec4\u5143\u6570\u662f\u786e\u5b9a\u7684\uff0c\u6545\u5f53\u76f8\u7684\u4e2a\u6570\u589e\u591a\uff0c\u81ea\u7531\u5ea6\u4f1a\u51cf\u5c11\u3002</p>"},{"location":"chapter_04_multicomponent_system/02_ideal_gas_mixture_gibbs_paradox.html","title":"\u6df7\u5408\u7406\u60f3\u6c14\u4f53\u3001Gibbs\u4f6f\u8c2c","text":""},{"location":"chapter_04_multicomponent_system/02_ideal_gas_mixture_gibbs_paradox.html#gibbs","title":"\u6df7\u5408\u7406\u60f3\u6c14\u4f53\u3001Gibbs\u4f6f\u8c2c","text":"<p>\u2605 \u5bf9\u4e8e\u6df7\u5408\u7406\u60f3\u6c14\u4f53\uff0c\u5728\u4f53\u79ef\u4e3aV\uff0c\u603b\u538b\u4e3ap\u7684\u7cfb\u7edf\u4e2d\uff1a</p> \\[ pV=\\sum_i p_i V=\\sum_i n_i RT \\] <p>\u4e0a\u5f0f\u53ef\u7406\u89e3\u4e3a\u9053\u5c14\u987f\u5206\u538b\u5b9a\u5f8b\u3002</p> <p>\u4e0b\u9762\u8003\u8651\u4e00\u4e2a\u534a\u900f\u819c\uff0c\u4ec5\u80fd\u901a\u8fc7\u67d0\u4e9b\u7269\u8d28\\(i\\)\uff0c\u800c\u5176\u4ed6\u7269\u8d28\u53ea\u80fd\u5728\u4e00\u8fb9\uff0c\u4e24\u8fb9\u53ef\u4ee5\u770b\u4f5c\u4e24\u76f8\\(\\alpha\\)\u548c\\(\\beta\\).\u5bf9\u8fd9\u4e9b\u80fd\u901a\u8fc7\u7684\u7269\u8d28\u6709\\(T^\\alpha=T^\\beta,p_i^\\alpha=p_i^\\beta,\\mu_i^\\alpha=\\mu_i^\\beta\\),\u8fd9\u662f\u5b9e\u9a8c\u7ed3\u679c\u3002\u57fa\u4e8e\u6b64\uff0c\u8bbe\u60f3\u4e00\u8fb9\u662f\u6df7\u5408\u6c14\u4f53\uff0c\u53e6\u4e00\u8fb9\u662f\u80fd\u901a\u8fc7\u819c\u7684\u7eaf\u6c14\u4f53\uff0c\u5219\u6709\uff1a \\(\\mu_i=\\mu(T,p_i)\\),\u4ece\u800c\u53ef\u4ee5\u5229\u7528\u7eaf\u6c14\u4f53\u7684\u5316\u5b66\u52bf\u5206\u6790\u6df7\u5408\u6c14\u4f53\uff1a</p> \\[ \\mu_i=RT(\\phi_i+lnp_i)=RT(\\phi_i+ln(px_i))\\qquad \\phi_i=\\frac{h_{0i}}{RT}-\\int\\frac{dT}{RT^2}\\int c_{pi}dT-\\frac{s_{0i}}{R} \\] <p>\u5f53\u70ed\u5bb9\u53ef\u4ee5\u770b\u4f5c\u5e38\u6570\u65f6\uff0c\u6709\uff1a</p> \\[ \\phi_i=\\frac{h_{0i}}{RT}-\\frac{c_{pi}}{R}lnT-\\frac{s_{0i}}{R} \\] <p>\u7531\u6b64\u6839\u636e\\(G=\\sum n_i\\mu_i\\)\uff0c\u5f97\u5230\u5409\u5e03\u65af\u51fd\u6570\uff1a</p> \\[ \\boxed{G=\\sum n_iRT(\\phi_i+ln(px_i))} \\] <p>\u901a\u8fc7\\(V=\\frac{\\partial G}{\\partial p},S=-\\frac{\\partial G}{\\partial T},H=G-T\\frac{\\partial G}{\\partial T}\\)\u53ef\u4ee5\u5f97\u5230V,S,H\u7684\u8868\u8fbe\u5f0f\uff1a</p> \\[ V=\\frac{\\sum n_iRT}{p}\\quad S=\\sum n_i\\left[\\int c_{pi}\\frac{dT}{T}-Rln(px_i) +s_{0i}\\right]\\quad H=\\sum n_i\\left(\\int c_{pi}dT+h_{0i}\\right) \\] <p>\u6b64\u5916\u4e5f\u53ef\u6c42\u51fa\u5185\u80fd\u7b49\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\uff0c\u6ce8\u610f\u9002\u7528\u6761\u4ef6\u662f\u7406\u60f3\u6c14\u4f53\u3002</p> <p>\u2605 \u8003\u5bdf\u71b5\u7684\u51fd\u6570S\uff0c\u53ef\u5c06\u71b5\u8868\u8fbe\u5f0f\u5199\u4e3a\u5982\u4e0b\u542f\u53d1\u610f\u4e49\u7684\u5f62\u5f0f\uff1a</p> \\[ S=\\sum n_i\\left[\\int c_{pi}\\frac{dT}{T}-Rln(p) +s_{0i}\\right]-R\\sum n_ilnx_i \\] <p>\u5176\u4e2d\u7b2c\u4e00\u9879\u4e3a\u7eaf\u7ec4\u5206\u7684\u71b5\u4e4b\u548c\uff0c\u7b2c\u4e8c\u9879\u662f\u6df7\u5408\u4e4b\u540e\u7684\u71b5\u589e\uff0c\u79f0\u4e3a\u6df7\u5408\u71b5\uff0c\u4e14\u6052\u6b63\u3002\u82e5\u5c06\u7ec4\u5206\u76f8\u540c\u7684\u6c14\u4f53\u6df7\u5408\uff0c\u6df7\u5408\u71b5\u5e94\u8be5\u4e0d\u4e3a0\uff1b\u4f46\u4ece\u71b5\u7684\u5e7f\u5ef6\u6027\u8d28\u6765\u770b\uff0c\u6df7\u5408\u4e4b\u540e\u7ec4\u5206\u6ca1\u53d8\u5316\uff0c\u6df7\u5408\u71b5\u4e3a0.\u8fd9\u5c31\u662f\u5409\u5e03\u65af\u4f6f\u8c2c.\u7a76\u5176\u539f\u56e0\uff0c\u9700\u8981\u7528\u5230\u5168\u540c\u7c92\u5b50\u7684\u7279\u6027\u6765\u89e3\u91ca\uff0c\u89c1\u540e\u9762\u7684\u7edf\u8ba1\u7269\u7406\u90e8\u5206\u3002</p>"},{"location":"chapter_04_multicomponent_system/03_chemical_equilibrium.html","title":"\u5316\u5b66\u5e73\u8861\u548c\u5316\u5b66\u5e38\u6570","text":""},{"location":"chapter_04_multicomponent_system/03_chemical_equilibrium.html#_1","title":"\u5316\u5b66\u5e73\u8861\u548c\u5316\u5b66\u5e38\u6570","text":"<p>\u2605 \u65b9\u4fbf\u8d77\u89c1\uff0c\u8fd9\u91cc\u4ec5\u8003\u8651\u5355\u76f8\u7cfb\u7684\u5316\u5b66\u5e73\u8861\u3002\u5316\u5b66\u53cd\u5e94\u4f5c\u4e3a\u5bf9\u7cfb\u7edf\u7ec4\u5206\u6469\u5c14\u91cf\u7684\u7ea6\u675f\u6761\u4ef6\uff0c\u9700\u8981\u62e5\u6709\u666e\u4e16\u7684\u6570\u5b66\u8868\u8ff0\u3002\u53ef\u4ee5\u5148\u4ece\u7b80\u5355\u3001\u5177\u4f53\u7684\u4f8b\u5b50\u5165\u624b\uff1a</p> \\[ 2\\mathrm{H}_2+\\mathrm{O}_2 \\xrightarrow{\\text{\u71c3\u70e7}} 2\\mathrm{H}_2\\mathrm{O} \\] <p>\u89c4\u5b9a\u751f\u6210\u7269\u7684\u5316\u5b66\u8ba1\u91cf\u6570\u4e3a\u6b63\uff0c\u53cd\u5e94\u7269\u7684\u4e3a\u8d1f\uff0c\u5e76\u7edf\u4e00\u7528\\(v_i\\)\u8868\u793a\u3002\u5404\u4e2a\u7ec4\u5206\u7684\u5316\u5b66\u5f0f\u7528\\(A_i\\)\u8868\u793a\u3002\u5219\u6b64\u5316\u5b66\u53cd\u5e94\u53ef\u5199\u4e3a\uff1a</p> \\[ \\sum_i v_iA_i=2\\mathrm{H}_2\\mathrm{O}-2\\mathrm{H}_2-\\mathrm{O}_2=0 \\] <p>\u5728\u5316\u5b66\u53cd\u5e94\u4e2d\uff0c\u7ec4\u5206\u7684\u53d8\u5316\u662f\u6839\u636e\u5316\u5b66\u8ba1\u91cf\u6570\u7684\u6bd4\u4f8b\u8fdb\u884c\u7684\uff0c\u5373\u53cd\u5e94\u8fdb\u5ea6\u7684\u5b9a\u4e49\u3002\u56e0\u800c\u53ef\u4ee5\u627e\u5230\u4e00\u4e2a\u5171\u540c\u7684\u6bd4\u4f8b\u56e0\u5b50\\(dn\\)\uff1a</p> \\[ dn_i=v_idn\\quad(i=1,2,...,k) \\] <p>\u8003\u8651\u7b49\u6e29\u7b49\u538b\u4e0b\u7684\u5409\u5e03\u65af\u5e73\u8861\u5224\u636e\uff0c\u5e76\u5c06\u4e0a\u5f0f\u53d8\u5206\u4ee3\u5165\uff1a</p> \\[ \\delta n_i=v_i\\delta n\\quad\\Rightarrow\\quad\\delta G=\\sum_i \\mu_i\\delta n_i=\\delta n\\sum_i v_i \\mu_i=0\\Rightarrow \\boxed{\\sum_iv_i\\mu_i=0} \\] <p>\u4e0a\u5f0f\u5373\u5316\u5b66\u5e73\u8861\u6761\u4ef6\u3002\u6839\u636e\\(\\delta G&lt;0\\)\u7684\u8d8b\u52bf\uff0c\u5f53\\(\\sum_iv_i\\mu_i&lt;0\\)\u65f6\u53cd\u5e94\u6b63\u5411\u8fdb\u884c\uff0c\\(\\sum_iv_i\\mu_i&gt;0\\)\u65f6\u53cd\u5e94\u9006\u5411\u8fdb\u884c\u3002</p> <p>\u2605 \u6211\u4eec\u5c06\u6df7\u5408\u6c14\u4f53\u7684\\(\\mu_i=RT(\\phi_i+ln(px_i))\\)\u4ee3\u5165\u5316\u5b66\u5e73\u8861\u6761\u4ef6\uff1a</p> \\[ \\sum_iv_i[RT(\\phi_i+ln(px_i))]=0\\Rightarrow \\sum_iv_iln(px_i)=\\boxed{-\\sum_iv_i\\phi_i(T)=lnK_p(T)} \\] <p>\u4e0a\u5f0f\u4e2d\\(K_p\\)\u5373\u5b9a\u538b\u5e73\u8861\u5e38\u6570\u3002\u4e25\u683c\u8bf4\u5e73\u8861\u5e38\u6570\u5e94\u7531\u65e0\u91cf\u7eb2\u7684\u76f8\u5bf9\u538b\u5f3a\u6216\u9038\u5ea6\u5b9a\u4e49\uff1b\u8fd9\u91cc\u6cbf\u7528\u70ed\u529b\u5b66\u7b14\u8bb0\u4e2d\u7684\u7b80\u5199\uff0c\u628a\u6807\u51c6\u538b\u5f3a\u5438\u6536\u5230\\(\\phi_i(T)\\)\u4e2d\u3002\u5229\u7528\\(p_i=px_i\\)\u53ef\u5c06\u5316\u5b66\u5e73\u8861\u6761\u4ef6\u5199\u4e3a\uff1a</p> \\[ K_p(T)=\\prod_ip_i^{v_i}=\\prod_ip^{v_i}x_i^{v_i}=p^{v}\\prod_ix_i^{v_i}=p^{v}K(T,p) \\] <p>\u4e0a\u5f0f\u4e2d\\(K(T,p)\\)\u79f0\u4e3a\u5e73\u8861\u5e38\u6570\uff0c\\(v=\\sum_iv_i\\)\u4e3a\u5316\u5b66\u8ba1\u91cf\u6570\u4e4b\u548c,\u5f53\u53cd\u5e94\u524d\u540e\u6469\u5c14\u6570\u4e0d\u53d8\u65f6\uff0c\\(K(T,p)\\)\u4e5f\u4ec5\u4ec5\u662f\u6e29\u5ea6\u7684\u51fd\u6570\u3002</p> <p>\u4e0e\u5316\u5b66\u5e73\u8861\u5224\u636e\u7c7b\u4f3c\uff0c\u5f53\\(\\prod_ip_i^{v_i}=K_p\\)\u65f6,\u5316\u5b66\u53cd\u5e94\u5e73\u8861\u3002\u5f53\\(\\prod_ip_i^{v_i}&lt;K_p\\)\u65f6,\u5316\u5b66\u53cd\u5e94\u6b63\u5411\u8fdb\u884c\u3002\u5f53\\(\\prod_ip_i^{v_i}&gt;K_p\\)\u65f6\uff0c\u5316\u5b66\u53cd\u5e94\u9006\u5411\u8fdb\u884c\u3002</p>"},{"location":"chapter_04_multicomponent_system/04_ideal_solution.html","title":"\u7406\u60f3\u6eb6\u6db2","text":""},{"location":"chapter_04_multicomponent_system/04_ideal_solution.html#_1","title":"\u7406\u60f3\u6eb6\u6db2","text":"<p>\u2605 \u6eb6\u6db2\u7406\u8bba\u5341\u5206\u590d\u6742\uff0c\u8fd9\u91cc\u4ec5\u4ec5\u8ba8\u8bba\u7b80\u5355\u7684\u7406\u60f3\u6eb6\u6db2\uff0c\u5373\u6eb6\u5242\u6ee1\u8db3\u62c9\u4e4c\u5c14\u5b9a\u5f8b\uff0c\u6eb6\u8d28\u6ee1\u8db3\u4ea8\u5229\u5b9a\u5f8b\u7684\u7a00\u6eb6\u6db2\u3002\u5bf9\u4e8e\u7ec4\u5143\\(n_i\\),\u5c06\u5360\u7edd\u5927\u591a\u6570\u7684\u6eb6\u5242\u8bbe\u4e3a\\(n_1\\)\uff0c\u5176\u4f59\u7684\u4e3a\u6eb6\u8d28\u3002\u6839\u636e\\(n_1\\)\u8db3\u591f\u5927\u7684\u6027\u8d28\uff0c\u5c06\u6eb6\u6db2\u7684\u5185\u80fd\u548c\u4f53\u79ef\u5c55\u5f00\u5230\u7ebf\u6027\u9879\uff1a</p> \\[ U=\\sum_{i=1}^ku_i(T,p)n_i\\qquad V=\\sum_{i=1}^kv_i(T,p)n_i \\] <p>\u7c7b\u6bd4\u6df7\u5408\u7406\u60f3\u6c14\u4f53\u7684\u71b5\uff0c\u6eb6\u6db2\u7684\u71b5\u4e5f\u53ef\u5199\u4f5c\uff1a</p> \\[ S=\\sum_{i=1}^k n_i( s_i(T,p)-Rln(x_i)) \\] <p>\u6709\u4e86\u4ee5\u4e0a\u7684\u57fa\u672c\u70ed\u529b\u5b66\u91cf\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ \\mu_i=g_i+RTln(x_i)\\qquad g_i=u_i+pv_i-Ts_i \\] <p>\u6211\u4eec\u5c06\u6eb6\u6db2\u4e2d\u67d0\u4e2a\u7ec4\u5143\\(i\\)\u7684\u84b8\u6c14\u770b\u4f5c\u7406\u60f3\u6c14\u4f53,\u6839\u636e\u5e73\u8861\u5316\u5b66\u52bf\u76f8\u7b49\uff1a</p> \\[ g_i+RTln(x_i)=RT(\\phi_i(T)+ln(p_i)) \\] <p>\u5c06\u5206\u538b\\(p_i\\)\u4e0e\\(x_i\\)\u5efa\u7acb\u8054\u7cfb\uff0c\u5e76\u8bbe\u6bd4\u4f8b\u7cfb\u6570\u4e3a\\(k_i\\)\u5219\uff1a</p> \\[ \\boxed{p_i=k_ix_i\\qquad lnk_i=\\frac{g_i}{RT}-\\phi_i(T)} \\] <p>\u5f53\\(i&gt;1\\)\u65f6\uff0c\u4e0a\u5f0f\u4e3a\u4ea8\u5229\u5b9a\u5f8b\uff0c\\(k_i\\)\u4e3a\u4ea8\u5229\u7cfb\u6570\uff0c\u968f\u6e29\u5ea6\u548c\u538b\u5f3a\u800c\u53d8\u5316\u3002\u5f53\\(i=1\\)\u65f6\uff0c\u4e0a\u5f0f\u4e3a\u62c9\u4e4c\u5c14\u5b9a\u5f8b\uff0c\u5e76\u4e14\u5229\u7528\u7eaf\u7269\u8d28\u7684\u6eb6\u5242\u6ee1\u8db3\uff1a</p> \\[ g_1+RTln(x_1)=g_1=RT(\\phi_1(T)+ln(p_1^*))\\Rightarrow lnk_1=lnp_1^*=\\frac{g_1}{RT}-\\phi_1(T) \\] <p>\u4ece\u800c\u62c9\u4e4c\u5c14\u5b9a\u5f8b\u4e5f\u5199\u4f5c\\(p_1=p_1^*x_1\\).</p> <p>\u2605 \u67d0\u534a\u900f\u819c\u53ea\u5141\u8bb8\u6eb6\u5242\u901a\u8fc7\uff0c\u5219\u4e00\u8fb9\u4e3a\u7eaf\u6eb6\u5242\uff0c\u53e6\u4e00\u8fb9\u5219\u4e3a\u7a00\u6eb6\u6db2\u3002\u7531\u4e8e\u7eaf\u6eb6\u5242\u7684\u5316\u5b66\u52bf\u5927\uff0c\u4ece\u800c\u7a00\u6eb6\u6db2\u9700\u8981\u5438\u6536\u6eb6\u5242\u4ea7\u751f\u989d\u5916\u538b\u5f3a\u4f7f\u5f97\u4e24\u8fb9\u5316\u5b66\u52bf\u5e73\u8861\uff0c\u6b64\u538b\u5f3a\u5219\u4e3a\u6e17\u900f\u538b\uff0c\u8bb0\u4e3a\\(\\Pi\\).\u6700\u7ec8\u5e73\u8861\u7684\u5316\u5b66\u52bf\u76f8\u7b49\u5f97\u5230\uff1a</p> \\[ \\mu_1(T,p^*)=\\mu_1(T,p)+RTln(x_1) \\] <p>\u7531\u4e8e\u8fc7\u7a0b\u7b49\u6e29\uff0c\u5e76\u5229\u7528\u8fd1\u4f3c\\(ln(x_1)=ln(1-\\sum_{i&gt;1}x_i)\\approx-\\sum_{i&gt;1}x_i\\),\u4ece\u800c\uff1a</p> \\[ \\mu_1(T,p)-\\mu_1(T,p^*)=\\int_{p^*}^{p} V_mdp=V_m(p-p^*)=V_m\\Pi=-RTln(x_1)=RT\\sum_{i&gt;1}x_i \\] <p>\u518d\u7531\u8fd1\u4f3c\\(\\sum_{i&gt;1}x_i=\\frac{n_B}{n_T}\\),\u4ece\u800c\u53ef\u4ee5\u7528\u6eb6\u8d28\u6469\u5c14\u6570\\(n_B\\)\u548c\u6eb6\u6db2\u4f53\u79ef\\(V_{sln}\\)\u8868\u8fbe\u4e3a\uff1a</p> \\[ \\Pi V_{sln}=n_BRT \\]"},{"location":"chapter_04_multicomponent_system/05_nernst_theorem.html","title":"\u80fd\u65af\u7279\u5b9a\u7406\u548c\u70ed\u529b\u5b66\u7b2c\u4e09\u5b9a\u5f8b","text":""},{"location":"chapter_04_multicomponent_system/05_nernst_theorem.html#_1","title":"\u80fd\u65af\u7279\u5b9a\u7406\u548c\u70ed\u529b\u5b66\u7b2c\u4e09\u5b9a\u5f8b","text":"<p>\u2605 \u80fd\u65af\u7279\u53d1\u73b0\u5728\u4f4e\u6e29\u4e0b\\(\\Delta G&lt;0\\)\u548c\\(\\Delta H&lt;0\\)\u4e24\u4e2a\u5316\u5b66\u53cd\u5e94\u7684\u5224\u636e\uff0c\u80fd\u7ed9\u51fa\u51e0\u4e4e\u76f8\u540c\u7684\u7ed3\u679c\u3002\u6211\u4eec\u8003\u8651\u7b49\u6e29\u8fc7\u7a0b\uff0c\u5e76\u8fd0\u7528\u6d1b\u5fc5\u8fbe\u6cd5\u5219\uff1a</p> \\[ \\Delta G=\\Delta H-T\\Delta S\\Rightarrow \\lim_{T \\to 0}(\\Delta S)=\\lim_{T \\to 0}\\frac{\\Delta H-\\Delta G}{T} =\\left(\\frac{\\partial \\Delta H}{\\partial T}\\right)_0-\\left(\\frac{\\partial \\Delta G}{\\partial T}\\right)_0 \\] <p>\u6839\u636e\u80fd\u65af\u7279\u7684\u76f8\u5207\u5047\u8bbe\uff0c\u5f97\u5230\uff1a</p> \\[ \\boxed{\\lim_{T \\to 0}(\\Delta S)=0} \\] <p>\u6b64\u5373\u70ed\u529b\u5b66\u7b2c\u4e09\u5b9a\u5f8b\u3002\u6b64\u5916\uff0c\u5176\u7b49\u4ef7\u8868\u8ff0\u4e3a\uff1a\u4e0d\u53ef\u80fd\u901a\u8fc7\u6709\u9650\u6b65\u9aa4\u4f7f\u5f97\u7269\u4f53\u51b7\u5374\u5230\u7edd\u5bf9\u96f6\u5ea6\u3002</p> <p>\u5bf9\u4e8e\u964d\u6e29\u800c\u8a00\uff0c\u6700\u6709\u6548\u7684\u662f\u53ef\u9006\u7edd\u70ed\u8fc7\u7a0b\u3002\u7531\u4e8e\u4f7f\u5f97\u7269\u4f53\u7684\u6e29\u5ea6\u5c3d\u53ef\u80fd\u4f4e\uff0c\u4e00\u5b9a\u4f1a\u4f4e\u4e8e\u5468\u56f4\u7269\u4f53\u7684\u6e29\u5ea6\uff0c\u4ece\u800c\u5438\u6536\u70ed\u91cf\uff0c\u56e0\u800c\u53ef\u9006\u7edd\u70ed\u8fc7\u7a0b\u6548\u679c\u6700\u597d\u3002\u5bf9\u4e8e\u6709\u9650\u6b65\u65e0\u6cd5\u8fbe\u5230\\(0K\\)\uff0c\u53ef\u4ee5\u7528\u7edd\u70ed\u53bb\u78c1\u5316\u7684\u4f8b\u5b50\uff0c\u5206\u6790\u5176S-T\u56fe\uff0c\u7c97\u7565\u5f97\u5230\u7ed3\u679c\u3002</p> <p>\u6700\u540e\uff0c\u70ed\u4e09\u8fd8\u544a\u8bc9\u6211\u4eec\\(S(0,y_A)=S(0,y_B)\\)\uff0c\u5373\u5728\\(0K\\)\u65f6\u4efb\u610f\u4e24\u79cd\u72b6\u6001\u7684\u71b5\u76f8\u7b49\u3002\u5229\u7528\u8fd9\u4e00\u6027\u8d28\uff0c\u53ef\u4ee5\u6709\u4ee5\u4e0b\u63a8\u8bba\u3002</p> <p>\u2605 \u9996\u5148\uff0c\u5bf9\u4e8e\u5728\u8d8b\u4e8e\\(0K\\)\u7684\u70ed\u5bb9\u6709\uff1a</p> \\[ C_y=T\\left(\\frac{\\partial S}{\\partial T}\\right)_y\\Rightarrow \\lim_{T \\to 0}C_y=0 \\] <p>\u6b64\u5916\uff0c\u5173\u4e8e\u71b5\u4e0e\u538b\u5f3a\u548c\u4f53\u79ef\u7684\u5173\u7cfb\uff0c\u5229\u7528\u9ea6\u6c0f\u5173\u7cfb\uff0c\u4e5f\u53ef\u5f97\u5230\u7c7b\u4f3c\u7684\u7ed3\u8bba\uff1a</p> \\[ \\lim_{T \\to 0}\\left(\\frac{\\partial S}{\\partial p}\\right)_T=\\lim_{T \\to 0}-\\left(\\frac{\\partial V}{\\partial T}\\right)_p=0\\qquad \\lim_{T \\to 0}\\left(\\frac{\\partial S}{\\partial V}\\right)_T=\\lim_{T \\to 0}\\left(\\frac{\\partial p}{\\partial T}\\right)_V=0 \\] <p>\u4e5f\u5c31\u662f\u8bf4\uff0c\u8d8b\u4e8e\\(0K\\)\u65f6\uff0c\\(\\alpha\\rightarrow0,\\beta\\rightarrow0\\)</p> <p>\u7531\u4e8e\\(0K\\)\u65f6\u4e0d\u540c\u76f8\u7684\u71b5\u4e5f\u76f8\u7b49\uff0c\u4ece\u800c\u6839\u636e\u514b\u62c9\u4f2f\u9f99\u65b9\u7a0b:</p> \\[ \\frac{dp}{dT}=\\frac{s^\\beta-s^\\alpha}{v^\\beta-v^\\alpha}=0 \\] <p>\u8fd9\u8bf4\u660e\uff0c\u4e00\u7ea7\u76f8\u53d8\u7684\u76f8\u5e73\u8861\u66f2\u7ebf\u8d8b\u4e8e\\(0K\\)\u65f6\uff0c\u659c\u7387\u4e3a0.</p> <p>\u2605 \u65e2\u7136\u4f53\u7cfb\u8d8b\u4e8e\\(0K\\)\u7684\u71b5\u4e3a\u7edd\u5bf9\u7684\u5e38\u6570\uff0c\u90a3\u4e48\u7d22\u6027\u76f4\u63a5\u4ee4\u5176\u4e3a0\uff0c\u8fd9\u4fbf\u662f\u666e\u6717\u514b\u5173\u4e8e\u7edd\u5bf9\u71b5\u6982\u5ff5\u7684\u60f3\u6cd5\u3002\u5373\uff1a</p> \\[ \\lim_{T \\to 0}S_0=0\\Rightarrow S(T,y)=\\int_0^T\\frac{C_y}{T}dT \\] <p>\u7edf\u8ba1\u7269\u7406\u4e2d\uff0c\u8fd8\u4f1a\u5bf9\u71b5\u6709\u66f4\u8fdb\u4e00\u6b65\u7684\u8ba4\u8bc6\u3002</p>"},{"location":"chapter_05_kinetic_theory/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_05_kinetic_theory/index.html#5","title":"\u7b2c5\u7ae0 \u5206\u5b50\u52a8\u7406\u5b66","text":"<p>\u70ed\u529b\u5b66\u4f9d\u6258\u4e8e\u70ed\u529b\u5b66\u5b9a\u5f8b\uff0c\u901a\u8fc7\u5b9e\u9a8c\u6d4b\u5f97\u67d0\u4e9b\u70ed\u529b\u5b66\u91cf\uff0c\u518d\u5229\u7528\u70ed\u529b\u5b66\u7684\u504f\u5bfc\u5173\u7cfb\u5bfc\u51fa\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\uff0c\u4ece\u800c\u552f\u8c61\u5730\u7814\u7a76\u5b8f\u89c2\u73b0\u8c61\u3002\u7136\u800c\uff0c\u5409\u5e03\u65af\u4f6f\u8c2c\u7b49\u8bf8\u591a\u95ee\u9898\u548c\u77db\u76fe\u5374\u4e0d\u80fd\u62b9\u9664\u3002\u7a76\u5176\u539f\u56e0\uff0c\u6b63\u662f\u56e0\u4e3a\u6ca1\u6709\u6df1\u5165\u5fae\u89c2\u7684\u673a\u7406\u3002</p> <p>\u7edf\u8ba1\u7269\u7406\u4fbf\u662f\u5728\u70ed\u529b\u5b66\u57fa\u672c\u6982\u5ff5\u548c\u5b9a\u4e49\u7684\u57fa\u7840\u4e4b\u4e0a\uff0c\u5efa\u7acb\u5b8f\u89c2\u91cf\u4e0e\u5fae\u89c2\u91cf\u7684\u5173\u7cfb\uff0c\u63a2\u7a76\u7269\u8d28\u66f4\u6df1\u523b\u7684\u673a\u7406\u3002\u4e00\u65b9\u9762\u4f7f\u5f97\u7406\u8bba\u8ba1\u7b97\u5bf9\u5b9e\u9a8c\u7684\u4f9d\u8d56\u6027\u8d8a\u6765\u8d8a\u5c0f\uff0c\u53e6\u4e00\u65b9\u9762\u4f7f\u5f97\u70ed\u529b\u5b66\u7684\u4e00\u4e9b\u95ee\u9898\u548c\u77db\u76fe\u5f97\u4ee5\u89e3\u51b3\u3002</p> <p>\u4f5c\u4e3a\u7edf\u8ba1\u7269\u7406\u7684\u5f15\u5b50\uff0c\u672c\u7ae0\u5feb\u901f\u56de\u987e\u4e00\u4e0b\u666e\u7269\u70ed\u5b66\u4e2d\u76f8\u5e94\u90e8\u5206\u7684\u57fa\u672c\u6982\u5ff5\u548c\u63a8\u5bfc\uff0c\u4e3a\u4e4b\u540e\u7edf\u8ba1\u7269\u7406\u601d\u7ef4\u7684\u517b\u6210\u505a\u94fa\u57ab\u3002</p>"},{"location":"chapter_05_kinetic_theory/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u78b0\u58c1\u6570\u3001\u538b\u5f3a\u3001\u6e29\u5ea6\u7684\u5fae\u89c2\u8868\u8fbe\u4e0e\u8303\u6c0f\u6c14\u4f53\u4fee\u6b63</li> <li>\u901f\u5ea6\u5206\u5e03</li> <li>\u8f93\u8fd0\u8fc7\u7a0b\u3001\u5e73\u5747\u81ea\u7531\u7a0b</li> </ul>"},{"location":"chapter_05_kinetic_theory/01_collision_pressure_temperature.html","title":"\u78b0\u58c1\u6570\u3001\u538b\u5f3a\u3001\u6e29\u5ea6\u7684\u5fae\u89c2\u8868\u8fbe\u4e0e\u8303\u6c0f\u6c14\u4f53\u4fee\u6b63","text":""},{"location":"chapter_05_kinetic_theory/01_collision_pressure_temperature.html#_1","title":"\u78b0\u58c1\u6570\u3001\u538b\u5f3a\u3001\u6e29\u5ea6\u7684\u5fae\u89c2\u8868\u8fbe\u4e0e\u8303\u6c0f\u6c14\u4f53\u4fee\u6b63","text":"<p>\u2605 \u5206\u5b50\u78b0\u58c1\u6570\u7684\u63a8\u5bfc\u57fa\u4e8e\u4ee5\u4e0b\u5047\u8bbe\uff1a(1)\u5206\u5b50\u7684\u7ebf\u5ea6&lt;&lt;\u5206\u5b50\u4e4b\u95f4\u7684\u8ddd\u79bb(2)\u4e0d\u8003\u8651\u78b0\u649e\u4e4b\u5916\u7684\u4f5c\u7528\uff0c\u4e14\u5206\u5b50\u5300\u901f\u76f4\u7ebf\u8fd0\u52a8(3)\u5904\u4e8e\u5e73\u8861\u6001\u7684\u7406\u60f3\u6c14\u4f53\uff0c\u4e0e\u58c1\u53d1\u751f\u5b8c\u5168\u5f39\u6027\u78b0\u649e(4)\u5206\u5b50\u6df7\u6c8c\u6027\u5047\u8bbe(\u7a7a\u95f4\u5404\u5411\u540c\u6027)</p> <p>\u8fd9\u662f\u4e00\u4e2a\u5178\u578b\u7684\u201c\u53cc\u5355\u201d\u95ee\u9898\uff0c\u5373\u5355\u4f4d\u65f6\u95f4\u5355\u4f4d\u9762\u79ef\u53d1\u751f\u7684\u7269\u7406\u8fc7\u7a0b\u3002\u5047\u8bbe\u7c92\u5b50\u78b0\u58c1\u7684\u9762\u79ef\u4e3a\\(\\Delta A\\)\uff0c\u5e73\u5747\u901f\u5ea6\u4e3a\\(\\bar{v}\\),\u6570\u5bc6\u5ea6\u4e3a\\(n\\),\u53ef\u5f97\u8fc7\u7a0b\u7ecf\u5386\\(\\Delta t\\)\u7684\u65f6\u95f4\u5bf9\u67d0\u4e00\u65b9\u5411\u53d1\u751f\u78b0\u649e\u7684\u7c92\u5b50\u6570\u4e3a\\(\\Delta N\\),\u518d\u7531\u5206\u5b50\u78b0\u58c1\u6570\\(\\Gamma\\)\u7684\u5b9a\u4e49\u5f97\u5230\uff1a</p> \\[ \\boxed{\\Delta N=\\Delta A \\bar{v}\\Delta t\\frac{n}{6}}\\quad\\Rightarrow\\quad \\Gamma=\\frac{\\Delta N}{\\Delta A\\Delta t}=\\frac{n\\bar{v}}{6} \\] <p>\u4e0a\u5f0f\u7684\\(1/6\\)\u6765\u81ea\u4e8e\u6df7\u6c8c\u6027\u5047\u8bbe\uff0c\u5373\u4e09\u7ef4\u7a7a\u95f4\u516d\u4e2a\u65b9\u5411\u78b0\u649e\u65b9\u5411\u3002\u7136\u800c\u66f4\u52a0\u7cbe\u786e\u7684\u7ed3\u679c\u5e94\u8be5\u4e3a\\(1/4\\)\uff0c\u540e\u9762\u5f15\u5165\u9ea6\u514b\u65af\u97e6\u5206\u5e03\u518d\u6765\u63a8\u5bfc\u3002</p> <p>\u4e0b\u9762\u57fa\u4e8e\u7c7b\u4f3c\u7684\u65b9\u6cd5\u63a8\u5bfc\u538b\u5f3a\u7684\u8868\u8fbe\u5f0f\u3002\u7531\u4e8e\u5047\u8bbe\u78b0\u58c1\u53d1\u751f\u7684\u662f\u5b8c\u5168\u5f39\u6027\u78b0\u649e\uff0c\u4ece\u800c\u5206\u5b50\u78b0\u649e\u524d\u540e\u52a8\u91cf\u6539\u53d8\\(\\Delta P=2m\\bar{v}\\Delta N\\),\u4ece\u800c\uff1a</p> \\[ p=\\frac{F}{\\Delta A}=\\frac{\\Delta P}{\\Delta A\\Delta t}=\\frac{2m\\bar{v}\\Delta N}{\\Delta A\\Delta t}=\\frac{\\overline{v}^2mn}{3}\\approx \\frac{nm\\overline{v^2}}{3}\\Rightarrow \\boxed{p=\\frac{nm\\overline{v^2}}{3}} \\] <p>\u4e0a\u5f0f\u7528\u5230\u8fd1\u4f3c\\(\\bar{v}^2\\approx\\bar{v^2}\\).\u8003\u8651\u5206\u5b50\u5e73\u52a8\u52a8\u80fd\\(\\bar{E_t}=\\frac{1}{2}m\\bar{v^2}\\)\u548c\u7406\u60f3\u6c14\u4f53\u65b9\u7a0b\u7684\u53d8\u5f62\\(p=nkT\\) \u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ p=\\frac{nm\\overline{v^2}}{3}=\\frac{2n}{3}\\bar{E_t}=nkT\\quad\\Rightarrow\\quad \\boxed{\\bar{E_t}=\\frac{3}{2}kT} \\] <p>\u4e0a\u5f0f\u5373\u5efa\u7acb\u4e86\u5e73\u5747\u5e73\u52a8\u52a8\u80fd\u4ec5\u4e0e\u6e29\u5ea6\u7684\u6b63\u6bd4\u5173\u7cfb\uff0c\u4e5f\u662f\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u7684\u57fa\u7840\u3002\u81f3\u6b64\uff0c\u5df2\u5c06\u5b8f\u89c2\u91cf\\(p,T\\)\u4e0e\u5206\u5b50\u7684\u5e73\u52a8\u52a8\u80fd\\(\\bar{E_t}\\)\u548c\u6570\u5bc6\u5ea6\\(n\\)\u8054\u7cfb\u8d77\u6765\u3002</p> <p>\u2605 \u8fd9\u91cc\u76f4\u89c2\u5730\u89e3\u91ca\u4e00\u4e0b\u8303\u6c0f\u6c14\u4f53\u4fee\u6b63\u9879\u7684\u7531\u6765\uff0c\u4e25\u683c\u7684\u63a8\u5bfc\u9700\u8981\u7528\u5230\u7cfb\u7efc\u7406\u8bba\u3002\u9996\u5148\u8003\u8651\\(1mol\\)\u5206\u5b50\u7684\u4f53\u79ef\\(b\\)\uff0c\u4ece\u800c\u5bf9\u4e8e\\(nmol\\)\u4f53\u79ef\u4fee\u6b63\u4e3a\\(V\\rightarrow (V-nb)\\).\u5176\u6b21\u8003\u8651\u5206\u5b50\u4e4b\u95f4\u7684\u5185\u805a\u529b\uff0c\u7c97\u7565\u6765\u8bb2\uff0c\\(N\\)\u4e2a\u5206\u5b50\u4e4b\u95f4\u4e24\u4e24\u7ec4\u5408\u7684\u5438\u5f15\u529b\u9879\u4e3a\\(\\frac{N(N-1)}{2}\\approx\\frac{N^2}{2}\\backsim N^2\\)\uff0c\u5355\u4f4d\u4f53\u79ef\u6469\u5c14\u6570\u4e3a\\(\\frac{n}{V}\\backsim N\\)\uff0c\u4ece\u800c\u53ef\u4ee5\u5f15\u5165\u7cfb\u6570\\(a\\)\u5c06\u538b\u5f3a\u9879\u4fee\u6b63\u4e3a\\(p\\rightarrow (p+\\frac{an^2}{V^2})\\),\u7531\u6b64\u5f97\u5230\uff1a</p> \\[ (V-nb)(p+\\frac{an^2}{V^2})=nRT \\]"},{"location":"chapter_05_kinetic_theory/02_velocity_distribution.html","title":"\u901f\u5ea6\u5206\u5e03","text":""},{"location":"chapter_05_kinetic_theory/02_velocity_distribution.html#_1","title":"\u901f\u5ea6\u5206\u5e03","text":"<p>\u2605 \u4ece\u6982\u7387\u8bba\u7684\u89d2\u5ea6\u800c\u8a00\uff0cMaxwell\u901f\u5ea6\u5206\u5e03\u5373\u6b63\u6001\u5206\u5e03\uff1a</p> \\[ v_x\\backsim N(0,\\frac{kT}{m})\\Rightarrow f(v_x)=\\sqrt{\\frac{m}{2\\pi kT}}e^{-\\frac{mv_x^2}{2kT}}\\Rightarrow\\boxed{f(\\vec{v})=\\left(\\frac{m}{2\\pi kT}\\right)^{\\frac{3}{2}}e^{-\\frac{mv^2}{2kT}}} \\] <p>\u7531\u6b64\u4e0d\u96be\u5f97\u5230\u4e09\u7ef4\u5230\u4e00\u7ef4\u7a7a\u95f4\u7684Maxwell\u901f\u7387\u5206\u5e03\uff1a</p> \\[ f(v)\\backsim 4\\pi v^2f(\\vec{v})\\qquad f(v)\\backsim 2\\pi vf(v_x)f(v_y)\\qquad f(v)\\backsim 2f(v_x) \\] <p>\u5206\u522b\u5bf9\u5e94\u901f\u5ea6\u7a7a\u95f4\u7684\u7403\u58f3\u8868\u9762\u79ef\u3001\u5706\u7684\u5468\u957f\u3001\u5173\u4e8e\u539f\u70b9\u5bf9\u79f0\u7684\u4e24\u70b9\u3002\u5176\u4e2d\u4e09\u7ef4\u7a7a\u95f4\u7684\u6700\u4e3a\u5e38\u7528\uff0c\u5373\uff1a</p> \\[ f(v)=4\\pi v^2\\left(\\frac{m}{2\\pi kT}\\right)^{\\frac{3}{2}}e^{-\\frac{mv^2}{2kT}} \\] <p>\u5229\u7528\u4e09\u7ef4\u901f\u7387\u5206\u5e03\uff0c\u53ef\u4ee5\u6c42\u51fa\u5e73\u5747\u901f\u7387\u3001\u65b9\u5747\u6839\u901f\u7387\u3001\u6700\u51e0\u901f\u7387\uff1a</p> \\[ \\bar{v}=\\frac{\\int_0^\\infty vf(v)dv}{\\int_0^\\infty f(v)dv}=\\sqrt{\\frac{8kT}{\\pi m}}\\qquad v_{rms}=\\sqrt{\\frac{\\int_0^\\infty v^2f(v)dv}{\\int_0^\\infty f(v)dv}}=\\sqrt{\\frac{3kT}{m}} \\] \\[ f'(v)=0\\Rightarrow v_p=\\sqrt{\\frac{2kT}{m}} \\] <p>\u2605 \u6839\u636e\u4ee5\u4e0a\u516c\u5f0f\uff0c\u8003\u8651x\u8f74\u67d0\u4e00\u65b9\u5411\u7684\u7c92\u5b50\u4e0e\u5668\u58c1\u53d1\u751f\u7684\u78b0\u649e\uff0c\u53ef\u4ee5\u66f4\u52a0\u4e25\u683c\u5730\u5bfc\u51fa\\(\\Gamma\\)\u7684\u5fae\u89c2\u8868\u8fbe\uff1a</p> \\[ \\Gamma=\\frac{\\Delta N}{\\Delta A\\Delta t}=\\frac{n\\Delta A\\overline{v}_{x_+}\\Delta t}{\\Delta A\\Delta t}=n\\int_0^\\infty v_xf(v_x)dv_x=n\\sqrt{\\frac{kT}{2\\pi m}}=\\frac{n\\bar{v}}{4} \\] <p>\u4eceMaxwell\u5206\u5e03\u8fd8\u53ef\u4ee5\u770b\u51fa\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u7684\u4e00\u4e9b\u542f\u793a\uff0c\u5373\u6709\\(\\bar{v^2}=3\\bar{v_x^2}=3\\bar{v_y^2}=3\\bar{v_z^2}\\)(\u6ce8\u610f\u901f\u5ea6\u548c\u901f\u7387\u79ef\u5206\u4e0a\u4e0b\u9650\u7684\u533a\u522b)\uff1a</p> \\[ \\int_0^\\infty v^2f(v)\\,dv=3\\int_{-\\infty}^\\infty v_x^2f(v_x)\\,dv_x=3\\int_{-\\infty}^\\infty v_y^2f(v_y)\\,dv_y=3\\int_{-\\infty}^\\infty v_z^2f(v_z)\\,dv_z=\\frac{3kT}{m} \\] <p>\u2605 \u6b64\u5916\uff0c\u8fd8\u6709\u6240\u8c13\u73bb\u5c14\u5179\u66fc\u5206\u5e03\uff0c\u5373\u5bf9\u4e8e\u4fdd\u5b88\u573a\u7684\u52bf\u80fd\\(\\epsilon(r) \\),\u7c92\u5b50\u6570\u670d\u4ece\uff1a</p> \\[ N(r)\\propto e^{-\\frac{\\epsilon(r) }{kT}} \\] <p>\u7531\u6b64\uff0cMaxwell\u901f\u5ea6\u5206\u5e03\u4e5f\u53ef\u770b\u4f5c\u662f\\(\\epsilon=\\frac{1}{2}mv^2 \\)\u7684\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u3002</p>"},{"location":"chapter_05_kinetic_theory/03_transport_mean_free_path.html","title":"\u8f93\u8fd0\u8fc7\u7a0b\u3001\u5e73\u5747\u81ea\u7531\u7a0b","text":""},{"location":"chapter_05_kinetic_theory/03_transport_mean_free_path.html#_1","title":"\u8f93\u8fd0\u8fc7\u7a0b\u3001\u5e73\u5747\u81ea\u7531\u7a0b","text":"<p>\u2605 \u5bf9\u4e8e\u975e\u5e73\u8861\u6001\u7684\u8f93\u8fd0\u8fc7\u7a0b\uff0c\u8fd9\u91cc\u4ec5\u8ba8\u8bba\u7c98\u6ede(\u52a8\u91cf\u8f6c\u79fb),\u6269\u6563(\u8d28\u91cf\u8f6c\u79fb),\u70ed\u4f20\u5bfc(\u80fd\u91cf\u8f6c\u79fb).</p> <p>\u25a0 \u5bf9\u4e8e\u7c98\u6ede\uff0c\u53ef\u4ee5\u4ece\u725b\u987f\u7c98\u6ede\u65b9\u7a0b\u5165\u624b\uff1a</p> \\[ f=\\frac{dP}{dt}=-\\eta\\frac{du}{dz}A\\Rightarrow J_p=\\frac{dP}{Adt}=-\\eta\\frac{du}{dz}\\Rightarrow \\boxed{J_p=-\\eta \\partial_z u} \\] <p>\\(J_p\\)\u4e3a\u5207\u5411\u52a8\u91cf\u6d41\u5bc6\u5ea6\uff0c\u5373\u5355\u4f4d\u65f6\u95f4\u5355\u4f4d\u9762\u79ef\u4e0d\u540c\u5c42\u4e4b\u95f4\u8f6c\u79fb\u7684\u52a8\u91cf\u3002</p> <p>\u5fae\u89c2\u673a\u5236\uff1a\u6d41\u4f53\u5206\u5b50\u7531\u4e8e\u70ed\u8fd0\u52a8\u800c\u5728\u5c42\u6d41\u95f4\u7a7f\u884c\uff0c\u70ed\u8fd0\u52a8\u5bfc\u81f4 \u7684\u4f20\u9012\u7387\u5404\u5411\u540c\u6027\uff0c\u4f46\u662f\u52a8\u91cf\u7684\u4ea4\u6362\u4e0d\u5747\u5300\uff0c\u4f1a\u5bfc\u81f4\u52a8\u91cf\u4e0d\u540c\u7684\u4e24\u5c42\u9010\u6e10\u7f29\u5c0f\u5dee\u8ddd\u3002</p> <p>\u25a0 \u5bf9\u4e8e\u6269\u6563\uff0c\u8981\u6ce8\u610f\u533a\u5206\u81ea\u6269\u6563(\u603b\u4f53\u8d28\u5fc3\u4f4d\u79fb\u4e0d\u5927)\u3001\u4e92\u6269\u6563(\u603b\u4f53\u8d28\u5fc3\u4f4d\u79fb\u8f83\u5927)\u548c\u81ea\u7531\u6269\u6563(\u5206\u5b50\u5411\u771f\u7a7a\u4e0d\u53d7\u963b\u788d\u7684\u6269\u6563)\u3002\u6269\u6563\u7531\u83f2\u514b\u5b9a\u5f8b\u63cf\u8ff0\uff1a</p> \\[ J_N=-D\\frac{dn}{dz}\\Rightarrow \\boxed{J_N=-D\\nabla n} \\] <p>\\(J_N\\)\u4e3a\u201c\u53cc\u5355\u201d\u7684\u6269\u6563\u7c92\u5b50\u6570\uff0cD\u4e3a\u6269\u6563\u7cfb\u6570\u3002</p> <p>\u5fae\u89c2\u673a\u5236\uff1a\u5206\u5b50\u6570\u5bc6\u5ea6\u4e0d\u5747\u5300\u5e76\u4e14\u6ca1\u6709\u529b\u91cf\u7ef4\u6301\u8fd9\u79cd\u4e0d\u5747\u5300\uff0c\u4e8e\u662f\u53d1\u751f\u5c42\u95f4\u5206\u5b50\u8d28\u91cf\u7684\u51c0\u4ea4\u6362\u3002</p> <p>\u25a0 \u5bf9\u4e8e\u70ed\u4f20\u5bfc\uff0c\u4ec5\u4ec5\u662f\u70ed\u4f20\u9012\u7684\u5185\u5bb9\u4e4b\u4e00\u3002\u81f3\u4e8e\u70ed\u5bf9\u6d41\u548c\u70ed\u8f90\u5c04\uff0c\u8fd9\u91cc\u4e0d\u8fdb\u884c\u8ba8\u8bba\u3002\u70ed\u4f20\u5bfc\u7531\u5085\u91cc\u53f6\u5b9a\u5f8b\u63cf\u8ff0\uff1a</p> \\[ J_T=-\\kappa\\frac{dT}{dz}\\Rightarrow \\boxed{J_T=-\\kappa\\nabla T} \\] <p>\\(J_T\\)\u4e3a\u70ed\u6d41\u5bc6\u5ea6\u3002\u7c7b\u6bd4\u7535\u538b\u3001\u7535\u963b\u548c\u7535\u6d41\uff0c\u70ed\u4f20\u5bfc\u4e5f\u6709\u7c7b\u4f3c\u7684\u5f0f\u5b50\uff0c\u8fd9\u91cc\u4ece\u7565\u3002</p> <p>\u5fae\u89c2\u673a\u5236\uff1a\u5bf9\u4e8e\u6c14\u4f53\uff0c\u70ed\u8fd0\u52a8\u4f7f\u5f97\u4e0d\u540c\u80fd\u91cf\u7684\u5206\u5b50\u53d1\u751f\u4ea4\u6362\uff1b\u5bf9\u4e8e\u56fa\u4f53\u548c\u6db2\u4f53\uff0c\u4e3b\u8981\u662f\u632f\u52a8\u7684\u5206\u5b50\u53d1\u751f\u78b0\u649e\u800c\u4f20\u9012\u80fd\u91cf\u3002</p> <p>\u66f4\u8fdb\u4e00\u6b65\uff0c\u5982\u679c\u7528\u573a\u7684\u601d\u60f3\u6765\u8003\u8651\u70ed\u4f20\u5bfc\u95ee\u9898\uff0c\u8bbe\u4f53\u79ef\u4e3a\\(V\\)\u8868\u9762\u79ef\u4e3a\\(S\\)\u7684\u533a\u57df\uff0c\u201c\u53cc\u5355\u201d\u653e\u51fa\u7684\u70ed\u91cf\u4e3a\\(f\\)\uff0c\u4e14\u8be5\u533a\u57df\u6bd4\u70ed\u5bb9\u4e3a\\(c\\)\uff0c\u5bc6\u5ea6\u4e3a\\(\\rho\\).\u7528\u6807\u91cf\u573a\\(u(\\vec{r},t)\\)\u6765\u63cf\u8ff0\u533a\u57df\u7684\u6e29\u5ea6\uff0c\u7531\u7269\u8d28\u589e\u52a0\u7684\u70ed\u91cf\u7b49\u4e8e\u6d41\u8fdb\u533a\u57df\u7684\u70ed\u4e0e\u533a\u57df\u5185\u4ea7\u751f\u7684\u70ed\u4e4b\u548c\uff0c\u53ef\u5199\u51fa\uff1a</p> \\[ \\int_V{c\\rho d\\tau u_t}=-\\oint_S\\vec{J_T}\\cdot\\vec{n}d\\sigma+\\int_Vfd\\tau=-\\int_V\\nabla\\cdot\\vec{J_T}d\\tau+\\int_Vfd\\tau \\] <p>\u4ee3\u5165\\(J_T=-\\kappa\\nabla u\\),\u4e0d\u96be\u5f97\u5230\u4f53\u7cfb\u7684\u5fae\u5206\u65b9\u7a0b\uff0c\u518d\u4ee4\u533a\u57df\u5747\u5300(\\(\\kappa=Const.\\))\u4e14\u65e0\u70ed\u6e90(\\(f=0\\))\u5219\u53ef\u5316\u4e3a\uff1a</p> \\[ c\\rho u_t=f+\\nabla\\cdot(\\kappa\\nabla u)\\Rightarrow \\boxed{u_t-\\frac{\\kappa}{\\rho c}\\nabla^2u=\\frac{f}{\\rho c}}\\Rightarrow \\boxed{u_t=\\frac{\\kappa}{\\rho c}\\nabla^2u} \\] <p>\u5373\u5f97\u5230\u70ed\u4f20\u5bfc\u65b9\u7a0b\u3002</p> <p>\u2605 \u5e73\u5747\u81ea\u7531\u7a0b\u5373\u7c92\u5b50\u5e73\u5747\u4e24\u6b21\u78b0\u649e\u6240\u8d70\u7684\u4f4d\u79fb\u3002\u5b9a\u4e49\\(\\bar{Z}\\)\u4e3a\u5355\u4e2a\u7c92\u5b50\u5355\u4f4d\u65f6\u95f4\u78b0\u649e\u7684\u5e73\u5747\u6b21\u6570\uff0c\\(\\bar{v}\\)\u5373\u5355\u4f4d\u65f6\u95f4\u5e73\u5747\u4f4d\u79fb\uff0c\u4ece\u800c\u53ef\u4ee5\u5b9a\u4e49\\(\\bar{\\lambda}=\\frac{\\bar{v}}{\\bar{Z}}\\).</p> <p>\u4ece\u800c\u7814\u7a76\u6e05\u695a\\(\\bar{Z}\\)\u5f88\u5173\u952e\uff0c\u8fd9\u91cc\u518d\u5f15\u5165\u78b0\u649e\u622a\u9762\u7684\u6982\u5ff5\u3002\u8bbe\u4e24\u79cd\u7c92\u5b50\u7684\u534a\u5f84\u4e3a\\(r_A,r_B\\)\u5219\u4e4b\u95f4\u7684\u78b0\u649e\u622a\u9762\u4e3a\\(\\sigma=\\pi(r_A+r_B)^2\\).\u73b0\u5728\u4ee5\u5355\u4e2a\u7c92\u5b50\u4e3a\u53c2\u8003\u7cfb\uff1a</p> \\[ \\bar{Z}=\\frac{\\Delta N}{\\Delta t}=\\frac{n\\sigma \\bar{v_{12}}\\Delta t}{\\Delta t}=\\sqrt{2}n\\sigma\\bar{v} \\] <p>\u4e3a\u4e86\u7b80\u5355\u8ba8\u8bba\uff0c\u4e0a\u5f0f\u5229\u7528\u4e86\u540c\u79cd\u7c92\u5b50\u901f\u5ea6\u7edf\u8ba1\u7684\u5173\u7cfb\u5f0f\uff1a\\(\\overline{v}_{12}=\\sqrt{2}\\bar{v}\\),\u7531\u4e8e\u4e0e\u73bb\u5c14\u5179\u66fc\u79ef\u5206\u5fae\u5206\u65b9\u7a0b\u6709\u5173(\u8be6\u89c1\u6c6a\u4e66\u4e60\u989811-5)\uff0c\u8fd9\u91cc\u76f4\u63a5\u7528\u7ed3\u8bba\u3002\u4f46\u5bf9\u4e8e\u7535\u5b50\uff0c\u5176\u901f\u5ea6\u8fc7\u5927\uff0c\u4ece\u800c\u6709\u8fd9\u6837\u7684\u5173\u7cfb\\(\\overline{v}_{12}\\approx\\bar{v}\\).\u901a\u5e38\u800c\u8a00\uff0c\u5e73\u5747\u81ea\u7531\u7a0b\u4e3a\uff1a</p> \\[ \\boxed{\\bar{\\lambda}=\\frac{\\bar{v}}{\\bar{Z}}=\\frac{1}{\\sqrt{2}n\\sigma}=\\frac{kT}{\\sqrt{2}\\sigma p}} \\] <p>\u6b64\u5916\uff0c\u5bf9\u4e8e\u7a00\u8584\u6c14\u4f53\uff0c\u82e5\u5bb9\u5668\u5c3a\u5ea6\u4e3aL,\u5219\u6709\\(\\bar{\\lambda}\\approx L\\).\u901a\u5e38\u7c98\u6ede\u5bf9\u5e94\u4e0e\u5668\u58c1\u6469\u64e6\uff0c\u6269\u6563\u5bf9\u5e94\u6cfb\u6d41\uff0c\u70ed\u4f20\u5bfc\u5bf9\u5e94\u4e0e\u5668\u58c1\u4ea4\u6362\u80fd\u91cf\u3002\u8fd9\u91cc\u4e0d\u8be6\u7ec6\u5c55\u5f00\u3002</p> <p>\u2605 \u6700\u540e\u5229\u7528\u5e73\u5747\u81ea\u7531\u7a0b\u7c97\u7565\u63a8\u5bfc\u4e09\u79cd\u8f93\u8fd0\u73b0\u8c61\u7684\u7cfb\u6570\u8868\u8fbe\u5f0f\u3002\u57fa\u672c\u5047\u8bbe\uff1a\u6240\u6709\u7a7f\u8fc7\u5206\u754c\u9762\u8fdb\u884c\u8f93\u8fd0\u7684\u5206\u5b50\u5747\u6765\u81ea\u4e8e\u79bb\u5206\u754c\u9762\u8ddd\u79bb\u7b49\u4e8e\u5e73\u5747\u81ea\u7531\u7a0b\u7684\u5730\u65b9,\u4e14\u9ed8\u8ba4\\(\\Gamma=\\frac{n\\bar{v}}{6}\\).</p> \\[ f=\\frac{dP}{dt}=\\frac{\\frac{1}{6}n\\bar{v}Adtm(u_d-u_u)}{dt}=-\\frac{\\frac{1}{6}n\\bar{v}Adtm \\frac{du}{dz}\\Delta z}{dt}=-\\frac{\\frac{1}{6}n\\bar{v}Adtm \\frac{du}{dz}2\\bar{\\lambda}}{dt} \\] \\[ =-\\frac{1}{3}nm\\bar{v}\\bar{\\lambda}\\frac{du}{dz}A\\Rightarrow \\boxed{\\eta=\\frac{1}{3}nm\\bar{v}\\bar{\\lambda}=\\frac{1}{3}\\rho \\bar{v}\\bar{\\lambda}} \\] \\[ J_N=\\frac{dN}{dtA}=\\frac{\\Delta\\Gamma dtA}{dtA}=\\frac{1}{6}\\Delta n\\bar{v}=\\frac{1}{6}\\bar{v}\\left(-2\\frac{dn}{dz}\\bar{\\lambda}\\right)= -\\frac{1}{3}\\bar{v}\\bar{\\lambda}\\frac{dn}{dz} \\Rightarrow \\boxed{D=\\frac{1}{3}\\bar{v}\\bar{\\lambda}} \\] \\[ J_T=\\frac{dQ}{dtA}=\\frac{\\Gamma \\Delta \\bar{E}dtA}{dtA}=\\frac{1}{6} n\\bar{v}\\Delta\\bar{E_t}=\\frac{1}{6}n\\bar{v}\\left(-2\\frac{d\\bar{E_t}}{dT}\\frac{dT}{dz}\\bar{\\lambda}\\right)=\\frac{1}{6}n\\bar{v}\\left(-3k\\frac{dT}{dz}\\bar{\\lambda}\\right)= \\] \\[ -\\frac{1}{2}kn\\bar{v}\\bar{\\lambda}\\frac{dT}{dz}\\Rightarrow \\boxed{\\kappa=\\frac{1}{2}kn\\bar{v}\\bar{\\lambda}} \\] <p>\u6ce8\u610f\uff0c\u8fd9\u91cc\u8003\u8651\u5c42\u4e0e\u5c42\u4e4b\u95f4\u7684\u8f93\u8fd0\u8fc7\u7a0b\uff0c\u901a\u5e38\u4e0a\u5c42\u88ab\u635f\u5931\uff0c\u4e0b\u5c42\u88ab\u83b7\u5f97\uff0c\u56e0\u800c\u8981\u4ed4\u7ec6\u8003\u91cf\u6b63\u8d1f\u53f7\u7684\u95ee\u9898\u3002\u4e25\u683c\u7684\u63a8\u5bfc\u6709\u4e9b\u590d\u6742\uff0c\u8fd9\u91cc\u4ec5\u91c7\u7528\u666e\u7269\u70ed\u5b66\u7684\u65b9\u6cd5\u3002\u6700\u540e\u7684\u70ed\u5bfc\u7387\u4e5f\u4ec5\u8003\u8651\u7684\u5355\u539f\u5b50\u5206\u5b50\u7684\u5e73\u52a8\u52a8\u80fd\u3002</p>"},{"location":"chapter_06_most_probable_distribution/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_06_most_probable_distribution/index.html#6","title":"\u7b2c6\u7ae0 \u8fd1\u72ec\u7acb\u5b50\u7cfb\u6700\u6982\u7136\u5206\u5e03","text":"<p>\u672c\u7ae0\u4f5c\u4e3a\u7edf\u8ba1\u7269\u7406\u90e8\u5206\u7684\u6b63\u5f0f\u5f00\u59cb\uff0c\u9996\u5148\u4ecb\u7ecd\u7edf\u8ba1\u7269\u7406\u7684\u601d\u60f3\u65b9\u6cd5\uff0c\u5373\u5fae\u89c2\u4e0e\u5b8f\u89c2\u5982\u4f55\u6c9f\u901a\u7684\u7ec6\u8282\u3002\u5728\u8fd9\u4e9b\u601d\u60f3\u65b9\u6cd5\u7684\u57fa\u7840\u4e0a\uff0c\u5bf9\u4e00\u4e9b\u6982\u5ff5\u548c\u63cf\u8ff0\u8fdb\u884c\u5b9a\u91cf\u5316\uff0c\u5e76\u5bfc\u51fa\u4e09\u79cd\u7edf\u8ba1\u7684\u6700\u6982\u7136\u5206\u5e03\u3002</p> <p>\u6b64\u5916\uff0c\u8981\u6ce8\u610f\u8ba8\u8bba\u7684\u51fa\u53d1\u70b9\u662f\u91cf\u5b50\u7cfb\u7edf\uff0c\u7ecf\u5178\u7cfb\u7edf\u88ab\u770b\u4f5c\u662f\u91cf\u5b50\u7cfb\u7edf\u7684\u67d0\u79cd\u7ecf\u5178\u6781\u9650\u3002\u540c\u65f6\uff0c\u8fd9\u91cc\u7528\u5230\u7684\u201c\u8fd1\u72ec\u7acb\u5b50\u7cfb\u201d\u4ec5\u662f\u4e4b\u540e\u7cfb\u7efc\u7406\u8bba\u7684\u7b80\u5316\u60c5\u51b5\uff0c\u6240\u4ee5\u5927\u591a\u6570\u63a8\u5bfc\u4e0d\u662f\u5f88\u4e25\u683c\uff0c\u4f46\u5bf9\u7edf\u8ba1\u7269\u7406\u7684\u521d\u6b65\u7406\u89e3\u7684\u786e\u5e2e\u52a9\u5f88\u5927\u3002</p>"},{"location":"chapter_06_most_probable_distribution/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u7edf\u8ba1\u7269\u7406\u7684\u57fa\u672c\u6982\u5ff5\u4e0e\u63cf\u8ff0</li> <li>\u7531\u4e09\u79cd\u72b6\u6001\u6570\u63a8\u5bfc\u4e09\u79cd\u6700\u6982\u7136\u5206\u5e03</li> </ul>"},{"location":"chapter_06_most_probable_distribution/01_statistical_basics.html","title":"\u7edf\u8ba1\u7269\u7406\u7684\u57fa\u672c\u6982\u5ff5\u4e0e\u63cf\u8ff0","text":""},{"location":"chapter_06_most_probable_distribution/01_statistical_basics.html#_1","title":"\u7edf\u8ba1\u7269\u7406\u7684\u57fa\u672c\u6982\u5ff5\u4e0e\u63cf\u8ff0","text":"<p>\u2605 \u63cf\u8ff0\u4e00\u4e2a\u7cfb\u7edf\u7684\u5b8f\u89c2\u6027\u8d28\uff0c\u65e0\u975e\u5c31\u662f\u77e5\u6653\u5176\u5fae\u89c2\u7c92\u5b50\u7684\u6240\u6709\u8fd0\u52a8\u7ec6\u8282\uff0c\u53d6\u65f6\u95f4\u5e73\u5747\u5373\u53ef\u6c42\u5f97\u5b8f\u89c2\u91cf\uff1a\\(\\bar{A}=\\frac{1}{T}\\int_{0}^{T}A(t)dt\\),\u8fd9\u4fbf\u662f\u5206\u5b50\u52a8\u529b\u5b66\u7684\u57fa\u672c\u601d\u60f3\uff0c\u4f46\u5b9e\u9645\u64cd\u4f5c\u4e2d\u53c8\u4f1a\u53d7\u9650\u4e8e\u7c92\u5b50\u6570\u76ee\u7b49\u3002\u4e8e\u662f\uff0c\u4ece\u72b6\u6001\\(A_s\\)\u51fa\u73b0\u7684\u6982\u7387\\(\\rho_s\\)\u7684\u89d2\u5ea6\u5165\u624b\uff0c\u53c8\u53ef\u63d0\u51fa\u8fd9\u6837\u7684\u6c42\u6cd5\uff1a\\(\\bar{A}=\\sum_sA_s\\rho_s\\),\u8fd9\u4fbf\u662f\u4e0a\u4e00\u7ae0\u4f7f\u7528\u7684\u65b9\u6cd5\u3002</p> <p>\u4e0e\u70ed\u529b\u5b66\u4e00\u6837\uff0c\u5728\u6ca1\u6709\u7279\u522b\u8bf4\u660e\u7684\u60c5\u51b5\u4e0b\uff0c\u7edf\u8ba1\u7269\u7406\u4e5f\u4ec5\u4ec5\u8ba8\u8bba\u5e73\u8861\u6001\u7684\u60c5\u51b5\u3002\u57fa\u4e8e\u5e73\u8861\u6001\u7684\u7edf\u8ba1\u7269\u7406\uff0c\u73bb\u5c14\u5179\u66fc\u7ed9\u51fa\u4e86\u552f\u4e00\u7684\u5047\u8bbe\uff1a\u7b49\u6982\u7387\u539f\u7406\u2014\u2014\u5bf9\u4e8e\u5904\u5728\u5e73\u8861\u72b6\u6001\u7684\u5b64\u7acb\u7cfb\u7edf\uff0c\u7cfb\u7edf\u5404\u4e2a\u53ef\u80fd\u7684\u5fae\u89c2\u72b6\u6001\u51fa\u73b0\u7684\u6982\u7387\u662f\u76f8\u7b49\u7684\u3002\u7531\u6b64\u4ece\u5fae\u89c2\u72b6\u6001\\(\\Omega\\)\u5165\u624b\uff0c\u53ef\u4ee5\u5c06\u4e4b\u524d\u7684\u5b8f\u89c2\u91cf\u5199\u4e3a\uff1a\\(\\bar{A}=\\sum_sA_s\\frac{1}{\\Omega}\\)</p> <p>\u5bf9\u4e8e\u4e00\u4e2a\u91cf\u5b50\u7cfb\u7edf\uff0c\u6bcf\u4e00\u79cd\u72b6\u6001\u53ef\u4ee5\u89c6\u4e3a\u79bb\u6563\u7684\u91cf\u5b50\u6001\uff0c\u5e76\u5e38\u5e38\u57fa\u4e8e\u80fd\u7ea7(\u80fd\u91cf\u5927\u5c0f)\u5bf9\u91cf\u5b50\u6001\u8fdb\u884c\u5206\u7c7b\u3002\u5bf9\u4e8e\u67d0\u4e2a\u80fd\u7ea7\\(\\varepsilon_l\\)\u800c\u8a00\uff0c\u53ef\u4ee5\u5217\u51fa\uff1a</p> \u80fd\u7ea7 \\(\\varepsilon_l\\) \\(\\varepsilon_l\\) ... \\(\\varepsilon_l\\) \\(\\varepsilon_l\\) \u91cf\u5b50\u6001 \\(\\lvert \\psi_1^l \\rangle\\) \\(\\lvert \\psi_2^l \\rangle\\) ... \\(\\lvert \\psi_{\\omega_l-1}^l \\rangle\\) \\(\\lvert \\psi_{\\omega_l}^l \\rangle\\) \u5360\u636e\u6570 \\(n_1^l\\) \\(n_2^l\\) ... \\(n_{\\omega_l-1}^l\\) \\(n_{\\omega_l}^l\\) <p>\u53ef\u4ee5\u770b\u51fa\u80fd\u7ea7\\(\\varepsilon_l\\)\u7684\u7b80\u5e76\u5ea6\u4e3a\\(\\omega_l\\),\u5e76\u4e14\u6b64\u80fd\u7ea7\u7684\u7c92\u5b50\u6570\\(a_l=\\sum_{s=1}^{\\omega_l} n_s^l\\).\u4e4b\u6240\u4ee5\u6309\u7167\u80fd\u7ea7\u8fdb\u884c\u5206\u7c7b\uff0c\u662f\u56e0\u4e3a\u4ece\u80fd\u91cf\u91cf\u5b50\u5316\u7684\u89d2\u5ea6\u597d\u5165\u624b\uff0c\u53ef\u4ee5\u66f4\u597d\u7684\u4e0e\u91cf\u5b50\u529b\u5b66\u7684\u4e00\u4e9b\u7ed3\u8bba\u76f8\u8054\u7cfb\uff0c\u5982\u76f8\u540c\u80fd\u7ea7\u4e0b\u5305\u542b\u7684\u91cf\u5b50\u6001\u7684\u4e2a\u6570\u79f0\u4e3a\u7b80\u5e76\u5ea6\\(\\omega_l\\)\u8fd9\u4e00\u6982\u5ff5\u3002\u7531\u6b64\uff0c\u53ef\u4ee5\u5f15\u5165\u80fd\u7ea7\u7c92\u5b50\u6570\u5206\u5e03\\(\\{a_l\\}\\)\u7684\u6982\u5ff5\uff0c\u5c06\u4e0d\u540c\u80fd\u7ea7\u4e0a\u7684\u5360\u636e\u6570\u89c6\u4f5c\u5206\u5e03\uff0c\u4e14\u901a\u5e38\u4e0d\u540c\u80fd\u7ea7\u7684\u76f8\u5bf9\u9ad8\u4f4e\u662f\u51e0\u4e4e\u4e0d\u53d8\u7684\uff0c\u53d8\u5316\u7684\u4ec5\u662f\u5360\u636e\u7684\u7c92\u5b50\u6570\u3002\u4ece\u800c\u5b8f\u89c2\u91cf\u8868\u8fbe\u5f0f\u53c8\u53ef\u5199\u4e3a\uff1a\\(\\bar{A}=\\sum_{\\{a_l\\}}A_{l}\\frac{\\Omega_{\\{a_l\\}}}{\\Omega}\\)</p> <p>\u25a0 \u8fd9\u91cc\u6765\u4e3e\u4e2a\u4f8b\u5b50\uff0c\u7b80\u5355\u8bf4\u660e\u4e0a\u9762\u7684\u601d\u60f3\u3002\u8bbe\u60f3\u4e00\u4e2a\u62e5\u6709N\u4e2a\u7c92\u5b50\u7684\u5bb9\u5668\u88ab\u5747\u5206\u4e3a\u4e24\u4e2a\u7a7a\u95f4\uff0c\u7c92\u5b50\u5728\u4e24\u4e2a\u4e0d\u540c\u7684\u7a7a\u95f4\u53ef\u89c6\u4e3a\u4e24\u79cd\u4e0d\u540c\u7684\u72b6\u6001\u3002\u6839\u636e\u7b49\u6982\u7387\u539f\u7406\uff0c\u6bcf\u4e2a\u7c92\u5b50\u5728\u5176\u4e2d\u4e00\u4e2a\u7a7a\u95f4\u51fa\u73b0\u7684\u6982\u7387\u4e3a1/2\u3002\u540c\u7406N\u4e2a\u7c92\u5b50\u53ef\u4ee5\u4e3a\u7cfb\u7edf\u63d0\u4f9b\u7684\u72b6\u6001\u6570\u4e3a\\(2^N\\)\uff0c\u4ece\u800c\u7cfb\u7edf\u5176\u4e2d\u4e00\u79cd\u72b6\u6001\u51fa\u73b0\u7684\u6982\u7387\u4e3a\\(1/2^N\\).\u5982\u679c\u8fd9\u6837\u5206\u6790\uff0c\u5c31\u8981\u8003\u8651\\(2^N\\)\u9879\uff0c\u7136\u800c\uff0c\u91c7\u7528\u5360\u636e\u6570\u5206\u5e03\u7684\u89c2\u70b9\uff0c\u5373\u8003\u8651\u4e24\u4e2a\u7a7a\u95f4\u7c92\u5b50\u5360\u636e\u7684\u6570\u91cf\uff0c\u95ee\u9898\u5c06\u5927\u5927\u7b80\u5316\u3002\u901a\u8fc7\u6392\u5217\u7ec4\u5408\u4e0d\u96be\u5f97\u5230\uff0c\u82e5\u7ed9\u5b9a\u5206\u5e03\u4e3a\u4e00\u4fa7\u7a7a\u95f4\u5185\u6709\\(i\\)\u4e2a\u7c92\u5b50\uff0c\u5219\u6ee1\u8db3\u6b64\u5206\u5e03\u7684\u72b6\u6001\u6570\u6709\\(C^i_N\\)\u4e2a\uff0c\u4ece\u800c\u8fd9\u79cd\u5206\u5e03\u51fa\u73b0\u7684\u6982\u7387\u4e3a\uff1a\\(P_i=C^{i}_{N}/2^N\\),\u4ec5\u8003\u8651N+1\u9879.\u8fd9\u4fbf\u662f\u7edf\u8ba1\u7269\u7406\u7684\u57fa\u672c\u601d\u60f3\u3002</p> <p>\u2605 \u7efc\u4e0a\uff0c\u53ef\u4ee5\u5f15\u51fa\u7edf\u8ba1\u7269\u7406\u7684\u4e09\u4e2a\u57fa\u672c\u95ee\u9898 1.\u5982\u4f55\u63cf\u8ff0\u7cfb\u7edf\u7684\u5fae\u89c2\u6001\uff1f 2.\u5404\u5fae\u89c2\u6001\u7684\u7edf\u8ba1\u6743\u91cd\u662f\u591a\u5c11\uff1f 3.\u5982\u4f55\u8ba1\u7b97\u5404\u4e2a\u70ed\u529b\u5b66\u91cf\uff1f \u5176\u4e2d\u524d\u4e24\u4e2a\u95ee\u9898\u662f\u672c\u7ae0\u5173\u6ce8\u7684\u6838\u5fc3\uff0c\u6700\u540e\u4e00\u4e2a\u95ee\u9898\u7531\u540e\u7eed\u7ae0\u8282\u9010\u6e10\u5c55\u5f00\u3002</p> <p>\u5728\u4e4b\u540e\u7cfb\u7efc\u7406\u8bba\u4e2d\uff0c\u76f8\u7a7a\u95f4\\(\\Gamma\\)\u7684\u4e00\u4e2a\u70b9\u5373\u4ee3\u8868\u6574\u4e2a\u7cfb\u7edf\u7684\u72b6\u6001\u3002\u800c\u76ee\u524d\u6240\u8ba8\u8bba\u7684\u8fd1\u72ec\u7acb\u5b50\u7cfb\uff0c\u5219\u662f\u5ffd\u7565\u76f8\u7a7a\u95f4\\(\\Gamma\\)\u5b50\u7cfb\u7edf\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\uff0c\u5206\u89e3\u4e3a\\(\\Gamma=\\mu_1\\otimes...\\otimes\\mu_n\\)\u7684\u5f62\u5f0f\u6240\u51fa\u73b0\u7684\\(\\mu\\)\u7a7a\u95f4(\u5b50\u76f8\u7a7a\u95f4)\u3002\u6ce8\u610f\uff0c\u867d\u7136\u5ffd\u7565\u76f8\u4e92\u4f5c\u7528\uff0c\u4f46\u5e76\u4e0d\u4ee3\u8868\u4e0d\u5b58\u5728\uff0c\u56e0\u4e3a\u8fd8\u8981\u9760\u76f8\u4e92\u4f5c\u7528\u6765\u4f7f\u5f97\u7cfb\u7edf\u8fbe\u5230\u5e73\u8861\u6001\u3002</p> <p>\u76ee\u524d\u800c\u8a00\uff0c\u53ef\u4ee5\u5c06\u5b50\u7cfb\u7edf\u5c31\u7406\u89e3\u4e3a\u7c92\u5b50\uff0c\u56e0\u800c\\(\\mu\\)\u7a7a\u95f4\u5373\u4e3a\u5355\u7c92\u5b50\u7684\u76f8\u7a7a\u95f4\uff0c\u4f8b\u5982\u82e5\u7cfb\u7edf\u7531N\u4e2a\u81ea\u7531\u5ea6\u4e3a\\(r\\)\u7684\u5168\u540c\u7c92\u5b50\u7ec4\u6210\uff0c\u90a3\u4e48\\(\\mu\\)\u7a7a\u95f4\u7684\u7ef4\u6570\u4e3a\\(2r\\).\u5c3d\u7ba1\u770b\u4f3c\u4e0d\u4e25\u8c28\uff0c\u4f46\u5728\u9762\u5bf9\u4f8b\u5982\uff0c\u7406\u60f3\u6c14\u4f53\u3001\u9ed1\u4f53\u8f90\u5c04\u3001\u5fb7\u62dc\u56fa\u4f53\u6a21\u578b\u7b49\uff0c\u6211\u4eec\u5c31\u53ef\u4ee5\u5728\u5355\u7c92\u5b50\u7684\u76f8\u7a7a\u95f4\u91cc\u5904\u7406\u95ee\u9898\uff0c\u4ece\u800c\u4f7f\u5904\u7406\u95ee\u9898\u7684\u65b9\u6cd5\u5f97\u5230\u7b80\u5316\u3002</p> <p>\u6b64\u5916\uff0c\u9700\u8981\u6ce8\u610f\uff0c\u5728\u7c92\u5b50\u53ef\u5206\u8fa8\u7684\u7cfb\u7edf\uff0c\u4f8b\u5982\u7ecf\u5178\u7cfb\u7edf\u6216\u5b9a\u57df\u7684\u91cf\u5b50\u7cfb\u7edf\u4e2d\uff0c\u786e\u5b9a\u7cfb\u7edf\u5fae\u89c2\u72b6\u6001\u5373\u786e\u5b9a\u5404\u4e2a\u7c92\u5b50\u7684\u5fae\u89c2\u6001\u3002\u5728\u7c92\u5b50\u4e0d\u53ef\u5206\u8fa8\u7684\u7cfb\u7edf\u4e2d\uff0c\u4f8b\u5982\u73bb\u8272\u7cfb\u7edf\u6216\u8d39\u7c73\u7cfb\u7edf\u4e2d\uff0c\u786e\u5b9a\u7cfb\u7edf\u5fae\u89c2\u6001\u5373\u786e\u5b9a\u91cf\u5b50\u6001\u4e0a\u7684\u5360\u636e\u6570\u3002\u4e0a\u8ff0\u56db\u79cd\u7cfb\u7edf\u5404\u4e0d\u76f8\u540c\uff0c\u5c24\u5176\u533a\u5206\u7ecf\u5178\u7cfb\u7edf\u548c\u5b9a\u57df\u91cf\u5b50\u7cfb\u7edf\u3002\u4e0b\u8282\u4f1a\u8be6\u7ec6\u9610\u8ff0\u3002</p> <p>\u2605 \u81ea\u7531\u5ea6\\(r\\)\u7684\\(2r\\)\u7ef4\\(\\mu\\)\u7a7a\u95f4\u4e2d\uff0c\u4f53\u79ef\u5143\\(d\\omega\\)\u53ef\u8868\u793a\u4e3a\\(d\\omega=\\prod_{i=1}^{r}(dq_idp_i)\\).\u5bf9\u4e8e\u81ea\u7531\u5ea61\u76842\u7ef4\\(\\mu\\)\u7a7a\u95f4\uff0c\u57fa\u4e8e\\(\\oint pdq=nh\\),\u66f2\u7ebf\u79ef\u5206\u5185\u90e8\u53ef\u5212\u5206\u51fa\\(n\\)\u4e2a\u4e0d\u540c\u7684\u683c\u5b50\u4ee3\u8868\\(n\\)\u4e2a\u4e0d\u540c\u7684\u91cf\u5b50\u6001\uff0c\u79f0\u4e4b\u4e3a\u201c\u76f8\u683c\u201d\u3002\u5c06\u4e4b\u63a8\u5e7f\u4e3a\u9ad8\u7ef4\u60c5\u51b5\u3002\u51c6\u8fde\u7eed\u4e0b\uff0c\u4e0d\u96be\u5199\u51fa\u4f53\u79ef\u5143\\(d\\omega\\)\u4e2d\u91cf\u5b50\u6001\u7684\u4e2a\u6570\\(dn\\)(\u53ef\u4ee5\u7406\u89e3\u4e3a\u76f8\u70b9\u7684\u7b80\u5e76\u5ea6)\uff1a</p> \\[ \\boxed{dn=\\frac{d\\omega}{h^r}=\\frac{\\prod_{i=1}^{r}(dq_idp_i)}{h^r}} \\] <p>\u901a\u5e38\u4e5f\u53ef\u5c06\u4e0a\u5f0f\u79ef\u5206\uff0c\u8868\u793a\u5728\\(\\omega\\)\u533a\u57df\u5185\u7684\u91cf\u5b50\u6001\u4e2a\u6570\u4e3a\\(\\frac{\\omega}{h^r}\\).</p> <p>\u6b64\u5916\uff0c\u8fd8\u53ef\u4ee5\u5b9a\u4e49\u91cf\u5b50\u6001\u5bc6\u5ea6\uff0c\u7b80\u79f0\u4e3a\u6001\u5bc6\u5ea6\u3002\u5373\u5bf9\u4e8e\u7269\u7406\u91cf\\(Q\\)\uff0c\u5219\uff1a</p> \\[ \\boxed{D(Q)=\\frac{dn}{dQ}}=\\frac{\\prod_{i=1}^{r}(dq_idp_i)}{h^rdQ}\\Rightarrow D(Q)dQ=\\frac{\\prod_{i=1}^{r}(dq_idp_i)}{h^r} \\] <p>\\(D(Q)\\)\u8868\u793a\u6001\u5bc6\u5ea6\uff0c\\(D(Q)dQ\\)\u8868\u793a\\(Q\\backsim Q+dQ\\)\u7684\u8303\u56f4\u5185\uff0c\u91cf\u5b50\u6001\u7684\u4e2a\u6570\u3002\u5e38\u7528\u7684\u6001\u5bc6\u5ea6\uff1a\u80fd\u91cf\u6001\u5bc6\u5ea6\\(D(\\varepsilon)\\)\u548c\u6ce2\u77e2\u6001\u5bc6\u5ea6\\(D(k)\\).</p> <p>\u25a0 (1)\u5bf9\u4e8e\u81ea\u7531\u7c92\u5b50\uff0c\u7531\u4e8e\u5176\u8272\u6563\u5173\u7cfb\u4e3a\\(\\varepsilon=\\frac{p^2}{2m}\\),\u5373\u80fd\u91cf\u4ec5\u548c\u52a8\u91cf\u5e73\u65b9\u6709\u5173\uff0c\u4e0e\u4f4d\u7f6e\u65e0\u5173\u3002\u56e0\u800c\u5728\\(\\varepsilon\\backsim\\varepsilon+d\\varepsilon\\)\u8303\u56f4\u5185\uff0c\u52a8\u91cf\u8981\u8003\u8651\u52a8\u91cf\u7684\u5927\u5c0f\uff0c\u5373\\(p^2=\\left(\\sqrt{p_x^2+p_y^2+p_z^2}\\right)^2\\),\u6545\u7c7b\u4f3c\u4e8e\u4e4b\u524d\u7684Maxwell\u901f\u7387\u5206\u5e03\uff1a\u5bf9\u4e8e\u4e09\u7ef4\u53d6\u7403\u58f3\\(dp_xdp_ydp_z=4\\pi p^2dp\\)\uff0c\u5bf9\u4e8e\u4e8c\u7ef4\u53d6\u5706\u5468\\(dp_xdp_y=2\\pi pdp\\)\uff0c\u5bf9\u4e8e\u4e00\u7ef4\u53d6\u5bf9\u79f0\u7684\u4e24\u4e2a\u70b9\\(dp_x=2dp\\)\u3002\u7531\u4e8e\u80fd\u91cf\u4e0e\u4f4d\u7f6e\u65e0\u5173\uff0c\u4ece\u800c\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u8fdb\u884c\u4f53\u79ef\u79ef\u5206\u5373\u53ef\u3002\u6700\u540e\uff0c\u5c06\\(dp\\)\u6539\u5199\u4e3a\\(d\\varepsilon\\)\uff0c\u4e0d\u96be\u5bfc\u51fa\u4e09\u7ef4\u81f3\u4e00\u7ef4\u7684\u6001\u5bc6\u5ea6\u5173\u7cfb\uff1a</p> \\[ D_{3d}(\\varepsilon)=\\frac{2\\pi L^3}{h^3}(2m)^{\\frac{3}{2}}\\varepsilon^{\\frac{1}{2}}\\qquad D_{2d}(\\varepsilon)=\\frac{2\\pi L^2}{h^2}m\\qquad D_{1d}(\\varepsilon)=\\frac{2L}{h}\\left(\\frac{m}{2\\varepsilon}\\right)^{\\frac{1}{2}} \\] <p>(2)\u5bf9\u4e8e\u4e00\u7ef4\u8c10\u632f\u5b50\uff0c\u8272\u6563\u5173\u7cfb\u4e3a\\(\\varepsilon=\\frac{p^2}{2m}+\\frac{1}{2}m\\omega^2x^2\\)\uff0c\u7531\u4e8e\u80fd\u91cf\u4e0d\u4ec5\u4e0e\u52a8\u91cf\u6709\u5173\uff0c\u8fd8\u4e0e\u4f4d\u7f6e\u6709\u5173\uff0c\u4ece\u800c\u7b80\u5355\u7684\u5904\u7406\u529e\u6cd5\u5c31\u662f\u5229\u7528\u79ef\u5206\u540e\u7684\u5f0f\u5b50\\( n=\\frac{\\omega_\\mu}{h}\\)\u8fdb\u884c\u8003\u8651\u3002\u4e0d\u96be\u770b\u51fa\uff0c\u8272\u6563\u5173\u7cfb\u5b9e\u9645\u4e0a\u5c31\u662f\\(\\mu\\)\u7a7a\u95f4\u4e2d\u7684\u692d\u5706\uff0c\u4ece\u800c\u80fd\u91cf\\(\\varepsilon\\)\u4ee5\u5185\u7684\u4f53\u79ef\u4e3a\\(\\pi a b=\\frac{\\varepsilon}{v}\\),\u5176\u4e2d\\(v=\\frac{\\omega}{2\\pi}\\)\u4e3a\u9891\u7387\u3002\u7531\u6b64\u53ef\u5f97\uff1a</p> \\[ dn=\\frac{d\\varepsilon}{hv}\\Rightarrow D(\\varepsilon)=\\frac{dn}{d\\varepsilon}=\\frac{1}{hv} \\] <p>\u2605 \u6ce8\u610f\uff0c\u82e5\u8003\u8651\u7535\u5b50\u81ea\u65cb\u6001\uff0c\u7b80\u5e76\u5ea6\\(\\omega_l\\rightarrow 2\\omega_l\\),\u4ece\u800c\u6001\u5bc6\u5ea6\u8fd8\u8981\u4e58\u4ee52.</p>"},{"location":"chapter_06_most_probable_distribution/02_most_probable_distributions.html","title":"\u7531\u4e09\u79cd\u72b6\u6001\u6570\u63a8\u5bfc\u4e09\u79cd\u6700\u6982\u7136\u5206\u5e03","text":""},{"location":"chapter_06_most_probable_distribution/02_most_probable_distributions.html#_1","title":"\u7531\u4e09\u79cd\u72b6\u6001\u6570\u63a8\u5bfc\u4e09\u79cd\u6700\u6982\u7136\u5206\u5e03","text":"<p>\u2605 \u76ee\u524d\uff0c\u4ec5\u8ba8\u8bba\u5168\u540c\u7c92\u5b50\u8fd1\u72ec\u7acb\u5b50\u7cfb\u4e0b\uff0c\u5373\u7cfb\u7edf\u7684\u54c8\u5bc6\u987f\u6ca1\u6709\u76f8\u4e92\u4f5c\u7528\u7684\u4ea4\u53c9\u9879\uff0c\u4e14\u80fd\u91cf\\(\\varepsilon_i\\)\u4ec5\u4e3a\u5750\u6807\\(q_i\\)\u52a8\u91cf\\(p_i\\)\u7684\u51fd\u6570\uff1a</p> \\[ E=\\sum_{i=1}^N\\varepsilon_i \\] <p>\u5bf9\u4e8e\u66f4\u52a0\u666e\u904d\u7684\u8ba8\u8bba\uff0c\u5c06\u5728\u7cfb\u7efc\u7406\u8bba\u4e2d\u8fdb\u884c\u3002</p> <p>\u5bf9\u4e8e\u4e00\u4e2a\u5168\u540c\u7c92\u5b50\u7684\u91cf\u5b50\u7cfb\u7edf\uff0c\u9700\u8981\u533a\u5206\u4e24\u4e2a\u91cd\u8981\u7684\u6982\u5ff5:\u5b9a\u57df\u7cfb\u7edf\u4e0e\u975e\u5b9a\u57df\u7cfb\u7edf\u3002\u5b9a\u57df\u7cfb\u7edf\u5373\u7c92\u5b50\u7684\u8fd0\u52a8\u53d7\u5230\u9650\u5236\uff0c\u53ef\u4ee5\u901a\u8fc7\u4f4d\u7f6e\u52a0\u4ee5\u533a\u5206\uff0c\u4e0d\u53d1\u751f\u6ce2\u51fd\u6570\u7684\u91cd\u53e0\uff1b\u975e\u5b9a\u57df\u7cfb\u7edf\u5373\u7c92\u5b50\u7684\u6ce2\u51fd\u6570\u4f1a\u53d1\u751f\u91cd\u53e0\uff0c\u4ece\u800c\u5c55\u73b0\u51fa\u5168\u540c\u7c92\u5b50\u4e0d\u53ef\u5206\u8fa8\u7684\u7279\u6027\u3002\u5b9a\u57df\u7cfb\u7edf\u5178\u578b\u7684\u4f8b\u5b50\u5c31\u662f\u56fa\u4f53\u4e2d\u539f\u5b50\u7684\u632f\u52a8\uff1b\u975e\u5b9a\u57df\u7cfb\u7edf\u7684\u4f8b\u5b50\u4e3a\u81ea\u7531\u7535\u5b50\u6c14\u3001\u81ea\u7531\u5149\u5b50\u4ee5\u53ca\u4f5c\u4e3a\u975e\u7b80\u5e76\u8fd1\u4f3c\u7684\u7406\u60f3\u6c14\u4f53\u3002</p> <p>\u8fd9\u4e24\u79cd\u7cfb\u7edf\u6709\u672c\u8d28\u7684\u533a\u522b\uff0c\u867d\u7136\u6ee1\u8db3\u4e00\u4e9b\u6761\u4ef6\u5176\u6700\u6982\u7136\u5206\u5e03\u53ef\u4ee5\u76f8\u540c\uff0c\u4f46\u7cfb\u7edf\u672c\u8eab\u4e0d\u80fd\u6539\u53d8\u3002\u4f8b\u5982\u7406\u60f3\u6c14\u4f53\u65e0\u8bba\u5982\u4f55\u7ecf\u5178\u8fd1\u4f3c\uff0c\u90fd\u65e0\u6cd5\u79f0\u4e3a\u5b9a\u57df\u7cfb\u7edf\uff0c\u5176\u4e0d\u53ef\u5206\u8fa8\u6027\u4e0d\u53ef\u62b9\u9664\uff0c\u5426\u5219\u4f1a\u9020\u6210Gibbs\u4f6f\u8c2c\uff0c\u5728\u4e0b\u4e00\u7ae0\u4f1a\u8be6\u7ec6\u8ba8\u8bba\u3002</p> <p>\u5bf9\u4e8e\u7ecf\u5178\u7cfb\u7edf\uff0c\u7c92\u5b50\u90fd\u662f\u53ef\u5206\u8fa8\u7684\uff0c\u56e0\u800c\u901a\u5e38\u6ca1\u6709\u5b9a\u57df\u4e0e\u5426\u7684\u533a\u522b\uff0c\u5b8c\u5168\u670d\u4ece\u6211\u4eec\u65e5\u5e38\u751f\u6d3b\u7ecf\u9a8c\u4e2d\u7684\u7edf\u8ba1\u89c4\u5f8b\u3002\u4f46\u8981\u6ce8\u610f\uff0c\u7ecf\u5178\u7cfb\u7edf\u7684\u80fd\u7ea7\u662f\u8fde\u7eed\u7684\u3002</p> <p>\u6700\u540e\uff0c\u5bf9\u4e8e\u91cf\u5b50\u7cfb\u7edf\uff0c\u8fd8\u8981\u6ce8\u610f\u8d39\u7c73\u5b50\u548c\u73bb\u8272\u5b50\u7684\u533a\u5206\u3002\u5bf9\u4e8e\u81ea\u65cb\u4e3a\u534a\u6574\u6570\u7684\u8d39\u7c73\u5b50\uff0c\u4e0d\u4ec5\u9700\u8981\u8003\u8651\u4e0d\u53ef\u5206\u8fa8\u6027\uff0c\u8fd8\u8981\u8003\u8651Pauli\u4e0d\u76f8\u5bb9\u539f\u7406\u5bf9\u91cf\u5b50\u6001\u5360\u636e\u7684\u5f71\u54cd\uff0c\u4e14\u5728\u81ea\u7136\u754c\u8d77\u7740\u201c\u79ef\u6728\u201d\u7684\u4f5c\u7528\uff1b\u5bf9\u4e8e\u81ea\u65cb\u4e3a\u6574\u6570\u7684\u73bb\u8272\u5b50\uff0c\u4ec5\u8003\u8651\u4e0d\u53ef\u5206\u8fa8\u6027\u5373\u53ef\uff0c\u4e14\u5728\u81ea\u7136\u754c\u8d77\u7740\u201c\u7c98\u5408\u79ef\u6728\u201d\u7684\u4f5c\u7528\u3002\u6b64\u5916\uff0c\u7531\u5947\u6570\u4e2a\u8d39\u7c73\u5b50\u7ec4\u6210\u7684\u4ecd\u4e3a\u8d39\u7c73\u5b50\uff0c\u5982\\({}^3 He\\);\u7531\u5076\u6570\u4e2a\u8d39\u7c73\u5b50\u7ec4\u6210\u7684\u5c06\u53d8\u4e3a\u73bb\u8272\u5b50\uff0c\u5982\\({}^ 4He\\).</p> <p>\u2605 \u6839\u636e\u4ee5\u4e0a\u7684\u6982\u5ff5\uff0c\u5c06\u5b9a\u57df\u7cfb\u7edf\u79f0\u4e3a\u73bb\u5c14\u5179\u66fc\u7cfb\u7edf\uff0c\u670d\u4ece\u9ea6\u514b\u65af\u97e6-\u73bb\u5c14\u5179\u66fc\u5206\u5e03\uff1b\u5c06\u975e\u5b9a\u57df\u7cfb\u7edf\u5206\u4e3a\u7531\u73bb\u8272\u5b50\u7ec4\u6210\u7684\u73bb\u8272\u7cfb\u7edf\u548c\u7531\u8d39\u7c73\u5b50\u7ec4\u6210\u7684\u8d39\u7c73\u7cfb\u7edf\uff0c\u5206\u522b\u670d\u4ece\u73bb\u8272-\u7231\u56e0\u65af\u5766\u5206\u5e03\u548c\u8d39\u7c73-\u72c4\u62c9\u514b\u5206\u5e03\uff0c\u4e0b\u9762\u5c06\u57fa\u4e8e\u5177\u6709\u786e\u5b9a\u7c92\u5b50\u6570\\(N\\)\u80fd\u91cf\\(E\\)\u4f53\u79ef\\(V\\)\u7684\u5b64\u7acb\u7cfb\u7edf\u5bfc\u51fa\u4e09\u79cd\u6700\u6982\u7136\u5206\u5e03\u3002</p> <p>\u9996\u5148\u6839\u636e\u7b49\u6982\u7387\u539f\u7406\uff0c\u4ece\u7cfb\u7edf\u7684\u5fae\u89c2\u72b6\u6001\u6570\u51fa\u53d1\uff0c\u5199\u51fa\u7c92\u5b50\u6570\\(N\\),\u80fd\u7ea7\\(\\varepsilon_l\\)\uff0c\u7b80\u5e76\u5ea6\\(\\omega_l\\)\u548c\u7ed9\u5b9a\u5206\u5e03\\(\\{a_l\\}\\)\u4e0b\uff0c\u7cfb\u7edf\u5bf9\u5e94\u7684\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega\\)\uff1a</p> <p>(1)\u5bf9\u4e8e\u5b9a\u57df\u7684\u73bb\u5c14\u5179\u66fc\u7cfb\u7edf\uff0c\u7531\u4e8e\u7c92\u5b50\u53ef\u5206\u8fa8\uff0c\u4f9d\u6b21\u586b\u6ee1\u5404\u4e2a\u80fd\u7ea7\u7684\u7ec4\u5408\u4e3a\\(C_{N}^{a_1}C_{N-a_1}^{a_2}...C_{a_l}^{a_l}\\).\u5373\u5148\u4ece\\(N\\)\u4e2a\u7c92\u5b50\u4e2d\u9009\u53d6\\(a_1\\)\u4e2a\uff0c\u586b\u5230\\(\\varepsilon_1\\)\u80fd\u7ea7\uff0c\u518d\u4ece\u5269\u4e0b\u7684\\(N-a_1\\)\u4e2a\u7c92\u5b50\u4e2d\u9009\u53d6\\(a_2\\)\u4e2a\uff0c\u7ee7\u7eed\u586b\u80fd\u7ea7\uff0c\u76f4\u5230\u6309\u7167\u5206\u5e03\u5168\u90e8\u586b\u5b8c\u3002\u5176\u6b21\uff0c\u5bf9\u4e8e\u67d0\u4e2a\\(\\varepsilon_l\\)\u80fd\u7ea7\u5185\u90e8\uff0c\u5176\\(a_l\\)\u4e2a\u7c92\u5b50\u5728\u7b80\u5e76\u7684\\(\\omega_l\\)\u4e2a\u91cf\u5b50\u6001\u4e2d\u4efb\u610f\u9009\u62e9\uff0c\u6545\u9009\u62e9\u7ed3\u679c\u4e3a\\(\\omega_l^{a_l}\\)\u79cd,\u4ece\u800c\u5bf9\u4e8e\u6240\u6709\u80fd\u7ea7\uff0c\u5171\u6709\\(\\prod_{l}\\omega_l^{a_l}\\)\u79cd\u7ed3\u679c\u3002\u7efc\u4e0a\uff1a</p> \\[ \\Omega_{M.B.}=C_{N}^{a_1}C_{N-a_1}^{a_2}...C_{a_l}^{a_l}\\cdot\\prod_{l}\\omega_l^{a_l}=N!\\prod_{l}\\frac{\\omega_l^{a_l}}{a_l!}\\Rightarrow\\boxed{\\Omega_{M.B.}=N!\\prod_{l}\\frac{\\omega_l^{a_l}}{a_l!}} \\] <p>(2)\u5bf9\u4e8e\u975e\u5b9a\u57df\u7684\u73bb\u8272\u7cfb\u7edf\uff0c\u7531\u4e8e\u7c92\u5b50\u4e0d\u53ef\u5206\u8fa8\uff0c\u4ece\u800c\u65e0\u6cd5\u8fdb\u884c\u4e00\u4e2a\u4e2a\u586b\u6ee1\u80fd\u7ea7\u7684\u6b65\u9aa4\uff0c\u56e0\u4e3a\u65e0\u8bba\u4f55\u79cd\u65b9\u5f0f\u586b\u90fd\u88ab\u89c6\u4e3a\u7cfb\u7edf\u7684\u540c\u4e00\u4e2a\u72b6\u6001\uff0c\u4ece\u800c\u8be5\u6b65\u9aa4\u7684\u5fae\u89c2\u72b6\u6001\u6570\u4e3a1.\u5176\u6b21\uff0c\u5bf9\u4e8e\u67d0\u4e2a\u80fd\u7ea7\\(\\varepsilon_l\\)\u800c\u8a00\uff0c\u540c\u6837\u7531\u4e8e\u4e0d\u53ef\u5206\u8fa8\uff0c\u8981\u7528\u5230\u201c\u9694\u677f\u6cd5\u201d\u6765\u5206\u6790\uff1a\u5bf9\u4e8e\\(a_l\\)\u4e2a\u7c92\u5b50\u8bbe\u7f6e\\(\\omega_l-1\\)\u4e2a\u9694\u677f\uff0c\u5206\u6210\\(\\omega_l\\)\u4efd\uff0c\u5373\u5171\u6709\\(a_l+\\omega_l-1\\)\u4e2a\u5143\u7d20\u3002\u5728\u8fd9\u4e9b\u5143\u7d20\u4e2d\u9009\u53d6\u4f5c\u4e3a\u7c92\u5b50\u7684\u9009\u62e9\u79cd\u7c7b\u4e3a\\(C_{\\omega_l+a_l-1}^{a_l}\\)\u79cd\uff0c\u4ece\u800c\u5bf9\u4e8e\u6240\u6709\u80fd\u7ea7\u6709\\(\\prod_{l}C_{\\omega_l+a_l-1}^{a_l}\\)\u79cd\u3002\u7efc\u4e0a\uff1a</p> \\[ \\Omega_{B.E.}=\\prod_{l}C_{\\omega_l+a_l-1}^{a_l}=\\prod_{l}\\frac{(\\omega_l+a_l-1)!}{a_l!(\\omega_l-1)!}\\Rightarrow\\boxed{\\Omega_{B.E.}=\\prod_{l}\\frac{(\\omega_l+a_l-1)!}{a_l!(\\omega_l-1)!}} \\] <p>(3)\u5bf9\u4e8e\u975e\u5b9a\u57df\u7684\u8d39\u7c73\u7cfb\u7edf\uff0c\u9664\u4e86\u7c92\u5b50\u4e0d\u53ef\u5206\u8fa8\uff0c\u8fd8\u8981\u8003\u8651Pauli\u4e0d\u76f8\u5bb9\u539f\u7406\uff0c\u5373\u76f8\u540c\u91cf\u5b50\u6001\u6700\u591a\u4ec5\u80fd\u88ab\u4e00\u4e2a\u5168\u540c\u7c92\u5b50\u5360\u636e\u3002\u56e0\u800c\u586b\u5145\u80fd\u7ea7\u4e0e\u73bb\u8272\u7cfb\u7edf\u7c7b\u4f3c\uff0c\u4ea7\u751f\u7684\u5fae\u89c2\u72b6\u6001\u6570\u4e3a1.\u5176\u6b21\uff0c\u4e0d\u76f8\u5bb9\u539f\u7406\u81ea\u52a8\u4fdd\u8bc1\u4e86\\(\\omega_l\\geqslant a_l\\),\u5426\u5219\u5fc5\u7136\u4f1a\u51fa\u73b0\u91cf\u5b50\u6001\u4e0a\u6709\u4e24\u4e2a\u5168\u540c\u7c92\u5b50\u3002\u5bf9\u4e8e\u7c92\u5b50\u6570\u4e3a\\(a_l\\),\u7b80\u5e76\u5ea6\u4e3a\\(\\omega_l\\)\u7684\u80fd\u7ea7\\(\\varepsilon_l\\)\u800c\u8a00\uff0c\u76f8\u5f53\u4e8e\u5728\\(\\omega_l\\)\u4e2a\u91cf\u5b50\u6001\u4e2d\u9009\u62e9\\(a_l\\)\u4e2a\u88ab\u5360\u636e\u7684\u6001\uff0c\u6545\u4e3a\\(C_{\\omega_l}^{a_l}\\)\uff0c\u4ece\u800c\u5bf9\u4e8e\u6240\u6709\u80fd\u7ea7\u5b58\u5728\\(\\prod_{l}C_{\\omega_l}^{a_l}\\)\u79cd\u5fae\u89c2\u72b6\u6001.\u7efc\u4e0a\uff1a</p> \\[ \\Omega_{F.D.}=\\prod_{l}C_{\\omega_l}^{a_l}=\\prod_{l}\\frac{\\omega_l!}{a_l!(\\omega_l-a_l)!}\\Rightarrow\\boxed{\\Omega_{F.D.}=\\prod_{l}\\frac{\\omega_l!}{a_l!(\\omega_l-a_l)!}} \\] <p>\u4ee5\u4e0a\u7ed9\u51fa\u4e86\u5728\u5206\u5e03\\(\\{a_l\\}\\)\u4e0b\uff0c\u7cfb\u7edf\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega\\)\u7684\u591a\u5c11\uff0c\u5373\u5efa\u7acb\u4e86\u7c7b\u4f3c\u4e8e\u201c\u6cdb\u51fd\u201d\\(\\Omega[\\{a_l\\}]\\),\u4e5f\u5c31\u662f\u8bf4\u6bcf\u4e00\u79cd\u5206\u5e03\\(\\{a_l\\}\\)\u90fd\u6620\u5c04\u5230\u4e86\u4e00\u4e2a\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega\\)\u4e0a\uff0c\u7c7b\u4f3c\u4e8e\u79ef\u5206\u6cdb\u51fd\\(J[y(x)]\\).\u73b0\u5728\u7684\u76ee\u6807\u662f\u6c42\u51fa\u4e09\u79cd\u7cfb\u7edf\u7684\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega\\)\u53d6\u6781\u5927\u7684\u6700\u6982\u7136\u5206\u5e03\\(\\{a_l\\}\\)\uff0c\u8fd9\u4e5f\u5c31\u7c7b\u4f3c\u4e8e\u6c42\u51fa\u6ee1\u8db3\\(\\delta J[y(x)]=0\\)\u7684\u51fd\u6570\\(y(x)\\).\u4ece\u800c\u6211\u4eec\u53ef\u4ee5\u4ece\\(\\delta \\Omega[\\{a_l\\}]=0\\)\u51fa\u53d1\uff0c\u6c42\u51fa\u6700\u6982\u7136\u5206\u5e03\u3002\u5f53\u7136\uff0c\u6570\u5b66\u4e0a\u4e3a\u4e86\u6d88\u53bb\u5206\u5f0f\u5e26\u6765\u7684\u9ebb\u70e6\uff0c\u901a\u5e38\u91c7\u7528\\(\\delta ln(\\Omega[\\{a_l\\}])=0\\)\u7684\u5f62\u5f0f\u5904\u7406.</p> <p>\u4e0e\u5206\u6790\u529b\u5b66\u7684\u8303\u5f0f\u4e00\u6837\uff0c\u5728\u6c42\u51fa\u6700\u6982\u7136\u5206\u5e03\u4e4b\u524d\uff0c\u9700\u8981\u5148\u660e\u786e\u7ea6\u675f\u6761\u4ef6\uff1a</p> \\[ N=\\sum_{l}a_l\\qquad E=\\sum_la_l\\varepsilon_l\\quad\\Rightarrow\\quad\\delta N=\\sum_l\\delta a_l\\qquad \\delta E=\\sum_l\\varepsilon_l\\delta a_l \\] <p>\u5373\u6ee1\u8db3\u7c92\u5b50\u6570\u548c\u80fd\u91cf\u5b88\u6052\u3002\u6b64\u5916\uff0c\u5f15\u5165\u62c9\u683c\u6717\u65e5\u4e58\u5b50\\(\\alpha,\\beta\\)\u5f97\u5230\uff1a</p> \\[ \\delta ln(\\Omega)-\\alpha\\delta N-\\beta\\delta E=\\delta ln(\\Omega)-\\alpha\\sum_l\\delta a_l-\\beta\\sum_l\\varepsilon_l\\delta a_l=0 \\] <p>\u5229\u7528Stirling\u8fd1\u4f3c\\(ln(x!)\\approx x(ln(x)-1),x\\gg1\\)\u53ef\u5c06\u4e0a\u5f0f\u7b2c\u4e00\u9879\u8fd1\u4f3c\uff1a</p> <p>(1)\u5bf9\u4e8e\u73bb\u5c14\u5179\u66fc\u7cfb\u7edf,\u4ee3\u5165\\(\\Omega_{M.B.}\\)\u53ef\u5f97\uff1a</p> \\[ \\delta ln(\\Omega_{M.B.})-\\alpha\\sum_l\\delta a_l-\\beta\\sum_l\\varepsilon_l\\delta a_l=0 \\] <p>\u5316\u7b80\u5229\u7528\u5230\\(N=\\sum_la_l\\),\u5e76\u4e14\u6ce8\u610f\u9664\u4e86\\(a_l\\)\u4ee5\u5916\uff0c\u5176\u4ed6\u90fd\u662f\u5e38\u91cf\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ -\\sum_l\\left[ln\\left(\\frac{a_l}{\\omega_l}\\right)+\\alpha+\\beta\\varepsilon_l\\right]\\delta a_l=0\\Rightarrow \\boxed{a_l=\\frac{\\omega_l}{e^{\\alpha+\\beta\\varepsilon_l}}} \\] <p>\u4ece\u800c\u5f97\u5230\u4e86\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u3002</p> <p>(2)\u5bf9\u4e8e\u73bb\u8272\u7cfb\u7edf,\u4ee3\u5165\\(\\Omega_{B.E.}\\)\u53ef\u5f97\uff1a</p> \\[ \\delta ln(\\Omega_{B.E.})-\\alpha\\sum_l\\delta a_l-\\beta\\sum_l\\varepsilon_l\\delta a_l=0 \\] <p>\u518d\u5229\u7528\u8fd1\u4f3c\\(\\omega_l-1\\approx\\omega_l\\),\u5f97\u5230\uff1a</p> \\[ \\sum_{l}\\left[ln(\\omega_l+a_l)-ln(a_l)-\\alpha-\\beta\\varepsilon_l\\right]\\delta a_l=0\\Rightarrow\\boxed{a_l=\\frac{\\omega_l}{e^{\\alpha+\\beta\\varepsilon_l}-1}} \\] <p>\u4ece\u800c\u5f97\u5230\u4e86\u73bb\u8272\u5206\u5e03\u3002</p> <p>(3)\u5bf9\u4e8e\u8d39\u7c73\u7cfb\u7edf,\u4ee3\u5165\\(\\Omega_{F.D.}\\)\u53ef\u5f97\uff1a</p> \\[ \\delta ln(\\Omega_{F.D.})-\\alpha\\sum_l\\delta a_l-\\beta\\sum_l\\varepsilon_l\\delta a_l=0 \\] \\[ \\sum_{l}\\left[ln(\\omega_l-a_l)-ln(a_l)-\\alpha-\\beta\\varepsilon_l\\right]\\delta a_l=0\\Rightarrow\\boxed{a_l=\\frac{\\omega_l}{e^{\\alpha+\\beta\\varepsilon_l}+1}} \\] <p>\u4ece\u800c\u5f97\u5230\u4e86\u8d39\u7c73\u5206\u5e03\u3002</p> <p>(4)\u9664\u4e86\u8003\u8651\u4e09\u79cd\u91cf\u5b50\u5206\u5e03\uff0c\u6709\u65f6\u8fd8\u9700\u8981\u8ba8\u8bba\u7ecf\u5178\u7cfb\u7edf\u7684\u5206\u5e03\u3002\u7531\u4e8e\u7ecf\u5178\u7cfb\u7edf\u53ef\u5206\u8fa8\uff0c\u53ef\u7c97\u7565\u5730\u770b\u4f5c\u80fd\u7ea7\u8fde\u7eed\u7684\u5b9a\u57df\u7cfb\u7edf\uff0c\u56e0\u6b64\u76f4\u63a5\u5bf9\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u8fdb\u884c\u5fae\u8c03\u5373\u53ef\uff1a</p> \\[ \\omega_l\\rightarrow \\frac{d\\omega_\\mu}{h^r}\\Rightarrow\\Omega_{C.}=N!\\prod_{l}\\frac{(d\\omega_\\mu/h^r)^{a_l}}{a_l!}\\Rightarrow\\boxed{da_l=\\frac{d\\omega_\\mu}{e^{\\alpha+\\beta\\varepsilon_l}h^r}} \\] <p>\u6ce8\u610f\u8fd9\u91cc\\(\\omega_l\\)\u548c\\(d\\omega_\\mu\\)\u5206\u522b\u8868\u793a\u7684\u662f\u91cf\u5b50\u7cfb\u7edf\u7684\u7b80\u5e76\u5ea6\u548c\u5b50\u76f8\u7a7a\u95f4\u7684\u4f53\u79ef\u5143\uff0c\\(da_l\\)\u8868\u793a\u5728\\(d\\omega_\\mu\\)\u8303\u56f4\u5185\u7684\u7c92\u5b50\u6570\uff0c\u7531\u6b64\u53ef\u4ee5\u63a8\u5bfc\u9ea6\u514b\u65af\u97e6\u901f\u5ea6\u5206\u5e03\uff0c\u8be6\u89c1\u4e0b\u4e00\u7ae0\u3002\u76f8\u683c\u5927\u5c0f\u53d6\u4e3a\\(h^r\\)\uff0c\u8fd9\u662f\u7ecf\u5178\u6781\u9650\u4e2d\u4fdd\u7559\u91cf\u5b50\u6001\u8ba1\u6570\u5f52\u4e00\u5316\u7684\u5199\u6cd5\u3002</p> <p>\u6700\u6982\u7136\u5206\u5e03\u7684\u63a8\u5bfc\u4e2d\u9ed8\u8ba4\\(a_l\\gg1,\\omega_l\\gg1\\)\uff0c\u4f46\u8fd9\u663e\u7136\u4e0d\u5408\u7406\uff0c\u7136\u800c\u6700\u7ec8\u7684\u7ed3\u679c\u662f\u6b63\u786e\u7684\u3002\u66f4\u52a0\u4e25\u683c\u7684\u63a8\u5bfc\u89c1\u7cfb\u7efc\u7406\u8bba\u7684\u6700\u540e\u3002\u5bf9\u4e8e\u5f15\u5165\u7684\u4e24\u4e2a\u7cfb\u6570\u4e58\u5b50\\(\\alpha,\\beta\\)\u53ef\u4ee5\u7531\u7ea6\u675f\u6761\u4ef6\u6c42\u51fa\uff1a</p> \\[ N=\\sum_{l}a_l\\qquad E=\\sum_la_l\\varepsilon_l\\quad\\Rightarrow\\quad to\\quad get \\quad\\alpha\\quad and\\quad\\beta \\] <p>\u6b64\u5916\uff0c\u5bf9\u4e8e\u591a\u7ec4\u5206\u7684\u6700\u6982\u7136\u5206\u5e03\u7684\u63a8\u5bfc\u5982\u6cd5\u70ae\u5236\uff0c\u9700\u8981\u6ce8\u610f\u5199\u7ea6\u675f\u6761\u4ef6\u65f6\uff0c\u5404\u7c92\u5b50\u4f53\u7cfb\u4e4b\u95f4\u53ef\u4ee5\u4ea4\u6362\u80fd\u91cf\uff0c\u56e0\u800c\u80fd\u91cf\u9700\u8981\u5408\u5728\u4e00\u8d77\u5199\uff0c\u6545\\(\\beta\\)\u76f8\u540c\u3002</p> <p>\u2605 \u73b0\u5728\u8ba8\u8bba\u8fd9\u4e09\u79cd\u5206\u5e03\u4e4b\u95f4\u7684\u8054\u7cfb\uff0c\u5f53\u6ee1\u8db3\\(\\omega_l\\gg a_l\\)\u65f6\uff0c\u5373\u5355\u4e2a\u91cf\u5b50\u6001\u4e0a\u7684\u7c92\u5b50\u8d8b\u5411\u4e8e1\u65f6\uff0c\u53ef\u4ee5\u6709\u5982\u4e0b\u8fd1\u4f3c\uff1a</p> \\[ \\Omega_{B.E.}=\\prod_{l}\\frac{(\\omega_l+a_l-1)!}{a_l!(\\omega_l-1)!}=\\prod_{l}\\frac{(\\omega_l+a_l-1)...\\omega_l}{a_l!}\\approx\\prod_l\\frac{\\omega^{a_l}}{a_l!}=\\frac{\\Omega_{M.B.}}{N!} \\] \\[ \\Omega_{F.D.}=\\prod_{l}\\frac{\\omega_l!}{a_l!(\\omega_l-a_l)!}=\\prod_{l}\\frac{\\omega_l...(\\omega_l-a_l+1)}{a_l!}\\approx\\prod_l\\frac{\\omega_l^{a_l}}{a_l!}=\\frac{\\Omega_{M.B.}}{N!} \\] <p>\u7531\u4e8e\\(N!\\)\u4e3a\u5e38\u6570\uff0c\u4ece\u800c\u73bb\u8272\u5206\u5e03\u548c\u8d39\u7c73\u5206\u5e03\u9000\u5316\u4e3a\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u3002\u8fd9\u4e00\u70b9\u4e5f\u53ef\u76f4\u63a5\u4ece\u5206\u5e03\u7684\u8868\u8fbe\u5f0f\u4e2d\u770b\u51fa\uff0c\u5f53\u6ee1\u8db3\\(e^\\alpha\\gg1\\)\u65f6\uff1a</p> \\[ a_l=\\frac{\\omega_l}{e^{\\alpha+\\beta\\varepsilon_l}\\pm1}\\approx \\frac{\\omega_l}{e^{\\alpha+\\beta\\varepsilon_l}} \\] <p>\u4ece\u800c\\(a_l/\\omega_l\\ll1\\)\u548c\\(e^\\alpha\\gg1\\)\u662f\u7b49\u4ef7\u7684\uff0c\u5747\u79f0\u4e3a\u975e\u7b80\u5e76\u6761\u4ef6\u3002\u4f46\u8981\u6ce8\u610f\uff0c\u73bb\u5c14\u5179\u66fc\u7cfb\u7edf\u548c\u7531\u975e\u5b9a\u57df\u7cfb\u7edf\u9000\u5316\u800c\u6765\u7684\u670d\u4ece\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u7684\u7cfb\u7edf\u5728\u5fae\u89c2\u72b6\u6001\u6570\u4e0a\u7684\u5dee\u522b\uff0c\u7531\u6b64\u5bfc\u81f4\u6d89\u53ca\u5fae\u89c2\u72b6\u6001\u6570\u7684\u70ed\u529b\u5b66\u91cf\u7684\u4e0d\u540c\uff0c\u4f8b\u5982\u71b5\u3001\u81ea\u7531\u80fd\u7b49\u3002</p> <p>\u867d\u7136\u975e\u5b9a\u57df\u548c\u5b9a\u57df\u7cfb\u7edf\u53ef\u4ee5\u901a\u8fc7\u975e\u7b80\u5e76\u6761\u4ef6\u4f7f\u5f97\u6700\u7ec8\u5206\u5e03\u4e00\u81f4\uff0c\u4f46\u975e\u5b9a\u57df\u7cfb\u7edf\u7ec8\u7a76\u4e0d\u80fd\u8f6c\u53d8\u4e3a\u5b9a\u57df\u7cfb\u7edf\uff0c\u5373\u65e0\u6cd5\u6dfb\u52a0\u8fd1\u4f3c\u6761\u4ef6\u6d88\u9664\u4e0d\u53ef\u5206\u8fa8\u7684\u9650\u5236\u3002\u4f46\u5bf9\u4e8e\u91cf\u5b50\u5b9a\u57df\u7cfb\u7edf\u548c\u7ecf\u5178\u7cfb\u7edf\u4e4b\u95f4\uff0c\u53ef\u4ee5\u901a\u8fc7\u80fd\u7ea7\u51c6\u8fde\u7eed\u6761\u4ef6\u8fbe\u5230\u4e00\u81f4\uff1a</p> \\[ \\frac{\\Delta\\varepsilon}{kT}\\ll1 \\] <p>\u7b80\u5355\u6765\u8bf4\uff0c\u5c31\u662f\u5206\u7acb\u7684\u80fd\u7ea7\u8d8b\u5411\u8fde\u7eed\uff0c\u4f7f\u5f97\u8ba8\u8bba\u7ecf\u5178\u7cfb\u7edf\u7684\u67d0\u4e9b\u7269\u7406\u91cf\u65f6\uff0c\u539f\u672c\u7684\u6c42\u548c\u53d8\u4e3a\u79ef\u5206\uff0c\u4ece\u800c\u5904\u7406\u8d77\u6765\u66f4\u52a0\u65b9\u4fbf\u3002</p> <p>\u2605 \u4e0a\u9762\u7684\u8ba8\u8bba\u4e2d\uff0c\u5206\u5e03\u5747\u8868\u793a\u4e3a\u5bf9\u80fd\u7ea7(levels)\u7684\u6c42\u548c\uff0c\u53c2\u8003\u672c\u7ae0\u5f00\u5934\u7684\u8868\u683c\uff0c\u8fd9\u663e\u7136\u662f\u5c06\u91cf\u5b50\u6001\u6309\u7167\u80fd\u7ea7\u5206\u7c7b\u540e\u7684\u8003\u91cf\uff0c\u56e0\u6b64\u8fd8\u5b58\u5728\u4e00\u79cd\u66f4\u52a0\u7cbe\u7ec6\u7684\u8868\u793a\u65b9\u5f0f\uff0c\u5373\u5bf9\u91cf\u5b50\u6001(states)\u7684\u6c42\u548c\u3002\u4e0b\u9762\u5c55\u793a\u4e24\u79cd\u4e0d\u540c\u8868\u793a\u4e4b\u95f4\u7684\u533a\u522b\u548c\u8054\u7cfb\uff0c\u8bbe\u5171\u6709\\(l_t\\)\u4e2a\u80fd\u7ea7\uff0c\\(s_t\\)\u4e2a\u91cf\u5b50\u6001\uff1a</p> \\[ \\sum_{l=1}^{l_t}\\omega_l=s_t \\qquad N=\\sum_{l=1}^{l_t}a_l=\\sum_{s=1}^{s_t}n_s\\qquad E=\\sum_{l=1}^{l_t}\\varepsilon_la_l=\\sum_{s=1}^{s_t}\\varepsilon_sn_s \\] \\[ a_l=\\frac{\\omega_l}{e^{\\alpha+\\beta\\varepsilon_l}+i}\\qquad n_s=\\frac{1}{e^{\\alpha+\\beta\\varepsilon_s}+i}\\qquad(i=0,\\pm 1) \\] <p>\u4e5f\u5c31\u662f\u8bf4\uff0c\u5360\u636e\u6570\u5206\u5e03\u7684\u63cf\u8ff0\u6709\u4e24\u79cd\uff1a \\(\\{a_l\\}\\) \\(\\{n_s\\}\\)\uff0c\\(a_l\\)\u8868\u793a\u5728\u80fd\u7ea7\\(\\varepsilon_l\\)\u4e0a(\u5305\u542b\u7b80\u5e76\u6001)\uff0c\u603b\u5171\u5360\u636e\u7684\u7c92\u5b50\u6570\uff1b\\(n_s\\)\u8868\u793a\u5728\\(\\left | \\psi_s  \\right \\rangle\\)\u91cf\u5b50\u6001\u4e0a\uff0c\u5360\u636e\u7684\u7c92\u5b50\u6570\u3002</p> <p>\u5bf9\u91cf\u5b50\u6001\u8fdb\u884c\u6c42\u548c\u7684\u8868\u793a\u4f7f\u5f97\u7b80\u5e76\u5ea6\u7684\u6982\u5ff5\u5f97\u4ee5\u7529\u6389\uff0c\u56e0\u4e3a\u8fd9\u91cc\u7684\u7b80\u5e76\u662f\u5bf9\u80fd\u7ea7\u800c\u8a00\u7684\u3002\u4f46\u5982\u679c\u5b8c\u5168\u91c7\u7528\\(n_s\\)\u7684\u5206\u5e03\u63cf\u8ff0\u6765\u7814\u7a76\u975e\u5b9a\u57df\u91cf\u5b50\u7cfb\u7edf\uff0c\u4e5f\u4f1a\u5e26\u6765\u4e00\u4e9b\u95ee\u9898\uff0c\u4f8b\u5982\u5bf9\u4e8e\u786e\u5b9a\u7684\\(\\{n_s\\}\\)\u4f1a\u6709\\(\\Omega_{B.E.}=\\Omega_{F.D.}=1\\).\u6b64\u5916\uff0c\u540e\u9762\u7684\u7cfb\u7efc\u7406\u8bba\u4e2d\uff0c\u8fd9\u79cd\u7c7b\u4f3c\u7684\u6c42\u548c\u5f62\u5f0f\u4e5f\u7ecf\u5e38\u51fa\u73b0\uff0c\u9700\u8981\u6df1\u5165\u7406\u89e3\u3002</p> <p>\u2605 \u6700\u540e\uff0c\u6839\u636e\u4e09\u79cd\u5206\u5e03\u7684\u6570\u5b66\u5f62\u5f0f\uff0c\u901a\u5e38\u4f1a\u9047\u5230\u5982\u4e0b\u7684\u79ef\u5206\uff0c\u8fd9\u91cc\u4e0d\u52a0\u8bc1\u660e\u5730\u7ed9\u51fa\u5982\u4e0b\u516c\u5f0f\uff0c\u65b9\u4fbf\u624b\u52a8\u8fdb\u884c\u8ba1\u7b97\uff1a</p> \\[ \\int_{0}^{\\infty}\\frac{x^n}{e^{bx^m}+i}dx=\\underbrace{\\overbrace{\\underbrace{\\frac{1}{m}\\frac{\\Gamma(\\heartsuit)}{b^\\heartsuit}}_{M.B.i=0}\\cdot\\sum_{k=1}^{\\infty}\\frac{1}{k^\\heartsuit}}^{B.E.i=-1}\\cdot\\frac{2^\\heartsuit-2}{2^\\heartsuit}}_{F.D.i=1}\\quad\\quad(i=0,\\pm 1) \\] <p>\u5176\u4e2d\\(\\heartsuit=\\frac{1+n}{m}\\),\u7b2c\u4e00\u9879\u5e38\u7528\u5230\\(\\Gamma(x)=(x-1)!\\)\u548c\\(\\Gamma(\\frac{1}{2})=\\sqrt{\\pi}\\),\u4e14\u7b2c\u4e8c\u9879\u76f8\u5f53\u4e8e\\(\\zeta(\\heartsuit)\\),\u9700\u8981\u8bb0\u4f4f\u5e38\u89c1\u7684\u51e0\u4e2a\uff1a</p> \\[ \\zeta(2)=\\frac{\\pi^2}{6},\\zeta(4)=\\frac{\\pi^4}{90}\\qquad\\sum_{k=1}^\\infty\\frac{1}{(2k)^\\heartsuit}=\\frac{\\zeta(\\heartsuit)}{2^\\heartsuit}\\quad \\sum_{k=1}^\\infty\\frac{1}{(2k-1)^\\heartsuit}=\\frac{2^\\heartsuit-1}{2^\\heartsuit}\\zeta(\\heartsuit) \\] <p>\u25a0 \u6ce8\u610f\u4e8b\u9879\uff1a(1)\u79ef\u5206\u533a\u95f4\u4e3a\u4e00\u7ef4\u534a\u7a7a\u95f4\uff0c\u5e38\u89c1\u8ba1\u7b97\u591a\u4e3a\u5bf9\u5168\u7a7a\u95f4\u7684\u79ef\u5206\uff0c\u56e0\u800c\u901a\u5e38\u662f\u8981\u5bf9\u7ed3\u679c\u4e58\u4ee52\u7684(2)\u5bf9\u4e8eb\u7684\u53d6\u503c\uff0c\u9700\u8981\u6ee1\u8db3\\(Re(b)&gt;0\\)\u624d\u80fd\u4f7f\u7528\u6b64\u5f0f(3)\u5bf9\u4e8e\u67d0\u4e9b\u7b80\u5355\u7684\u79ef\u5206\uff0c\u4f7f\u7528\u6b64\u5f0f\u53ef\u80fd\u4f1a\u51fa\u73b0\u6781\u9650\u4e0d\u5b9a\u578b\uff0c\u56e0\u6b64\u4f7f\u7528\u4e4b\u524d\u8bf7\u614e\u91cd\u8003\u8651</p>"},{"location":"chapter_07_boltzmann_statistics/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_07_boltzmann_statistics/index.html#7-boltzmann","title":"\u7b2c7\u7ae0 Boltzmann\u7edf\u8ba1\u7406\u8bba","text":"<p>\u672c\u7ae0\u4e3b\u8981\u7814\u7a76\u5b9a\u57df\u7cfb\u7edf\u6216\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7cfb\u7edf(\u90fd\u670d\u4ece\u73bb\u5c14\u5179\u66fc\u5206\u5e03)\uff0c\u8ba8\u8bba\u7cfb\u7edf\u70ed\u529b\u5b66\u91cf\u7684\u5fae\u89c2\u8868\u8fbe\u5f0f\u3002\u9996\u5148\uff0c\u5f15\u5165\u7c92\u5b50\u914d\u5206\u51fd\u6570\u5e76\u5c06\u57fa\u672c\u70ed\u529b\u5b66\u91cf\u4e0e\u7c92\u5b50\u914d\u5206\u51fd\u6570\u5efa\u7acb\u8054\u7cfb\u3002\u5176\u6b21\uff0c\u6c42\u51fa\u4e0d\u540c\u7cfb\u7edf\u7684\u7c92\u5b50\u914d\u5206\u51fd\u6570(\u7406\u60f3\u6c14\u4f53\u3001\u9ed1\u4f53\u8f90\u5c04\u3001\u5e38\u89c1\u56fa\u4f53)\uff0c\u4ece\u800c\u5f97\u5230\u5b83\u4eec\u7684\u70ed\u529b\u5b66\u6027\u8d28\u3002</p>"},{"location":"chapter_07_boltzmann_statistics/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u63a8\u5bfc\u70ed\u529b\u5b66\u91cf</li> <li>\u4e8c\u80fd\u7ea7\u7cfb\u7edf</li> <li>\u7406\u60f3\u6c14\u4f53\u5e73\u52a8\u70ed\u529b\u5b66\u91cf\u4e0eMaxwell\u901f\u5ea6\u5206\u5e03</li> <li>\u5e7f\u4e49\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u4e0e\u9ed1\u4f53\u8f90\u5c04</li> <li>\u7406\u60f3\u6c14\u4f53\u7684\u70ed\u529b\u5b66\u91cf</li> <li>\u56fa\u4f53\u70ed\u5bb9\u7406\u8bba</li> </ul>"},{"location":"chapter_07_boltzmann_statistics/01_partition_function_thermo.html","title":"\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u63a8\u5bfc\u70ed\u529b\u5b66\u91cf","text":""},{"location":"chapter_07_boltzmann_statistics/01_partition_function_thermo.html#_1","title":"\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u63a8\u5bfc\u70ed\u529b\u5b66\u91cf","text":"<p>\u2605 \u8003\u8651\u5728\u670d\u4ece\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u7684\u7cfb\u7edf\u4e2d\uff0c\u7c92\u5b50\u5904\u5728\\(\\varepsilon_l\\)\u80fd\u7ea7\u7684\u6982\u7387\u4e3a\uff1a</p> \\[ P_l=\\frac{a_l}{\\sum_la_l}=\\frac{\\omega_le^{-\\alpha-\\beta\\varepsilon_l}}{\\sum_l\\omega_le^{-\\alpha-\\beta\\varepsilon_l}}=\\frac{\\omega_le^{-\\beta\\varepsilon_l}}{\\sum_l\\omega_le^{-\\beta\\varepsilon_l}}=\\frac{\\omega_le^{-\\beta\\varepsilon_l}}{Z_1}\\Rightarrow \\boxed{Z_1=\\sum_l\\omega_le^{-\\beta\\varepsilon_l}} \\] <p>\u8fd9\u91cc\u5f15\u5165\u7c92\u5b50\u914d\u5206\u51fd\u6570\\(Z_1\\)\uff0c\u53ef\u89c1\u5176\u4f5c\u7528\u76f8\u5f53\u4e8e\u5f52\u4e00\u5316\u56e0\u5b50\u3002\u6b64\u5916\uff0c\u6ce8\u610f\u5176\u89d2\u6807\\(1\\)\u8868\u793a\u5355\u7c92\u5b50\u7684\u610f\u601d\uff0c\u539f\u56e0\u5728\u4e8e\u76ee\u524d\u7684\u8ba8\u8bba\u90fd\u57fa\u4e8e\u5b50\u76f8\u7a7a\u95f4\uff0c\u5b50\u7cfb\u7edf\u90fd\u662f\u5355\u7c92\u5b50\uff0c\u4e4b\u540e\u7cfb\u7efc\u7406\u8bba\u5f53\u4e2d\u8fd8\u4f1a\u51fa\u73b0(\u7cfb\u7edf)\u914d\u5206\u51fd\u6570\\(Z\\)\u548c\u5de8\u914d\u5206\u51fd\u6570\\(\\Xi\\)\u7b49.</p> <p>\u70ed\u529b\u5b66\u91cf\u6709\u4e24\u7c7b\uff0c\u4e00\u7c7b\u76f4\u63a5\u4e0e\u5fae\u89c2\u91cf\u6709\u5bf9\u5e94\uff0c\u4ece\u800c\u6c42\u51fa\u76f8\u5e94\u5fae\u89c2\u91cf\u7684\u7edf\u8ba1\u5e73\u5747\uff0c\u5c31\u5f97\u51fa\u6b64\u70ed\u529b\u5b66\u91cf\uff0c\u4f8b\u5982\u5185\u80fd\u3001\u5e7f\u4e49\u529b\uff1b\u53e6\u4e00\u7c7b\u4e0e\u5fae\u89c2\u91cf\u6ca1\u6709\u76f4\u63a5\u5bf9\u5e94\uff0c\u9700\u8981\u5229\u7528\u70ed\u529b\u5b66\u516c\u5f0f\u7c7b\u6bd4\u6c42\u51fa\uff0c\u4f8b\u5982\u70ed\u91cf\u3001\u71b5\u3002</p> <p>\u57fa\u4e8e\\(Z_1(\\beta,y)\\)\u4e3a\\(\\beta\\)\u548c\u5916\u53c2\u91cf\\(y\\)\u7684\u51fd\u6570\uff0c\u5c06\u57fa\u672c\u70ed\u529b\u5b66\u91cf\u8fdb\u884c\u6539\u5199\uff0c\u9996\u5148\u4ece\u4f53\u7cfb\u7684\u5185\u80fd\u548c\u7c92\u5b50\u6570\u5165\u624b\uff1a</p> \\[ N=\\sum_la_l=e^{-\\alpha}\\sum_l\\omega_le^{-\\beta\\varepsilon_l}=e^{-\\alpha}Z_1\\Rightarrow\\boxed{e^{-\\alpha}=\\frac{N}{Z_1}} \\] \\[ U=\\sum_l\\varepsilon_la_l=e^{-\\alpha}\\sum_l\\varepsilon_l\\omega_le^{-\\beta\\varepsilon_l}=e^{-\\alpha}\\left(-\\frac{\\partial}{\\partial\\beta}\\right)\\sum_l\\omega_le^{-\\beta\\varepsilon_l} \\] <p>\u8054\u7acb\u4ee5\u4e0a\u4e24\u5f0f\uff0c\u5373\u7528\u4ee3\u6362\\(e^{-\\alpha}=\\frac{N}{Z_1}\\)\u5f97\u5230\uff1a</p> \\[ U=\\frac{N}{Z_1}\\left(-\\frac{\\partial}{\\partial\\beta}\\right)Z_1=-N\\left(\\frac{\\partial}{\\partial\\beta}\\right)ln(Z_1)\\Rightarrow\\boxed{U=-N\\frac{\\partial}{\\partial\\beta}ln(Z_1)} \\] <p>\u6839\u636e\u5fae\u89c2\u8fc7\u7a0b\u7684\u80fd\u91cf\u5b88\u6052\uff0c\u5373\u5916\u754c\u5bf9\u7cfb\u7edf\u505a\u529f\u7b49\u4e8e\u7cfb\u7edf\u5fae\u89c2\u80fd\u91cf\u7684\u589e\u91cf\uff1a</p> \\[ Ydy=\\sum_la_l\\frac{\\partial\\varepsilon_l}{\\partial y}dy \\] <p>\u4ece\u800c\u53ef\u5c06\u5e7f\u4e49\u529b\u6539\u5199\u5982\u4e0b\uff1a</p> \\[ \\Rightarrow Y=\\sum_la_l\\frac{\\partial\\varepsilon_l}{\\partial y}=e^{-\\alpha}\\sum_l\\frac{\\partial\\varepsilon_l}{\\partial y}\\omega_le^{-\\beta\\varepsilon_l}=e^{-\\alpha}\\sum_l\\frac{\\partial\\varepsilon_l}{\\partial y}\\omega_l\\frac{-1}{\\beta}\\frac{\\partial}{\\partial \\varepsilon_l}e^{-\\beta \\varepsilon_l} \\] \\[ \\Rightarrow Y=e^{-\\alpha}\\left(-\\frac{1}{\\beta}\\frac{\\partial}{\\partial y}\\right)\\sum_l\\omega_le^{-\\beta \\varepsilon_l}\\Rightarrow\\boxed{Y=-\\frac{N}{\\beta}\\frac{\\partial}{\\partial y}ln(Z_1)} \\] <p>\u7531\u6b64\u5f97\u5230\u5e7f\u4e49\u529b\\(Y\\)\u57fa\u4e8e\\(Z_1\\)\u7684\u8868\u8fbe\u5f0f\u3002\u4e3a\u4e86\u5f62\u8c61\u7406\u89e3\uff0c\u4ee5\u538b\u5f3a\u4e3a\u4f8b\uff1a\\(\\delta W=Ydy=-pdV=pd(-V)\\)\u7531\u4e8e\u76ee\u6807\u662f\u6c42\u51fa\u4e0d\u5e26\u8d1f\u53f7\u7684\\(p\\)\uff0c\u4ece\u800c\u5fc5\u987b\u5c06\u8d1f\u53f7\u4e22\u7ed9\\(dV\\)\uff0c\u8fd9\u91cc\u7684\u7ec6\u8282\u9700\u8981\u6df1\u523b\u7406\u89e3\uff0c\u7ecf\u5e38\u8981\u7528\u5230\u3002\u4ece\u800c\u6709:</p> \\[ p=\\frac{N}{\\beta}\\frac{\\partial}{\\partial V}ln(Z_1) \\] <p>\u6ce8\u610f\u4ee5\u4e0a\u6c42\u51fa\u7684\\(U\\)\u548c\\(Y\\)\u7684\u8868\u8fbe\u5f0f\uff0c\u672c\u8d28\u4e0a\u90fd\u662f\u5bf9\u4e0e\u4e4b\u76f8\u5e94\u7684\u5fae\u89c2\u91cf\u8fdb\u884c\u7edf\u8ba1\u5e73\u5747\uff0c\u5e76\u7edf\u4e00\u5730\u7528\\(Z_1\\)\u8fdb\u884c\u8868\u8fbe\u800c\u5df2\u3002\u4e0e\u6b64\u4e0d\u540c\uff0c\u71b5\\(S\\)\u6ca1\u6709\u76f4\u63a5\u5bf9\u5e94\u7684\u5fae\u89c2\u91cf\uff0c\u65e0\u6cd5\u8fdb\u884c\u7edf\u8ba1\u5e73\u5747\uff0c\u800c\u9700\u8981\u70ed\u529b\u5b66\u516c\u5f0f\u7684\u7c7b\u6bd4\u624d\u80fd\u5bfc\u51fa\uff1a</p> <p>\u5bf9\u6bd4\u5185\u80fd\u7684\u5b8f\u89c2\u4e0e\u5fae\u89c2\u8868\u8fbe\u5f0f\uff0c\u5c06\u5e7f\u4e49\u529b\u505a\u529f\u7684\u8868\u8fbe\u5f0f\u4ee3\u5165\u53ef\u770b\u51fa\uff1a\u505a\u529f\u6539\u53d8\u7cfb\u7edf\u80fd\u7ea7\u672c\u8eab\u7684\u5927\u5c0f\uff0c\u5438\u70ed\u6539\u53d8\u7cfb\u7edf\u4e0d\u540c\u80fd\u7ea7\u4e0a\u7684\u7c92\u5b50\u6570\uff0c\u5373\uff1a</p> \\[ dU=\\delta Q+\\delta W=\\sum_l\\varepsilon_lda_l+\\sum_la_ld\\varepsilon_l\\Rightarrow \\delta W=\\sum_la_ld\\varepsilon_l \\] \\[ \\Rightarrow\\delta Q=dU-\\delta W=dU-Ydy=\\sum_l\\varepsilon_lda_l \\] <p>\u4e00\u65b9\u9762\uff0c\u70ed\u529b\u5b66\u90e8\u5206\u4e2d\u63d0\u5230\uff0c\u6e29\u5ea6\\(T\\)\u7684\u5012\u6570\u4e3a\\(\\delta Q\\)\u7684\u79ef\u5206\u56e0\u5b50\uff0c\u5373:\\(dS=\\frac{1}{T}\\delta Q\\).\u53e6\u4e00\u65b9\u9762\uff0c\u62c9\u683c\u6717\u65e5\u4e58\u5b50\\(\\beta\\)\u4e5f\u4e3a\\(\\delta Q\\)\u7684\u79ef\u5206\u56e0\u5b50\uff0c\u8bc1\u660e\u5982\u4e0b\uff1a(\u4e3a\u4e86\u65b9\u4fbf\u8fd0\u7b97\uff0c\u8fd9\u91cc\u91c7\u7528\\(\\delta Q=dU-Ydy\\))</p> \\[ \\beta\\delta Q=\\beta(dU-Ydy)=-N\\beta d\\left(\\frac{\\partial ln(Z_1)}{\\partial \\beta}\\right)+N\\frac{\\partial ln(Z_1)}{\\partial y}dy \\] <p>\u6839\u636e\\(ln(Z_1)\\)\u7684\u5168\u5fae\u5206\uff0c\u53ef\u5c06\u4e0a\u5f0f\u51d1\u6210\u5168\u5fae\u5206\u7684\u5f62\u5f0f\uff1a</p> \\[ dln(Z_1)=\\frac{\\partial ln(Z_1)}{\\partial\\beta}d\\beta+\\frac{\\partial ln(Z_1)}{\\partial y}dy\\quad\\Rightarrow\\quad \\beta\\delta Q=Nd\\left(ln(Z_1)-\\beta\\frac{\\partial ln(Z_1)}{\\partial \\beta}\\right) \\] <p>\u7531\u6b64\u5373\u8bc1\\(\\beta\\)\u4e5f\u4e3a\\(\\delta Q\\)\u7684\u79ef\u5206\u56e0\u5b50\u3002\u6839\u636e\u5fae\u5206\u65b9\u7a0b\u7406\u8bba\uff0c\u4e24\u4e2a\u79ef\u5206\u56e0\u5b50\u7684\u6bd4\u503c\u4e3a\u71b5\u7684\u5168\u5fae\u5206\u7684\u51fd\u6570\uff0c\u8bbe\u8fd9\u4e2a\u51fd\u6570\u4e3a\\(k(S)\\),\u79f0\u4e3a\u73bb\u5c14\u5179\u66fc\u5e38\u6570\uff0c\u4ece\u800c\uff1a</p> \\[ \\beta=\\frac{1}{k(S)T} \\] <p>\u4e0a\u4e00\u7ae0\u63d0\u5230\uff0c\u591a\u79cd\u5206\u7684\u6700\u6982\u7136\u5206\u5e03\u5f53\u4e2d\\(\\beta\\)\u76f8\u540c\uff0c\u5373\u5f53\u591a\u4e2a\u7cfb\u7edf\u76f8\u4e92\u63a5\u89e6\u8fbe\u5230\u5e73\u8861\u6001\u65f6\uff0c\u62e5\u6709\u5171\u540c\u7684\\(\\beta\\)\uff0c\u7531\u6b64\u5426\u8ba4\u4e86\\(\\beta\\)\u4f1a\u968f\u71b5\\(S\\)\u53d8\u5316\u3002\u8fdb\u800c\\(k(S)\\)\u4e5f\u4e3a\u5e38\u91cf\u51fd\u6570\uff0c\u5b9e\u9a8c\u4e0a\u6d4b\u5f97\u4e3a\\(1.38\\times10^{-23}J/K\\).\u7531\u6b64\u6839\u636e\\(dS=\\frac{\\delta Q}{T}\\)\u5f97\u5230\u71b5\u7684\u8868\u8fbe\u5f0f\uff1a</p> \\[ dS=k\\beta\\delta Q=kNd\\left(ln(Z_1)-\\beta\\frac{\\partial ln(Z_1)}{\\partial \\beta}\\right) \\] <p>\u6839\u636e\u7edd\u5bf9\u71b5\\(S_0=0\\)\u7684\u89c4\u5b9a\uff0c\u79ef\u5206\u7ed3\u679c\u4e3a\uff1a</p> \\[ \\boxed{S=Nk\\left(ln(Z_1)-\\beta\\frac{\\partial}{\\partial \\beta}ln(Z_1)\\right)} \\] <p>\u81f3\u6b64\uff0c\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u4e0b\u7684\u57fa\u672c\u70ed\u529b\u5b66\u91cf\u90fd\u5df2\u7ecf\u5b8c\u5168\u4e0e\\(Z_1\\)\u5efa\u7acb\u8054\u7cfb\u4e86\uff0c\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\u5747\u53ef\u7531\u6b64\u5bfc\u51fa\u3002\u4f8b\u5982\u5e38\u7528\u5230\u7684\u81ea\u7531\u80fd\\(F\\):</p> \\[ F=U-TS=-NkTln(Z_1)\\Rightarrow\\boxed{F=-NkTln(Z_1)} \\] <p>\u7c7b\u6bd4\\(F(T,V)\\)\u548c\\(Z_1(\\beta,y)=Z_1(\\frac{1}{kT},V)\\),\u5176\u53d8\u91cf\u4ec5\u4ec5\u5dee\u4e86\u73bb\u5c14\u5179\u66fc\u5e38\u6570\\(k\\)\uff0c\u8fd9\u6837\u4e5f\u5c31\u4e0d\u96be\u7406\u89e3\u4e3a\u4f55\u4e24\u8005\u5f62\u5f0f\u5982\u6b64\u76f8\u50cf\u3002</p> <p>\u6b64\u5916\uff0c\u5e94\u5f53\u6ce8\u610f\u4ee5\u4e0a\u90fd\u662f\u57fa\u4e8e\u5b9a\u57df\u7cfb\u7edf\u8ba8\u8bba\u7684\u7ed3\u679c\uff0c\u5f53\u7cfb\u7edf\u662f\u901a\u8fc7\u975e\u7b80\u5e76\u6761\u4ef6\u8fd1\u4f3c\u4e3a\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\u65f6\uff0c\u4e00\u5b9a\u8981\u8003\u8651\u5176\u7cfb\u7edf\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega\\)\u7684\u5f71\u54cd\uff0c\u8fd9\u5c31\u6d89\u53ca\u5230\u73bb\u5c14\u5179\u66fc\u5173\u7cfb\u7684\u95ee\u9898\u3002</p> <p>\u2605 \u5bf9\u5e38\u7528\u4ee3\u6362\\(e^{-\\alpha}=\\frac{N}{Z_1}\\)\u4e24\u8fb9\u53d6\u5bf9\u6570\u5f97\u5230\uff1a\\(ln(Z_1)=ln(N)+\\alpha\\),\u4ee3\u5165\u71b5\u7684\u8868\u8fbe\u5f0f\u5f53\u4e2d,\u6d88\u53bb\\(Z_1\\)\u9879\uff1a</p> \\[ S=k(Nln(N)+\\alpha N+\\beta U)=k\\left[Nln(N)+\\sum_l(\\alpha+\\beta\\varepsilon_l)a_l\\right] \\] <p>\u4ee3\u5165\u73bb\u5c14\u5179\u66fc\u5206\u5e03\\(a_l=\\omega_le^{-\\alpha-\\beta\\varepsilon_l}\\),\u5e76\u4e14\u9006\u5411\u4f7f\u7528Stirling\u516c\u5f0f\uff1a</p> \\[ S=kln(\\Omega_{M.B.})\\Rightarrow \\boxed{S=kln(\\Omega)} \\] <p>\u4e0a\u5f0f\u8868\u660e\u5728\u73bb\u5c14\u5179\u66fc\u7cfb\u7edf\u4e2d\uff0c\u71b5\u4e0e\u5fae\u89c2\u72b6\u6001\u6570\u6709\u76f4\u63a5\u7684\u5173\u7cfb\uff0c\u5e76\u5c06\u8fd9\u4e00\u7279\u6027\u63a8\u5e7f\u5230\u4efb\u610f\u7cfb\u7edf\uff0c\u79f0\u4e3a\u73bb\u5c14\u5179\u66fc\u5173\u7cfb\u3002</p> <p>\u7531\u6b64\u4e0d\u96be\u60f3\u89c1\uff0c\u5bf9\u4e8e\u901a\u8fc7\u975e\u7b80\u5e76\u6761\u4ef6\u8fd1\u4f3c\u4e3a\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\uff0c\u7531\u4e8e\u5176\u5fae\u89c2\u72b6\u6001\u6570\u4e0e\u5b9a\u57df\u7cfb\u7edf\u76f8\u5dee\\(N!\\)\u500d\uff0c\u4ece\u800c\u6d89\u53ca\\(\\Omega\\)\u7684\u71b5\u4ee5\u53ca\u4e0e\u71b5\u76f8\u5173\u7684\u8868\u8fbe\u5f0f\u90fd\u5e94\u8fdb\u884c\u4fee\u6b63\uff1a</p> \\[ \\Omega=\\Omega_{B,E}=\\Omega_{F.D.}=\\frac{\\Omega_{M.B.}}{N!}\\Rightarrow S=kln(\\Omega)=kln(\\Omega_{M.B.})-kln(N!) \\] <p>\u5373\u53ea\u9700\u5728\u4e4b\u524d\u5bfc\u51fa\u7684\u71b5\u7684\u57fa\u7840\u4e4b\u4e0a\uff0c\u51cf\u53bb\\(kln(N!)\\)\u5373\u53ef\u3002\u540c\u65f6\uff0c\u81ea\u7531\u80fd\u4e5f\u53ef\u6839\u636e\u5b9a\u4e49\u8fdb\u884c\u4fee\u6539\uff1a</p> \\[ \\boxed{S'=S-kln(N!)\\qquad F'=F+kTln(N!)} \\] <p>\u7531\u6b64\u53ef\u89c1\uff0c\u5728\u6c42\u7cfb\u7edf\u7684\u70ed\u529b\u5b66\u91cf\u65f6\uff0c\u9996\u5148\u8981\u660e\u786e\u7684\u662f\u7cfb\u7edf\u7684\u5b9a\u57df\u6027\u3002\u6b64\u5916\uff0c\u7cfb\u7efc\u7406\u8bba\u4e2d\u5c06\u4ee5\u4e0a\u7684\u4fee\u6b63\u9879\u90fd\u5c01\u88c5\u5728\u914d\u5206\u51fd\u6570\\(Z\\)\u5f53\u4e2d\u4e86\uff0c\u5e76\u4e14\\(N!\\)\u4ec5\u4ec5\u51fa\u73b0\u5728\u975e\u5b9a\u57df\u7cfb\u7edf\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u70ed\u529b\u5b66\u91cf\u4e2d\uff0c\u4ece\u800c\u7cfb\u7edf\u53ef\u4ee5\u8fd1\u4f3c\u4e3a\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u3002\u4f46\u5bf9\u4e8e\u5f3a\u7b80\u5e76\u7cfb\u7edf\uff0c\u6240\u4f7f\u7528\u7684\u5de8\u914d\u5206\u51fd\u6570\u5c31\u4e0d\u7528\u8003\u8651\u6b64\u9879\u3002</p> <p>\u4e8b\u5b9e\u4e0a\uff0c\u71b5\u9664\u4e86\u4ee5\u4e0a\u7684\u8868\u8fbe\u5f62\u5f0f\uff0c\u8fd8\u6709\u5f88\u591a\u7684\u7b49\u4ef7\u8868\u8fbe\u3002\u4f8b\u5982\u53ef\u4ee5\u5229\u7528\u7c92\u5b50\u5904\u5728\\(s\\)\u6001\u7684\u6982\u7387\\(P_s\\)\u6765\u8868\u8fbe\uff1a</p> \\[ P_s=\\frac{e^{-\\alpha-\\beta\\varepsilon_s}}{N}=\\frac{e^{-\\beta\\varepsilon_s}}{Z_1}\\Rightarrow S=Nk\\left(ln(Z_1)-\\beta\\frac{\\partial}{\\partial \\beta}ln(Z_1)\\right) \\] <p>\u8bbe\u7c92\u5b50\u5e73\u5747\u80fd\u91cf\u4e3a\\(\\bar{\\varepsilon}=\\frac{U}{N}\\)\u5e76\u5229\u7528\\(\\sum_sP_s=1\\),\u5219\uff1a</p> \\[ S=Nk\\left(ln(Z_1)+\\beta\\bar{\\varepsilon}\\right)=Nk\\left(ln(Z_1)\\sum_sP_s+\\beta\\sum_sP_s\\varepsilon_s\\right)=Nk\\sum_sP_s(ln(Z_1)+\\beta\\varepsilon_s) \\] <p>\u5bf9\\(P_s\\)\u7684\u5b9a\u4e49\u5f0f\u53d6\u5bf9\u6570\uff0c\u4ee3\u5165\u5f97\u5230\uff1a</p> \\[ ln(P_s)=-\\beta\\varepsilon_s-ln(Z_1)\\Rightarrow\\boxed{S=-Nk\\sum_sP_slnP_s} \\] <p>\u4e0a\u5f0f\u7684\u542f\u53d1\u610f\u4e49\u9887\u5927\uff0c\u8868\u660e\u71b5\u7684\u5927\u5c0f\u53ef\u4ee5\u7406\u89e3\u4e3a\u4fe1\u606f\u7f3a\u4e4f\u7684\u5ea6\u91cf\u3002\u6b64\u5916\uff0c\u5c06\\(P_s\\)\u6362\u4e3a\u5176\u4ed6\u5f62\u5f0f\u7684\u6982\u7387\uff0c\u7c7b\u4f3c\u7684\u71b5\u7684\u57fa\u672c\u5f62\u5f0f\u4e5f\u4e0d\u53d8\uff0c\u5982\u4fe1\u606f\u71b5\u3001\u7ea0\u7f20\u71b5\u3002</p> <p>\u2605 \u6700\u540e\uff0c\u6211\u4eec\u5bf9\u7ecf\u5178\u7684\u7c92\u5b50\u914d\u5206\u51fd\u6570\u8fdb\u884c\u8ba8\u8bba\u3002\u7ecf\u5178\u7cfb\u7edf\u7684\u7279\u5f81\u5c31\u662f\u80fd\u7ea7\u51c6\u8fde\u7eed\uff0c\u6839\u636e\u51c6\u8fde\u7eed\u6761\u4ef6\uff0c\u5f97\u5230\u80fd\u7ea7\u5360\u636e\u7684\u5206\u5e03\uff0c\u8fdb\u800c\u5f97\u5230\u7c92\u5b50\u914d\u5206\u51fd\u6570\uff1a</p> \\[ \\frac{\\Delta\\varepsilon}{kT}\\ll1\\Rightarrow da_l=\\frac{d\\omega}{h^r}e^{-\\alpha-\\beta\\varepsilon_l}\\Rightarrow \\boxed{Z_1=\\int\\frac{d\\omega}{h^r}e^{-\\beta\\varepsilon_l}} \\] <p>\u4ee5\u4e0a\u5229\u7528\u7ecf\u5178\u7cfb\u7edf\u80fd\u7ea7\u7684\u8fde\u7eed\u6027\uff0c\u5c06\u6c42\u548c\u5199\u4e3a\u79ef\u5206\u5f62\u5f0f\u3002\u5728\u5206\u6790\u4f8b\u5982\u7406\u60f3\u6c14\u4f53\u80fd\u7ea7\u51c6\u8fde\u7eed\u7684\u7cfb\u7edf\u65f6\uff0c\u5e38\u5e38\u4f1a\u7528\u5230\u6b64\u5f0f\u3002</p>"},{"location":"chapter_07_boltzmann_statistics/02_two_level_system.html","title":"\u4e8c\u80fd\u7ea7\u7cfb\u7edf","text":""},{"location":"chapter_07_boltzmann_statistics/02_two_level_system.html#_1","title":"\u4e8c\u80fd\u7ea7\u7cfb\u7edf","text":"<p>%\u8d1f\u6e29\u5ea6\u3001\u4e09\u80fd\u7ea7\u7cfb\u7edf</p> <p>\u2605 \u4e8c\u80fd\u7ea7\u7cfb\u7edf\u5728\u7269\u7406\u4e2d\u5e94\u7528\u5341\u5206\u5e7f\u6cdb\uff0c\u4f8b\u5982\u94c1\u78c1\u76f8\u53d8\u3001\u6fc0\u5149\u8f93\u8fd0\u7b49\uff0c\u8fd9\u91cc\u4ec5\u8ba8\u8bba\u8fd1\u72ec\u7acb\u7684\u5b9a\u57df\u4e8c\u80fd\u7ea7\u7cfb\u7edf\u3002\u4e3a\u4e86\u8ba8\u8bba\u65b9\u4fbf\uff0c\u8fd9\u91cc\u5728\u7a00\u78c1\u7cfb\u7edf\u7684\u80cc\u666f\u4e0b\uff0c\u8bbe\u4e24\u4e2a\u975e\u7b80\u5e76\u7684\u80fd\u7ea7\u5206\u522b\u4e3a\\(\\varepsilon_1=-\\mu B,\\varepsilon_2=\\mu B\\)\u5206\u522b\u4ee3\u8868\u4e24\u79cd\u81ea\u65cb\u72b6\u6001:</p> \\[ Z_1=\\sum_l\\omega_le^{-\\beta\\varepsilon_l}=e^{\\beta\\mu B}+e^{-\\beta\\mu B}=2cosh(\\frac{\\mu B}{kT}) \\] <p>\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\uff0c\u4e0d\u96be\u5f97\u5230\u5185\u80fd\u548c\u71b5\u7684\u8868\u8fbe\u5f0f:</p> \\[ U=-N\\frac{\\partial}{\\partial \\beta}ln(Z_1)=-N\\mu Btanh(\\frac{\\mu B}{kT}) \\] \\[ S=Nk\\left(ln(Z_1)-\\beta\\frac{\\partial}{\\partial \\beta}ln(Z_1)\\right)=Nk\\left[ln(2cosh(\\frac{\\mu B}{kT}))-\\frac{\\mu B}{kT}tanh(\\frac{\\mu B}{kT})\\right] \\] <p>\u71b5\u4e5f\u53ef\u4ee5\u7531\\(S=-Nk\\sum_sP_slnP_s\\)\u6765\u6c42\u5f97\u3002  \u4e0b\u9762\u8ba8\u8bba\u4e24\u4e2a\u6709\u8da3\u7684\u95ee\u9898\uff1a</p> <ul> <li>\u201c\u8d1f\u6e29\u5ea6\u201d\uff1a\u4ece\\(T=\\left(\\frac{\\partial U}{\\partial S}\\right)_y\\)\u7684\u89c6\u89d2\u6765\u770b\u5f85\u6e29\u5ea6\\(T\\),\u9996\u5148\u9700\u8981\u5f97\u5230\u51fd\u6570\\(S(U)\\)\uff0c\u4f46\u663e\u7136\u4e0a\u5f0f\u5f88\u96be\u5efa\u7acbS\u4e0eU\u7684\u5173\u7cfb\u5f0f\uff0c\u56e0\u800c\u53e6\u8f9f\u8e4a\u5f84\uff1a</li> </ul> \\[ N=N_++N_-\\quad U=\\mu B(N_+-N_-) \\] \\[ \\Rightarrow N_+=\\frac{N}{2}\\left(1+\\frac{U}{N\\mu B}\\right)\\quad N_-=\\frac{N}{2}\\left(1-\\frac{U}{N\\mu B}\\right) \\] <p>\u6839\u636e\u73bb\u5c14\u5179\u66fc\u5173\u7cfb\uff0c\u53ef\u6c42\u51fa\\(S(U)\\)\uff1a</p> \\[ S=kln(\\Omega)=kln\\left(\\frac{N!}{N_+!N_-!}\\right)\\approx k(NlnN-N_+lnN_+-N_-lnN_-) \\] <p>\u4e0a\u5f0f\u4f7f\u7528\u4e86Stirling\u8fd1\u4f3c\uff0c\u7531\u6b64\u5f97\u51fa\u6e29\u5ea6\u4e3a\uff1a</p> \\[ T=\\left(\\frac{\\partial U}{\\partial S}\\right)_B=\\left[\\frac{k}{2\\mu B}ln\\left(\\frac{N\\mu B-U}{N\\mu B+U}\\right)\\right]^{-1} \\] <p>\u4e8b\u5b9e\u4e0a\uff0c\u4e5f\u53ef\u4ece\\(U(T)\\)\u5bfc\u51fa\u4e0a\u5f0f\u3002\u5177\u4f53\u7684\u6e29\u5ea6\u968f\u5185\u80fd\u7684\u53d8\u5316\u5982\u4e0b\u56fe\uff1a</p> <p></p> <p>\u901a\u5e38\u8fd9\u79cd\u5947\u7279\u7684\u73b0\u8c61\u51fa\u73b0\u5728\u6838\u81ea\u65cb\u7cfb\u7edf\uff0c\u56e0\u4e3a\u5176\u76f8\u5bf9\u5bb9\u6613\u6ee1\u8db3\u4e24\u4e2a\u5fc5\u8981\u6761\u4ef6\uff1a(1)\u7cfb\u7edf\u7684\u80fd\u91cf\u6709\u4e0a\u9650(2)\u7cfb\u7edf\u4e0e\u4efb\u4f55\u6b63\u6e29\u5ea6\u7cfb\u7edf\u9694\u7edd\u3002</p> <ul> <li>\u8096\u7279\u57fa\u70ed\u5bb9\uff1a\u6839\u636e\u5185\u80fd\u7684\u8868\u8fbe\u5f0f\u548c\u70ed\u5bb9\u5b9a\u4e49:</li> </ul> \\[ C_V=\\frac{\\partial U}{\\partial T}=\\frac{NB^2\\mu^2sech(\\frac{\\mu B}{kT})^2}{kT^2} \\] <p>\u4e0d\u96be\u770b\u51fa\u5f53\\(T\\rightarrow0\\)\u548c\\(T\\rightarrow\\infty\\)\u65f6\uff0c\u70ed\u5bb9\u5206\u522b\u4ee5\u6307\u6570\u548c\u5e42\u6b21\u8d8b\u5411\u4e8e0.\u4e14\u5728\u67d0\u4e00\u6e29\u5ea6\u70ed\u5bb9\u4f1a\u6709\u6781\u5927\u503c\u3002</p> <p>\u2605 \u4e0b\u9762\u7814\u7a76\u987a\u78c1\u6027\u4e0e\u6e29\u5ea6\u7684\u5173\u7cfb,\u4e00\u65b9\u9762\u53ef\u4ee5\u4ece\u78c1\u77e9\u80fd\u91cf\\(E=-\\mu\\cdot B\\)\u51fa\u53d1\uff0c\u7531\u4e8e\u78c1\u77e9\u4e3a\u5b9a\u503c\u5f97\u5230\\(\\delta W=-n\\mu dB\\),\u76f4\u63a5\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u5f97\u51fa\uff1a</p> \\[ M=\\frac{n}{\\beta}\\frac{\\partial}{\\partial B}ln(Z_1)=n\\mu tanh(\\frac{\\mu B}{kT}) \\] <p>\u53e6\u4e00\u65b9\u9762\u4e5f\u53ef\u4ece\u4e8c\u80fd\u7ea7\u51fa\u73b0\u7684\u6982\u7387\u5165\u624b\uff0c\u6c42\u51fa\u4f53\u7cfb\u7684\u5e73\u5747\u78c1\u77e9;</p> \\[ P_+=\\frac{e^{-\\beta \\mu B}}{Z_1}\\quad P_-=\\frac{e^{\\beta \\mu B}}{Z_1}\\Rightarrow M=n(-\\mu P_++\\mu P_-)=n\\mu tanh(\\frac{\\mu B}{kT}) \\] <p>(1)\u82e5\u4f53\u7cfb\u9ad8\u6e29\u6216\u5f31\u573a\u65f6\uff1a</p> \\[ \\frac{\\mu B}{kT}\\rightarrow0\\quad\\Rightarrow\\quad M\\rightarrow n\\mu \\frac{\\mu B}{kT}=\\chi H\\quad S\\rightarrow Nkln2\\quad P_\\pm\\rightarrow \\frac{1}{2} \\] <p>\u7531\u6b64\u53ef\u770b\u51fa\u5c45\u91cc\u5b9a\u5f8b\uff0c\u4ee5\u53ca\u9ad8\u6e29\u4e0b\u4e24\u79cd\u80fd\u7ea7\u5360\u636e\u7684\u6570\u91cf\u662f\u57fa\u672c\u76f8\u7b49\u7684\u3002</p> <p>(2)\u82e5\u4f53\u7cfb\u4f4e\u6e29\u6216\u5f3a\u573a\u65f6\uff1a</p> \\[ \\frac{\\mu B}{kT}\\rightarrow\\infty\\quad\\Rightarrow\\quad M\\rightarrow n\\mu \\quad S\\rightarrow0\\quad P_+\\rightarrow 0 \\quad P_-\\rightarrow 1 \\] <p>\u5373\u5728\u4f4e\u6e29\u6216\u5f3a\u573a\u4e0b\uff0c\u78c1\u77e9\u5747\u6cbf\u7740\u76f8\u540c\u7684\u65b9\u5411\u3002</p> <p>\u2605 \u9664\u4e86\u4e8c\u80fd\u7ea7\u7cfb\u7edf\uff0c\u5e38\u5e38\u4e5f\u4f1a\u8003\u8651\u4e09\u80fd\u7ea7\u7cfb\u7edf\uff0c\u4f8b\u5982\u603b\u81ea\u65cb\u4e3a1\u7684\u5b9a\u57df\u7c92\u5b50\u7cfb\u7edf\uff0c\u78c1\u91cf\u5b50\u6570\u53ef\u4ee5\u53d6\\(-1,0,1\\)\u4e09\u79cd\u72b6\u6001\uff0c\u5373\u4e09\u80fd\u7ea7\u7cfb\u7edf\u3002\u5982\uff1a</p> \\[ Z_1=e^{\\beta\\mu B}+1+e^{-\\beta\\mu B}=1+2cosh(\\frac{\\mu B}{kT})\\quad\\Rightarrow\\quad ln(Z_1)=ln(1+2cosh(\\frac{\\mu B}{kT})) \\] <p>\u53ef\u89c1\\(ln(Z_1)\\)\u4e0e\u4e8c\u80fd\u7ea7\u7cfb\u7edf\u76f8\u6bd4\uff0c\u5bf9\u6570\u5185\u90e8\u591a\u4e86\\(1\\)\u8fd9\u4e00\u9879\uff0c\u4ece\u800c\u5bfc\u81f4\u70ed\u529b\u5b66\u91cf\u6027\u8d28\u7684\u5dee\u5f02\uff0c\u4f46\u53d6\u5f97\u8fd1\u4f3c\u540e\uff0c\u4e5f\u4ec5\u4ec5\u662f\u7cfb\u6570\u4e0a\u7684\u4e0d\u540c\u3002</p>"},{"location":"chapter_07_boltzmann_statistics/03_ideal_gas_translation.html","title":"\u7406\u60f3\u6c14\u4f53\u5e73\u52a8\u70ed\u529b\u5b66\u91cf\u4e0eMaxwell\u901f\u5ea6\u5206\u5e03","text":""},{"location":"chapter_07_boltzmann_statistics/03_ideal_gas_translation.html#maxwell","title":"\u7406\u60f3\u6c14\u4f53\u5e73\u52a8\u70ed\u529b\u5b66\u91cf\u4e0eMaxwell\u901f\u5ea6\u5206\u5e03","text":"<p>%\u6ce8\u610f\u5316\u5b66\u52bf\u963f\u5c14\u6cd5\u3001\u6cfb\u6d41</p> <p>\u2605 \u6839\u636e\u4e09\u7ef4\u7406\u60f3\u6c14\u4f53\u5e73\u52a8\u80fd\u91cf\u548c\u80fd\u7ea7\u8fde\u7eed\u7684\u7279\u5f81\uff0c\u53ef\u76f4\u63a5\u5f97\u5230\\(Z_1\\)\uff1a</p> \\[ \\varepsilon=\\frac{p^2}{2m}\\Rightarrow Z_1=\\int\\frac{dxdydzdp_xdp_ydp_z}{h^3}e^{-\\beta\\frac{p_x^2+p_y^2+p_z^2}{2m}}\\Rightarrow\\boxed{Z_1=\\frac{V}{h^3}\\left(\\frac{2m\\pi}{\\beta}\\right)^{\\frac{3}{2}}} \\] <p>\u4e0a\u5f0f\u9ed8\u8ba4\u6c14\u4f53\u7684\u4f53\u79ef\u4e3aV.\u7531\u6b64\u7acb\u5373\u5f97\u5230\u4f53\u7cfb\u7684\u5185\u80fd\u548c\u538b\u5f3a\uff1a</p> \\[ U=\\frac{3}{2}NkT\\qquad p=\\frac{NkT}{V} \\] <p>\u5bf9\u4e8e\u71b5\u7684\u5bfc\u51fa\u9700\u8981\u6ce8\u610f\uff0c\u5982\u679c\u4f7f\u7528\u5b9a\u57df\u7cfb\u7edf\u7684\u71b5\u8868\u8fbe\u5f0f\uff0c\u5c31\u4f1a\u4f7f\u5f97\u71b5\u4e0d\u6ee1\u8db3\u5e7f\u5ef6\u6027\uff0c\u4ea7\u751f\u4e4b\u524d\u63d0\u5230\u7684\u5409\u5e03\u65af\u4f6f\u8c2c\uff0c\u56e0\u800c\u5fc5\u987b\u5c06\u7406\u60f3\u6c14\u4f53\u89c6\u4f5c\u975e\u5b9a\u57df\u7cfb\u7edf\uff0c\u4f7f\u7528\u975e\u5b9a\u57df\u4fee\u6b63\u7684\u71b5\u7684\u8868\u8fbe\u5f0f\uff0c\u4ece\u800c\u5f97\u5230\uff1a</p> \\[ S=\\frac{3}{2}NklnT+Nkln\\frac{V}{N}+\\frac{3}{2}Nk\\left[\\frac{5}{3}+ln\\left(\\frac{2\\pi mk}{h^2}\\right)\\right] \\] <p>\u6ce8\u610f\u7406\u60f3\u6c14\u4f53\u71b5\u7684\u8868\u8fbe\u5f0f\u4e2d\u542b\u6709\u666e\u6717\u514b\u5e38\u6570\\(h\\)\uff0c\u8bf4\u660e\u7406\u60f3\u6c14\u4f53\u5fc5\u5b9a\u6d89\u53ca\u91cf\u5b50\u529b\u5b66\u3002\u4e3a\u4e86\u9a8c\u8bc1\u5176\u6b63\u786e\u6027\uff0c\u53ef\u901a\u8fc7Sakur-Tetrode\u63cf\u8ff0\u9971\u548c\u84b8\u6c14\u538b\u516c\u5f0f\u3002\u901a\u8fc7\u5bf9\u7406\u60f3\u6c14\u4f53\u71b5\u7684\u6539\u5199\u4ee5\u53ca\u76f8\u53d8\u6f5c\u70ed\\(L\\)\u4e0d\u96be\u5bfc\u51fa\u6b64\u516c\u5f0f\uff1a</p> \\[ S_{vap}\\approx S_{vap}-S_{con}=\\frac{L}{T}\\quad\\Rightarrow\\quad lnp=-\\frac{L}{RT}+\\frac{5}{2}lnT+\\frac{5}{2}+ln\\left[k^{\\frac{5}{2}}\\left(\\frac{2\\pi m}{h^2}\\right)^{\\frac{3}{2}}\\right] \\] <p>\u5bf9\u4e8e\u6d89\u53ca\u5230\u81ea\u7531\u80fd\u7684\u5316\u5b66\u52bf\uff0c\u4e5f\u9700\u8981\u91c7\u7528\u975e\u5b9a\u57df\u4fee\u6b63\u7684\u5f62\u5f0f\u8fdb\u884c\u8ba1\u7b97\uff1a</p> \\[ \\mu=\\left(\\frac{\\partial F}{\\partial N}\\right)_{T,V}=-kTln\\left(\\frac{Z_1}{N}\\right)=-kTln(e^\\alpha)=-kT\\alpha\\Rightarrow\\boxed{\\alpha=-\\frac{\\mu}{kT}} \\] \\[ \\boxed{e^\\alpha=\\frac{Z_1}{N}=\\frac{V}{Nh^3}\\left(\\frac{2m\\pi}{\\beta}\\right)^{\\frac{3}{2}}}\\Rightarrow \\mu=kTln\\left[\\frac{Nh^3}{V}\\left(\\frac{\\beta}{2m\\pi}\\right)^{\\frac{3}{2}}\\right] \\] <p>\u2605 \u8fd9\u91cc\u5bf9\u975e\u7b80\u5e76\u6761\u4ef6\\(e^\\alpha\\gg1\\)\u8fdb\u884c\u8ba8\u8bba:</p> \\[ e^a=\\frac{V}{Nh^3}\\left(\\frac{2m\\pi}{\\beta}\\right)^{\\frac{3}{2}}=\\frac{V}{N}\\left(\\frac{2m\\pi kT}{h^2}\\right)^{\\frac{3}{2}}\\gg1 \\] <p>\u53ef\u89c1\u7406\u60f3\u6c14\u4f53\u7684\u5316\u5b66\u52bf\u4e3a\u8d1f\u503c\u3002\u6b64\u5916\uff0c\u8be5\u6761\u4ef6\u4e5f\u53ef\u7528\u5fb7\u5e03\u7f57\u610f\u70ed\u6ce2\u957f\\(\\lambda_T\\)\u5199\u4e3a\uff1a</p> \\[ \\lambda_T=\\frac{h}{\\sqrt{2\\pi mkT}}\\quad n=\\frac{N}{V}\\quad\\Rightarrow\\quad \\boxed{n\\lambda_T^3\\ll1} \\] <p>\u2605 \u57fa\u4e8e\u4ee5\u4e0a\u5e73\u52a8\u7684\u8ba8\u8bba\uff0c\u4e0b\u9762\u5bfc\u51faMaxwell\u901f\u5ea6\u5206\u5e03\u3002\u8003\u8651\u7406\u60f3\u6c14\u4f53\u5728\\(dv_xdv_ydv_z\\)\u8303\u56f4\u5185\u7684\u7c92\u5b50\u6570\uff1a</p> \\[ da_l=\\frac{Vdp_xdp_ydp_z}{h^3}e^{-\\alpha-\\beta\\varepsilon_l} \\] <p>\u6839\u636e\u603b\u7c92\u5b50\u6570\u4e3aN\u7684\u6761\u4ef6\uff0c\u53ef\u4ee5\u5f97\u5230\u4e0e\u4e4b\u524d\u81ea\u6d3d\u7684\\(e^{-\\alpha}\\):</p> \\[ \\int\\frac{Vdp_xdp_ydp_z}{h^3}e^{-\\alpha-\\beta\\varepsilon_l}=N\\quad\\Rightarrow\\quad e^{-\\alpha}=\\frac{N}{V}\\left(\\frac{h^2}{2\\pi mkT}\\right)^{\\frac{3}{2}} \\] <p>\u5229\u7528\\(dp_i=mdv_i\\)\u7684\u5173\u7cfb\u4ee3\u6362\uff0c\u6c42\u51fa\u4ee5\\(dv_xdv_ydv_z\\)\u4e3a\u53d8\u91cf\u7684\u7c92\u5b50\u6570\u8868\u8fbe\u5f0f\uff1a</p> \\[ da_l=N\\left(\\frac{m}{2\\pi kT}\\right)^{\\frac{3}{2}}e^{-\\frac{m}{2kT}(v_x^2+v_y^2+v_z^2)}dv_xdv_ydv_z=Nf(\\vec{v})dv_xdv_ydv_z \\] <p>\u4e0a\u5f0f\u5373\u5bfc\u51fa\u4e86Maxwell\u901f\u5ea6\u5206\u5e03\uff0c\u5bf9\u4e8e\u6b64\u5206\u5e03\u7684\u6b63\u786e\u6027\uff0c\u53ef\u7531\u591a\u666e\u52d2\u589e\u5bbd\u6548\u5e94\u6240\u9a8c\u8bc1\u3002\u6b64\u5916\uff0c\u7531\u4e8e\u4e4b\u524d\u7684\u7ae0\u8282\u5df2\u7ecf\u5bf9\u5206\u5e03\u901f\u5ea6\u8fdb\u884c\u4e86\u7814\u7a76\uff0c\u8fd9\u91cc\u4ec5\u5bf9\u6cfb\u6d41\u95ee\u9898\u8fdb\u884c\u7b80\u5355\u8ba8\u8bba\uff1a</p> \\[ \\Gamma_1=\\Gamma_2\\Rightarrow n_1\\bar{v_1}=n_2\\bar{v_2}\\Rightarrow \\frac{p_1}{\\sqrt{T_1}}=\\frac{p_2}{\\sqrt{T_2}} \\] <p>\u4e0a\u5f0f\u8003\u8651\u4e86\u5c0f\u5b54\u4e24\u8fb9\u7c92\u5b50\u8fbe\u5230\u5e73\u8861\u7684\u6761\u4ef6\\(\\Gamma_1=\\Gamma_2\\),\u518d\u901a\u8fc7\\(p=nkT\\)\u548c\\(T=\\frac{1}{3k}m\\bar{v^2}\\approx\\frac{1}{3k}m\\bar{v}^2\\)\u8fdb\u884c\u5316\u7b80,\u5f97\u5230\u538b\u5f3a\u548c\u6e29\u5ea6\u7684\u5173\u7cfb\u3002</p>"},{"location":"chapter_07_boltzmann_statistics/04_equipartition_blackbody.html","title":"\u5e7f\u4e49\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u4e0e\u9ed1\u4f53\u8f90\u5c04","text":""},{"location":"chapter_07_boltzmann_statistics/04_equipartition_blackbody.html#_1","title":"\u5e7f\u4e49\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u4e0e\u9ed1\u4f53\u8f90\u5c04","text":"<p>%\u5e7f\u4e49\u80fd\u91cf\u5747\u5206\u5b9a\u7406\uff0c\u5e94\u7528\uff1a\u745e\u5229\u91d1\u65af\u516c\u5f0f</p> <p>\u2605 \u8fd9\u91cc\u57fa\u4e8e\u5e73\u8861\u6001\u7684\u7ecf\u5178\u7cfb\u7edf\uff0c\u76f4\u63a5\u63a8\u5bfc\u5e7f\u4e49\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u3002\u8bbe\\(x_i,x_j\\)\u4e3a2r\u4e2a\u5e7f\u4e49\u5750\u6807\u4e2d\u7684\u4efb\u610f\u4e00\u9879\u3002\u5229\u7528\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u53ef\u5f97\uff1a</p> \\[ \\left \\langle x_i\\frac{\\partial \\varepsilon}{\\partial x_j} \\right \\rangle=\\frac{\\int x_i\\frac{\\partial \\varepsilon}{\\partial x_j} e^{-\\beta\\varepsilon(q,p)}d\\omega}{\\int e^{-\\beta\\varepsilon(q,p)}d\\omega}=\\frac{\\int x_i\\frac{\\partial \\varepsilon}{\\partial x_j} e^{-\\beta\\varepsilon(q,p)}dx_jd\\omega'}{\\int e^{-\\beta\\varepsilon(q,p)}d\\omega}=\\frac{kT\\delta_{ij}\\int e^{-\\beta\\varepsilon(q,p)}dx_jd\\omega'}{\\int e^{-\\beta\\varepsilon(q,p)}d\\omega} \\] \\[ \\Rightarrow\\boxed{\\left \\langle x_i\\frac{\\partial \\varepsilon}{\\partial x_j} \\right \\rangle =kT\\delta_{ij}} \\] <p>\u6ce8\u610f\uff0c\u63a8\u5bfc\u8fc7\u7a0b\u4e2d\u8fd0\u7528\u4e86\u5206\u90e8\u79ef\u5206\u7684\u6280\u5de7\u3002</p> <p>\u5728\u4f7f\u7528\u65f6\uff0c\u5e38\u89c1\u7684\u80fd\u91cf\u5177\u6709\\(\\varepsilon=ax_i^2\\)\u7684\u5f62\u5f0f\uff0c\u4ece\u800c\u6709\uff1a</p> \\[ \\left\\langle 2ax_i^2\\right\\rangle=kT\\quad\\Rightarrow\\quad\\left\\langle \\varepsilon\\right\\rangle=\\frac{1}{2}kT \\] <p>\u5373\u7c92\u5b50\u80fd\u91cf\u4e2d\u6bcf\u4e2a\u5e73\u65b9\u9879\u7684\u5e73\u5747\u503c\u7b49\u4e8e\\(\\frac{1}{2}kT\\).</p> <p>\u5982\u679c\u5c06\\(\\varepsilon\\)\u6539\u4e3a\\(H\\)\uff0c\u5982\u6cd5\u70ae\u5236\u53ef\u5f97\u5230\u5177\u6709\u76f8\u4e92\u4f5c\u7528\u7684\u5e7f\u4e49\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u3002\u518d\u5229\u7528\u54c8\u5bc6\u987f\u6b63\u5219\u65b9\u7a0b\uff0c\u53ef\u4ee5\u5f97\u5230\u975e\u5e38\u91cd\u8981\u7684\u4f4d\u529b\u5b9a\u7406\uff1a</p> \\[ \\boxed{\\left \\langle x_i\\frac{\\partial H}{\\partial x_j} \\right \\rangle =kT\\delta_{ij}}\\quad\\Rightarrow\\quad \\boxed{\\left \\langle \\sum_iq_iF_i \\right \\rangle=-3NkT} \\] <p>\u4f4d\u529b\u5b9a\u7406\u8868\u660e\u7cfb\u7edf\u5404\u4e2a\u81ea\u7531\u5ea6\u5750\u6807\\(q_i\\)\u4e0e\u5bf9\u8be5\u81ea\u7531\u5ea6\u7684\u4f5c\u7528\u529b\\(F_i\\)\u7684\u4e58\u79ef\u4e4b\u548c\u4e3a\\(-3NkT\\),\u5e76\u4e14\\(\\left \\langle \\sum_iq_iF_i \\right \\rangle\\)\u88ab\u79f0\u4e3a\u4f4d\u529b\u3002</p> <p>\u2605 \u80fd\u91cf\u5747\u5206\u5b9a\u7406\u5bf9\u7ecf\u5178\u7cfb\u7edf\u57fa\u672c\u662f\u9002\u7528\u7684\uff0c\u4f46\u5f53\u53bb\u7814\u7a76\u91cf\u5b50\u7cfb\u7edf\u65f6\u5374\u4f1a\u51fa\u73b0\u5927\u95ee\u9898\uff0c\u9ed1\u4f53\u8f90\u5c04\u4fbf\u662f\u4e00\u4e2a\u5f88\u597d\u7684\u4f8b\u8bc1\u3002</p> <p>\u8f90\u5c04\u7684\u672c\u8d28\u5c31\u662f\u7535\u78c1\u6ce2\u7684\u53d1\u5c04\uff0c\u5176\u6240\u4ea7\u751f\u7684\u6548\u5e94\u901a\u5e38\u662f\u4e0d\u540c\u7535\u78c1\u6ce2\u7684\u7edf\u8ba1\u5e73\u5747\u7684\u7efc\u5408\u6548\u679c\u3002\u5bf9\u4e8e\u7535\u78c1\u6ce2\uff0c\u4e00\u822c\u6709\u4e24\u79cd\u89c2\u70b9\u3002\u4e00\u79cd\u662f\u4ee5\u7535\u78c1\u573a\u6ce2\u52a8\u7684\u89c2\u70b9\u6765\u770b\u5f85\uff0c\u5373\u7528Maxwell\u65b9\u7a0b\u7ec4\u6765\u63cf\u8ff0\uff0c\u4e5f\u662f\u672c\u8282\u91c7\u7528\u7684\u89c2\u70b9\uff1b\u53e6\u4e00\u79cd\u662f\u4ee5\u7c92\u5b50\u7684\u89c2\u70b9\uff0c\u5c06\u5149\u770b\u6210\u5149\u5b50\u7ec4\u6210\u7684\u201c\u7406\u60f3\u6c14\u4f53\u201d\uff0c\u8fd9\u5c06\u5728\u73bb\u8272\u7edf\u8ba1\u90e8\u5206\u5c55\u5f00\u3002\u4e00\u8bf4\uff0c\u5bf9\u4e8e\u540c\u4e00\u9891\u7387\u7684\u7535\u78c1\u6ce2\uff0c\u7531\u4e8e\u632f\u5e45\u4e0d\u540c\u4ece\u800c\u53ef\u4ee5\u5206\u8fa8\uff1b\u4f46\u4ece\u7c92\u5b50\u7684\u89d2\u5ea6\u770b\uff0c\u632f\u5e45\u7684\u53d8\u5316\u4ec5\u4ec5\u662f\u5168\u540c\u5149\u5b50\u4e2a\u6570\u7684\u4e0d\u540c\uff0c\u6545\u4e0d\u53ef\u5206\u8fa8\u3002\u4e8b\u5b9e\u4e0a\uff0c\u7535\u78c1\u6ce2\u4f5c\u4e3a\u7ecf\u5178\u7684\u6ce2\uff0c\u5c5e\u4e8e\u7ecf\u5178\u7cfb\u7edf\uff0c\u80af\u5b9a\u662f\u53ef\u5206\u8fa8\u7684\u3002\u4e3a\u4e86\u6570\u5b66\u4e0a\u7684\u65b9\u4fbf\uff0c\u8fd9\u91cc\u5047\u8bbe\u5bb9\u5668\u4e3a\u8fb9\u957f\u4e3aL\u7684\u7acb\u65b9\u4f53\uff0c\u5e76\u91c7\u7528\u5468\u671f\u6027\u8fb9\u754c\u6761\u4ef6\u3002</p> <p>\u9996\u5148\u5c06\u8f90\u5c04\u573a\u770b\u4f5c\u65e0\u7a77\u591a\u5355\u8272\u5e73\u9762\u6ce2\u7684\u53e0\u52a0\uff0c\u6839\u636e\u5468\u671f\u6027\u8fb9\u754c\u6761\u4ef6\uff1a</p> \\[ k_i=\\frac{2\\pi}{L}n_i\\qquad(i=x,y,z\\quad n_i=\\pm1,\\pm2,...) \\] <p>\u8003\u5bdf\u6ce2\u77e2\u5927\u5c0f\u5728\\(k\\sim k+dk\\)\u8303\u56f4\u5185\u5355\u8272\u5e73\u9762\u6ce2\u7684\u4e2a\u6570\\(dn\\)\uff1a</p> \\[ dn=dn_xdn_ydn_z=\\left(\\frac{L}{2\\pi}\\right)^3dk_xdk_ydk_z=4\\pi k^2\\left(\\frac{L}{2\\pi}\\right)^3dk \\] <p>\u7531\u4e8e\u7535\u78c1\u6ce2\u4e3a\u6a2a\u6ce2\uff0c\u56e0\u800c\u8fd8\u8981\u8003\u8651\u504f\u632f\u5e26\u6765\u7684\u989d\u5916\u81ea\u7531\u5ea6,\u6240\u4ee5\u5355\u8272\u5e73\u9762\u6ce2\u4e2a\u6570\u5e94\u8be5\u4e3a\\(2dn\\).\u6709\u4e86\u7535\u78c1\u6ce2\u4e2a\u6570\u7684\u5206\u5e03\uff0c\u4e0b\u9762\u5c31\u8981\u6c42\u51fa\u6bcf\u4e2a\u6ce2\u7684\u80fd\u91cf\uff0c\u76f8\u4e58\u5373\u53ef\u5f97\u51fa\u8c31\u5bc6\u5ea6\u3002\u6839\u636e\u7535\u78c1\u6ce2\u7684\u80fd\u91cf\u548c\u80fd\u91cf\u5747\u5206\u5b9a\u7406\uff1a</p> \\[ \\left\\langle \\varepsilon \\right\\rangle=\\left\\langle \\frac{1}{2}\\varepsilon_0 E^2+\\frac{1}{2}\\mu_0H^2 \\right\\rangle=kT \\] <p>\u6700\u540e\u5c06\\(dk\\)\u5229\u7528\u8272\u6563\u5173\u7cfb\\(\\omega=ck\\)\u6362\u4e3a\\(d\\omega\\)\uff0c\u5373\u53ef\u5f97\u5230\u80fd\u91cf\u5206\u5e03\\(U(\\omega)d\\omega\\)\uff1a</p> \\[ \\qquad Ud\\omega=\\left\\langle \\varepsilon \\right\\rangle 2dn=\\boxed{kT\\frac{L^3\\omega^2}{c^3\\pi^2}d\\omega} \\] <p>\u4e0a\u5f0f\u5373\u745e\u5229-\u91d1\u65af\u516c\u5f0f\uff0c\u867d\u7136\u5b83\u5728\u4f4e\u9891\u533a\u4e0e\u5b9e\u9a8c\u7ed3\u679c\u7b26\u5408\u7684\u975e\u5e38\u597d\uff0c\u4f46\u663e\u7136\u5bf9\u9891\u7387\u79ef\u5206\u4f1a\u53d1\u73b0\u603b\u7684\u80fd\u91cf\u4f1a\u53d1\u6563\u5230\u65e0\u7a77\u5927\uff0c\u5e76\u4e0d\u7b26\u5408\\(aT^4\\)\uff0c\u8fd9\u4fbf\u662f\u7d2b\u5916\u707e\u96be\u3002</p> <p>\u95ee\u9898\u51fa\u5728\u5747\u5206\u5b9a\u7406\u4e0a\uff1a\u666e\u6717\u514b\u5047\u8bbe\u7535\u78c1\u6ce2\u7684\u80fd\u91cf\u4e3a\\(\\varepsilon=n\\hbar\\omega\\),\u4ece\u800c\uff1a</p> \\[ Z_1=\\sum_{n=0}^{\\infty}e^{-\\frac{n\\hbar\\omega}{kT}}=\\frac{e^{\\frac{\\hbar\\omega}{kT}}}{e^{\\frac{\\hbar\\omega}{kT}}-1}\\quad\\Rightarrow\\quad \\left\\langle \\varepsilon \\right\\rangle=\\frac{\\hbar\\omega}{e^{\\frac{\\hbar\\omega}{kT}}-1} \\] <p>\u4ece\u800c\u5f97\u5230\u80fd\u91cf\u5206\u5e03\u4e3a\uff1a</p> \\[ Ud\\omega=\\frac{\\hbar\\omega}{e^{\\frac{\\hbar\\omega}{kT}}-1}\\frac{L^3\\omega^2}{c^3\\pi^2}d\\omega=\\boxed{\\frac{L^3}{c^3\\pi^2}\\frac{\\hbar\\omega^3}{e^{\\frac{\\hbar\\omega}{kT}}-1}d\\omega} \\] <p>\u5bf9\u5176\u9891\u7387\u8fdb\u884c\u79ef\u5206\u6709\uff1a</p> \\[ \\int_0^\\infty Ud\\omega=\\frac{k^4\\pi^2L^3}{15c^3\\hbar^3}T^4\\Rightarrow u=\\frac{k^4\\pi^2}{15c^3\\hbar^3}T^4\\Rightarrow \\boxed{a=\\frac{k^4\\pi^2}{15c^3\\hbar^3}}\\Rightarrow\\boxed{\\sigma=\\frac{k^4\\pi^2}{60c^2\\hbar^3}} \\] <p>\u663e\u7136\u666e\u6717\u514b\u7684\u5047\u8bbe\u4e0d\u4ec5\u89e3\u51b3\u4e86\u7d2b\u5916\u707e\u96be\uff0c\u8fd8\u5b9a\u91cf\u8ba1\u7b97\u51fa\u70ed\u529b\u5b66\u4e2d\u65e0\u6cd5\u8ba1\u7b97\u7684\u5f85\u5b9a\u7cfb\u6570\uff0c\u66f4\u662f\u63a8\u52a8\u4e86\u91cf\u5b50\u529b\u5b66\u7684\u53d1\u5c55\u3002</p>"},{"location":"chapter_07_boltzmann_statistics/05_ideal_gas_thermo.html","title":"\u7406\u60f3\u6c14\u4f53\u7684\u70ed\u529b\u5b66\u91cf","text":""},{"location":"chapter_07_boltzmann_statistics/05_ideal_gas_thermo.html#_1","title":"\u7406\u60f3\u6c14\u4f53\u7684\u70ed\u529b\u5b66\u91cf","text":"<p>\u2605 \u4e4b\u524d\u7684\u8ba8\u8bba\u662f\u5c06\u7406\u60f3\u6c14\u4f53\u89c6\u4e3a\u8d28\u70b9\uff0c\u4ec5\u8003\u8651\u4e86\u5e73\u52a8\u5bf9\u70ed\u529b\u5b66\u91cf\u7684\u8d21\u732e\u3002\u4e25\u683c\u6765\u8bf4\uff0c\u7ec4\u6210\u7406\u60f3\u6c14\u4f53\u7684\u7c92\u5b50\u4e0d\u4ec5\u5177\u6709\u5e73\u52a8\uff0c\u8fd8\u6709\u8f6c\u52a8\u3001\u632f\u52a8\u3001\u7535\u5b50\u8fd0\u52a8\u7b49\u3002\u4ece\u5b8c\u5168\u7ecf\u5178\u7684\u89d2\u5ea6\u800c\u8a00\uff0c\u53ef\u4ee5\u5199\u51fa\u7c92\u5b50\u603b\u80fd\u91cf\u7684\u7ecf\u5178\u8868\u8fbe\u5f0f\uff0c\u5229\u7528\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u5f97\u5230\u5185\u80fd\u548c\u70ed\u5bb9\uff0c\u5f53\u7136\uff0c\u8fd9\u4e00\u70b9\u4e5f\u53ef\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u5b9e\u73b0\u3002</p> <p>\u4e0b\u9762\u5206\u522b\u5199\u51fa\u7ecf\u5178\u7cfb\u7edf\u4e2d\u7684\u5e73\u52a8\u52a8\u80fd\u3001\u8f6c\u52a8\u52a8\u80fd\u3001\u632f\u52a8\u52a8\u80fd\uff1a</p> \\[ \\varepsilon^t=\\frac{1}{2m}(p_x^2+p_y^2+p_z^2)\\quad\\varepsilon^r=\\frac{1}{2I}\\left(p_\\theta^2+\\frac{p_\\phi^2}{sin(\\theta)^2}\\right)\\quad\\varepsilon^v=\\frac{1}{2m}(p^2_r+m^2\\omega^2r^2) \\] <p>\u5bf9\u4e8e\u5355\u539f\u5b50\u5206\u5b50\uff0c\u53ea\u9700\u8003\u8651\u5e73\u52a8\u5373\u53ef\u3002\u7531\u4e8e\u5e73\u52a8\u5171\u67093\u4e2a\u5e73\u65b9\u9879\uff0c\u6240\u4ee5\u5f97\u5230\u548c\u4e4b\u524d\u4e00\u6837\u7684\u5185\u80fd\u548c\u70ed\u5bb9\uff1a</p> \\[ U=\\frac{3}{2}NkT\\qquad C_V=\\frac{3}{2}Nk \\] <p>\u5bf9\u4e8e\u521a\u6027\u5f02\u6838\u53cc\u539f\u5b50\u5206\u5b50\uff0c\u9700\u8981\u8003\u8651\u5e73\u52a8\u548c\u8f6c\u52a8\u3002\u5e73\u52a8\u548c\u8f6c\u52a8\u5171\u67095\u4e2a\u5e73\u65b9\u9879\uff0c\u6240\u4ee5\u5185\u80fd\u548c\u70ed\u5bb9\u5982\u4e0b\uff1a</p> \\[ U=\\frac{5}{2}NkT\\qquad C_V=\\frac{5}{2}Nk \\] <p>\u5bf9\u4e8e\u7b80\u8c10\u632f\u52a8\u7684\u5f02\u6838\u53cc\u539f\u5b50\u5206\u5b50\uff0c\u8fd8\u8981\u8003\u8651\u632f\u52a8\uff0c\u4ece\u800c\u67097\u4e2a\u5e73\u65b9\u9879\uff1a</p> \\[ U=\\frac{7}{2}NkT\\qquad C_V=\\frac{7}{2}Nk \\] <p>\u5bf9\u4e8e\u540c\u6838\u53cc\u539f\u5b50\u5206\u5b50\uff0c\u9700\u8981\u8003\u8651\u91cf\u5b50\u6548\u5e94\uff0c\u4e4b\u540e\u4f1a\u8be6\u7ec6\u8ba8\u8bba\u3002\u5bf9\u4e8e\u521a\u6027\u591a\u539f\u5b50\u5206\u5b50\uff0c\u76f8\u5f53\u4e8e\u4e00\u822c\u521a\u4f53\uff0c\u5177\u67096\u4e2a\u5e73\u65b9\u9879\uff0c\u4ece\u800c\\(U=3NkT,C_V=3Nk\\).\u6b64\u5916\uff0c\u5982\u679c\u5229\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\uff0c\u8fd8\u53ef\u6c42\u51fa\u71b5\u7b49\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\uff0c\u5177\u4f53\u8fc7\u7a0b\u8fd9\u91cc\u7565\u53bb\u3002\u4f46\u8981\u6ce8\u610f\u4e00\u70b9:\u975e\u5b9a\u57df\u4fee\u6b63\u9879\\(N!\\)\u5728\u5e73\u52a8\u71b5\u4e2d\u5df2\u7ecf\u51fa\u73b0\u8fc7\u4e00\u6b21\u4e86\uff0c\u56e0\u800c\u8f6c\u52a8\u3001\u632f\u52a8\u7b49\u5747\u4e0d\u7528\u8003\u8651\u6b64\u9879\uff1b\u6216\u8005\u76f4\u63a5\u5c06\\(Z_1=Z_1^tZ_1^rZ_1^v\\)\u4ee3\u5165\u4fee\u6b63\u7684\u71b5\u7684\u8868\u8fbe\u5f0f\u5373\u53ef\u3002</p> <p>\u2605 \u4e0b\u9762\u4ece\u91cf\u5b50\u529b\u5b66\u7684\u89d2\u5ea6\u5168\u9762\u5730\u8003\u5bdf\u53cc\u539f\u5b50\u5206\u5b50\u7684\u5185\u80fd\u548c\u70ed\u5bb9\u3002\u4e00\u65b9\u9762\uff0c\u4e3a\u4e86\u5168\u9762\u7684\u5206\u6790\u7c92\u5b50\u7684\u8fd0\u52a8\uff0c\u9664\u4e86\u4e0a\u8ff0\u7684\u5e73\u52a8\u3001\u8f6c\u52a8\u3001\u632f\u52a8\u8fd8\u8981\u8003\u8651\u7535\u5b50\u7684\u8fd0\u52a8\u4e0e\u6838\u7684\u8fd0\u52a8\uff0c\u56e0\u800c\u5b8c\u6574\u7684\u80fd\u91cf\u5e94\u8be5\u5199\u4e3a\uff1a</p> \\[ \\varepsilon=\\varepsilon^t+\\varepsilon^r+\\varepsilon^v+\\varepsilon^e+\\varepsilon^n \\] <p>\u4f46\u53e6\u4e00\u65b9\u9762\uff0c\u7531\u4e8e\u70ed\u8fd0\u52a8\u96be\u4ee5\u4f7f\u5f97\u7535\u5b50\u548c\u6838\u8dc3\u8fc1\u5230\u6fc0\u53d1\u6001\uff0c\u56e0\u6b64\u7535\u5b50\u548c\u6838\u88ab\u51bb\u7ed3\u5728\u57fa\u6001\u800c\u4e0d\u4ea7\u751f\u8d21\u732e\uff0c\u4ece\u800c\u4ec5\u8003\u8651\u524d\u4e09\u9879\u7684\u8d21\u732e\u3002\u6b64\u5916\uff0c\u4e3a\u4e86\u6570\u5b66\u5f62\u5f0f\u4e0a\u7684\u7b80\u5355\uff0c\u901a\u5e38\u6839\u636e\u6240\u5b9a\u4e49\u7684\u7279\u5f81\u6e29\u5ea6\\(\\theta\\)\u4e0e\u70ed\u529b\u5b66\u6e29\u5ea6\\(T\\)\u8fdb\u884c\u6bd4\u8f83\uff0c\u636e\u6b64\u5bf9\u7ed3\u679c\u8fdb\u884c\u8fd1\u4f3c\u6c42\u89e3\uff0c\u4f8b\u5982\u6c42\u548c\u8fd1\u4f3c\u4e3a\u79ef\u5206\u3001\u53d6\u6781\u9650\u7b49\u3002</p> <p>\u7efc\u4e0a\uff0c\u4e3a\u4e86\u6293\u4f4f\u4e3b\u8981\u77db\u76fe\u5e76\u4e14\u907f\u514d\u5e73\u52a8\u63a8\u5bfc\u7684\u91cd\u590d\uff0c\u4ec5\u8003\u8651\u8f6c\u52a8\u548c\u632f\u52a8\uff1a</p> <p>(1)\u8f6c\u52a8\uff1a\u6839\u636e\u91cf\u5b50\u529b\u5b66\u5bf9\u89d2\u52a8\u91cf\u7684\u91cf\u5b50\u5316\uff0c\u5206\u5b50\u8f6c\u52a8\u80fd\u91cf\u4e3a</p> \\[ \\varepsilon^r=\\frac{L^2}{2I}=\\frac{l(l+1)\\hbar^2}{2I}\\quad(l=0,1,2,...) \\] <p>\u82e5\u4e3a\u5f02\u6838\u53cc\u539f\u5b50\u5206\u5b50\uff0c\u5219\\(l\\)\u6309\u4e0a\u8ff0\u53d6\u503c\u5373\u53ef\uff0c\u4f46\u5bf9\u4e8e\u540c\u6838\u53cc\u539f\u5b50\u5206\u5b50\uff0c\u5219\\(l\\)\u7684\u5947\u5076\u6027\u9700\u8981\u53d7\u5230\u9650\u5236\uff0c\u56e0\u800c\u5148\u8ba8\u8bba\u7b80\u5355\u7684\u5f02\u6838\u53cc\u539f\u5b50\u5206\u5b50\uff1a</p> \\[ Z_1^r=\\sum_{l=0}^\\infty (2l+1)e^{-\\frac{l(l+1)\\hbar^2}{2IkT}}=\\sum_{l=0}^\\infty (2l+1)e^{-\\frac{\\theta_r}{T}l(l+1)} \\] <p>\u6ce8\u610f\uff0c\u4e0a\u5f0f\u8003\u8651\u5230\u4e86\u7b80\u5e76\u5ea6\\(2l+1\\)\u5e76\u4e14\u5f15\u5165\u4e86\u8f6c\u52a8\u7279\u5f81\u6e29\u5ea6\\(\\theta_r=\\frac{\\hbar^2}{2Ik}\\).\u6839\u636e\u5206\u5b50\u5149\u8c31\u6d4b\u5b9a\uff0c\u5e38\u6e29\u4e0b\\(\\theta_r\\ll T\\),\u4ece\u800c\u80fd\u7ea7\u53ef\u4ee5\u770b\u4f5c\u51c6\u8fde\u7eed\uff0c\u5229\u7528\u79ef\u5206\u8fdb\u884c\u8fd1\u4f3c\uff1a</p> \\[ x=l(l+1)\\frac{\\theta_r}{T}\\quad dx=(2l+1)\\frac{\\theta_r}{T}dl\\quad\\Rightarrow\\quad Z_1=\\frac{T}{\\theta_r}\\int_0^\\infty e^{-x} dx=\\frac{2I}{\\beta\\hbar^2} \\] <p>\u6ce8\u610f\\(l\\)\u53d6\u503c\u7684\u95f4\u9694\u4e3a1\uff0c\u4ece\u800c\\(dl=1\\).\u7531\u6b64\u5f97\u5230\u5185\u80fd\u548c\u70ed\u5bb9\uff1a</p> \\[ U^r=-N\\frac{\\partial}{\\partial\\beta}ln(Z_1)=NkT\\qquad C_V=Nk \\] <p>\u8fd9\u4e0e\u4e4b\u524d\u80fd\u91cf\u5747\u5206\u5b9a\u7406\u7684\u7ed3\u679c\u4e00\u81f4\uff0c\u8fd9\u662f\u56e0\u4e3a\u5e38\u6e29\u8303\u56f4\u5185\u8f6c\u52a8\u80fd\u7ea7\u95f4\u8ddd\u8fdc\u5c0f\u4e8e\\(kT\\).\u4e0b\u9762\u5bf9\u540c\u6838\u53cc\u539f\u5b50\u5206\u5b50\u8fdb\u884c\u8ba8\u8bba\uff0c\u8fd9\u91cc\u4ee5\\(H_2\\)\u4e3a\u4f8b\u3002</p> <p>\\(H_2\\)\u6709\u4e24\u79cd\u8f6c\u52a8\u72b6\u6001\uff0c\u4e00\u79cd\u662f\u4e24\u4e2a\u6c22\u539f\u5b50\u81ea\u65cb\u65b9\u5411\u76f8\u540c\uff0c\u603b\u81ea\u65cb\u6570\u4e3a\\(s=1\\),\u4ece\u800c\u5177\u6709\u201c\u4e09\u91cd\u6001\u201d\uff0c\u901a\u5e38\u5360\u6bd4\\(\\frac{3}{4}\\),\u79f0\u4e3a\u6b63\u6c22;\u53e6\u4e00\u79cd\u662f\u81ea\u65cb\u65b9\u5411\u76f8\u53cd\uff0c\u603b\u81ea\u65cb\u6570\u4e3a\\(s=0\\),\u4e3a\u201c\u5355\u6001\u201d\uff0c\u901a\u5e38\u5360\u6bd4\\(\\frac{1}{4}\\)\uff0c\u79f0\u4e3a\u4ef2\u6c22\u3002\u4ece\u800c\u6c22\u6c14\u5373\u53ef\u770b\u4f5c\u662f\u6b63\u6c22\u548c\u4ef2\u6c22\u7684\u6df7\u5408\u7269\u3002</p> <p>\u7531\u4e8e\u5168\u540c\u8d39\u7c73\u7cfb\u7edf\u5bf9\u6ce2\u51fd\u6570\u53cd\u5bf9\u79f0\u6027\u7684\u8981\u6c42\uff0c\u4f7f\u5f97\u6c42\u548c\u5947\u5076\u6027\u4e0d\u540c:</p> \\[ \\psi_{l,s=1}=\\chi_1\\cdot Y_{l,m}\\quad(l=1,3,5,...)\\qquad\\psi_{l,s=0}=\\chi_0\\cdot Y_{l,m}\\quad(l=0,2,4,...) \\] <p>\u6ce8\u610f\\(\\chi_1\\)\u8868\u793a\u81ea\u65cb\u76f8\u540c\u7684\u5bf9\u79f0\u6ce2\u51fd\u6570;\\(\\chi_0\\)\u8868\u793a\u81ea\u65cb\u76f8\u53cd\u7684\u53cd\u5bf9\u79f0\u6ce2\u51fd\u6570,\u7403\u8c10\u51fd\u6570\\(Y_{l,m}\\)\u662f\u5206\u5b50\u6574\u4f53\u7684\u8f6c\u52a8\u6ce2\u51fd\u6570\uff0c\u5176\u5bf9\u79f0\u6027\u53ef\u770b\u4f5c\u662f\\(Y_{l,m}\\)\u7684\u5b87\u79f0\u3002\u6545\uff1a</p> \\[ \\Rightarrow Z_{1o}^r=\\sum_{l=1,3,5,...}(2l+1)e^{-\\frac{\\theta_r}{T}l(l+1)}\\qquad Z_{1p}^r=\\sum_{l=0,2,4,...}(2l+1)e^{-\\frac{\\theta_r}{T}l(l+1)} \\] <p>\u4ece\u800c\u5bf9\u4e24\u79cd\u914d\u5206\u51fd\u6570\u6309\\(3:1\\)\u7684\u6bd4\u4f8b\u8fdb\u884c\u52a0\u6743\u5e73\u5747\uff0c\u53ef\u6c42\u51fa\u5185\u80fd\u548c\u70ed\u5bb9\u3002\u7136\u800c\uff0c\u8003\u8651\u5230\u8f6c\u52a8\u7279\u5f81\u6e29\u5ea6\\(\\theta_r\\)\u4e3a85K\u5de6\u53f3\uff0c\u6545\u5e38\u6e29\u4e0b\u6709\\(\\theta_r\\ll T\\),\u4ece\u800c\u8fd1\u4f3c\u4e3a\u4e24\u79cd\u6c22\u5bf9\u5185\u80fd\u548c\u70ed\u5bb9\u7684\u8d21\u732e\u6ca1\u6709\u5dee\u5f02\uff0c\u53c8\u56de\u5230\u4e86\u7ecf\u5178\u7684\u7ed3\u679c\u3002\u4f46\u5728\u4f4e\u6e29\u65f6\uff0c\u5fc5\u987b\u4e25\u683c\u6309\u7167\u4e0a\u8ff0\u65b9\u6cd5\u6c42\u51fa\u7ea7\u6570\u548c\uff0c\u624d\u80fd\u4e0e\u5b9e\u9a8c\u7ed3\u679c\u76f8\u7b26\u3002</p> <p>(2)\u632f\u52a8\uff1a\u4e24\u539f\u5b50\u4e4b\u95f4\u53ef\u4ee5\u770b\u4f5c\u7ebf\u6027\u8c10\u632f\u5b50\uff0c\u4ece\u800c\u6839\u636e\u91cf\u5b50\u529b\u5b66\uff1a</p> \\[ \\varepsilon^v=\\left(n+\\frac{1}{2}\\right)\\hbar\\omega\\quad(n=0,1,2,...)\\quad\\Rightarrow\\quad Z_1^v=\\sum_{n=0}^{\\infty}e^{-\\beta\\varepsilon^v}=\\frac{e^{-\\frac{\\beta\\hbar\\omega}{2}}}{1-e^{-\\beta\\hbar\\omega}} \\] <p>\u7531\u6b64\u5f97\u5230\u5185\u80fd\u548c\u70ed\u5bb9\uff1a</p> \\[ U=-N\\frac{\\partial}{\\partial\\beta}ln(Z_1)=N\\frac{\\hbar\\omega}{2}+\\frac{N\\hbar\\omega}{e^{\\beta\\hbar\\omega}-1}\\qquad C_V=Nk\\left(\\frac{\\hbar\\omega}{kT}\\right)^2\\frac{e^{\\frac{\\hbar\\omega}{kT}}}{(e^{\\frac{\\hbar\\omega}{kT}}-1)^2} \\] <p>\u5f15\u5165\u7279\u5f81\u6e29\u5ea6\\(\\theta_v=\\frac{\\hbar\\omega}{k}\\),\u6839\u636e\u5206\u5b50\u5149\u8c31\u6d4b\u5f97\u5e38\u6e29\u4e0b\\(\\theta_v\\gg T\\).\u4ece\u800c\u4e0e\u7535\u5b50\u8fd0\u52a8\u7684\u80fd\u7ea7\u7c7b\u4f3c\uff0c\u5bf9\u70ed\u5bb9\u7684\u8d21\u732e\u51e0\u4e4e\u4e3a0.\u4f46\u5728\u9ad8\u6e29\u4e0b\uff0c\u82e5\u6ee1\u8db3\\(\\theta_v\\ll T\\),\u5219\u70ed\u5bb9\u4e3a\\(C_V\\rightarrow Nk\\),\u4e0e\u7ecf\u5178\u7ed3\u679c\u4e00\u81f4\u3002</p> <p>\u2605 \u53ef\u4ee5\u770b\u5230\uff0c\u5229\u7528\u91cf\u5b50\u529b\u5b66\u5f97\u51fa\u7684\u7ed3\u679c\u548c\u4e4b\u524d\u5747\u5206\u5b9a\u7406\u7684\u7ed3\u679c\u51e0\u4e4e\u6ca1\u6709\u533a\u522b\u3002\u8fd9\u4e3b\u8981\u6765\u6e90\u4e8e\u7279\u5f81\u6e29\u5ea6\u6570\u91cf\u7ea7\u5e26\u6765\u7684\u8fd1\u4f3c\u3002\u901a\u5e38\u6765\u8bf4\u6570\u91cf\u7ea7\u5173\u7cfb\u5982\u4e0b\uff1a</p> \\[ \\theta_n\\gg\\theta_e\\gg\\theta_v\\ge kT\\ge\\theta_r \\] <p>\u4e0a\u5f0f\u8868\u660e\uff0c\u6838\u80fd\u7ea7\u548c\u7535\u5b50\u80fd\u7ea7\u7531\u4e8e\u95f4\u8ddd\u8fc7\u5927\uff0c\u5728\u4e00\u822c\u7684\u6e29\u5ea6\u4e0b\u5904\u4e8e\u51bb\u7ed3\u72b6\u6001\uff0c\u6ca1\u6709\u8d21\u732e\u3002\u5bf9\u4e8e\u5927\u90e8\u5206\u7684\u632f\u52a8\u80fd\u7ea7\u4e5f\u6709\u8fd9\u6837\u7684\u60c5\u51b5\uff0c\u4f46\u5728\u9ad8\u6e29\u4e0b\uff0c\u53c8\u4f1a\u548c\u6e29\u5ea6\u76f8\u5339\u914d\uff0c\u4ece\u800c\u9700\u8981\u8003\u8651\u632f\u52a8\u5e26\u6765\u7684\u5f71\u54cd\u3002\u5bf9\u4e8e\u8f6c\u52a8\u80fd\u7ea7\uff0c\u53c8\u662f\u53e6\u4e00\u4e2a\u6781\u7aef\uff0c\u901a\u5e38\u80fd\u7ea7\u95f4\u8ddd\u8fc7\u5c0f\uff0c\u4ee5\u81f3\u4e8e\u8fde\u7eed\uff0c\u4ece\u800c\u53ef\u4ee5\u8fd1\u4f3c\u4e3a\u7ecf\u5178\u5206\u5e03\uff0c\u4f46\u5728\u4f4e\u6e29\u4e0b\uff0c\u53ef\u80fd\u4e0e\u6e29\u5ea6\u76f8\u5339\u914d\uff0c\u4ece\u800c\u5fc5\u987b\u5f97\u6c42\u51fa\u7ea7\u6570\u7684\u548c\u3002</p> <p>\u7528\u91cf\u5b50\u529b\u5b66\u6765\u7814\u7a76\u5206\u5b50\u8fd0\u52a8\uff0c\u8fdb\u800c\u5bfc\u51fa\u70ed\u529b\u5b66\u6027\u8d28\u662f\u6709\u4e00\u5b9a\u96be\u5ea6\u7684\uff0c\u8fd9\u91cc\u4e5f\u4ec5\u7c97\u7565\u5730\u8ba8\u8bba\u4e86\u53cc\u539f\u5b50\u5206\u5b50\u7684\u5185\u80fd\u548c\u70ed\u5bb9\uff0c\u66f4\u591a\u7684\u7ec6\u8282\u6d89\u53ca\u5230\u5206\u5b50\u5149\u8c31\u5b66\u3002</p>"},{"location":"chapter_07_boltzmann_statistics/06_solid_heat_capacity.html","title":"\u56fa\u4f53\u70ed\u5bb9\u7406\u8bba","text":""},{"location":"chapter_07_boltzmann_statistics/06_solid_heat_capacity.html#_1","title":"\u56fa\u4f53\u70ed\u5bb9\u7406\u8bba","text":"<p>\u2605 \u4e0e\u975e\u5b9a\u57df\u7684\u7406\u60f3\u6c14\u4f53\u4e0d\u540c\uff0c\u56fa\u4f53\u4e2d\u7684\u7c92\u5b50\u7531\u4e8e\u76f8\u4e92\u4f5c\u7528\u5f62\u6210\u4e86\u7a33\u5b9a\u7684\u7ed3\u6784\uff0c\u4ece\u800c\u53ef\u4ee5\u901a\u8fc7\u4f4d\u7f6e\u5c06\u7c92\u5b50\u5206\u8fa8\uff0c\u56e0\u800c\u56fa\u4f53\u901a\u5e38\u88ab\u89c6\u4f5c\u5b9a\u57df\u7cfb\u7edf\u3002</p> <p>\u6839\u636e\u80fd\u91cf\u5747\u5206\u5b9a\u7406\uff0c\u7c92\u5b50\u7684\u80fd\u91cf\u8868\u8fbe\u5f0f\u76f8\u5f53\u4e8e3\u4e2a\u632f\u5b50\uff0c\u5177\u67096\u4e2a\u5e73\u65b9\u9879\uff0c\u4ece\u800c\u56fa\u4f53\u70ed\u5bb9\\(C_V=3Nk\\).\u7136\u800c\uff0c\u5b9e\u9a8c\u4e0a\u6d4b\u5f97\u7684\u5927\u90e8\u5206\u56fa\u4f53\u4ec5\u5728\u9ad8\u6e29\u4e0b\u6ee1\u8db3\u6b64\u5f0f\uff0c\u5728\u4f4e\u6e29\u60c5\u51b5\u4e0b\u5c06\u8d8b\u5411\u4e8e0.\u5f53\u7136\uff0c\u8fd9\u4e5f\u662f\u70ed\u4e09\u7684\u5fc5\u7136\u7ed3\u679c.</p> <p>\u4e3a\u4e86\u8c03\u548c\u4e0a\u9762\u7684\u77db\u76fe\uff0cEinstein\u5c06\u56fa\u4f53\u7c92\u5b50\u7684\u6bcf\u4e2a\u632f\u5b50\u770b\u4f5c\u662f\u91cf\u5b50\u529b\u5b66\u4e2d\u7684\u4e00\u7ef4\u8c10\u632f\u5b50\uff0c\u5e76\u5047\u8bbe\u5176\u9891\u7387\u5747\u4e3a\\(\\omega\\),\u4ece\u800c\u5f97\u5230\u7c92\u5b50\u914d\u5206\u51fd\u6570\uff1a</p> \\[ \\varepsilon_n=\\left(n+\\frac{1}{2}\\right)\\hbar\\omega\\quad(n=0,1,2,...)\\quad\\Rightarrow\\quad Z_1=\\sum_{n=0}^{\\infty}e^{-\\beta\\varepsilon_n}=\\frac{e^{-\\frac{\\beta\\hbar\\omega}{2}}}{1-e^{-\\beta\\hbar\\omega}} \\] <p>\u82e5\u56fa\u4f53\u4e2d\u6709N\u4e2a\u7c92\u5b50\uff0c\u5373\u67093N\u4e2a\u632f\u5b50(x,y,z\u4e09\u4e2a\u65b9\u5411)\uff0c\u5177\u67096N\u4e2a\u5e73\u65b9\u9879(\u4e00\u4e2a\u632f\u5b50\u5177\u6709\u4e24\u4e2a\u5e73\u65b9\u9879).\u5e94\u5f53\u6ce8\u610f\uff0c\u4e0a\u5f0f\u7684\u80fd\u91cf\u662f\u5bf9\u4e8e\u632f\u5b50\u800c\u8a00\u7684\uff0c\u4e0d\u662f\u7c92\u5b50\u4e5f\u4e0d\u662f\u5e73\u65b9\u9879\uff0c\u4ece\u800c\u5185\u80fd\u6709\uff1a</p> \\[ U=-3N\\frac{\\partial}{\\partial\\beta}ln(Z_1)=3N\\frac{\\hbar\\omega}{2}+\\frac{3N\\hbar\\omega}{e^{\\beta\\hbar\\omega}-1} \\] <p>\u5982\u679c\u4ece\u5177\u6709\u73bb\u8272\u5b50\u5c5e\u6027\u7684\u201c\u58f0\u5b50\u201d\u7684\u89d2\u5ea6\u6765\u770b\uff0c\u5185\u80fd\u5b9e\u9645\u4e0a\u5c31\u662f\u58f0\u5b50\u7684\u96f6\u70b9\u80fd\u52a0\u4e0a\u5176\u670d\u4ece\u73bb\u8272\u5206\u5e03\u7684\u80fd\u91cf\u7684\u7edf\u8ba1\u5e73\u5747\u3002\u5bf9\u5185\u80fd\u5173\u4e8e\u6e29\u5ea6\u6c42\u5bfc\u53ef\u5f97\u5230\u70ed\u5bb9\uff1a</p> \\[ C_V=\\frac{\\partial U}{\\partial T}=3Nk\\left(\\frac{\\hbar\\omega}{kT}\\right)^2\\frac{e^{\\frac{\\hbar\\omega}{kT}}}{(e^{\\frac{\\hbar\\omega}{kT}}-1)^2} \\] <p>\u4e3a\u4e86\u65b9\u4fbf\u7406\u89e3\uff0c\u5c06\\(\\omega\\)\u4e5f\u53ef\u770b\u4f5c\u67d0\u79cd\u6e29\u5ea6\uff0c\u5f15\u5165Einstein\u7279\u5f81\u6e29\u5ea6\\(\\theta_E\\):</p> \\[ \\theta_E=\\frac{\\hbar\\omega}{k}\\quad\\Rightarrow\\quad\\boxed{C_V=3Nk\\left(\\frac{\\theta_E}{T}\\right)^2\\frac{e^{\\frac{\\theta_E}{T}}}{(e^{\\frac{\\theta_E}{T}}-1)^2}} \\] <p>\u5f53\u53d6\u9ad8\u6e29\u6781\u9650\u65f6\uff0c\\(T\\gg\\theta_E\\)\u4ece\u800c\\(C_V\\rightarrow 3Nk\\);\u5f53\u53d6\u4f4e\u6e29\u6781\u9650\u5e76\u4e14\u6e29\u5ea6\u8d8b\u5411\u4e8e0\u65f6\uff0c\\(T\\ll\\theta_E,T\\rightarrow0\\)\u4ece\u800c\\(C_V\\rightarrow0\\).\u7531\u6b64\u63cf\u8ff0\u4e86\u56fa\u4f53\u70ed\u5bb9\u968f\u6e29\u5ea6\u7684\u53d8\u5316\uff0c\u89e3\u91ca\u4e86\u5b9e\u9a8c\u73b0\u8c61\u3002\u7136\u800c\uff0c\u7531\u4e8e\u4e00\u5f00\u59cb\u7b80\u5355\u5047\u8bbe\u4e86\u6240\u6709\u632f\u5b50\u7684\u9891\u7387\u90fd\u76f8\u540c\uff0c\u4f7f\u5f97\u70ed\u5bb9\u8fc7\u5feb\u7684\u8d8b\u5411\u4e8e0\u3002\u4f46\u4ece\u91cf\u5b50\u8c10\u632f\u5b50\u6a21\u578b\u51fa\u53d1\uff0c\u5229\u7528\u80fd\u7ea7\u5dee\\(\\hbar\\omega\\)\u4e0e\u6e29\u5ea6\\(kT\\)\u7684\u76f8\u4e92\u7ade\u4e89\uff0c\u663e\u73b0\u51fa\u56fa\u4f53\u4e0d\u540c\u6e29\u5ea6\u4e0b\u5177\u6709\u4e0d\u540c\u70ed\u5bb9\u7684\u56fe\u666f\u662f\u6b63\u786e\u7684\u3002</p> <p>\u2605 \u57fa\u4e8eEinstein\u7ed9\u51fa\u7684\u80fd\u91cf\u5206\u5e03\uff0c\u5fb7\u62dc\u5c06\u56fa\u4f53\u770b\u4f5c\u8fde\u7eed\u4ecb\u8d28\uff0c\u7c7b\u6bd4\u9ed1\u4f53\u8f90\u5c04\u7535\u78c1\u6ce2\u9891\u7387\u5206\u5e03\u7684\u63a8\u5bfc\u65b9\u6cd5\uff0c\u7ed9\u51fa\u5728\u4f4e\u6e29\u4e0b\u4e0e\u5b9e\u9a8c\u7b26\u5408\u975e\u5e38\u597d\u7684\u5fb7\u62dc\u6a21\u578b\u3002\u4f46\u8981\u6ce8\u610f\uff0c\u56fa\u4f53\u4e2d\u7684\u6ce2\u52a8\u4e0d\u4ec5\u4ec5\u6709\u6a2a\u6ce2(T)\uff0c\u8fd8\u5b58\u5728\u7eb5\u6ce2(L)\uff0c\u56e0\u800c\u4e24\u79cd\u8272\u6563\u5173\u7cfb\u8981\u5206\u5f00\u5199\u51fa\uff1a</p> \\[ \\omega=c_tk\\quad\\omega=c_lk \\] <p>\u4e0e\u7535\u78c1\u6ce2\u7684\u63a8\u5bfc\u7c7b\u4f3c\uff0c\u4f7f\u7528\u5468\u671f\u6027\u8fb9\u754c\u6761\u4ef6\uff0c\u8003\u8651\u5230\u6a2a\u6ce2\u6709\u4e24\u4e2a\u81ea\u7531\u5ea6\uff0c\u7eb5\u6ce2\u6709\u4e00\u4e2a\u81ea\u7531\u5ea6\uff0c\u4ece\u800c\u5904\u5728\\(\\omega\\sim\\omega+d\\omega\\)\u8303\u56f4\u5185\u7684\u632f\u5b50\u7684\u4e2a\u6570\u4e3a\uff1a</p> \\[ dn=\\frac{L^3}{2\\pi^2}\\left(\\frac{1}{c_l^3}+\\frac{2}{c_t^3}\\right)\\omega^2d\\omega=B\\omega^2d\\omega\\quad\\Rightarrow \\quad B=\\frac{L^3}{2\\pi^2}\\left(\\frac{1}{c_l^3}+\\frac{2}{c_t^3}\\right) \\] <p>\u6ce8\u610f\uff0c\u56fa\u4f53\u4e2d\u632f\u5b50\u7684\u4e2a\u6570\u4e3a\\(3N\\),\u4ece\u800c\u5b58\u5728\u622a\u6b62\u9891\u7387\\(\\omega_D\\),\u79f0\u4e3a\u5fb7\u62dc\u9891\u7387\u3002</p> \\[ \\int_0^{\\omega_D}B\\omega^2d\\omega=3N\\quad\\Rightarrow\\quad\\omega_D^3=\\frac{9N}{B} \\] <p>\u4ece\u800c\uff0c\u5185\u80fd\u7531\u5355\u4e2a\u632f\u5b50\u7684\u5e73\u5747\u80fd\u91cf\u5bfc\u51fa\uff1a</p> \\[ U=\\int_0^{\\omega_D}\\left(\\frac{\\hbar\\omega}{2}+\\frac{\\hbar\\omega}{e^{\\beta\\hbar\\omega}-1}\\right)B\\omega^2d\\omega=U_0+3NkT\\mathscr{D}(x) \\] <p>\u5176\u4e2d\uff1a</p> \\[ U_0=\\frac{B\\hbar\\omega_D^4}{8}\\qquad\\mathscr{D}(x)=\\frac{3}{x^3}\\int_0^x\\frac{y^3dy}{e^y-1}\\qquad x=\\frac{\\theta_D}{T}=\\frac{\\hbar\\omega_D}{kT}\\qquad y=\\frac{\\hbar\\omega}{kT} \\] <p>\u9ad8\u6e29\u6761\u4ef6\u4e0b\\(x\\ll1\\),\u4ece\u800c\\(\\mathscr{D}(x)\\rightarrow1\\),\u70ed\u5bb9\\(C_V\\rightarrow 3Nk\\).\u4f4e\u6e29\u6761\u4ef6\u4e0b\\(x\\gg1\\),\u4ece\u800c\u6709\uff1a</p> \\[ \\mathscr{D}(x)\\rightarrow\\frac{3}{x^3}\\int_0^\\infty\\frac{y^3dy}{e^y-1}=\\frac{\\pi^4}{15}\\cdot\\frac{3}{x^3}=\\frac{\\pi^4}{5x^3}\\quad\\Rightarrow\\quad\\boxed{C_V=3Nk\\frac{4\\pi^4}{5}\\left(\\frac{T}{\\theta_D}\\right)^3} \\] <p>\u6b64\u5373\u5fb7\u62dc\\(T^3\\)\u5f8b.\u5bf9\u4e8e\u975e\u91d1\u5c5e\u56fa\u4f53\u4e0e\u5b9e\u9a8c\u76f8\u7b26\uff0c\u5bf9\u4e8e\u91d1\u5c5e\u56fa\u4f53\u5728\u4f4e\u6e29\u4e0b\u8fd8\u8981\u8003\u8651\u81ea\u7531\u7535\u5b50\u5bf9\u70ed\u5bb9\u7684\u8d21\u732e\u3002\u6b64\u5916\uff0c\u7531\u4e8e\u5c06\u56fa\u4f53\u89c6\u4f5c\u8fde\u7eed\u4ecb\u8d28\uff0c\u4ece\u800c\u9002\u7528\u6761\u4ef6\u4e3a\\(\\lambda_D\\gg a\\),\u5176\u4e2d\\(a\\)\u4e3a\u56fa\u4f53\u539f\u5b50\u7684\u5c3a\u5ea6\u3002</p>"},{"location":"chapter_08_bose_fermi_statistics/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_08_bose_fermi_statistics/index.html#8-bosefermi","title":"\u7b2c8\u7ae0 Bose/Fermi\u7edf\u8ba1\u7406\u8bba","text":"<p>\u5bf9\u4e8e\u5b9a\u57df\u7cfb\u7edf\u6216\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\uff0c\u7531\u4e8e\u670d\u4ece\u73bb\u5c14\u5179\u66fc\u5206\u5e03\uff0c\u6545\u4f7f\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u6c42\u51fa\u5404\u4e2a\u70ed\u529b\u5b66\u91cf\u3002\u7136\u800c\uff0c\u5bf9\u4e8e\u5f31\u7b80\u5e76\u6216\u5f3a\u7b80\u5e76\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\uff0c\u7531\u4e8e\u670d\u4ece\u73bb\u8272\u5206\u5e03\u6216\u8d39\u7c73\u5206\u5e03\uff0c\u9700\u8981\u5f15\u5165\u4e00\u4e2a\u65b0\u7684\u51fd\u6570\uff0c\u5373\u5de8\u914d\u5206\u51fd\u6570\u3002\u672c\u7ae0\u5c06\u5ef6\u7eed\u524d\u9762\u5bf9\u8fd1\u72ec\u7acb\u5b50\u7cfb\u7684\u8ba8\u8bba\uff0c\u8ba8\u8bba\u73bb\u8272\u6c14\u4f53\u548c\u8d39\u7c73\u6c14\u4f53\uff0c\u5e76\u7814\u7a76Bose-Einstein\u51dd\u805a\u7b49\u6709\u8da3\u7684\u7269\u7406\u7cfb\u7edf\u3002</p>"},{"location":"chapter_08_bose_fermi_statistics/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>Bose\u6c14\u4f53\u548cFermi\u6c14\u4f53\u7684\u70ed\u529b\u5b66\u91cf</li> <li>Bose-Einstein\u51dd\u805a</li> <li>\u8f90\u5c04\u7cfb\u7edf\u4e2d\u7684\u5149\u5b50\u6c14\u4f53</li> <li>\u91d1\u5c5e\u4e2d\u7684\u81ea\u7531\u7535\u5b50\u6c14\u4f53</li> </ul>"},{"location":"chapter_08_bose_fermi_statistics/01_bose_fermi_thermo.html","title":"Bose\u6c14\u4f53\u548cFermi\u6c14\u4f53\u7684\u70ed\u529b\u5b66\u91cf","text":""},{"location":"chapter_08_bose_fermi_statistics/01_bose_fermi_thermo.html#bosefermi","title":"Bose\u6c14\u4f53\u548cFermi\u6c14\u4f53\u7684\u70ed\u529b\u5b66\u91cf","text":"<p>\u2605 \u4e3a\u4e86\u7814\u7a76\u975e\u5b9a\u57df\u7cfb\u7edf\uff0c\u901a\u5e38\u5f15\u5165\u5de8\u914d\u5206\u51fd\u6570\\(\\Xi\\):</p> \\[ B.E.\\quad\\Xi=\\prod_l\\Xi_l=\\prod_l(1-e^{-\\alpha-\\beta\\varepsilon_l})^{-\\omega_l}\\qquad F.D.\\quad\\Xi=\\prod_l\\Xi_l=\\prod_l(1+e^{-\\alpha-\\beta\\varepsilon_l})^{\\omega_l} \\] <p>\u6ce8\u610f\u73bb\u8272\u5206\u5e03\u548c\u8d39\u7c73\u5206\u5e03\u5de8\u914d\u5206\u51fd\u6570\u7684\u6b63\u8d1f\u53f7\u5dee\u5f02\u3002\u81f3\u4e8e\u5de8\u914d\u5206\u51fd\u6570\u5982\u6b64\u5b9a\u4e49\u7684\u52a8\u673a\u548c\u5408\u7406\u6027\uff0c\u5230\u4e0b\u4e00\u7ae0\u7cfb\u7efc\u7406\u8bba\u7684\u6700\u540e\u624d\u80fd\u8bf4\u6e05\u695a\uff0c\u672c\u7ae0\u4ec5\u9700\u63a5\u53d7\u8fd9\u4e2a\u5b9a\u4e49\u5373\u53ef\u3002\u5bf9\u4e8e\u5e38\u7528\u7684\u70ed\u529b\u5b66\u91cf\uff0c\u8fd9\u91cc\u4e5f\u76f4\u63a5\u7ed9\u51fa\uff0c\u8be6\u7ec6\u8fc7\u7a0b\u53ef\u7c7b\u6bd4\u7c92\u5b50\u914d\u5206\u51fd\u6570\u6216\u89c1\u7cfb\u7efc\u7406\u8bba\u3002</p> \\[ \\overline{N}=-\\frac{\\partial}{\\partial \\alpha}ln\\Xi\\quad U=-\\frac{\\partial}{\\partial\\beta}ln\\Xi\\quad Y=-\\frac{1}{\\beta}\\frac{\\partial}{\\partial y}ln\\Xi\\quad J=-kTln\\Xi \\] \\[ S=k\\left(ln\\Xi-\\alpha\\frac{\\partial}{\\partial\\alpha}ln\\Xi-\\beta\\frac{\\partial}{\\partial\\beta}ln\\Xi\\right)\\qquad F=-kTln\\Xi+kT\\alpha\\frac{\\partial}{\\partial\\alpha}ln\\Xi \\] \\[ S=kln(\\Omega)\\qquad\\alpha=-\\frac{\\mu}{kT} \\] <p>\u2605 \u5728\u8fd1\u72ec\u7acb\u6700\u6982\u7136\u5206\u5e03\u4e2d\u5f15\u5165\u7684\u201c\u975e\u7b80\u5e76\u6761\u4ef6\u201d\u8868\u660e\uff0c\u5982\u679c\u6ee1\u8db3\\(e^\\alpha\\gg1\\)\u6216\\(n\\lambda_T^3\\ll1\\)\u7684\u6761\u4ef6\uff0c\u73bb\u8272\u5206\u5e03\u548c\u8d39\u7c73\u5206\u5e03\u5747\u53ef\u8fd1\u4f3c\u4e3a\u73bb\u5c14\u5179\u66fc\u5206\u5e03\u6765\u5904\u7406(\u4f46\u8981\u8003\u8651\\(N!\\)\u7684\u4fee\u6b63\u9879).\u6570\u5b66\u4e0a\uff0c\u5de8\u914d\u5206\u51fd\u6570\u53ef\u7531\u7c92\u5b50\u914d\u5206\u51fd\u6570\u51b3\u5b9a\uff1a</p> \\[ ln\\Xi=\\pm\\sum_l\\omega_lln(1\\pm e^{-\\alpha -\\beta\\varepsilon_l})\\approx\\sum_l\\omega_le^{-\\alpha-\\beta\\varepsilon_l}=e^{-\\alpha}Z_1 \\] <p>\u5982\u679c\u5c06\u6761\u4ef6\u653e\u5bbd\u4e00\u70b9\uff0c\u5373\u6ee1\u8db3\\(e^\\alpha&gt;1\\)\uff0c\u79f0\u4e3a\u5f31\u7b80\u5e76\u6761\u4ef6\u3002\u8fd9\u65f6\u5c31\u8981\u8003\u8651\u73bb\u8272\u5206\u5e03\u548c\u8d39\u7c73\u5206\u5e03\u7684\u5dee\u5f02\u6027\uff0c\u5e76\u5229\u7528\u5f31\u7b80\u5e76\u6761\u4ef6\u8fdb\u884c\u8fd1\u4f3c\u5904\u7406\u3002\u5f53\u6ee1\u8db3\\(e^\\alpha\\leqslant1\\)\u65f6\uff0c\u79f0\u4e3a\u5f3a\u7b80\u5e76\u6761\u4ef6\u3002\u6ce8\u610f\uff0c\u53ea\u8981\u975e\u5b9a\u57df\u7cfb\u7edf\u4e0d\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\uff0c\u5c31\u8981\u7528\u5de8\u914d\u5206\u51fd\u6570\u8fdb\u884c\u8ba1\u7b97\u3002\u6b64\u5916\uff0c\u7531\u4e8e\u4e4b\u540e\u7cfb\u7efc\u7406\u8bba\u4e2d\u63a8\u5bfc\u73bb\u8272\u548c\u8d39\u7c73\u5206\u5e03\u65f6\uff0c\u662f\u5c06\u4e00\u822c\u7684\u5de8\u914d\u5206\u51fd\u6570\u5229\u7528\u73bb\u8272\u548c\u8d39\u7c73\u7cfb\u7edf\u7684\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega\\)\u8fdb\u884c\u5f62\u5f0f\u4e0a\u7684\u6539\u9020\uff0c\u56e0\u800c\u4e0d\u7528\u8003\u8651\u5168\u540c\u6027\u5e26\u6765\u7684\\(N!\\)\u4fee\u6b63\u9879\u7684\u95ee\u9898\u3002</p> <p>\u2605 \u9996\u5148\u7814\u7a76\u5f31\u7b80\u5e76\u73bb\u8272\u6c14\u4f53\u7684\u6027\u8d28\u3002\u4e3a\u4e86\u65b9\u4fbf\uff0c\u8fd9\u91cc\u5047\u8bbe\u6c14\u4f53\u7c92\u5b50\u81ea\u65cb\u4e3a0\uff0c\u5e76\u4e14\u4ec5\u8003\u8651\u975e\u76f8\u5bf9\u8bba\u7684\u5e73\u52a8\u60c5\u51b5\uff1a</p> \\[ \\varepsilon=\\frac{p^2}{2m}\\quad\\Rightarrow\\quad ln\\Xi=-\\sum_l\\omega_lln(1-e^{-\\alpha-\\beta\\varepsilon_l})=-\\int\\frac{d\\omega_{\\mu}}{h^3}ln(1-e^{-\\alpha-\\beta\\varepsilon}) \\] <p>\u4e0a\u5f0f\u7528\u5230\u4e86\u5e73\u52a8\u80fd\u7ea7\u51c6\u8fde\u7eed\u7684\u7279\u6027\u3002\u4e3a\u4e86\u65b9\u4fbf\u5904\u7406\u79ef\u5206\uff0c\u901a\u5e38\u5c06\u53d8\u91cf\u6362\u4e3a\u80fd\u91cf\uff0c\u4ece\u800c\u7531\u6001\u5bc6\u5ea6\u8868\u8fbe\uff1a</p> \\[ ln\\Xi=-\\int_0^\\infty D(\\varepsilon)ln(1-e^{-\\alpha-\\beta\\varepsilon})d\\varepsilon=-\\frac{2\\pi V}{h^3}(2m)^{\\frac{3}{2}}\\int_0^\\infty \\varepsilon^{\\frac{1}{2}}ln(1-e^{-\\alpha-\\beta\\varepsilon})d\\varepsilon \\] <p>\u4e3a\u4e86\u65b9\u4fbf\u5904\u7406\uff0c\u4ee4\\(x=\\beta\\varepsilon&gt;0\\),\u4ece\u800c\u5316\u4e3a\uff1a</p> \\[ ln\\Xi=-\\frac{2\\pi V}{h^3}(\\frac{2m}{\\beta})^{\\frac{3}{2}}\\int_0^\\infty x^{\\frac{1}{2}}ln(1-e^{-\\alpha-x})dx=\\frac{2\\pi V}{h^3}(\\frac{2m}{\\beta})^{\\frac{3}{2}}\\int_0^\\infty x^{\\frac{1}{2}}\\sum_{i=1}^\\infty\\frac{e^{-(\\alpha+x)i}}{i}dx \\] <p>\u4e0a\u5f0f\u5229\u7528\u5230\u4e86\u5f31\u7b80\u5e76\u6761\u4ef6\\(e^{\\alpha}&gt;1\\),\u5373\\(e^{-\\alpha-x}&lt;e^{-\\alpha}&lt;1\\).\u6545\u5bf9\\(ln(1-e^{-\\alpha-x})\\)\u8fdb\u884c\u5c55\u5f00\uff0c\u7531\u6b64\u53ef\u4ee5\u5c06\u6c42\u548c\u4e2d\u7684\u6bcf\u4e00\u9879\u8fdb\u884c\u79ef\u5206\uff0c\u5f97\u5230\uff1a</p> \\[ ln\\Xi=V\\left(\\frac{2\\pi m}{\\beta h^2}\\right)^{3/2}\\sum_{i=1}^\\infty\\frac{z^{ i}}{i^{5/2}}=\\frac{V}{\\lambda_T^3}Li_{5/2}(z) \\] <p>\u5176\u4e2d\\(\\boxed{z=e^{-\\alpha}=e^{\\frac{\\mu}{kT}}&lt;1}\\)\u79f0\u4e3a\u9038\u5ea6\uff0c\u5e76\u6709\\(n\\lambda_T^3=Li_{3/2}(z)\\)\u3002\u5728\u5f31\u7b80\u5e76\u6781\u9650\u4e0b\uff0c\u624d\u6709\\(z\\approx n\\lambda_T^3\\)\u3002\u7531\u6b64\u5f97\u5230\u5404\u4e2a\u70ed\u529b\u5b66\u91cf\uff1a</p> \\[ N=\\frac{V}{\\lambda_{T}^3}Li_{3/2}(z)\\qquad U=\\frac{3}{2}kT\\frac{V}{\\lambda_T^3}Li_{5/2}(z)\\qquad p=\\frac{kT}{\\lambda_T^3}Li_{5/2}(z) \\] <p>\u8054\u7acb\u4e0a\u5f0f\uff0c\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ U=\\frac{3}{2}NkT\\frac{Li_{5/2}(z)}{Li_{3/2}(z)}\\approx\\frac{3}{2}NkT\\left(1-\\frac{z}{2^{5/2}}\\right)=\\frac{3}{2}NkT\\left(1-\\frac{n\\lambda_{T}^3}{4\\sqrt{2}}\\right) \\] \\[ p=nkT\\frac{Li_{5/2}(z)}{Li_{3/2}(z)}\\approx nkT\\left(1-\\frac{z}{2^{5/2}}\\right)=nkT\\left(1-\\frac{n\\lambda_{T}^3}{4\\sqrt{2}}\\right) \\] <p>\u5f31\u7b80\u5e76\u8d39\u7c73\u6c14\u4f53\u7684\u6027\u8d28\u4e5f\u53ef\u7528\u7c7b\u4f3c\u7684\u65b9\u6cd5\u5f97\u5230\uff0c\u4e0d\u8fc7\u8d39\u7c73\u5b50\u901a\u5e38\u81ea\u65cb\u4e3a\\(\\frac{1}{2}\\),\u6545\u8981\u8003\u8651\u81ea\u65cb\u7b80\u5e76\u5ea6\\(g=2\\)\u5e26\u6765\u7684\u989d\u5916\u81ea\u7531\u5ea6\uff0c\u4ece\u800c\uff1a</p> \\[ ln\\Xi=-2\\frac{V}{\\lambda_{T}^3}Li_{5/2}(-z) \\] <p>\u540c\u7406\u4e0d\u96be\u6c42\u5f97\u5404\u4e2a\u70ed\u529b\u5b66\u91cf\uff0c\u8fd9\u91cc\u4ec5\u5217\u51fa\u5185\u80fd\u548c\u7269\u6001\u65b9\u7a0b\u7684\u8fd1\u4f3c\u8868\u8fbe\u5f0f\uff1a</p> \\[ U\\approx\\frac{3}{2}NkT\\left(1+\\frac{n\\lambda_{T}^3}{8\\sqrt{2}}\\right)\\qquad p\\approx nkT\\left(1+\\frac{n\\lambda_{T}^3}{8\\sqrt{2}}\\right) \\] <p>\u4e0d\u96be\u53d1\u73b0\uff0c\u5f53\u6c14\u4f53\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\\(n\\lambda_{T}^3\\ll1\\)\u65f6\uff0c\u73bb\u8272\u548c\u8d39\u7c73\u6c14\u4f53\u7684\u7269\u6001\u65b9\u7a0b\u5747\u9000\u5316\u4e3a\u4e4b\u524d\u7684\u7ecf\u5178\u7406\u60f3\u6c14\u4f53\u7684\u60c5\u51b5\u3002\u6b64\u5916\uff0c\u5bf9\u6bd4\u73bb\u8272\u6c14\u4f53\u548c\u8d39\u7c73\u6c14\u4f53\u7684\u5185\u80fd\uff0c\u4e0d\u96be\u770b\u51fa\u73bb\u8272\u6c14\u4f53\u4e4b\u95f4\u4f3c\u4e4e\u6709\u67d0\u79cd\u76f8\u4e92\u7684\u5438\u5f15\u529b\uff0c\u4f7f\u5f97\u5185\u80fd\u964d\u4f4e\uff1b\u800c\u8d39\u7c73\u6c14\u4f53\u5219\u6709\u76f8\u4e92\u6392\u65a5\u7684\u529b\uff0c\u4f7f\u5f97\u5185\u80fd\u589e\u5927\u3002\u8fd9\u4fbf\u662f\u6709\u8da3\u7684\u7edf\u8ba1\u5173\u8054\uff0c\u4e5f\u5c31\u662f\u91cf\u5b50\u529b\u5b66\u4e2d\u7684\u4ea4\u6362\u529b\u6548\u5e94\uff0c\u5b8c\u5168\u662f\u7531\u4e8e\u7c92\u5b50\u7684\u5168\u540c\u6027\u6240\u8981\u6c42\u7684\u6ce2\u51fd\u6570\u7684\u5bf9\u79f0\u548c\u53cd\u5bf9\u79f0\u6240\u5f15\u8d77\u7684\u3002</p> <p>\u81f3\u4e8e\u5f3a\u7b80\u5e76\u6c14\u4f53\u7684\u8ba8\u8bba\uff0c\u5c06\u5728\u4e0b\u9762\u51e0\u8282\u5c55\u5f00\u3002</p>"},{"location":"chapter_08_bose_fermi_statistics/02_bose_einstein_condensation.html","title":"Bose-Einstein\u51dd\u805a","text":""},{"location":"chapter_08_bose_fermi_statistics/02_bose_einstein_condensation.html#bose-einstein","title":"Bose-Einstein\u51dd\u805a","text":"<p>\u2605 \u5728\u8ba8\u8bbaBEC\u4e4b\u524d\uff0c\u5148\u6765\u7814\u7a76\u4e00\u4e0b\u73bb\u8272\u6c14\u4f53\u7c92\u5b50\u6570\u7684\u6027\u8d28\uff1a</p> \\[ N=\\frac{V}{\\lambda_{T}^3}Li_{3/2}(z)&gt;0,\\qquad z=e^{\\mu/kT} \\] <p>\u5bf9\u7406\u60f3\u73bb\u8272\u6c14\u4f53\uff0c\u57fa\u6001\u80fd\u91cf\u53d6\u4e3a0\u65f6\u9700\u6709\\(\\mu\\leqslant0\\)\uff0c\u56e0\u6b64\\(0&lt;z\\leqslant1\\)\u3002\u8fd9\u4e0d\u662f\u5355\u7eaf\u7531\\(N&gt;0\\)\u63a8\u51fa\u7684\uff0c\u800c\u662f\u7531\u73bb\u8272\u5206\u5e03\u5206\u6bcd\\(e^{\\beta(\\varepsilon-\\mu)}-1\\)\u5fc5\u987b\u4e3a\u6b63\u63a8\u51fa\u7684\u3002</p> <p>\u6b64\u5916\uff0c\u5728\u6b64\u533a\u95f4\u8303\u56f4\u5185\\(Li_{3/2}(z)\\)\u662f\u5355\u8c03\u9012\u589e\u7684\uff0c\u6545\u5728\\(z=0\\)\u65f6\u53d6\u5f97\u6700\u5c0f\u503c\\(Li_{3/2}(0)=0\\);\u5728\\(z=1\\)\u65f6\u53d6\u5f97\u6700\u5927\u503c\\(Li_{3/2}(1)=\\zeta(\\frac{3}{2})\\approx2.612\\).</p> <p>\u73b0\u5728\u8003\u8651\u5f53\u603b\u7c92\u5b50\u6570\\(N\\)\u56fa\u5b9a\uff0c\u6e29\u5ea6\u4e0b\u964d\u7684\u60c5\u51b5\u3002\u6839\u636e\\(\\frac{1}{\\lambda_T^3}\\sim T^{\\frac{3}{2}}\\)\u7684\u5173\u7cfb,\\(Li_{3/2}(z)\\)\u5fc5\u7136\u8981\u4e0a\u5347\uff0c\u624d\u80fd\u4fdd\u6301\u6fc0\u53d1\u6001\u5bb9\u7eb3\u8db3\u591f\u591a\u7684\u7c92\u5b50\u3002\u7136\u800c\\(Li_{3/2}(z)\\)\u7684\u53d6\u503c\u4e0a\u9650\u4e3a\\(\\zeta(\\frac{3}{2})\\),\u4ece\u800c\u5f53\u6e29\u5ea6\u4e0b\u964d\u5230\u8db3\u591f\u4f4e\u7684\\(T_c\\)\u65f6\uff0c\u6fc0\u53d1\u6001\u53ef\u5bb9\u7eb3\u7684\u7c92\u5b50\u6570\u8fbe\u5230\u4e0a\u9650\uff0c\u5269\u4f59\u7c92\u5b50\u53ea\u80fd\u8fdb\u5165\u57fa\u6001\u3002</p> \\[ N=\\frac{V}{\\lambda_{T_c}^3}Li_{3/2}(1)=\\frac{V}{h^3}(2\\pi m kT_c)^{3/2}Li_{3/2}(1)\\quad\\Rightarrow\\quad n\\lambda_{T}^3&gt;\\zeta(\\frac{3}{2})\\approx2.612 \\] <p>\u4e0a\u5f0f\u5373\u4e3a\u8fd9\u79cd\u4e34\u754c\u72b6\u6001\u6240\u6ee1\u8db3\u7684\u7b49\u5f0f\uff1b\u5f53\\(n\\lambda_T^3&gt;\\zeta(\\frac{3}{2})\\)\u65f6\uff0c\u4ec5\u9760\u6fc0\u53d1\u6001\u5df2\u7ecf\u65e0\u6cd5\u5bb9\u7eb3\u5168\u90e8\u7c92\u5b50\u3002\u4e8b\u5b9e\u4e0a\uff0c\u4e0a\u4e00\u8282\u63a8\u5bfc\u73bb\u8272\u6c14\u4f53\u7684\u5de8\u914d\u5206\u51fd\u6570\u65f6\uff0c\u5176\u4e2d\\(D(\\varepsilon)\\sim\\varepsilon^{\\frac{1}{2}}\\),\u4f7f\u5f97\u5904\u4e8e\u57fa\u6001\\(\\varepsilon=0\\)\u7684\u91cf\u5b50\u6001\u5bf9\u8fde\u7eed\u6001\u5bc6\u5ea6\u6ca1\u6709\u8d21\u732e\u3002\u4f4e\u4e8e\\(T_c\\)\u65f6\uff0c\u57fa\u6001\u7c92\u5b50\u6570\u5f00\u59cb\u5b8f\u89c2\u589e\u5927\uff0c\u8fd9\u6b63\u662fBEC\u7684\u4f53\u73b0\uff1b\u7531\u4e8e\u8fd9\u91cc\u6d89\u53ca\\(z=e^{-\\alpha}\\rightarrow1\\),\u6545\u5c5e\u4e8e\u5f3a\u7b80\u5e76\u7684\u60c5\u51b5\u3002 *</p> <p>\u2605 \u4e0b\u9762\u5c06\u57fa\u6001\u7c92\u5b50\u6570\u5bf9\u5de8\u914d\u5206\u51fd\u6570\u7684\u8d21\u732e\u5355\u72ec\u4f5c\u4e3a\u4e00\u9879\uff0c\\(ln\\Xi\\)\u4fee\u6b63\u4e3a:</p> \\[ ln\\Xi=-\\sum_l\\omega_lln(1-e^{-\\alpha-\\beta\\varepsilon_l})=-\\omega_1ln(1-e^{-\\alpha})+\\frac{V}{\\lambda_T^3}Li_{5/2}(z) \\] <p>\u4e3a\u4e86\u65b9\u4fbf\uff0c\u53d6\u57fa\u6001\u7b80\u5e76\u5ea6\u4e3a1\uff0c\u5373\\(\\omega_1=1\\),\u4ece\u800c\u5f97\u5230\u4fee\u6b63\u7684\u7c92\u5b50\u6570\u4e3a\uff1a</p> \\[ \\boxed{N=\\frac{z}{1-z}+\\frac{V}{\\lambda_{T}^3}Li_{3/2}(z)} \\] <p>\u5bf9\u4e8e\u5185\u80fd\u548c\u7269\u6001\u65b9\u7a0b\uff0c\u7531\u4e8e\\(ln\\Xi\\)\u7684\u57fa\u6001\u4fee\u6b63\u9879\u4e2d\u4e0d\u542b\\(\\beta\\)\u548c\u5916\u53c2\u91cf\\(V\\),\u6545\u4ecd\u4e3a\u539f\u6765\u7684\u8868\u8fbe\u5f0f\u3002\u7136\u800c\uff0c\u6709\u65f6\u4e3a\u4e86\u7814\u7a76\\(T&lt;T_c\\)\u6761\u4ef6\u4e0b\uff0c\u5404\u4e2a\u70ed\u529b\u5b66\u91cf\u4e0e\\(\\frac{T}{T_c}\\)\u7684\u5173\u7cfb\uff0c\u9ed8\u8ba4\\(z\\approx1\\);\u4e14\\(T=T_c\\)\u65f6\uff0c\u57fa\u6001\u7c92\u5b50\u6570\u53ef\u4ee5\u5ffd\u7565\u4e0d\u8ba1\uff0c\u90a3\u4e48\u6709\uff1a</p> \\[ N\\approx\\frac{V}{\\lambda_{T_c}^3}Li_{3/2}(1)\\quad\\Rightarrow\\quad N_{exc}=N\\left(\\frac{T}{T_c}\\right)^{3/2}\\quad N_0=N\\left[1-\\left(\\frac{T}{T_c}\\right)^{3/2}\\right] \\] <p>\u6ce8\u610f\u7c92\u5b50\u6570\\(N\\)\u7684\u8868\u8fbe\u5f0f\u4e2d\u6e29\u5ea6\u6052\u4e3a\\(T_c\\),\u800c\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\u4e2d\u7684\\(T\\)\u4e3a\u53d8\u91cf\u3002\u6545\uff1a</p> \\[ \\frac{pV}{NkT}=\\frac{U}{\\frac{3}{2}NkT}=\\frac{Li_{5/2}(z)}{Li_{3/2}(z)}\\left(\\frac{T}{T_c}\\right)^{3/2}\\quad\\Rightarrow\\quad C_V=\\left(\\frac{\\partial U}{\\partial T}\\right)_V=\\frac{15Li_{5/2}(z)}{4Li_{3/2}(z)}Nk\\left(\\frac{T}{T_c}\\right)^{3/2} \\] <p>\u5373\u5f53\\(T\\rightarrow0\\)\u65f6\uff0c\\(U,p\\)\u548c\\(C_V\\)\u5206\u522b\u4ee5\\(T^{5/2}\\)\u548c\\(T^{3/2}\\)\u7684\u5e42\u6b21\u8d8b\u5411\u4e8e0.\u8fd9\u4f53\u73b0\u51fa\u73bb\u8272\u6c14\u4f53\u7684\u7279\u70b9\uff0c\u4f46\u5728\u5f3a\u7b80\u5e76\u7684\u8d39\u7c73\u6c14\u4f53\u4e2d\uff0c\u7531\u4e8e\u6ce1\u5229\u4e0d\u76f8\u5bb9\u539f\u7406\uff0c\u80fd\u91cf\u3001\u538b\u5f3a\u7b49\u4e0d\u4f1a\u968f\u6e29\u5ea6\u8d8b\u5411\u4e8e0.</p> <p>\u503c\u5f97\u6ce8\u610f\uff0c\u4e25\u683c\u6765\u8bf4\\(z(T)\\)\u9700\u8981\u6839\u636e\u7c92\u5b50\u6570\u65b9\u7a0b\\(N=N(T,z)\\)\u6765\u786e\u5b9a\u3002\u5728\u70ed\u529b\u5b66\u6781\u9650\u4e0b\uff0c\\(T&lt;T_c\\)\u65f6\u901a\u5e38\u53d6\\(z\\rightarrow1\\)\uff0c\u800c\u4e0d\u662f\u628a\\(z\\)\u770b\u6210\u8d8b\u4e8e0\u3002</p> <p>\u2605 \u672c\u8282\u4ece\u5de8\u914d\u5206\u51fd\u6570\u5bfc\u51fa\u7684\u7c92\u5b50\u6570\u51fa\u53d1\uff0c\u53d1\u73b0\u5728\u4f4e\u4e8e\\(T_c\\)\u7684\u6e29\u5ea6\u4e0b\uff0c\u7c92\u5b50\u6570\u4f1a\u51cf\u5c11\uff0c\u4ece\u800c\u5224\u65adBEC\u7684\u5b58\u5728\u3002\u7136\u800c\uff0c\u5206\u6790\u65b0\u7684\u4f53\u7cfb\u8fd9\u6837\u7684\u8fc7\u7a0b\u4e5f\u8bb8\u8fc7\u4e8e\u7e41\u6742\uff0c\u6211\u4eec\u53ef\u4ee5\u4ece\u5316\u5b66\u52bf\\(\\mu\\)\u5165\u624b\uff0c\u5206\u6790\u4e34\u754c\u72b6\u6001\uff0c\u4ece\u800c\u5224\u65ad\\(T_c\\)\u662f\u5426\u5b58\u5728\u3002\u4f8b\u5982\u5206\u6790\u4e8c\u7ef4\u73bb\u8272\u6c14\u4f53\u4e0d\u4f1a\u53d1\u751fBEC,\u4f46\u5904\u5728\u78c1\u5149\u9677\u9631\u4e2d\u7684\u4e8c\u7ef4\u539f\u5b50\u5374\u53ef\u4ee5\u3002</p>"},{"location":"chapter_08_bose_fermi_statistics/03_photon_gas.html","title":"\u8f90\u5c04\u7cfb\u7edf\u4e2d\u7684\u5149\u5b50\u6c14\u4f53","text":""},{"location":"chapter_08_bose_fermi_statistics/03_photon_gas.html#_1","title":"\u8f90\u5c04\u7cfb\u7edf\u4e2d\u7684\u5149\u5b50\u6c14\u4f53","text":"<p>\u2605 \u4e0e\u4e4b\u524d\u6ce2\u52a8\u7684\u89c2\u70b9\u4e0d\u540c\uff0c\u8fd9\u91cc\u5c06\u8f90\u5c04\u7cfb\u7edf\u770b\u4f5c\u7531\u5168\u540c\u7684\u5149\u5b50\u7ec4\u6210\u7684\u7cfb\u7edf\u3002\u6ce8\u610f\u5230\u5149\u5b50\u5316\u5b66\u52bf\\(\\mu=0\\Rightarrow e^\\alpha=1\\),\u6545\u5c5e\u4e8e\u5f3a\u7b80\u5e76\u7684\u60c5\u51b5\uff0c\u4ece\u800c\u4e0d\u80fd\u4f7f\u7528\u7c92\u5b50\u914d\u5206\u51fd\u6570\u8fdb\u884c\u8ba1\u7b97\uff0c\u800c\u8981\u4f7f\u7528\u5de8\u914d\u5206\u51fd\u6570\u3002\u5149\u5b50\u7684\u81ea\u65cb\u4e3a1,\u6309\u5e38\u7406\u6765\u8bf4\u5e94\u8be5\u6709\\(-1,0,1\\)\u4e09\u79cd\u81ea\u65cb\u6001\uff0c\u4f46\u7531\u4e8e\u4e0d\u5b58\u5728\u4e00\u4e2a\u5149\u5b50\u7684\u9759\u6b62\u53c2\u8003\u7cfb\uff0c\u56e0\u6b64\u5bf9\u4e8e\u4efb\u4f55\u89c2\u5bdf\u8005\u6765\u8bf4\uff0c\u5149\u90fd\u6709\u4e00\u4e2a\u8fd0\u52a8\u65b9\u5411\uff0c\u5176\u89d2\u52a8\u91cf\u90fd\u53ea\u80fd\u7ed5\u7740\u5176\u8fd0\u52a8\u65b9\u5411\u8fdb\u884c\u65cb\u8f6c\uff0c\u56e0\u6b64\u5c31\u53ea\u6709\u5de6\u65cb\u548c\u53f3\u65cb\u4e24\u79cd\u81ea\u65cb\u6001\u3002</p> <p>\u6b64\u5916\uff0c\u7531\u4e8e\u4e0a\u4e00\u7ae0\u5df2\u7ecf\u5f97\u5230\u8f90\u5c04\u7cfb\u7edf\u7684\u80fd\u91cf\u5206\u5e03\uff0c\u56e0\u6b64\u672c\u8282\u4ec5\u4ec5\u5229\u7528\u5de8\u914d\u5206\u51fd\u6570\u63a8\u5bfc\u7cfb\u7edf\u6574\u4f53\u7684\u6027\u8d28\uff0c\u4f53\u4f1a\u4e00\u4e0b\u5de8\u914d\u5206\u51fd\u6570\u7684\u4f7f\u7528\u65b9\u6cd5\u3002</p> \\[ ln\\Xi=-\\sum_l\\omega_lln(1-e^{-\\beta\\varepsilon_l})=-\\int_0^\\infty D(\\omega)ln(1-e^{-\\alpha-\\beta\\hbar\\omega})d\\omega \\] <p>\u4e0a\u5f0f\u5c06\u7b80\u5e76\u5ea6\u5316\u4e3a\u89d2\u9891\u7387\u7684\u6001\u5bc6\u5ea6\uff0c\u76f4\u63a5\u5229\u7528\u4e0a\u4e00\u7ae0\u63a8\u5bfc\u7684\u7ed3\u679c\u5f97\u5230\uff1a</p> \\[ ln\\Xi=-\\frac{V}{c^3\\pi^2}\\int_0^\\infty\\omega^2 ln(1-e^{-\\beta\\hbar\\omega})d\\omega=\\frac{\\pi^2V}{45c^3}\\frac{1}{(\\beta\\hbar)^3} \\] <p>\u6ce8\u610f\u4e0a\u5f0f\u9700\u8981\u5c06\\(\\omega^2d\\omega\\rightarrow \\frac{1}{3}d\\omega^3\\)\u8fdb\u884c\u4e00\u6b65\u5206\u90e8\u79ef\u5206\uff0c\u4ece\u800c\u5316\u4e3a\u719f\u6089\u7684\u79ef\u5206\u5f62\u5f0f\u8fdb\u884c\u8ba1\u7b97\u3002\u636e\u6b64\u53ef\u4ee5\u5bfc\u51fa\u5404\u79cd\u70ed\u529b\u5b66\u91cf:</p> \\[ U=-\\frac{\\partial}{\\partial\\beta}ln\\Xi=\\frac{\\pi^2k^4V}{15c^3\\hbar^3}T^4\\qquad p=\\frac{U}{3V}=\\frac{\\pi^2k^4}{45c^3\\hbar^3}T^4 \\] \\[ J_u=\\frac{cU}{4V}=\\frac{\\pi^2k^4}{60c^2\\hbar^3}T^4\\qquad S=k\\left(ln\\Xi-\\beta\\frac{\\partial}{\\partial\\beta}ln\\Xi\\right)=\\frac{4\\pi^2k^4V}{45c^3\\hbar^3}T^3V \\] <p>\u6ce8\u610f\u8f90\u5c04\u901a\u91cf\u5bc6\u5ea6\\(J_u\\)\u662f\u57fa\u4e8e\u4e09\u7ef4\u7684\u6548\u679c\uff0c\u5bf9\u4e8e\u4e8c\u7ef4\u8f90\u5c04\u6709\\(J_u=\\frac{cU}{\\pi V}\\).</p> <p>\u2605 \u5bf9\u4e8e\u8f90\u5c04\u7cfb\u7edf\uff0c\u65e2\u53ef\u4ee5\u5229\u7528\u6ce2\u52a8\u7684\u89c2\u70b9\uff0c\u4ea6\u53ef\u5229\u7528\u7c92\u5b50\u7684\u89c2\u70b9\uff0c\u867d\u7136\u4e24\u8005\u7684\u6570\u5b66\u5904\u7406\u5dee\u5f02\u5f88\u5927\uff0c\u4f46\u7ed3\u679c\u5b8c\u5168\u76f8\u540c\u3002\u8fd9\u4e00\u70b9\u5728\u5206\u6790\u56fa\u4f53\u70ed\u5bb9\u65f6\uff0c\u65e2\u53ef\u4ee5\u7528\u8c10\u632f\u5b50\u7684\u89c2\u70b9\uff0c\u4e5f\u53ef\u4ee5\u5229\u7528\u58f0\u5b50\u7684\u89c2\u70b9\u7c7b\u4f3c\u3002\u8fd9\u4e00\u7c7b\u5c06\u4f53\u7cfb\u7684\u6ce2\u52a8\uff0c\u5229\u7528\u7c92\u5b50\u7684\u89c2\u70b9\u5206\u6790\u7684\u65b9\u6cd5\u53eb\u5143\u6fc0\u53d1\uff0c\u4e5f\u53ef\u7406\u89e3\u4e3a\u4e8c\u6b21\u91cf\u5b50\u5316\u6216\u573a\u91cf\u5b50\u5316\u3002\u901a\u5e38\u5728\u6e29\u5ea6\u4e0d\u592a\u9ad8\u7684\u4f4e\u80fd\u7cfb\u7edf\u4e2d\u6bd4\u8f83\u5e38\u7528\uff0c\u5177\u4f53\u7ec6\u8282\u53ef\u53c2\u8003\u51dd\u805a\u6001\u7684 \u76f8\u5173\u4e66\u7c4d\u3002</p>"},{"location":"chapter_08_bose_fermi_statistics/04_free_electron_gas.html","title":"\u91d1\u5c5e\u4e2d\u7684\u81ea\u7531\u7535\u5b50\u6c14\u4f53","text":""},{"location":"chapter_08_bose_fermi_statistics/04_free_electron_gas.html#_1","title":"\u91d1\u5c5e\u4e2d\u7684\u81ea\u7531\u7535\u5b50\u6c14\u4f53","text":"<p>\u2605 \u672c\u8282\u7814\u7a76\u91d1\u5c5e\u4e2d\u7684\u81ea\u7531\u5bfc\u7535\u7535\u5b50\u7684\u7279\u6027\uff0c\u7531\u4e8e\u5176\u5f25\u6563\u5728\u6574\u4e2a\u91d1\u5c5e\u5185\uff0c\u6545\u53ef\u4ee5\u5c06\u5b83\u4eec\u770b\u4f5c\u81ea\u7531\u7535\u5b50\u6c14\u4f53\u3002\u5229\u7528\u94dc\u539f\u5b50\u7684\u6570\u636e\uff0c\u5e76\u5047\u8bbe\u4e00\u4e2a\u94dc\u539f\u5b50\u8d21\u732e\u4e00\u4e2a\u7535\u5b50\uff0c\u5f97\u5230\\(n\\lambda_T^3\\approx3400\\gg1\\),\u6545\u4e3a\u5f3a\u7b80\u5e76\u60c5\u51b5\u3002</p> <p>\u7535\u5b50\u7684\u81ea\u65cb\u4e3a\\(\\frac{1}{2}\\),\u4ece\u800c\u81ea\u65cb\u81ea\u7531\u5ea6\u4e3a2.\u8fd9\u91cc\u5047\u8bbe\u7535\u5b50\u7684\u901f\u5ea6\u4e0d\u591f\u5feb\uff0c\u4ece\u800c\u6ee1\u8db3\u7ecf\u5178\u7684\u80fd\u91cf\u52a8\u91cf\u5173\u7cfb\u3002\u6545\u4e00\u4e2a\u91cf\u5b50\u6001\u4e0a\u7684\u5e73\u5747\u7535\u5b50\u6570\u4e3a\uff1a</p> \\[ f(\\varepsilon)=\\frac{1}{e^{(\\varepsilon-\\mu)/kT}+1}\\qquad \\varepsilon=\\frac{p^2}{2m}\\qquad D(\\varepsilon)=\\frac{4\\pi V}{h^3}(2m)^{\\frac{3}{2}}\\varepsilon^{\\frac{1}{2}} \\] <p>\u6709\u65f6\u4e3a\u4e86\u65b9\u4fbf\uff0c\u6c42\u89e3\u67d0\u4e9b\u70ed\u529b\u5b66\u91cf\u65f6\uff0c\u4e0d\u4e00\u5b9a\u8981\u4ece\u5de8\u914d\u5206\u51fd\u6570\u51fa\u53d1\uff0c\u800c\u662f\u7528\u7edf\u8ba1\u5e73\u5747\u7684\u601d\u60f3\uff0c\u76f4\u63a5\u4e0e\u70ed\u529b\u5b66\u91cf\u76f8\u8054\u7cfb\uff1a</p> \\[ \\bar{N}=\\sum_sf_s=\\int_0^\\infty f(\\varepsilon)D(\\varepsilon)d\\varepsilon\\quad U=\\sum_s\\varepsilon_sf_s=\\int_0^\\infty \\varepsilon f(\\varepsilon)D(\\varepsilon)d\\varepsilon\\quad p=\\frac{2U}{3V} \\] <p>\u7531\u6b64\u53ef\u89c1\uff0c\u786e\u5b9a\\(f(\\varepsilon)\\)\u548c\\(D(\\varepsilon)\\)\u7684\u5f62\u5f0f\u5341\u5206\u91cd\u8981\u3002</p> <p>\u2605 \u9996\u5148\u8003\u8651\\(T=0K\\)\u7684\u7406\u60f3\u60c5\u51b5\uff0c\u8bbe\u6b64\u65f6\u5316\u5b66\u52bf\u4e3a\\(\\mu(0)\\),\u90a3\u4e48\\(f(\\varepsilon)\\)\u5728\\(\\varepsilon&lt;\\mu(0)\\)\u7684\u503c\u4e3a1\uff0c\u5728\\(\\varepsilon&gt;\\mu(0)\\)\u7684\u503c\u4e3a0,\u76f8\u5f53\u4e8e\u4e00\u4e2a\u9636\u8dc3\u51fd\u6570\u3002\u4ece\u7269\u7406\u4e0a\u8bb2\uff0c\u5f53\\(T=0K\\)\u7535\u5b50\u4f1a\u5c3d\u53ef\u80fd\u5360\u636e\u6700\u4f4e\u7684\u80fd\u7ea7\uff0c\u4f46\u7531\u4e8e\u6ce1\u5229\u4e0d\u76f8\u5bb9\u539f\u7406\uff0c\u4e24\u4e2a\u7535\u5b50\u4e0d\u80fd\u5360\u636e\u540c\u4e00\u4e2a\u91cf\u5b50\u6001\uff0c\u8fdb\u800c\u4f7f\u5f97\u7535\u5b50\u53ef\u4ee5\u5360\u636e\u8f83\u9ad8\u7684\u80fd\u7ea7\uff0c\u800c\u6700\u9ad8\u7684\u80fd\u7ea7\u88ab\u79f0\u4e3a\u8d39\u7c73\u80fd\u7ea7\uff0c\u8bb0\u4f5c\\(\\varepsilon_F\\),\u4e5f\u5c31\u662f\u8fd9\u91cc\\(0K\\)\u7684\u5316\u5b66\u52bf\\(\\mu(0)\\).\u6839\u636e\u603b\u7535\u5b50\u6570\\(N\\)\uff1a</p> \\[ N=\\int_0^\\infty f(\\varepsilon)D(\\varepsilon)d\\varepsilon=\\int_0^{\\mu(0)} D(\\varepsilon)d\\varepsilon=\\frac{8\\pi V}{3h^3}[2m\\mu(0)]^{\\frac{3}{2}} \\] \\[ \\Rightarrow\\quad\\boxed{\\varepsilon_F=\\mu(0)=\\frac{\\hbar^2}{2m}(3\\pi^2 n)^{\\frac{2}{3}}} \\] <p>\u7531\u8d39\u7c73\u80fd\u7ea7\uff0c\u53ef\u4ee5\u5f15\u51fa\u8d39\u7c73\u52a8\u91cf\u3001\u8d39\u7c73\u901f\u5ea6\u548c\u8d39\u7c73\u6e29\u5ea6\uff1a</p> \\[ p_F=\\sqrt{2m\\varepsilon_F}=\\hbar(3\\pi^2n)^{\\frac{1}{3}}\\qquad v_F=\\frac{p_F}{m}\\qquad T_F=\\frac{\\varepsilon_F}{k} \\] <p>\u53ef\u89c1\uff0c\u9664\u5e38\u6570\u5916\uff0c\u4f53\u5bc6\u5ea6\\(n\\)\u5728\u8fd9\u4e9b\u91cf\u4e2d\u8d77\u51b3\u5b9a\u6027\u4f5c\u7528\u3002\u53ef\u77e5\uff0c\u7535\u5b50\u7684\u52a8\u80fd\u4e0e\\(n^{\\frac{2}{3}}\\)\u6210\u6b63\u6bd4\uff1b\u7535\u5b50\u4e4b\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\u80fd\uff0c\u7531\u4e8e\u4f53\u5bc6\u5ea6\u4e3a3\u7ef4\u7684\uff0c\u6545\u4e0e\\(\\frac{1}{r}\\sim n^{\\frac{1}{3}}\\)\u6210\u6b63\u6bd4\u3002\u4ece\u800c\u4f53\u5bc6\u5ea6\\(n\\)\u8d8a\u5927\uff0c\u76f8\u4e92\u4f5c\u7528\u8d8a\u5bb9\u6613\u5ffd\u7565\uff0c\u4ece\u800c\u8d8a\u63a5\u8fd1\u7406\u60f3\u6c14\u4f53\u3002\u4e0e\u4e4b\u76f8\u53cd\uff0c\u82e5\u4f53\u5bc6\u5ea6\\(n\\)\u5f88\u5c0f\uff0c\u5219\u4f1a\u51fa\u73b0\u7ef4\u683c\u7eb3\u6676\u683c\u7684\u73b0\u8c61</p> <p>\u65e2\u7136\\(\\mu(0)\\)\u5df2\u7ecf\u6c42\u51fa\uff0c\u5373\u53ef\u5229\u7528\u7edf\u8ba1\u5e73\u5747\u7684\u65b9\u6cd5\u5f97\u5230\u5185\u80fd\u548c\u538b\u5f3a\uff1a</p> \\[ U=\\int_0^\\infty \\varepsilon f(\\varepsilon)D(\\varepsilon)d\\varepsilon=\\int_0^{\\mu(0)} \\varepsilon D(\\varepsilon)d\\varepsilon=\\frac{3}{5}N\\mu(0) \\] \\[ p(0)=\\frac{2U}{3V}=\\frac{2}{5}n\\mu(0) \\] <p>\u2605 \u73b0\u5728\u8003\u5bdf\\(T\\neq0K\\)\u7684\u60c5\u51b5\uff0c\u6839\u636e\u603b\u7535\u5b50\u6570\\(N\\)\u548c\u5185\u80fd\\(U\\)\u7684\u7edf\u8ba1\u5e73\u5747\uff1a</p> \\[ N=\\int_0^\\infty f(\\varepsilon)D(\\varepsilon)d\\varepsilon=\\frac{4\\pi V}{h^3}(2m)^{\\frac{3}{2}}\\int_0^\\infty\\frac{\\varepsilon^{\\frac{1}{2}}d\\varepsilon}{e^{(\\varepsilon-\\mu)/kT}+1} \\] \\[ U=\\int_0^\\infty \\varepsilon f(\\varepsilon)D(\\varepsilon)d\\varepsilon=\\frac{4\\pi V}{h^3}(2m)^{\\frac{3}{2}}\\int_0^\\infty\\frac{\\varepsilon^{\\frac{3}{2}}d\\varepsilon}{e^{(\\varepsilon-\\mu)/kT}+1} \\] <p>\u5bf9\u4e8e\u4e0a\u5f0f\u7684\u79ef\u5206\uff0c\u53ef\u4ee5\u76f4\u63a5\u5957\u7528\u7d22\u672b\u83f2\u5c55\u5f00\u7684\u516c\u5f0f\uff1a</p> \\[ \\int_{-\\infty}^{\\infty}\\frac{H(\\varepsilon)}{e^{\\beta(\\varepsilon-\\mu)}+1}d\\varepsilon=\\int_{-\\infty}^\\mu H(\\varepsilon)d\\varepsilon+\\frac{\\pi^2}{6}\\left(\\frac{1}{\\beta}\\right)^2 H'(\\mu)+O\\left(\\frac{1}{\\beta\\mu}\\right)^4 \\] <p>\u53ef\u4ee5\u5c06\\(H(\\varepsilon)\\)\u5904\u7406\u6210\u5206\u6bb5\u51fd\u6570\uff0c\u5373\\(\\varepsilon&lt;0\\)\u65f6\uff0c\\(H(\\varepsilon)=0\\);\u800c\\(\\varepsilon\\geqslant0\\)\u65f6\uff0c\\(H(\\varepsilon)\\)\u4e3a\\(\\varepsilon^{\\frac{1}{2}}\\)\u6216\\(\\varepsilon^{\\frac{3}{2}}\\),\u4e3a\u4e86\u8868\u8fbe\u65b9\u4fbf\u4ee4\\(C=\\frac{4\\pi V}{h^3}(2m)^{\\frac{3}{2}}\\),\u4e0d\u96be\u5f97\u5230\uff1a</p> \\[ N=\\frac{2}{3}C\\mu^{\\frac{3}{2}}\\left[1+\\frac{\\pi^2}{8}\\left(\\frac{kT}{\\mu}\\right)^2\\right]\\qquad U=\\frac{2}{5}C\\mu^{\\frac{5}{2}}\\left[1+\\frac{5\\pi^2}{8}\\left(\\frac{kT}{\\mu}\\right)^2\\right] \\] <p>\u7531\u6b64\u4e5f\u53ef\u89e3\u51fa\u5316\u5b66\u52bf\uff1a</p> \\[ \\mu=\\left(\\frac{3N}{2C}\\right)^{\\frac{2}{3}}\\left[1+\\frac{\\pi^2}{8}\\left(\\frac{kT}{\\mu}\\right)^2\\right]^{-\\frac{2}{3}}\\approx\\mu(0)\\left[1+\\frac{\\pi^2}{8}\\left(\\frac{kT}{\\mu(0)}\\right)^2\\right]^{-\\frac{2}{3}}\\approx\\mu(0)\\left[1-\\frac{\\pi^2}{12}\\left(\\frac{kT}{\\mu(0)}\\right)^2\\right] \\] <p>\u4e3a\u4e86\u5f97\u5230\u5316\u5b66\u52bf\\(\\mu\\)\u968f\u6e29\u5ea6\u7684\u663e\u5f0f\uff0c\u8fd9\u91cc\u5c06\u7b2c\u4e8c\u9879\u7684\\(\\mu\\)\u8fd1\u4f3c\u4e3a\\(\\mu(0)\\),\u5e76\u8fdb\u884c\u591a\u9879\u5f0f\u8fd1\u4f3c\u5f97\u5230\u4e0a\u8ff0\u8868\u8fbe\u5f0f\u3002\u53ef\u89c1\u5316\u5b66\u52bf\u968f\u7740\u6e29\u5ea6\u4e0a\u5347\u800c\u4e0b\u964d\u3002\u7531\u6b64\uff0c\u53ef\u5bfc\u51fa\u91d1\u5c5e\u4e2d\u7535\u5b50\u8d21\u732e\u7684\u70ed\u5bb9\uff1a</p> \\[ U\\approx\\frac{3}{5}N\\mu(0)\\left[1+\\frac{5}{12}\\pi^2\\left(\\frac{kT}{\\mu(0)}\\right)^2\\right]\\quad\\Rightarrow\\quad C_V^e=\\left(\\frac{\\partial U}{\\partial T}\\right)_V=Nk\\frac{\\pi^2kT}{2\\mu(0)}=\\gamma_0T \\] <p>\u53ef\u89c1\uff0c\u7535\u5b50\u70ed\u5bb9\u4e0e\u6e29\u5ea6\u662f\u6b63\u6bd4\u5173\u7cfb\uff0c\u7ed3\u5408\u4e4b\u524d\u5fb7\u62dc\u56fa\u4f53\u70ed\u5bb9\u7684\u7406\u8bba\uff0c\u53ef\u5c06\u91d1\u5c5e\u4f4e\u6e29\u70ed\u5bb9\u8868\u8fbe\u5982\u4e0b\uff1a</p> \\[ C_V=\\gamma_0T+AT^3 \\]"},{"location":"chapter_09_ensembles/index.html","title":"\u7ae0\u8282\u6982\u89c8","text":""},{"location":"chapter_09_ensembles/index.html#9","title":"\u7b2c9\u7ae0 \u7cfb\u7efc\u7406\u8bba","text":"<p>\u4e0e\u8fd1\u72ec\u7acb\u5b50\u7cfb\u7684\u5b50\u76f8\u7a7a\u95f4\u4e0d\u540c\uff0c\u672c\u7ae0\u5c06\u5728\u76f8\u7a7a\u95f4\u4e2d\u7814\u7a76\u95ee\u9898\uff0c\u56e0\u800c\u53ef\u4ee5\u5904\u7406\u7c92\u5b50\u95f4\u7684\u76f8\u4e92\u4f5c\u7528\uff0c\u5e76\u4e14\u57fa\u672c\u7684\u7814\u7a76\u5355\u5143\u4ece\u7c92\u5b50\u53d8\u4e3a\u4e86\u7cfb\u7edf\uff0c\u4ece\u800c\u5f15\u51fa\u7cfb\u7efc\u7684\u6982\u5ff5\u3002\u7cfb\u7efc\u7406\u8bba\u7684\u89c6\u91ce\u66f4\u4e3a\u5e7f\u9614\uff0c\u662f\u7edf\u8ba1\u7269\u7406\u7684\u57fa\u672c\u5de5\u5177\u3002</p> <p>\u672c\u7ae0\u7684\u6838\u5fc3\u662f\u638c\u63e1\u4e09\u79cd\u6700\u5e38\u89c1\u7684\u7cfb\u7efc\uff1a\u5fae\u6b63\u5219\u7cfb\u7efc\u3001\u6b63\u5219\u7cfb\u7efc\u3001\u5de8\u6b63\u5219\u7cfb\u7efc\uff0c\u7406\u89e3\u63a8\u5bfc\u7684\u51fa\u53d1\u70b9\u4e0e\u7cfb\u7efc\u76f8\u4e92\u4e4b\u95f4\u7684\u8054\u7cfb\uff0c\u4ee5\u53ca\u5bf9\u6bd4\u914d\u5206\u51fd\u6570\u548c\u70ed\u529b\u5b66\u91cf\u8868\u8fbe\u5f0f\u4e0e\u5b50\u76f8\u7a7a\u95f4\u7684\u5f02\u540c\u3002</p>"},{"location":"chapter_09_ensembles/index.html#_1","title":"\u5c0f\u7ed3\u76ee\u5f55","text":"<ul> <li>\u76f8\u7a7a\u95f4\u4e0e\u5218\u7ef4\u5c14\u5b9a\u7406</li> <li>\u5fae\u6b63\u5219\u7cfb\u7efc</li> <li>\u6b63\u5219\u7cfb\u7efc</li> <li>\u5de8\u6b63\u5219\u7cfb\u7efc</li> <li>\u53c2\u8003\u8d44\u6599</li> </ul>"},{"location":"chapter_09_ensembles/01_phase_space_liouville.html","title":"\u76f8\u7a7a\u95f4\u4e0e\u5218\u7ef4\u5c14\u5b9a\u7406","text":""},{"location":"chapter_09_ensembles/01_phase_space_liouville.html#_1","title":"\u76f8\u7a7a\u95f4\u4e0e\u5218\u7ef4\u5c14\u5b9a\u7406","text":"<p>\u2605 \u82e5\u6240\u7814\u7a76\u7684\u7cfb\u7edf\u7531\u76f8\u4e92\u4f5c\u7528\u7684\u591a\u79cd\u7c92\u5b50\u7ec4\u6210\uff0c\u7b2c\\(i\\)\u79cd\u7c92\u5b50\u7684\u81ea\u7531\u5ea6\u4e3a\\(r_i\\),\u7c92\u5b50\u6570\u4e3a\\(N_i\\),\u4ece\u800c\u7cfb\u7edf\u7684\u81ea\u7531\u5ea6\u4e3a\\(f=\\sum_ir_iN_i\\),\u6240\u5bf9\u5e94\u76f8\u7a7a\u95f4\\(\\Gamma\\)\u7684\u7ef4\u6570\u4e3a\\(2f\\).\u7cfb\u7edf\u72b6\u6001\u7531\u76f8\u7a7a\u95f4\u4e2d\u4ee3\u8868\u70b9\\((q_1,...,q_f,p_1,...,p_f)\\)\u8868\u793a\uff0c\u5e76\u7531\u6b63\u5219\u65b9\u7a0b\uff1a</p> \\[ \\frac{\\partial H}{\\partial p_i}=\\dot{q_i}\\qquad\\frac{\\partial H}{\\partial q_i}=-\\dot{p_i}\\quad (i=1,2,...,f) \\] <p>\u786e\u5b9a\u4ee3\u8868\u70b9\u7684\u8f68\u8ff9\uff0c\u5373\u7cfb\u7edf\u72b6\u6001\u968f\u65f6\u95f4\u7684\u53d8\u5316\u3002\u4e3a\u4e86\u533a\u5206\u5b50\u76f8\u7a7a\u95f4\u4e2d\u7684\u4f53\u79ef\u5143\\(d\\omega\\),\u76f8\u7a7a\u95f4\u4e2d\u91c7\u7528\\(d\\Omega\\)\u8868\u793a\u4f53\u79ef\u5143\uff1a</p> \\[ \\rho(q_1,...q_f,p_1,...,p_f,t)dq_1...dq_fdp_1...dp_f=\\rho(q_1,...q_f,p_1,...,p_f,t)d\\Omega \\] <p>\u5176\u4e2d\\(\\rho d\\Omega\\)\u8868\u793a\u7cfb\u7edf\u4ee3\u8868\u70b9\u5728\\(d\\Omega\\)\u5904\u51fa\u73b0\u7684\u6982\u7387\uff0c\u79f0\u4e3a\u7cfb\u7edf\u5fae\u89c2\u72b6\u6001\u7684\u6982\u7387\u5bc6\u5ea6\u3002\u7ed3\u5408\u6982\u7387\u5bc6\u5ea6\u7684\u4e00\u822c\u6027\u8d28\uff0c\u6709\uff1a</p> \\[ \\int\\rho d\\Omega=1\\qquad\\bar{A}=\\int A\\cdot\\rho d\\Omega \\] <p>\u5206\u522b\u8868\u793a\u6982\u7387\u5f52\u4e00\u5316\u548c\u529b\u5b66\u91cf\\(A\\)\u7684\u7edf\u8ba1\u5e73\u5747\u3002\u4ece\u800c\uff0c\u6c42\u89e3\\(\\rho\\)\u7684\u5177\u4f53\u8868\u8fbe\u5f0f\uff0c\u4fbf\u662f\u7edf\u8ba1\u7269\u7406\u7684\u6838\u5fc3\u4efb\u52a1\u3002</p> <p>\u6709\u65f6\u8fd8\u4f1a\u5f15\u5165\u4ee3\u8868\u70b9\u5bc6\u5ea6\\(\\widetilde{\\rho}\\).\u4ece\u800c\\(\\widetilde{\\rho}d\\Omega\\)\u8868\u793a\u5728\\(d\\Omega\\)\u8303\u56f4\u5185\uff0c\u4ee3\u8868\u70b9\u7684\u4e2a\u6570\uff0c\u4e5f\u5c31\u662f\u7cfb\u7edf\u5fae\u89c2\u72b6\u6001\u7684\u4e2a\u6570\u3002\u8bbe\\(\\mathscr{N}\\)\u4e3a\u7cfb\u7edf\u5fae\u89c2\u6001\u7684\u603b\u6570\uff0c\u4ece\u800c\uff1a</p> \\[ \\rho d\\Omega=\\frac{\\widetilde{\\rho}d\\Omega}{\\int\\widetilde{\\rho}d\\Omega}=\\frac{\\widetilde{\\rho}d\\Omega}{\\mathscr{N}}\\propto\\widetilde{\\rho}d\\Omega\\qquad\\int\\widetilde{\\rho}d\\Omega=\\mathscr{N} \\] <p>\u53ef\u89c1\\(\\rho d\\Omega\\)\u4e0e\\(\\widetilde{\\rho}d\\Omega\\)\u6210\u6b63\u6bd4\u5173\u7cfb\u3002</p> <p>\u2605 \u901a\u5e38\u6765\u8bf4\uff0c\u4e3a\u4e86\u7814\u7a76\u4e00\u679a\u786c\u5e01\u6295\u63b7\u540e\u51fa\u73b0\u6b63\u53cd\u9762\u7684\u6982\u7387\uff0c\u4f1a\u5c06\u786c\u5e01\u5728\u4e00\u4e2a\u65f6\u95f4\u6bb5\u5185\u53cd\u590d\u6295\u63b7\uff0c\u7edf\u8ba1\u4e24\u79cd\u72b6\u6001\u51fa\u73b0\u7684\u6b21\u6570\uff0c\u4ece\u800c\u8ba1\u7b97\u786c\u5e01\u4e24\u79cd\u72b6\u6001\u51fa\u73b0\u7684\u6982\u7387\u3002\u7136\u800c\uff0c\u8fd9\u79cd\u505a\u6cd5\u5fc5\u7136\u6d89\u53ca\u5230\u5229\u7528\u65f6\u95f4\u6765\u533a\u5206\u6295\u63b7\u7684\u6b21\u6570\uff0c\u4ece\u800c\u5bf9\u65f6\u95f4\u5f62\u6210\u4f9d\u8d56\u3002\u4e3a\u4e86\u6446\u8131\u5bf9\u65f6\u95f4\u7684\u4f9d\u8d56\uff0c\u53ef\u4ee5\u5728\u540c\u4e00\u65f6\u523b\u6295\u63b7\u5927\u91cf\u76f8\u540c\u7684\u786c\u5e01\uff0c\u4ece\u800c\u4e00\u6b21\u6027\u5f97\u51fa\u7ed3\u679c\u3002\u5982\u679c\u5c06\u201c\u786c\u5e01\u201d\u89c6\u4f5c\u6211\u4eec\u6240\u7814\u7a76\u7684\u201c\u7cfb\u7edf\u201d\uff0c\u90a3\u4e48\u201c\u5927\u91cf\u76f8\u540c\u7684\u786c\u5e01\u201d\u5373\u4e3a\u201c\u7cfb\u7efc\u201d\u7684\u5bf9\u5e94\u3002\u53ef\u89c1\uff0c\u7cfb\u7efc\u4ec5\u4ec5\u662f\u4e00\u4e2a\u6982\u5ff5\u6027\u8d28\u7684\u5de5\u5177\uff0c\u5f15\u5165\u7684\u76ee\u7684\u662f\u7528\u7cfb\u7efc\u5e73\u5747\u6765\u4ee3\u66ff\u65f6\u95f4\u5e73\u5747\u3002</p> <p>\u8fdb\u4e00\u6b65\u8bf4\uff0c\u6309\u7167\u7cfb\u7efc\u7684\u7cbe\u795e\uff0c\u7cfb\u7efc\u53ef\u4ee5\u770b\u4f5c\u662f\u6240\u7814\u7a76\u7684\u7cfb\u7edf\u5728\u4e00\u5b9a\u5b8f\u89c2\u6761\u4ef6\u4e0b\u7684\u5404\u79cd\u5fae\u89c2\u72b6\u6001\u7684\u201c\u5316\u8eab\u201d\u3002\u90a3\u4e48\\(\\mathscr{N}\\)\u4e2a\u5fae\u89c2\u72b6\u6001\u5c31\u5bf9\u5e94\u7740\\(\\mathscr{N}\\)\u4e2a\u5047\u60f3\u7684\u7cfb\u7edf\uff0c\u5b83\u4eec\u7ec4\u6210\u7684\u96c6\u5408\u5c31\u662f\u7cfb\u7efc\u3002</p> <p>\u2605 \u8bbe\u7cfb\u7edf\u7684\u54c8\u5bc6\u987f\u91cf\\(H(q_1,...,q_f,p_1,...,p_f)\\)\u4e0d\u663e\u542b\u65f6\u95f4\\(t\\)\uff0c\u5373\u7cfb\u7edf\u4e3a\u4fdd\u5b88\u7cfb\u3002\u4e3a\u4e86\u65b9\u4fbf\u7406\u89e3\uff0c\u5229\u7528\\(\\rho d\\Omega\\)\u4e0e\\(\\widetilde{\\rho}d\\Omega\\)\u6210\u6b63\u6bd4\u7684\u6027\u8d28\uff0c\u5148\u8ba8\u8bba\u4ee3\u8868\u70b9\u5bc6\u5ea6\\(\\widetilde{\\rho}\\)\uff0c\u5e76\u5b9a\u4e49\u76f8\u7a7a\u95f4\u4e2d\u7684\u5750\u6807\\(\\vec{r}\\)\u548c\u901f\u5ea6\\(\\vec{v}\\)\uff1a</p> \\[ \\vec{r}=(q_1,...,q_f,p_1,...,p_f)\\qquad\\vec{v}=(\\dot{q_1},...,\\dot{q_f},\\dot{p_1},...,\\dot{p_f}) \\] <p>\u7c7b\u6bd4\u6d41\u5bc6\u5ea6\u5b88\u6052\u7684\u8868\u8fbe\u5f0f\u6709\uff1a</p> \\[ -\\frac{\\partial\\widetilde{\\rho}}{\\partial t}=\\nabla\\cdot(\\widetilde{\\rho}\\vec{v})=\\nabla\\widetilde{\\rho}\\cdot\\vec{v}+\\widetilde{\\rho}\\nabla\\cdot\\vec{v}=\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial q_i}\\dot{q_i}+\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial p_i}\\dot{p_i}+\\widetilde{\\rho}\\left(\\sum_{i=1}^f\\frac{\\partial\\dot{q_i}}{\\partial q_i}+\\sum_{i=1}^f\\frac{\\partial\\dot{p_i}}{\\partial p_i}\\right) \\] <p>\u4ee3\u5165\u4fdd\u5b88\u7cfb\u7684\u6b63\u5219\u65b9\u7a0b\uff0c\u5e76\u9ed8\u8ba4\u4e8c\u9636\u504f\u5bfc\u53ef\u4ea4\u6362\uff0c\u5219\u6709\uff1a</p> \\[ =\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial q_i}\\dot{q_i}+\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial p_i}\\dot{p_i}+\\widetilde{\\rho}\\left(\\sum_{i=1}^f\\frac{\\partial^2H}{\\partial q_i\\partial p_i}-\\sum_{i=1}^f\\frac{\\partial^2H}{\\partial p_i\\partial q_i}\\right)=\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial q_i}\\dot{q_i}+\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial p_i}\\dot{p_i} \\] \\[ \\Rightarrow-\\frac{\\partial\\widetilde{\\rho}}{\\partial t}=\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial q_i}\\dot{q_i}+\\sum_{i=1}^f\\frac{\\partial\\widetilde{\\rho}}{\\partial p_i}\\dot{p_i} \\] <p>\u4ece\u800c\u5f97\u5230\uff1a</p> \\[ \\Rightarrow\\frac{d\\widetilde{\\rho}}{dt}=\\frac{\\partial \\widetilde{\\rho}}{\\partial t}+\\sum_{i=1}^f\\left(\\frac{\\partial \\widetilde{\\rho}}{\\partial q_i}\\dot{q_i}+\\frac{\\partial \\widetilde{\\rho}}{\\partial p_i}\\dot{p_i}\\right)=0 \\] <p>\u8fd9\u5c31\u662f\u5218\u7ef4\u5c14\u5b9a\u7406\uff0c\u53c8\u79f0\u4e3a\u5bc6\u5ea6\u4e0d\u53d8\u6216\u6d41\u4f53\u4e0d\u53ef\u538b\u7f29\u5b9a\u7406\u3002\u5218\u7ef4\u5c14\u5b9a\u7406\u5bf9\u7b49\u6982\u7387\u5047\u8bbe\u662f\u4e2a\u6709\u529b\u7684\u652f\u6301\u3002\u76f8\u7a7a\u95f4\u4e2d\u7684\u4e00\u4e2a\u7cfb\u7edf\u7684\u4e0d\u540c\u5fae\u89c2\u72b6\u6001\u7528\u4ee3\u8868\u70b9\u8868\u793a\uff0c\u5982\u679c\u8fd9\u4e9b\u70b9\u5728\u67d0\u4e00\u65f6\u523b\u662f\u5747\u5300\u5206\u5e03\u7684\uff0c\u5219\u5728\u4efb\u4f55\u65f6\u523b\u4e5f\u662f\u5747\u5300\u7684\uff0c\u65e2\u4e0d\u6269\u5f20\uff0c\u4e5f\u4e0d\u4f1a\u7f29\u5c0f\u3002\u8fd9\u662f\u76f8\u5bc6\u5ea6\u5b88\u6052\u7684\u81ea\u7136\u7ed3\u679c\u3002\u76f8\u5bc6\u5ea6\u7684\u7269\u7406\u610f\u4e49\u662f\u8868\u793a\u5728\u67d0\u65f6\u523b\u5728\u76f8\u7b49\u7684\u4f53\u79ef\u5185\u627e\u5230\u7684\u6982\u7387\u91cf\u5ea6\u3002\u6240\u4ee5\uff0c\u5bc6\u5ea6\u4e0d\u53d8\u5373\u8868\u793a\u7b49\u6982\u7387\u5047\u8bbe\u662f\u6210\u7acb\u7684\u3002</p> <p>\u4e5f\u5c31\u662f\u8bf4\uff0c\u6839\u636e\u6b63\u6bd4\u5173\u7cfb\uff0c\u4e5f\u53ef\u4ee5\u8868\u8ff0\u5982\u4e0b\uff1a</p> \\[ \\boxed{\\frac{d\\rho}{dt}=0} \\] <p>\u6b64\u5916\u8981\u6ce8\u610f\u4e24\u70b9(1)\\(\\frac{d\\rho}{dt}=0\\)\u8868\u793a\u4e24\u4e2a\u533a\u57df\u7684\u6982\u7387\u5bc6\u5ea6\u4e0d\u968f\u65f6\u95f4\u53d8\u5316\uff1b\\(\\frac{\\partial\\rho}{\\partial t}=0\\)\u8868\u793a\u540c\u4e00\u533a\u57df\u7684\u6982\u7387\u5bc6\u5ea6\u4e0d\u968f\u65f6\u95f4\u53d8\u5316\uff0c\u5373\u7cfb\u7edf\u8fbe\u5230\u5e73\u8861\u6001\u3002 (2)\u7531\u4e8e\u8fd9\u91cc\u9ed8\u8ba4\u6b63\u5219\u65b9\u7a0b\u4e3a\u4fdd\u5b88\u7cfb\u4e0b\u7684\u5f62\u5f0f\uff0c\u6545\u9700\u8981\u6ce8\u610f\u5218\u7ef4\u5c14\u5b9a\u7406\u7684\u9002\u7528\u6761\u4ef6\u4e3a\u4fdd\u5b88\u7cfb\u3002</p>"},{"location":"chapter_09_ensembles/02_microcanonical_ensemble.html","title":"\u5fae\u6b63\u5219\u7cfb\u7efc","text":""},{"location":"chapter_09_ensembles/02_microcanonical_ensemble.html#_1","title":"\u5fae\u6b63\u5219\u7cfb\u7efc","text":"<p>\u2605 \u8003\u8651\u80fd\u91cf\u6052\u4e3a\\(E\\)\u7684\u5e73\u8861\u5b64\u7acb\u7cfb\u7edf\uff0c\u5373\u8ba4\u4e3a\u80fd\u91cfE\u3001\u4f53\u79efV\u548c\u7c92\u5b50\u6570N\u90fd\u4e3a\u5e38\u6570\u7684\u7cfb\u7edf\uff0c\u8be5\u7cfb\u7edf\u7ec4\u6210\u7684\u7cfb\u7efc\u79f0\u4e3a\u5fae\u6b63\u5219\u7cfb\u7efc\u3002\u7531\u4e8e\u5b64\u7acb\u548c\u5e73\u8861\u7684\u5c5e\u6027\uff0c\u6709\uff1a</p> \\[ \\frac{d\\rho}{dt}=0\\qquad\\frac{\\partial \\rho}{\\partial t}=0\\quad\\Rightarrow\\quad\\rho=Const. \\] <p>\u5982\u679c\u8fd9\u91cc\u76f4\u63a5\u627f\u8ba4\u7b49\u6982\u7387\u539f\u7406\uff0c\u53ef\u5f97\u5230\u7ecf\u5178\u7edf\u8ba1\u7cfb\u7efc\u7684\u5206\u5e03\u6982\u7387\\((\\Delta E \\rightarrow 0)\\) :</p> \\[ \\rho=\\left\\{\\begin{matrix} C\\quad &amp;E\\ll H\\ll E+\\Delta E \\\\ 0\\quad &amp;others \\end{matrix}\\right.\\qquad C=\\frac{1}{\\int_{\\Delta E}d\\Omega} \\] <p>\u4ee5\u53ca\u91cf\u5b50\u7edf\u8ba1\u7cfb\u7efc\u7684\u5206\u5e03\u6982\u7387\uff0c\u5176\u4e2d\\(\\Omega(N,E,V)\\)\u8868\u793a\u91cf\u5b50\u6001\u603b\u6570\uff1a</p> \\[ \\rho_s=\\left\\{\\begin{matrix} C\\quad &amp;E_s=E \\\\ 0\\quad &amp;E_s\\neq E \\end{matrix}\\right. \\qquad C=\\frac{1}{\\Omega(N,E,V)} \\] <p>\u7136\u800c\uff0c\u5982\u679c\u4e0d\u5229\u7528\u7b49\u6982\u7387\u539f\u7406\u8fd9\u4e2a\u7edf\u8ba1\u5047\u8bbe\uff0c\u800c\u662f\u4ece\u7eaf\u529b\u5b66\u51fa\u53d1\uff0c\u5bfc\u51fa\u76f8\u540c\u7684\u7ed3\u679c\uff0c\u8fd9\u4fbf\u662f\u73bb\u5c14\u5179\u66fc\u7684\u601d\u8def\uff0c\u6d89\u53ca\u5230\u5404\u6001\u5386\u7ecf\u5047\u8bf4\u3002\u4e0d\u5e78\u7684\u662f\uff0c\u8fd9\u4e2a\u5047\u8bbe\u5728\u6570\u5b66\u4e0a\u88ab\u8bc1\u660e\u662f\u9519\u8bef\u7684\uff0c\u5e76\u4e14\u9010\u6e10\u5730\uff0c\u66f4\u591a\u4eba\u5f00\u59cb\u8ba4\u540c\u5c06\u7b49\u6982\u7387\u539f\u7406\u4f5c\u4e3a\u8d85\u8131\u4e8e\u7eaf\u529b\u5b66\u800c\u5c5e\u4e8e\u7edf\u8ba1\u7269\u7406\u7684\u57fa\u672c\u5047\u8bbe\u3002\u6211\u4eec\u91c7\u53d6\u8fd9\u79cd\u7b80\u6d01\u660e\u4e86\u7684\u505a\u6cd5\u3002</p> <p>\u2605 \u4e3a\u4e86\u7814\u7a76\u5fae\u6b63\u5219\u7cfb\u7efc\u7684\u7ed3\u6784\uff0c\u53ef\u4ee5\u5c06\u5b64\u7acb\u7cfb\u7edf\\(A^{(0)}\\)\u770b\u6210\u7531\u4e24\u4e2a\u5b50\u7cfb\u7edf\\(A_1\\)\u548c\\(A_2\\)\u7ec4\u6210\uff0c\u5e76\u4e14\u4e4b\u95f4\u53ef\u4ea4\u6362\u80fd\u91cf\u3001\u4f53\u79ef\u548c\u7c92\u5b50\uff0c\u90a3\u4e48\u6709\u5982\u4e0b\u5173\u7cfb\uff1a</p> \\[ \\Omega^{(0)}(N^{(0)},E^{(0)},V^{(0)})=\\Omega_1(N_1,E_1,V_1)\\cdot\\Omega_2(N_2,E_2,V_2) \\] \\[ N^{(0)}=N_1+N_2\\qquad E^{(0)}=E_1+E_2\\qquad V^{(0)}=V_1+V_2 \\] <p>\u6545\\(\\Omega^{(0)}\\)\u53ef\u4ee5\u770b\u4f5c\u4e3a\\((N_1,E_1,V_1)\\)\u7684\u51fd\u6570:</p> \\[ \\Omega^{(0)}=\\Omega_1(N_1,E_1,V_1)\\cdot\\Omega_2(N^{(0)}-N_1,E^{(0)}-E_1,V^{(0)}-V_1) \\] <p>\u518d\u6839\u636e\u6700\u6982\u7136\u5206\u5e03\u6761\u4ef6\\(\\delta ln(\\Omega^{(0)})=0\\)\u5f97\u5230\uff1a</p> \\[ \\delta ln(\\Omega^{(0)})=\\left(\\frac{\\partial ln\\Omega^{(0)}}{\\partial N_1}\\right)_{E_1,V_1}\\delta{N_1}+\\left(\\frac{\\partial ln\\Omega^{(0)}}{\\partial E_1}\\right)_{V_1,N_1}\\delta{E_1}+\\left(\\frac{\\partial ln\\Omega^{(0)}}{\\partial V_1}\\right)_{N_1,E_1}\\delta{V_1}=0 \\] <p>\u7531\u4e8e\\(\\delta N_1,\\delta E_1,\\delta V_1\\)\u4efb\u610f\u53d8\u52a8\uff0c\u6545\uff1a</p> \\[ \\left(\\frac{\\partial ln\\Omega^{(0)}}{\\partial N_1}\\right)_{E_1,V_1}=\\left(\\frac{\\partial ln\\Omega_1}{\\partial N_1}\\right)_{E_1,V_1}+\\left(\\frac{\\partial ln\\Omega_2}{\\partial (N^{(0)}-N_1)}\\right)_{E_1,V_1}\\frac{d (N^{(0)}-N_1)}{d N_1}=0 \\] \\[ \\Rightarrow \\left(\\frac{\\partial ln\\Omega_1}{\\partial N_1}\\right)_{E_1,V_1}=\\left(\\frac{\\partial ln\\Omega_2}{\\partial N_2}\\right)_{E_1,V_1}=\\left(\\frac{\\partial ln\\Omega_2}{\\partial N_2}\\right)_{E_2,V_2} \\] <p>\u540c\u7406\uff0c\u7efc\u5408\u5f97\u5230\uff1a</p> \\[ \\left(\\frac{\\partial ln\\Omega_1}{\\partial N_1}\\right)_{E_1,V_1}=\\left(\\frac{\\partial ln\\Omega_2}{\\partial N_2}\\right)_{E_2,V_2}=\\alpha \\] \\[ \\left(\\frac{\\partial ln\\Omega_1}{\\partial E_1}\\right)_{V_1,N_1}=\\left(\\frac{\\partial ln\\Omega_2}{\\partial E_2}\\right)_{V_2,N_2}=\\beta \\] \\[ \\left(\\frac{\\partial ln\\Omega_1}{\\partial V_1}\\right)_{N_1,E_1}=\\left(\\frac{\\partial ln\\Omega_2}{\\partial V_2}\\right)_{N_2,E_2}=\\gamma \\] <p>\u5176\u4e2d\\(\\alpha,\\beta,\\gamma\\)\u4e3a\u5f15\u5165\u7684\u5e38\u6570\uff0c\u5e76\u4e14\u4e0a\u5f0f\u53ef\u770b\u4f5c\u5e73\u8861\u6761\u4ef6\u3002\u4ece\u800c\uff0c\u5bf9\u4e8e\u7ed9\u5b9a\u7cfb\u7edf\u7684\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega(N,E,V)\\)\uff0c\u53ef\u4ee5\u6709:</p> \\[ dln(\\Omega)=\\beta dE+\\gamma dV+\\alpha dN \\] <p>\u7c7b\u6bd4\u71b5\u7684\u5168\u5fae\u5206\\(dS=\\frac{dU}{T}+\\frac{p}{T}dV-\\frac{\\mu}{T}dN\\),\u81ea\u7136\u6709\uff1a</p> \\[ \\boxed{S=kln(\\Omega)}\\quad\\Rightarrow\\quad\\boxed{\\alpha=-\\frac{\\mu}{kT}\\qquad\\beta=\\frac{1}{kT}\\qquad\\gamma=\\frac{p}{kT}} \\] <p>\u4e0a\u9762\u5047\u8bbe\\(S\\)\u4e0e\\(ln(\\Omega)\\)\u7684\u6bd4\u4f8b\u7cfb\u6570\u4e3a\\(k\\)\uff0c\u5373\u5b9e\u9a8c\u4e0a\u6d4b\u5f97\u7684\u73bb\u5c14\u5179\u66fc\u5e38\u6570\u3002\\(S\\)\u4e0e\\(ln(\\Omega)\\)\u7684\u5173\u7cfb\uff0c\u79f0\u4e3a\u73bb\u5c14\u5179\u66fc\u5173\u7cfb\u3002</p> <p>\u2605 \u5c06\u7ecf\u5178\u7cfb\u7edf\u89c6\u4e3a\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7684\u91cf\u5b50\u7cfb\u7edf(\u9700\u8981\u8003\u8651\u5168\u540c\u6027)\uff0c\u82e5\u7cfb\u7edf\u7531\u591a\u79cd\u7c92\u5b50\u7ec4\u6210\uff0c\u4e14\u7b2c\\(i\\)\u79cd\u7c92\u5b50\u7684\u4e2a\u6570\u4e3a\\(N_i\\),\u90a3\u4e48\u603b\u7684\u5fae\u89c2\u72b6\u6001\\(\\Omega\\)\u6709\uff1a</p> \\[ \\Omega=\\frac{1}{\\prod_iN_i!h^f}\\int_{\\Delta E}d\\Omega \\] <p>\u73b0\u5728\u5229\u7528\u4e0a\u5f0f\u8ba8\u8bba\u5355\u539f\u5b50\u7406\u60f3\u6c14\u4f53\u7ec4\u6210\u7684\u5b64\u7acb\u7cfb\u7edf,\u8bbe\u5176\u5177\u6709\u56fa\u5b9a\u80fd\u91cf\\(E\\),\u56fa\u5b9a\u4f53\u79ef\\(V\\),\u56fa\u5b9a\u7c92\u5b50\u6570\\(N\\)\u3002\u7531\u4e8e\u7406\u60f3\u6c14\u4f53\u662f\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\uff0c\u4e14\u80fd\u7ea7\u51c6\u8fde\u7eed\uff0c\u6545\u5176\u5fae\u89c2\u72b6\u6001\u4e3a\uff1a</p> \\[ \\Omega(N,E,V)=\\frac{1}{N!h^{3N}}\\int_{\\Delta E} d\\Omega=\\frac{V^{N}}{N!h^{3N}}\\int_{\\Delta E} d^3\\vec{p}_1...d^3\\vec{p}_{N} \\] <p>\u5355\u539f\u5b50\u4ec5\u8003\u8651\u5e73\u52a8\uff0c\u6545\u4f53\u7cfb\u7684\u54c8\u5bc6\u987f\u91cf\u4e3a\uff1a</p> \\[ H=\\sum_{i=1}^N\\frac{|\\vec{p_i}|^2}{2m}=\\frac{\\sum_{i=1}^N(p^2_{xi}+p_{yi}^2+p_{zi}^2)}{2m}=\\frac{P^2}{2m}\\Rightarrow P=\\sqrt{\\sum_{i=1}^{N}(p^2_{xi}+p_{yi}^2+p_{zi}^2)} \\] <p>\u5176\u4e2d\\(P\\)\u4e3a\u52a8\u91cf\u7a7a\u95f4\u4e2d\u7684\u534a\u5f84\uff0c\u7531\u6b64\u5c06\\(d^3\\vec{p}_1...d^3\\vec{p}_{N}\\)\u770b\u4f5c\u5728\\(3N\\)\u7ef4\u7a7a\u95f4\u534a\u5f84\\(P\\)\u4ece\\(\\sqrt{2mE}\\)\u5230\\(\\sqrt{2m(E+\\Delta E)}\\)\u7684\u7403\u58f3\uff0c\u6839\u636e\\(d\\)\u7ef4\u7a7a\u95f4\u4e2d\u7403\u7684\u4f53\u79ef\uff0c\u5f97\u5230\uff1a</p> \\[ \\boxed{V_d=\\frac{\\pi^{\\frac{d}{2}}}{\\Gamma(\\frac{d}{2}+1)}R^d}\\quad\\Rightarrow\\quad S_d=V_d'=\\frac{d\\pi^{\\frac{d}{2}}}{\\Gamma(\\frac{d}{2}+1)}R^{d-1}\\quad\\Rightarrow\\quad S_{3N}=\\frac{3N\\pi^{\\frac{3N}{2}}}{\\Gamma(\\frac{3N}{2}+1)}R^{3N-1} \\] <p>\u4ee3\u5165\\(R=P\\)\u5e76\u4e14\u79ef\u5206\uff0c\u5f97\u5230\uff1a</p> \\[ \\Omega(N,E,V)=\\frac{V^{N}}{N!h^{3N}}\\frac{3N\\pi^{\\frac{3N}{2}}}{\\Gamma(\\frac{3N}{2}+1)}\\int_{\\sqrt{2mE}}^{\\sqrt{2m(E+\\Delta E)}} P^{3N-1}dP \\] \\[ =\\frac{V^{N}}{N!h^{3N}}\\frac{3N\\pi^{\\frac{3N}{2}}}{\\Gamma(\\frac{3N}{2}+1)}\\frac{(2m)^{\\frac{3N}{2}}\\left[(E+\\Delta E)^{\\frac{3N}{2}}-E^{\\frac{3N}{2}}\\right]}{3N} \\] \\[ = \\frac{V^{N}}{N!h^{3N}}\\frac{(2m\\pi)^{\\frac{3N}{2}}}{\\Gamma(\\frac{3N}{2}+1)}\\left[(E+\\Delta E)^{\\frac{3N}{2}}-E^{\\frac{3N}{2}}\\right]=\\frac{V^{N}}{N!h^{3N}}\\frac{(2m\\pi E)^{\\frac{3N}{2}}}{\\Gamma(\\frac{3N}{2}+1)}\\left[(1+\\frac{\\Delta E}{E})^{\\frac{3N}{2}}-1\\right] \\] <p>\u7531\u4e8e\\(\\frac{\\Delta E}{E}\\rightarrow0\\),\u5229\u7528\u8fd1\u4f3c\\((1+x)^\\alpha-1\\approx\\alpha x\\)\u5f97\u5230:</p> \\[ \\Omega(N,E,V)=\\frac{V^{N}}{N!h^{3N}}\\frac{(2m\\pi E)^{\\frac{3N}{2}}}{\\Gamma(\\frac{3N}{2}+1)}\\frac{3N}{2}\\frac{\\Delta E}{E}=\\Sigma(E)\\frac{3N}{2}\\frac{\\Delta E}{E}\\propto E^{\\frac{3N}{2}} \\] <p>\u5176\u4e2d\\(\\Sigma(E)\\)\u8868\u793a\u80fd\u91cf\u5c0f\u4e8e\\(E\\)\u7684\u5fae\u89c2\u72b6\u6001\u6570\uff0c\u7531\u6b64\u53ef\u4ee5\u7b80\u5316\u8868\u8fbe\u3002</p> <p>\u5229\u7528\u73bb\u5c14\u5179\u66fc\u5173\u7cfb\\(S=kln(\\Omega)\\)\u4e0d\u96be\u5f97\u5230\u7279\u6027\u51fd\u6570\\(S(N,E,V)\\),\u4ece\u800c\u5f97\u5230\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\u3002\u7efc\u4e0a\uff0c\u5fae\u6b63\u5219\u7cfb\u7efc\u6c42\u89e3\u95ee\u9898\u7684\u65b9\u6cd5\u662f\u5148\u6c42\u51fa\\(\\Omega\\),\u4ece\u800c\u5f97\u5230\u7279\u6027\u51fd\u6570\\(S\\),\u6700\u7ec8\u5f97\u5230\u5176\u4ed6\u70ed\u529b\u5b66\u91cf\u3002\u4f46\u7531\u4e8e\u8ba1\u7b97\u590d\u6742\uff0c\u7531\u6b64\u5f15\u5165\u5176\u4ed6\u7684\u7cfb\u7efc\u3002</p>"},{"location":"chapter_09_ensembles/03_canonical_ensemble.html","title":"\u6b63\u5219\u7cfb\u7efc","text":""},{"location":"chapter_09_ensembles/03_canonical_ensemble.html#_1","title":"\u6b63\u5219\u7cfb\u7efc","text":"<p>\u2605 \u5fae\u6b63\u5219\u7cfb\u7efc\u5904\u7406\u7684\u662f\u5b64\u7acb\u7cfb\u7edf\uff0c\u800c\u5b9e\u9645\u95ee\u9898\u5f80\u5f80\u90fd\u662f\u5c01\u95ed\u7cfb\u7edf\uff0c\u751a\u81f3\u662f\u5f00\u653e\u7cfb\u7edf\u3002\u56e0\u6b64\u6709\u5fc5\u8981\u5229\u7528\u5fae\u6b63\u5219\u7cfb\u7efc\u5f00\u53d1\u51fa\u5176\u4ed6\u7cfb\u7efc\uff0c\u4ece\u800c\u65b9\u4fbf\u5904\u7406\u5b9e\u9645\u95ee\u9898\u3002\u672c\u8282\u7814\u7a76\u7cfb\u7edf\u4e0e\u5927\u70ed\u6e90\uff08\u6216\u70ed\u5e93\uff09\u63a5\u89e6\u8fbe\u5230\u5e73\u8861\u7684\u6b63\u5219\u7cfb\u7efc\u3002</p> <p>\u7531\u4e8e\u4e0e\u70ed\u6e90\u63a5\u89e6\uff0c\u6545\u7cfb\u7edf\u53ef\u4ee5\u4e0e\u5916\u754c\u8fdb\u884c\u80fd\u91cf\u4ea4\u6362\uff0c\u4f46\u7c92\u5b50\u6570\u548c\u4f53\u79ef\u6052\u5b9a\uff0c\u4ece\u800c\u53ef\u4ee5\u770b\u4f5c\u5c01\u95ed\u7cfb\u7edf\u3002\u6b64\u5916\u7531\u4e8e\u8fbe\u5230\u5e73\u8861\uff0c\u6545\u7cfb\u7edf\u6709\u786e\u5b9a\u7684\u6e29\u5ea6\u3002\u901a\u5e38\u7531\\((N,T,V)\\)\u8868\u793a\u6b63\u5219\u7cfb\u7efc\u7684\u7279\u5f81\u3002</p> <p>\u4e3a\u4e86\u5229\u7528\u5fae\u6b63\u5219\u7cfb\u7efc\u7814\u7a76\u6b63\u5219\u7cfb\u7efc\uff0c\u5c06\u70ed\u6e90\\(A_r\\)\u4e0e\u5c01\u95ed\u7cfb\u7edf\\(A_s\\)\u7ec4\u6210\u7684\u5927\u7cfb\u7edf\u89c6\u4e3a\u4e00\u4e2a\u5b64\u7acb\u7cfb\u7edf\\(A^{(0)}\\)\uff0c\u5219\u6709\u5982\u4e0b\u5173\u7cfb\uff1a</p> \\[ E_s+E_r=E^{(0)}\\quad E_s\\ll E^{(0)} \\] <p>\u5176\u4e2d\\(E_s\\)\u8868\u793a\u7cfb\u7edf\u5904\u4e8e\\(s\\)\u91cf\u5b50\u6001\u6240\u5177\u6709\u7684\u80fd\u91cf\uff0c\u4ece\u800c\u70ed\u6e90\u7684\u5fae\u89c2\u72b6\u6001\u6570\u4e3a\\(\\Omega_r(E^{(0)}-E_s)\\),\u518d\u6839\u636e\u7b49\u6982\u7387\u539f\u7406\uff0c\u5f97\u5230\u7cfb\u7edf\u5904\u4e8e\\(s\\)\u6001\u7684\u6982\u7387:</p> \\[ \\rho_s=\\frac{\\Omega_r(E^{(0)}-E_s)}{\\Omega^{(0)}}\\propto\\Omega_r(E^{(0)}-E_s) \\] <p>\u7531\u4e8e\\(E_s\\ll E^{(0)}\\)\u7684\u5173\u7cfb\uff0c\u5bf9\u4e0a\u5f0f\u53d6\u5bf9\u6570\u518d\u5728\\(E_s=0\\)\u5904\u5c55\u5f00\u5230\u7b2c\u4e8c\u9879\uff1a</p> \\[ ln\\Omega_r(E^{(0)}-E_s)\\approx ln\\Omega_r(E^{(0)})+\\left(\\frac{\\partial ln\\Omega_r}{\\partial E_r}\\right)_{E_r=E^{(0)}}\\frac{d E_r}{d E_s}E_s=ln\\Omega_r(E^{(0)})-\\beta E_s \\] <p>\u4ece\u800c\u5f97\u5230\u6982\u7387\u7684\u6b63\u6bd4\u5173\u7cfb\uff1a</p> \\[ \\rho_s\\propto e^{ln\\Omega_r(E^{(0)})-\\beta E_s}=\\Omega_r(E^{(0)})e^{-\\beta E_s}\\propto e^{-\\beta E_s}\\quad\\Rightarrow\\quad\\boxed{\\rho_s=\\frac{e^{-\\beta E_s}}{Z}\\quad Z=\\sum_s e^{-\\beta E_s}} \\] <p>\u5176\u4e2d\\(Z\\)\u79f0\u4e3a\u7cfb\u7edf\u914d\u5206\u51fd\u6570\u6216N\u7c92\u5b50\u914d\u5206\u51fd\u6570\uff0c\u7b80\u79f0\u4e3a\u914d\u5206\u51fd\u6570\u3002</p> <p>\u5982\u679c\u8003\u8651\u7ecf\u5178\u6781\u9650\uff0c\u5373\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\u4e14\u80fd\u7ea7\u51c6\u8fde\u7eed\uff0c\u5219\u6982\u7387\u7531\u6982\u7387\u5bc6\u5ea6\\(\\rho\\)\u548c\u76f8\u7a7a\u95f4\u4f53\u79ef\u5143\\(d\\Omega\\)\u8868\u8fbe\u4e3a\uff1a</p> \\[ \\boxed{\\rho d\\Omega=\\frac{d\\Omega}{N!h^{f}}\\frac{1}{Z}e^{-\\beta E_s}\\quad Z=\\frac{1}{N!h^f}\\int e^{-\\beta E_s}d\\Omega} \\] <p>\u6ce8\u610f\u4e0a\u5f0f\u90fd\u662f\u5bf9\u7cfb\u7edf\u80fd\u91cf\\(E_s\\)\u7684\u6c42\u548c\uff0c\u800c\u4e4b\u524d\u5728\u8fd1\u72ec\u7acb\u5b50\u7cfb\u4e2d\u5f15\u5165\u7684\u7c92\u5b50\u914d\u5206\u51fd\u6570\uff0c\u5219\u662f\u5bf9\u5355\u4e2a\u7c92\u5b50\u7684\u80fd\u91cf\\(\\varepsilon_s\\)\u6c42\u548c\u3002\u5982\u679c\u7cfb\u7edf\u7684\u80fd\u91cf\u4ecd\u7136\u4e0e\u8fd1\u72ec\u7acb\u76f8\u540c\uff0c\u5373\u80fd\u91cf\u4e0d\u542b\u4ea4\u53c9\u9879\uff0c\u5219\u914d\u5206\u51fd\u6570\u4e0e\u7c92\u5b50\u914d\u5206\u51fd\u6570\u6709\u5982\u4e0b\u5173\u7cfb:</p> \\[ E_s=\\sum_{i=1}^N\\varepsilon_{si}\\quad\\Rightarrow\\quad Z=\\sum_s e^{-\\beta E_s}=\\sum_s\\prod_{i=1}^Ne^{-\\beta\\varepsilon_{si}}=\\prod_{i=1}^N\\sum_{si}e^{-\\beta\\varepsilon_{si}} \\] <p>\u4e0a\u5f0f\u6700\u540e\u4e00\u4e2a\u7b49\u53f7\u5229\u7528\u4e86\u5168\u540c\u7c92\u5b50\u53ef\u9009\u53d6\u7684\u6001\u90fd\u76f8\u540c\u7684\u6027\u8d28\uff0c\u5e76\u4e14\u6700\u7ec8\u7684\u6c42\u548c\u4e00\u5b9a\u662f\\(N\\)\u4e2a\u7c92\u5b50\u53d6\u4e0d\u540c\u6001\u7684\u5168\u90e8\u7ec4\u5408\uff0c\u5373\u7cfb\u7edf\u53d6\u76f8\u540c\u80fd\u91cf\u65f6\uff0c\u524d\u9762\u7684\u7cfb\u6570\u4e3a\u4e8c\u9879\u5f0f\u7cfb\u6570\uff0c\u4ece\u800c\u53ef\u4ee5\u5199\u6210\u4e58\u79ef\u7684\u5f62\u5f0f\u3002\u7531\u6b64\u53ef\u5f97\uff1a</p> \\[ \\boxed{Z=Z^N_1\\qquad or\\qquad Z=\\frac{1}{N!}Z^N_1} \\] <p>\u2605 \u4e0e\u8fd1\u72ec\u7acb\u5b50\u7cfb\u7c7b\u4f3c\uff0c\u70ed\u529b\u5b66\u91cf\u4e0e\u914d\u5206\u51fd\u6570\u7684\u5173\u7cfb\u4e5f\u53ef\u6839\u636e\u5b9a\u4e49\u5bfc\u51fa:</p> \\[ U=\\overline{E}=\\sum_sE_s\\rho_s=\\frac{1}{Z}\\sum_sE_se^{-\\beta E_s}=-\\frac{\\partial}{\\partial\\beta}ln(Z) \\] \\[ Y=\\sum_s\\frac{\\partial E_s}{\\partial y}\\rho_s=\\frac{1}{Z}\\sum_s\\frac{\\partial E_s}{\\partial y}e^{-\\beta E_s}=-\\frac{1}{\\beta}\\frac{\\partial}{\\partial y}ln(Z) \\] \\[ S=k\\left(ln(Z)-\\beta\\frac{\\partial}{\\partial\\beta}ln(Z)\\right)\\qquad F=-kTln(Z) \\] <p>\u53ef\u89c1\uff0c\u914d\u5206\u51fd\u6570\u5bfc\u51fa\u57fa\u672c\u70ed\u529b\u5b66\u91cf\u7684\u8868\u8fbe\u5f0f\u4e2d\uff0c\u4e0d\u542b\\(N\\)\u548c\\(N!\\),\u8fd9\u662f\u56e0\u4e3a\u5b83\u4eec\u90fd\u5728\u914d\u5206\u51fd\u6570\u672c\u8eab\u4e2d\u8574\u542b\u3002\u4f7f\u7528\u65f6\u8981\u6ce8\u610f\u8868\u8fbe\u5f0f\u4e2d\u7684\u6b63\u8d1f\u53f7\uff0c\u4ee5\u53ca\u914d\u5206\u51fd\u6570\u662f\u5426\u9664\u4ee5\\(N!\\).\u6b64\u5916\uff0c\u6839\u636e\u6b63\u5219\u7cfb\u7efc(N,T,V)\u53ef\u770b\u51fa\uff0c\u81ea\u7531\u80fd\\(F\\)\u4e3a\u7279\u6027\u51fd\u6570\u3002</p> <p>\u4e0b\u9762\u8ba8\u8bba\u6b63\u5219\u7cfb\u7efc\u4e2d\u7684\u80fd\u91cf\u6da8\u843d\uff0c\u6240\u8c13\u6da8\u843d\u5373\u504f\u5dee\u5e73\u65b9\u7684\u5e73\u5747\u503c\uff0c\u6545\uff1a</p> \\[ \\overline{(E_s-\\overline{E})^2}=\\sum_s\\rho_s(E_s^2-2E_s\\overline{E}+\\overline{E}^2)=\\overline{E^2}-\\overline{E}^2 \\] <p>\u5176\u4e2d\\(\\overline{E^2}\\)\u53ef\u4ee5\u8fdb\u4e00\u6b65\u5199\u51fa\uff1a</p> \\[ \\overline{E^2}=\\sum_sE^2\\rho_s=\\sum_sE^2\\frac{e^{-\\beta E_s}}{Z}=\\frac{1}{Z}\\sum_s\\frac{\\partial^2}{\\partial \\beta^2}e^{-\\beta E_s}=\\frac{1}{Z}\\frac{\\partial^2}{\\partial\\beta^2}Z \\] <p>\u518d\u505a\u4e00\u6b65\u914d\u5206\uff1a</p> \\[ \\overline{E^2}=\\frac{\\partial}{\\partial\\beta}\\left(\\frac{1}{Z}\\frac{\\partial}{\\partial\\beta}Z\\right)-\\frac{\\partial}{\\partial\\beta}\\left(\\frac{1}{Z}\\right)\\frac{\\partial Z}{\\partial\\beta}=-\\frac{\\partial}{\\partial\\beta}\\overline{E}+\\overline{E}^2 \\] <p>\u7efc\u4e0a\u5f97\u5230\uff1a</p> \\[ \\overline{(E_s-\\overline{E})^2}=-\\frac{\\partial}{\\partial\\beta}\\overline{E}=kT^2\\frac{\\partial\\overline{E}}{\\partial T}=kT^2C_V&gt;0 \\] <p>\u4e5f\u53ef\u5b9a\u4e49\u76f8\u5bf9\u6da8\u843d\uff1a</p> \\[ \\frac{\\overline{(E_s-\\overline{E})^2}}{\\overline{E}^2}=\\frac{kT^2C_V}{\\overline{E}^2}\\propto\\frac{1}{N} \\] <p>\u7531\u4e8e\\(\\overline{E}\\)\u4e0e\\(C_V\\)\u90fd\u4e0e\u7c92\u5b50\u6570\\(N\\)\u6210\u6b63\u6bd4\uff0c\u4ece\u800c\u8868\u660e\u76f8\u5bf9\u6da8\u843d\u4e0e\u7c92\u5b50\u6570\u6210\u53cd\u6bd4\uff0c\\(N\\rightarrow\\infty\\),\u6da8\u843d\u8d8b\u4e8e0.</p> <p>\u2605 \u975e\u7406\u60f3\u6c14\u4f53\u7269\u6001\u65b9\u7a0b\u7684\u63a8\u5bfc\u2014\u2014\u96c6\u56e2\u5c55\u5f00\u6cd5</p>   *\u5b8c\u5168\u5199\u6e05\u695a\u8fc7\u4e8e\u590d\u6742\uff0c\u8be6\u89c1\u674e\u653f\u9053\u300a\u7edf\u8ba1\u529b\u5b66\u300bp65-p74\u7b49\u5176\u4ed6\u53c2\u8003\u4e66*"},{"location":"chapter_09_ensembles/04_grand_canonical_ensemble.html","title":"\u5de8\u6b63\u5219\u7cfb\u7efc","text":""},{"location":"chapter_09_ensembles/04_grand_canonical_ensemble.html#_1","title":"\u5de8\u6b63\u5219\u7cfb\u7efc","text":"<p>\u2605 \u987a\u7740\u4e0a\u8282\u7684\u601d\u8def\uff0c\u82e5\u7cfb\u7edf\u4e0e\u70ed\u6e90\u4e0d\u4ec5\u6709\u80fd\u91cf\u4ea4\u6362\uff0c\u8fd8\u80fd\u8fdb\u884c\u7c92\u5b50\u6570\u7684\u4ea4\u6362\uff0c\u5e76\u4fdd\u6301\u7cfb\u7edf\u4f53\u79ef\u3001\u5316\u5b66\u52bf\u6052\u5b9a\u4e14\u4e0e\u70ed\u6e90\u8fbe\u5230\u70ed\u5e73\u8861\uff0c\u7531\u8fd9\u6837\u7684\u5f00\u653e\u7cfb\u7edf\u7ec4\u6210\u7684\u7cfb\u7efc\u79f0\u4e3a\u5de8\u6b63\u5219\u7cfb\u7efc\u3002\u6839\u636e\u56fa\u5b9a\u7684\u53c2\u6570\uff0c\u901a\u5e38\u8868\u793a\u4e3a\\((\\mu,T,V)\\).</p> <p>\u540c\u6837\u53ef\u4ee5\u5c06\u70ed\u6e90\\(A_r\\)\u4e0e\u5f00\u653e\u7cfb\u7edf\\(A_s\\)\u770b\u4f5c\u4e00\u4e2a\u5b64\u7acb\u7cfb\u7edf\\(A^{(0)}\\)\uff0c\u5229\u7528\u5fae\u6b63\u5219\u7cfb\u7efc\u6765\u7814\u7a76\u3002\u7531\u4e8e\u6574\u4f53\u80fd\u91cf\u548c\u7c92\u5b50\u6570\u5b88\u6052\uff0c\u6709\uff1a</p> \\[ E_s+E_r=E^{(0)}\\quad E_s\\ll E^{(0)}  \\qquad N+N_r=N^{(0)}\\quad N\\ll N^{(0)} \\] <p>\u6839\u636e\u7b49\u6982\u7387\u539f\u7406\uff0c\u5f97\u5230\uff1a</p> \\[ \\rho_{s,N}=\\frac{\\Omega_r(N^{(0)}-N,E^{(0)}-E_s)}{\\Omega^{(0)}}\\propto\\Omega_r(N^{(0)}-N,E^{(0)}-E_s) \\] <p>\u7531\u4e8e\\( E_s\\ll E^{(0)}\\)\u548c\\(N\\ll N^{(0)}\\)\u7684\u5173\u7cfb\uff0c\u5bf9\\(\\Omega_r\\)\u53d6\u5bf9\u6570\u3001\u5c55\u5f00\u5f97\u5230\uff1a</p> \\[ ln\\Omega_r(N^{(0)}-N,E^{(0)}-E_s)\\approx ln\\Omega_r(N^{(0)},E^{(0)})-\\alpha N-\\beta E_s \\] <p>\u4ece\u800c\u5f97\u5230\u6982\u7387\u7684\u6b63\u6bd4\u5173\u7cfb\uff1a</p> \\[ \\rho_{s,N}\\propto e^{ln\\Omega_r(N^{(0)},E^{(0)})-\\alpha N-\\beta E_s}=\\Omega_r(N^{(0)},E^{(0)})e^{-\\alpha N-\\beta E_s}\\propto e^{-\\alpha N-\\beta E_s} \\] \\[ \\Rightarrow\\boxed{\\rho_{s,N}=\\frac{1}{\\Xi}e^{-\\alpha N-\\beta E_s}\\quad\\Xi=\\sum_{N=0}^\\infty\\sum_se^{-\\alpha N-\\beta E_s}} \\] <p>\u5176\u4e2d\\(\\Xi\\)\u4e3a\u5de8\u914d\u5206\u51fd\u6570\u3002\u9700\u8981\u6ce8\u610f\uff0c\u7cfb\u7edf\u6240\u542b\u7c92\u5b50\u6570\u4e0d\u540c\u65f6\uff0c\u5176\u91cf\u5b50\u6001\u4e5f\u4e0d\u540c\uff0c\u56e0\u800c\u63cf\u8ff0\u91cf\u5b50\u6001\u5e94\u5148\u660e\u786e\u7c92\u5b50\u6570\u3002\u4f8b\u5982\u63cf\u8ff0\u6ee1\u8db3\u7ecf\u5178\u6781\u9650\u7684\u7cfb\u7edf,\u5219\u6709\uff1a</p> \\[ \\boxed{\\rho_N d\\Omega_N=\\frac{d\\Omega_N}{N!h^{f}}\\frac{1}{\\Xi}e^{-\\alpha N-\\beta E_s}\\quad \\Xi=\\sum_{N=0}^\\infty\\frac{e^{-\\alpha N}}{N!h^f}\\int e^{-\\beta E_s}d\\Omega_N} \\] <p>\u6b64\u5916\uff0c\u4e0d\u96be\u5f97\u5230\u5de8\u914d\u5206\u51fd\u6570\u4e0e\u914d\u5206\u51fd\u6570\u7684\u5173\u7cfb\uff1a</p> \\[ \\Xi=\\sum_{N=0}^\\infty e^{-\\alpha N}\\sum_s e^{-\\beta E_s}=\\sum_{N=0}^\\infty e^{-\\alpha N}Z=\\sum_{N=0}^\\infty e^{-\\alpha N}Z_1^N\\quad or\\quad\\sum_{N=0}^\\infty e^{-\\alpha N}\\frac{Z_1^N}{N!} \\] <p>\u4f8b\u5982\u5bf9\u4e8e\u975e\u5b9a\u57df\u7684\u7406\u60f3\u6c14\u4f53\u7684\u5de8\u914d\u5206\u51fd\u6570\u4e3a\\(\\Xi=e^{e^{-\\alpha}Z_1}\\).</p> <p>\u2605 \u5de8\u6b63\u5219\u7cfb\u7efc\u8ba1\u7b97\u70ed\u529b\u5b66\u91cf\u7684\u516c\u5f0f\u63a8\u5bfc\u5982\u4e0b\uff1a</p> \\[ \\overline{N}=\\sum_N\\sum_s N\\rho_{s,N}=\\frac{1}{\\Xi}\\sum_N\\sum_s Ne^{-\\alpha N-\\beta E_s}=-\\frac{\\partial}{\\partial \\alpha}ln\\Xi \\] \\[ U=\\overline{E}=\\sum_N\\sum_sE_s\\rho_{s,N}=\\frac{1}{\\Xi}\\sum_N\\sum_sE_se^{-\\alpha N-\\beta E_s}=-\\frac{\\partial}{\\partial\\beta}ln\\Xi \\] \\[ Y=\\sum_N\\sum_s\\frac{\\partial E_s}{\\partial y}\\rho_{s,N}=\\frac{1}{\\Xi}\\sum_N\\sum_s\\frac{\\partial E_s}{\\partial y}e^{-\\alpha N-\\beta E_s}=-\\frac{1}{\\beta}\\frac{\\partial}{\\partial y}ln\\Xi \\] \\[ S=k\\left(ln\\Xi-\\alpha\\frac{\\partial}{\\partial\\alpha}ln\\Xi-\\beta\\frac{\\partial}{\\partial\\beta}ln\\Xi\\right)\\qquad F=-kTln\\Xi+kT\\alpha\\frac{\\partial}{\\partial\\alpha}ln\\Xi \\] <p>\u663e\u7136\u8fd9\u91cc\u81ea\u7531\u80fd\u7684\u8868\u8fbe\u5f62\u5f0f\u4e0d\u591f\u7b80\u5355\uff0c\u4e3b\u8981\u539f\u56e0\u662f\u5176\u4e0d\u662f\u5de8\u6b63\u5219\u7cfb\u7efc\\((\\mu,T,V)\\)\u7684\u51fd\u6570\uff0c\u6545\u53ef\u91c7\u7528\u4e4b\u524d\u5728\u70ed\u529b\u5b66\u4e2d\u5b9a\u4e49\u7684\u5de8\u52bf\u51fd\u6570\uff1a</p> \\[ J=F-G=F-\\overline{N}\\mu=-kTln\\Xi \\] <p>\u7531\u6b64\uff0c\u5de8\u52bf\u51fd\u6570\u5373\u4e3a\u5de8\u6b63\u5219\u7cfb\u7efc\u7684\u7279\u6027\u51fd\u6570\u3002</p> <p>\u4e0e\u6b63\u5219\u7cfb\u7efc\u4e00\u6837\uff0c\u8fd9\u91cc\u8ba8\u8bba\u5de8\u6b63\u5219\u7cfb\u7efc\u7684\u80fd\u91cf\u6da8\u843d\u4ee5\u53ca\u7c92\u5b50\u6570\u6da8\u843d\u3002\u5bf9\u4e8e\u80fd\u91cf\u6da8\u843d\uff0c\u5f62\u5f0f\u4e0a\u4ecd\u53ef\u7531\u5bf9\\(\\beta\\)\u7684\u4e8c\u9636\u5bfc\u6570\u5f97\u5230\uff0c\u4f46\u5de8\u6b63\u5219\u7cfb\u7efc\u4e2d\u7c92\u5b50\u6570\u4e5f\u4f1a\u6da8\u843d\uff0c\u56e0\u6b64\u8fd9\u91cc\u7684\u70ed\u5bb9\u5e94\u7406\u89e3\u4e3a\u56fa\u5b9a\\(\\alpha\\)\u548c\\(V\\)\u65f6\u7684\u54cd\u5e94\u91cf\uff0c\u800c\u4e0d\u662f\u56fa\u5b9a\u7c92\u5b50\u6570\u7684\u6b63\u5219\u70ed\u5bb9\uff1a</p> \\[ \\overline{(E_s-\\overline{E})^2}=-\\left(\\frac{\\partial\\overline{E}}{\\partial\\beta}\\right)_{\\alpha,V}=kT^2\\left(\\frac{\\partial\\overline{E}}{\\partial T}\\right)_{\\alpha,V}\\qquad\\frac{\\overline{(E_s-\\overline{E})^2}}{\\overline{E}^2}\\propto\\frac{1}{N} \\] <p>\u4e0b\u9762\u63a8\u5bfc\u7c92\u5b50\u6570\u7684\u6da8\u843d\uff1a</p> \\[ \\overline{N^2}=\\sum_N\\sum_sN^2\\rho_{s,N}=\\frac{1}{\\Xi}\\frac{\\partial^2}{\\partial\\alpha^2}\\sum_N\\sum_se^{-\\alpha N-\\beta E_s}=\\overline{N}^2-\\frac{\\partial\\overline{N}}{\\partial\\alpha} \\] \\[ \\Rightarrow\\overline{(N-\\overline{N})^2}=\\overline{N^2}-\\overline{N}^2=-\\frac{\\partial\\overline{N}}{\\partial\\alpha}=kT\\frac{\\partial\\overline{N}}{\\partial\\mu} \\] <p>\u5229\u7528\\(d\\mu=-sdT+vdp\\)\u5728\u7b49\u6e29\u6761\u4ef6\u4e0b\u7684\u7b49\u5f0f\uff0c\u5e76\u5229\u7528\u4f53\u79ef\u56fa\u5b9a\u7684\u6761\u4ef6\uff1a</p> \\[ \\left(\\frac{\\partial \\mu}{\\partial v}\\right)_T=v\\left(\\frac{\\partial p}{\\partial v}\\right)_T\\quad v=\\frac{V}{\\overline{N}}\\Rightarrow\\frac{\\overline{(N-\\overline{N})^2}}{\\overline{N}^2}=\\frac{kT}{V}\\kappa_{T}\\propto\\frac{1}{N} \\] <p>\u2605 \u4e0b\u9762\u8ba8\u8bba\u4e24\u4e2a\u5de8\u6b63\u5219\u7cfb\u7efc\u6709\u8da3\u7684\u5e94\u7528\u3002</p> <p>(1)\u56fa\u4f53\u8868\u9762\u7684\u5438\u9644\u7387\uff1a\u8bbe\u5438\u9644\u4e2d\u5fc3\u7684\u603b\u6570\u4e3a\\(N_0\\),\u88ab\u5438\u9644\u5206\u5b50\u5e73\u5747\u6570\u4e3a\\(\\overline{N}\\),\u5438\u9644\u7387\u5b9a\u4e49\u4e3a\\(\\theta=\\frac{\\overline{N}}{N_0}\\),\u82e5\u88ab\u5438\u9644\u7684\u5206\u5b50\u5e26\u6765\u7684\u80fd\u91cf\u4e3a\\(-\\varepsilon_0\\),\u5219\u6709\\(N\\)\u4e2a\u5206\u5b50\u88ab\u5438\u9644\uff0c\u4f53\u7cfb\u80fd\u91cf\u4e3a\\(E_s=-N\\varepsilon_0\\),\u4ece\u800c\u88ab\u5438\u9644\u7684\u5de8\u914d\u5206\u51fd\u6570\u4e3a\uff1a</p> \\[ \\Xi=\\sum_{N=0}^{N_0}\\sum_se^{-\\alpha N-\\beta E_s}=\\sum_{N=0}^{N_0} \\sum_se^{\\beta(\\mu+\\varepsilon_0)N} \\] <p>\u4e0a\u5f0f\u7528\u5230\u4e86\\(\\alpha=-\\beta\\mu\\).\u5bf9\u4e8e\u540c\u4e00\\(N\\)\u5171\u6709\\(C_{N_0}^N\\)\u79cd\u7ec4\u5408\uff0c\u6545\u5bf9\\(s\\)\u7684\u6c42\u548c\u53ef\u4ee5\u5199\u4e3a\uff1a</p> \\[ \\Xi=\\sum_{N=0}^{N_0}\\frac{N_0!}{N!(N_0-N)!}e^{\\beta (\\mu+\\varepsilon_0)N}=\\left[1+e^{\\beta(\\mu+\\varepsilon_0)}\\right]^{N_0} \\] <p>\u4e0a\u5f0f\u7528\u5230\u4e86\u4e8c\u9879\u5f0f\u5c55\u5f00\u7684\u9006\u8fc7\u7a0b\u3002\u5229\u7528\u4e0a\u5f0f\u5de8\u914d\u5206\u51fd\u6570\uff0c\u53ef\u4ee5\u6c42\u51fa\\(\\overline{N}\\).\u82e5\u5c06\u5206\u5b50\u89c6\u4e3a\u7406\u60f3\u6c14\u4f53\uff0c\u4ee3\u5165\u7406\u60f3\u6c14\u4f53\u7684\u5316\u5b66\u52bf\uff0c\u5f97\u5230\uff1a</p> \\[ \\overline{N}=-\\frac{\\partial}{\\partial\\alpha}ln\\Xi=\\frac{N_0}{1+e^{-\\beta(\\mu+\\varepsilon_0)}}\\quad\\Rightarrow\\quad\\theta=\\frac{1}{1+\\frac{kT}{p}\\left(\\frac{2\\pi mkT}{h^2}\\right)^{3/2}e^{-\\frac{\\varepsilon_0}{kT}}} \\] <p>\u4e0a\u5f0f\u8868\u660e\uff0c\\(\\theta\\)\u968f\\(p\\)\u7684\u4e0a\u5347\u800c\u589e\u5927\uff0c\u968f\\(T\\)\u7684\u4e0a\u5347\u800c\u51cf\u5c0f\uff0e</p> <p>(2)\u63a8\u5bfc\u73bb\u8272\u5206\u5e03\u548c\u8d39\u7c73\u5206\u5e03\uff1a\u4e4b\u524d\u8ba8\u8bba\u8fd1\u72ec\u7acb\u5b50\u7cfb\u7684\u73bb\u8272\u548c\u8d39\u7c73\u5206\u5e03\u65f6\u6240\u4f7f\u7528\u7684\u5de8\u914d\u5206\u51fd\u6570\u4f3c\u4e4e\u4e0e\u8fd9\u91cc\u4e0d\u540c\uff0c\u4e8b\u5b9e\u4e0a\u8fd9\u6e90\u4e8e\\(\\sum_s\\)\u6c42\u548c\u65b9\u5f0f\u7684\u4e0d\u540c\u3002\u4e0b\u9762\u901a\u8fc7\u6539\u53d8\u5de8\u914d\u5206\u51fd\u6570\u7684\u6c42\u548c\u65b9\u5f0f\uff0c\u4ee5\u6b64\u5bfc\u51fa\u4e0a\u4e00\u7ae0\u5de8\u914d\u5206\u51fd\u6570\u7684\u7279\u6b8a\u5f62\u5f0f\uff0c\u5e76\u5bfc\u51fa\u73bb\u8272\u5206\u5e03\u548c\u8d39\u7c73\u5206\u5e03\u3002</p> <p>\u9996\u5148\u5c06\u76f8\u540c\u7684\u80fd\u91cf\u8fdb\u884c\u5206\u7c7b\uff0c\u4ece\u800c\u8425\u9020\u51fa\u7c92\u5b50\u6570\u548c\u80fd\u91cf\u5747\u56fa\u5b9a\u7684\u6c42\u548c\u73af\u5883\u3002\u800c\u6ee1\u8db3\u4e24\u8005\u56fa\u5b9a\u7684\u7cfb\u7edf\u72b6\u6001\u7684\u4e2a\u6570(\u7b80\u5e76\u5ea6)\uff0c\u6b63\u597d\u5c31\u662f\u8fd1\u72ec\u7acb\u5b50\u7cfb\u6240\u8003\u8651\u5728\u5206\u5e03\\(\\{a_l\\}\\)\u4e0b\u7684\u5fae\u89c2\u72b6\u6001\u6570\\(\\Omega[\\{a_l\\}]\\),\u4ece\u800c\uff1a</p> \\[ \\Xi=\\sum_N\\sum_se^{-\\alpha N-\\beta E_s}=\\sum_N\\sum_E\\Omega[\\{a_l\\}] e^{-\\alpha N-\\beta E} \\] <p>\u5176\u6b21\uff0c\u5229\u7528\u7c92\u5b50\u6570\u4e0e\u80fd\u91cf\u56fa\u5b9a\u7684\u6761\u4ef6\uff0c\u5f97\u5230\uff1a</p> \\[ N=\\sum_la_l\\quad E=\\sum_l\\varepsilon_la_l\\quad\\Rightarrow\\quad\\Xi=\\sum_{N,E}\\Omega[\\{a_l\\}]e^{-\\sum_l(\\alpha+\\beta\\varepsilon_l)a_l} \\] <p>\u73b0\u5728\u5c06\u5206\u5e03\\(\\{a_l\\}\\)\u63a8\u5e7f\u5230\u80fd\u91cf\u548c\u7c92\u5b50\u6570\u4e0d\u56fa\u5b9a\u7684\u60c5\u51b5\uff0c\u5373\\(\\sum_{\\{a_l\\}}\\)\u8868\u793a\u5bf9\u4e00\u5207\u53ef\u80fd\u7684\u5206\u5e03\u6c42\u548c\uff1a</p> \\[ \\Xi=\\sum_{\\{a_l\\}}\\Omega[\\{a_l\\}]e^{-\\sum_l(\\alpha+\\beta\\varepsilon_l)a_l} \\] <p>\u8bbe\u5bf9\u4e8e\u67d0\u4e2a\u80fd\u7ea7\\(l\\)\u603b\u7684\u91cf\u5b50\u6001\u4e3a\\(W_l\\)\u4e2a\uff0c\u4ece\u800c\u6709\\(\\Omega[\\{a_l\\}]=\\prod_lW_l\\),\u7531\u6b64\uff1a</p> \\[ \\Xi=\\sum_{\\{a_l\\}}\\prod_l\\left[W_le^{-(\\alpha+\\beta\\varepsilon_l)a_l}\\right]=\\prod_l\\Xi_l\\quad\\Rightarrow\\quad\\boxed{\\Xi_l=\\sum_{a_l}W_le^{-(\\alpha+\\beta\\varepsilon_l)a_l}} \\] <p>\u4e0a\u5f0f\u6c42\u548c\u53d8\u6362\u7684\u6280\u5de7\u5728\u4e8e\u5c06\u7cfb\u7edf\u6309\u6574\u4e2a\u5206\u5e03\u53bb\u6c42\u548c\uff0c\u8f6c\u5316\u4e3a\u5bf9\u5355\u4e2a\u80fd\u7ea7\u7684\u6c42\u548c\u518d\u8fde\u4e58\uff0c\u4ece\u800c\u5b9a\u4e49\u51fa\\(\\Xi_l\\).\u5bf9\u4e8e\u73bb\u8272\u7cfb\u7edf\u548c\u8d39\u7c73\u7cfb\u7edf\u7684\u67d0\u4e2a\u80fd\u7ea7\\(l\\)\uff0c\u6709\uff1a</p> \\[ B.E.\\quad\\Xi_l=\\sum_{a_l=0}^\\infty C_{w_l+a_l-1}^{a_l}e^{-(\\alpha+\\beta\\varepsilon_l)a_l}\\qquad F.D.\\quad\\Xi_l=\\sum_{a_l=0}^{\\omega_l}C_{w_l}^{a_l}e^{-(\\alpha+\\beta\\varepsilon_l)a_l} \\] <p>\u5229\u7528\\((1-x)^{-\\omega_l}\\)\u548c\\((1+x)^{\\omega_l}\\)\u7684\u5c55\u5f00\u5f0f\uff0c\u5f97\u5230\u5de8\u914d\u5206\u51fd\u6570\uff1a</p> \\[ B.E.\\quad\\Xi=\\prod_l\\Xi_l=\\prod_l(1-e^{-\\alpha-\\beta\\varepsilon_l})^{-\\omega_l}\\qquad F.D.\\quad\\Xi=\\prod_l\\Xi_l=\\prod_l(1+e^{-\\alpha-\\beta\\varepsilon_l})^{\\omega_l} \\] <p>\u4ee5\u4e0a\u5373\u4e0a\u4e00\u7ae0\u5f15\u5165\u7684\u5de8\u914d\u5206\u51fd\u6570\uff0c\u53ef\u89c1\u5176\u672c\u8d28\u548c\u672c\u7ae0\u7684\u5b8c\u5168\u76f8\u540c\uff0c\u53ea\u4e0d\u8fc7\u5f62\u5f0f\u4e0d\u540c\u800c\u5df2\u3002\u6700\u540e\uff0c\u5bfc\u51fa\u80fd\u7ea7\\(l\\)\u4e0a\u7684\u7c92\u5b50\u6570\u5206\u5e03\uff1a</p> \\[ B.E.\\quad\\bar{a_l}=-\\frac{\\partial}{\\partial\\alpha}ln\\Xi_l=\\frac{\\omega_l}{e^{\\alpha+\\beta \\varepsilon_l}-1}\\qquad F.D.\\quad\\bar{a_l}=-\\frac{\\partial}{\\partial\\alpha}ln\\Xi_l=\\frac{\\omega_l}{e^{\\alpha+\\beta \\varepsilon_l}+1} \\] <p>\u2605 \u6700\u540e\uff0c\u8ba8\u8bba\u4e00\u4e0b\u4e09\u79cd\u7cfb\u7efc\u7684\u5173\u7cfb\u3002\u5982\u679c\u6ee1\u8db3\u70ed\u529b\u5b66\u6781\u9650\u6761\u4ef6</p> \\[ \\mathop{lim}\\limits_{N,V \\to \\infty}\\frac{N}{V}=\\mathrm{finite} \\] <p>\u90a3\u4e48\u4e09\u79cd\u7cfb\u7efc\u662f\u7b49\u4ef7\u7684,\u4f8b\u5982\u7c92\u5b50\u6570\u5b88\u6052\u7684\u7406\u60f3\u6c14\u4f53\u4e5f\u53ef\u5229\u7528\u5de8\u914d\u5206\u51fd\u6570\u6765\u8ba1\u7b97\u3002\u4f46\u82e5\u4e0d\u6ee1\u8db3\u6b64\u6761\u4ef6\uff0c\u5f80\u5f80\u4f1a\u5bfc\u51fa\u9519\u8bef\u7684\u7ed3\u679c\u3002</p> <p>\u5bf9\u4e8e\u6982\u7387\\(\\rho_{s,N}\\)\u800c\u8a00\uff0c\u82e5\u5c06\u5de8\u6b63\u5219\u7cfb\u7efc\u4e2d\u7684\u7c92\u5b50\u6570\\(N\\)\u56fa\u5b9a\uff0c\u5219\u9000\u5316\u4e3a\u6b63\u5219\u7cfb\u7efc\u7684\u6982\u7387\\(\\rho_s\\).\u5982\u679c\u518d\u5c06\u6b63\u5219\u7cfb\u7efc\u7684\u80fd\u91cf\\(E_s\\)\u56fa\u5b9a\uff0c\u5219\u6982\u7387\u5c06\u6210\u4e3a\u5e38\u6570\uff0c\u5373\u4e3a\u5fae\u6b63\u5219\u7cfb\u7efc\u7684\u6982\u7387\\(\\rho_s=Const.\\)</p> <p>\u4ece\u5b9e\u7528\u6027\u7684\u89d2\u5ea6\uff0c\u6700\u4e3a\u5e38\u7528\u7684\u662f\u6b63\u5219\u7cfb\u7efc\u548c\u5de8\u6b63\u5219\u7cfb\u7efc\uff0c\u800c\u8fd9\u4e24\u8005\u7684\u9009\u53d6\u901a\u5e38\u5f88\u5fae\u5999\u3002\u4e00\u822c\u7684\u89c4\u5f8b\u662f\u5b9a\u57df\u7cfb\u7edf\u6216\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\u5e38\u7528\u6b63\u5219\u7cfb\u7efc\uff0c\u4e0d\u6ee1\u8db3\u975e\u7b80\u5e76\u6761\u4ef6\u7684\u975e\u5b9a\u57df\u7cfb\u7edf\u5e38\u7528\u5de8\u6b63\u5219\u7cfb\u7efc\u3002</p>"}]};
